from pycocotools.coco import COCO
import json
import os

coco_gt = COCO("/content/coco_eval/annotations/instances_val2017.json")

# Map filename -> COCO image ID
filename_to_id = {}

for img_id in selected_image_ids:
    info = coco_gt.loadImgs(img_id)[0]
    filename_to_id[info["file_name"]] = img_id

print("Image mapping created:", len(filename_to_id))

coco_predictions = []

for result in results:

    image_path = result.path
    filename = os.path.basename(image_path)

    image_id = filename_to_id[filename]

    if result.boxes is None:
        continue

    boxes = result.boxes

    xyxy = boxes.xyxy.cpu().numpy()
    scores = boxes.conf.cpu().numpy()
    classes = boxes.cls.cpu().numpy().astype(int)

    for box, score, cls in zip(xyxy, scores, classes):

        x1, y1, x2, y2 = box

        width = x2 - x1
        height = y2 - y1

        coco_predictions.append({
            "image_id": int(image_id),
            "category_id": int(cls + 1),
            "bbox": [
                float(x1),
                float(y1),
                float(width),
                float(height)
            ],
            "score": float(score)
        })

print("Total detections:", len(coco_predictions))

# Check the COCO category IDs
categories = coco_gt.loadCats(coco_gt.getCatIds())

for cat in categories[:10]:
    print(cat["id"], "->", cat["name"])

categories = coco_gt.loadCats(coco_gt.getCatIds())

for cat in categories[:10]:
    print(cat["id"], "->", cat["name"])

# Create COCO category-name -> official COCO category-ID mapping

coco_categories = coco_gt.loadCats(coco_gt.getCatIds())

coco_name_to_id = {
    cat["name"]: cat["id"]
    for cat in coco_categories
}

# YOLO class ID -> COCO category ID
yolo_to_coco = {}

for yolo_id, class_name in model.names.items():
    if class_name in coco_name_to_id:
        yolo_to_coco[yolo_id] = coco_name_to_id[class_name]

print("YOLO → COCO mapping created")
print()

for yolo_id in range(10):
    class_name = model.names[yolo_id]
    coco_id = yolo_to_coco[yolo_id]

    print(
        f"YOLO {yolo_id:2d} -> "
        f"{class_name:15s} -> "
        f"COCO {coco_id}"
    )

coco_predictions = []

for result in results:

    filename = os.path.basename(result.path)

    if filename not in filename_to_id:
        continue

    image_id = filename_to_id[filename]

    if result.boxes is None:
        continue

    xyxy = result.boxes.xyxy.cpu().numpy()
    scores = result.boxes.conf.cpu().numpy()
    classes = result.boxes.cls.cpu().numpy().astype(int)

    for box, score, yolo_cls in zip(xyxy, scores, classes):

        if yolo_cls not in yolo_to_coco:
            continue

        x1, y1, x2, y2 = box

        coco_predictions.append({
            "image_id": int(image_id),
            "category_id": int(yolo_to_coco[yolo_cls]),
            "bbox": [
                float(x1),
                float(y1),
                float(x2 - x1),
                float(y2 - y1)
            ],
            "score": float(score)
        })

print("Total detections:", len(coco_predictions))

import json

prediction_file = "/content/coco_eval/predictions/coco_predictions_100.json"

with open(prediction_file, "w") as f:
    json.dump(coco_predictions, f)

print("Saved:", prediction_file)

subset_gt = {
    "images": coco_gt.loadImgs(selected_image_ids),
    "annotations": [],
    "categories": coco_categories
}

for image_id in selected_image_ids:

    annotation_ids = coco_gt.getAnnIds(
        imgIds=[image_id]
    )

    annotations = coco_gt.loadAnns(annotation_ids)

    subset_gt["annotations"].extend(annotations)

subset_file = "/content/coco_eval/coco_subset_100.json"

with open(subset_file, "w") as f:
    json.dump(subset_gt, f)

print("Subset annotation file created.")
print("Images:", len(subset_gt["images"]))
print("Annotations:", len(subset_gt["annotations"]))

from pycocotools.cocoeval import COCOeval

# Load our 100-image ground truth
coco_subset = COCO(subset_file)

# Load predictions
coco_results = coco_subset.loadRes(prediction_file)

# Create evaluator
coco_eval = COCOeval(
    coco_subset,
    coco_results,
    "bbox"
)

# Evaluate ONLY selected 100 images
coco_eval.params.imgIds = selected_image_ids

coco_eval.evaluate()
coco_eval.accumulate()
coco_eval.summarize()

map_50_95 = float(coco_eval.stats[0])
map_50 = float(coco_eval.stats[1])
map_75 = float(coco_eval.stats[2])

print("mAP@50:95 :", round(map_50_95, 4))
print("mAP@50    :", round(map_50, 4))
print("mAP@75    :", round(map_75, 4))

import numpy as np

TP = 0
FP = 0
FN = 0

confidence_threshold = 0.50
iou_threshold = 0.50

def calculate_iou(box1, box2):
    """
    box format:
    [x1, y1, x2, y2]
    """

    x1 = max(box1[0], box2[0])
    y1 = max(box1[1], box2[1])

    x2 = min(box1[2], box2[2])
    y2 = min(box1[3], box2[3])

    intersection_width = max(0, x2 - x1)
    intersection_height = max(0, y2 - y1)

    intersection = (
        intersection_width *
        intersection_height
    )

    area1 = (
        max(0, box1[2] - box1[0]) *
        max(0, box1[3] - box1[1])
    )

    area2 = (
        max(0, box2[2] - box2[0]) *
        max(0, box2[3] - box2[1])
    )

    union = area1 + area2 - intersection

    if union == 0:
        return 0

    return intersection / union

from collections import defaultdict

# Ground truth annotations by image
gt_by_image = defaultdict(list)

for ann in subset_gt["annotations"]:

    if ann.get("iscrowd", 0):
        continue

    x, y, w, h = ann["bbox"]

    gt_box = [
        x,
        y,
        x + w,
        y + h
    ]

    gt_by_image[ann["image_id"]].append({
        "category_id": ann["category_id"],
        "bbox": gt_box,
        "matched": False
    })

pred_by_image = defaultdict(list)

for pred in coco_predictions:

    if pred["score"] < confidence_threshold:
        continue

    x, y, w, h = pred["bbox"]

    pred_box = [
        x,
        y,
        x + w,
        y + h
    ]

    pred_by_image[pred["image_id"]].append({
        "category_id": pred["category_id"],
        "bbox": pred_box,
        "score": pred["score"]
    })

TP = 0
FP = 0
FN = 0

for image_id in selected_image_ids:

    ground_truths = gt_by_image[image_id]
    predictions = pred_by_image[image_id]

    # Highest confidence first
    predictions = sorted(
        predictions,
        key=lambda x: x["score"],
        reverse=True
    )

    matched_gt = set()

    for pred in predictions:

        best_iou = 0
        best_gt_index = None

        for gt_index, gt in enumerate(ground_truths):

            if gt_index in matched_gt:
                continue

            if pred["category_id"] != gt["category_id"]:
                continue

            iou = calculate_iou(
                pred["bbox"],
                gt["bbox"]
            )

            if iou > best_iou:
                best_iou = iou
                best_gt_index = gt_index

        if (
            best_gt_index is not None
            and best_iou >= iou_threshold
        ):
            TP += 1
            matched_gt.add(best_gt_index)

        else:
            FP += 1

    FN += len(ground_truths) - len(matched_gt)

print("TP:", TP)
print("FP:", FP)
print("FN:", FN)

precision = TP / (TP + FP) if (TP + FP) > 0 else 0
recall = TP / (TP + FN) if (TP + FN) > 0 else 0

f1 = (
    2 * precision * recall /
    (precision + recall)
    if (precision + recall) > 0
    else 0
)

print("Precision:", round(precision, 4))
print("Recall   :", round(recall, 4))
print("F1       :", round(f1, 4))

print("Precision:", round(precision * 100, 2), "%")
print("Recall   :", round(recall * 100, 2), "%")
print("F1       :", round(f1 * 100, 2), "%")

import pandas as pd

