print("Saved research summary.")

# Per-category AP at IoU=0.50:0.95

precision_array = coco_eval.eval["precision"]

category_results = []

for idx, cat_id in enumerate(coco_eval.params.catIds):

    category_name = coco_gt.loadCats([cat_id])[0]["name"]

    # precision dimensions:
    # IoU × Recall × Category × Area × MaxDets

    values = precision_array[:, :, idx, 0, 2]

    values = values[values > -1]

    if len(values) > 0:
        ap = values.mean()
    else:
        ap = float("nan")

    category_results.append({
        "category_id": cat_id,
        "category": category_name,
        "AP50_95": ap
    })

per_class_df = pd.DataFrame(category_results)

per_class_df = per_class_df.sort_values(
    "AP50_95",
    ascending=False
)

per_class_df.head(20)

per_class_df.to_csv(
    "/content/coco_eval/COCO_EXP_001_per_class.csv",
    index=False
)

print("Per-class results saved.")

print(per_class_df.head(20).to_string(index=False))

