# Locate images and labels
image_dir = os.path.join(VAL_DIR, "images")
label_dir = os.path.join(VAL_DIR, "labels")

images = sorted(
    glob.glob(os.path.join(image_dir, "*.jpg")) +
    glob.glob(os.path.join(image_dir, "*.jpeg")) +
    glob.glob(os.path.join(image_dir, "*.png"))
)

labels = sorted(glob.glob(os.path.join(label_dir, "*.txt")))

print("\nNumber of validation images:", len(images))
print("Number of validation labels:", len(labels))

# Check matching image-label filenames
image_names = {os.path.splitext(os.path.basename(x))[0] for x in images}
label_names = {os.path.splitext(os.path.basename(x))[0] for x in labels}

missing_labels = image_names - label_names
orphan_labels = label_names - image_names

print("\nImages without labels:", len(missing_labels))
print("Labels without images:", len(orphan_labels))

# Read data.yaml
yaml_path = os.path.join(DATASET_ROOT, "data.yaml")

print("\n--- data.yaml ---")
with open(yaml_path, "r") as f:
    print(f.read())

# Show a few example pairs
print("\nExample image-label pairs:")
for name in sorted(image_names)[:5]:
    print(
        " ",
        name + ".jpg",
        "<->",
        name + ".txt"
    )

