# ============================================================

import os
import random
import shutil

DATASET_ROOT = "/content/bdd_eval/dataset"

SOURCE_IMAGES = os.path.join(DATASET_ROOT, "val", "images")
SOURCE_LABELS = os.path.join(DATASET_ROOT, "val", "labels")

SUBSET_ROOT = "/content/bdd_eval/subset_100"
SUBSET_IMAGES = os.path.join(SUBSET_ROOT, "images")
SUBSET_LABELS = os.path.join(SUBSET_ROOT, "labels")

os.makedirs(SUBSET_IMAGES, exist_ok=True)
os.makedirs(SUBSET_LABELS, exist_ok=True)

# Reproducible selection
SEED = 42
NUM_SAMPLES = 100

random.seed(SEED)

all_images = sorted([
    f for f in os.listdir(SOURCE_IMAGES)
    if f.lower().endswith((".jpg", ".jpeg", ".png"))
])

selected_images = random.sample(all_images, NUM_SAMPLES)

# Copy image + corresponding label
copied = 0

for image_name in selected_images:
    image_path = os.path.join(SOURCE_IMAGES, image_name)

    base_name = os.path.splitext(image_name)[0]
    label_name = base_name + ".txt"
    label_path = os.path.join(SOURCE_LABELS, label_name)

    if not os.path.exists(label_path):
        print("WARNING: Missing label:", image_name)
        continue

    shutil.copy2(image_path, os.path.join(SUBSET_IMAGES, image_name))
    shutil.copy2(label_path, os.path.join(SUBSET_LABELS, label_name))

    copied += 1

print("============================================")
print("BDD100K EXPERIMENT SUBSET")
print("============================================")
print("Experiment ID :", "BDD-EXP-001")
print("Random seed   :", SEED)
print("Requested     :", NUM_SAMPLES)
print("Copied        :", copied)
print("Image folder  :", SUBSET_IMAGES)
print("Label folder  :", SUBSET_LABELS)
print("============================================")

# Show first 10 selected images
print("\nFirst 10 selected images:")
for name in selected_images[:10]:
    print(" ", name)

# ============================================================
# BDD100K EXP-001 — GROUND-TRUTH CLASS DISTRIBUTION
# ============================================================

import os
from collections import Counter

LABEL_DIR = "/content/bdd_eval/subset_100/labels"

CLASS_NAMES = [
    "person",
    "rider",
    "car",
    "bus",
    "truck",
    "bike",
    "motor",
    "traffic light",
    "traffic sign",
    "train"
]

class_counts = Counter()
images_with_class = Counter()
total_objects = 0

label_files = sorted([
    f for f in os.listdir(LABEL_DIR)
    if f.endswith(".txt")
])

for label_file in label_files:
    path = os.path.join(LABEL_DIR, label_file)

    seen_in_image = set()

    with open(path, "r") as f:
        for line in f:
            parts = line.strip().split()

            if len(parts) < 5:
                continue

            class_id = int(parts[0])

            if 0 <= class_id < len(CLASS_NAMES):
                class_counts[class_id] += 1
                total_objects += 1
                seen_in_image.add(class_id)

    for class_id in seen_in_image:
        images_with_class[class_id] += 1

print("============================================")
print("BDD100K EXP-001 GROUND TRUTH")
print("============================================")
print("Evaluation images :", len(label_files))
print("Total GT objects  :", total_objects)
print()

print(f"{'ID':<5}{'Class':<18}{'Objects':<10}{'Images':<10}")
print("-" * 43)

for class_id, name in enumerate(CLASS_NAMES):
    print(
        f"{class_id:<5}"
        f"{name:<18}"
        f"{class_counts[class_id]:<10}"
        f"{images_with_class[class_id]:<10}"
    )

print("============================================")

