# MODULE 3 — MAPILLARY VISTAS
# STEP 9: SEARCH ENTIRE RUNTIME FOR ZIP
# ============================================================

import os

target = "mapillary-vistas-dataset_public_v2.0.zip"
found = []

search_dirs = [
    "/content",
    "/root",
    "/tmp"
]

for base in search_dirs:
    print("Searching:", base)

    for root, dirs, files in os.walk(base):
        # Skip some directories that can contain huge numbers of files
        dirs[:] = [
            d for d in dirs
            if d not in ["node_modules", ".cache/pip"]
        ]

        if target in files:
            path = os.path.join(root, target)
            found.append(path)

print("\n" + "=" * 60)
print("RESULT")
print("=" * 60)

if found:
    for path in found:
        size_gb = os.path.getsize(path) / (1024**3)
        print("FOUND:", path)
        print("SIZE :", round(size_gb, 2), "GB")
else:
    print("ZIP NOT FOUND IN CURRENT RUNTIME")

