# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 20: VERIFY IMAGE / MASK / POLYGON MATCHING
# ============================================================

import zipfile
import os

zip_path = "/content/mapillary_download/mapillary-vistas-dataset_public_v2.0.zip"

with zipfile.ZipFile(zip_path, "r") as z:

    files = z.namelist()

    # Build filename-stem sets
    image_ids = {
        os.path.splitext(os.path.basename(f))[0]
        for f in files
        if f.startswith("validation/images/")
        and f.lower().endswith(".jpg")
    }

    mask_ids = {
        os.path.splitext(os.path.basename(f))[0]
        for f in files
        if f.startswith("validation/v2.0/labels/")
        and f.lower().endswith(".png")
    }

    polygon_ids = {
        os.path.splitext(os.path.basename(f))[0]
        for f in files
        if f.startswith("validation/v2.0/polygons/")
        and f.lower().endswith(".json")
    }

print("Images:", len(image_ids))
print("Masks:", len(mask_ids))
print("Polygons:", len(polygon_ids))

# IDs that have all three
complete_ids = image_ids & mask_ids & polygon_ids

print("\nComplete image+mask+polygon matches:", len(complete_ids))

print("\nImages without masks:", len(image_ids - mask_ids))
print("Images without polygons:", len(image_ids - polygon_ids))
print("Masks without images:", len(mask_ids - image_ids))
print("Polygons without images:", len(polygon_ids - image_ids))

print("\n--- SAMPLE COMPLETE MATCHES ---")

for image_id in sorted(complete_ids)[:20]:
    print(
        f"{image_id}.jpg  <->  "
        f"{image_id}.png  <->  "
        f"{image_id}.json"
    )

