# MODULE 3 — MAPILLARY VISTAS
# STEP 21: INSPECT MAPILLARY V2.0 CLASS CONFIGURATION
# ============================================================

import zipfile
import json

zip_path = "/content/mapillary_download/mapillary-vistas-dataset_public_v2.0.zip"

config_path = "config_v2.0.json"

with zipfile.ZipFile(zip_path, "r") as z:

    # Read configuration directly from ZIP
    with z.open(config_path) as f:
        config = json.load(f)

print("Configuration loaded successfully.")
print("Top-level keys:")
print(list(config.keys()))

print("\n--- CONFIGURATION SUMMARY ---")

for key, value in config.items():

    if isinstance(value, list):
        print(f"{key}: list with {len(value)} items")

    elif isinstance(value, dict):
        print(f"{key}: dictionary with {len(value)} entries")

    else:
        print(f"{key}: {value}")

# Inspect likely label/class information
print("\n--- POSSIBLE CLASS DEFINITIONS ---")

for key in config.keys():

    key_lower = key.lower()

    if any(word in key_lower for word in
           ["label", "class", "category", "object"]):

        print(f"\nKEY: {key}")

        value = config[key]

        if isinstance(value, list):
            for item in value[:10]:
                print(item)

            if len(value) > 10:
                print(f"... ({len(value) - 10} more)")

        elif isinstance(value, dict):
            for k, v in list(value.items())[:10]:
                print(k, ":", v)

            if len(value) > 10:
                print(f"... ({len(value) - 10} more)")

