# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 25: EXTRACT 100-IMAGE VALIDATION SUBSET
# ============================================================

import zipfile
import os
import random
import shutil

zip_path = "/content/mapillary_download/mapillary-vistas-dataset_public_v2.0.zip"

output_root = "/content/mapillary_eval"
image_out = os.path.join(output_root, "images")
mask_out = os.path.join(output_root, "masks")
polygon_out = os.path.join(output_root, "polygons")

os.makedirs(image_out, exist_ok=True)
os.makedirs(mask_out, exist_ok=True)
os.makedirs(polygon_out, exist_ok=True)

# ------------------------------------------------------------
# 1. Find all validation images
# ------------------------------------------------------------

with zipfile.ZipFile(zip_path, "r") as z:

    image_files = [
        f for f in z.namelist()
        if f.startswith("validation/images/")
        and f.lower().endswith(".jpg")
    ]

print("Total validation images available:", len(image_files))

# ------------------------------------------------------------
# 2. Reproducible random selection
# ------------------------------------------------------------

random.seed(42)

selected_images = random.sample(image_files, 100)

print("Selected images:", len(selected_images))

# ------------------------------------------------------------
# 3. Extract image + mask + polygon
# ------------------------------------------------------------

extracted = 0
missing = []

with zipfile.ZipFile(zip_path, "r") as z:

    for image_path in selected_images:

        filename = os.path.basename(image_path)
        stem = os.path.splitext(filename)[0]

        mask_path = (
            f"validation/v2.0/labels/{stem}.png"
        )

        polygon_path = (
            f"validation/v2.0/polygons/{stem}.json"
        )

        # Check all three exist
        required_files = [
            image_path,
            mask_path,
            polygon_path
        ]

        if not all(path in z.namelist() for path in required_files):
            missing.append(stem)
            continue

        # Extract image
        with z.open(image_path) as src:
            with open(
                os.path.join(image_out, filename),
                "wb"
            ) as dst:
                shutil.copyfileobj(src, dst)

        # Extract mask
        with z.open(mask_path) as src:
            with open(
                os.path.join(mask_out, stem + ".png"),
                "wb"
            ) as dst:
                shutil.copyfileobj(src, dst)

        # Extract polygon annotation
        with z.open(polygon_path) as src:
            with open(
                os.path.join(polygon_out, stem + ".json"),
                "wb"
            ) as dst:
                shutil.copyfileobj(src, dst)

        extracted += 1

print("\nExtraction complete.")
print("Successfully extracted:", extracted)
print("Missing samples:", len(missing))

if missing:
    print("\nMissing IDs:")
    for stem in missing:
        print(stem)

# ------------------------------------------------------------
# 4. Verify extracted files
# ------------------------------------------------------------

images = [
    f for f in os.listdir(image_out)
    if f.lower().endswith(".jpg")
]

masks = [
    f for f in os.listdir(mask_out)
    if f.lower().endswith(".png")
]

polygons = [
    f for f in os.listdir(polygon_out)
    if f.lower().endswith(".json")
]

print("\n--- FINAL SUBSET COUNTS ---")
print("Images :", len(images))
print("Masks  :", len(masks))
print("Polygons:", len(polygons))

assert len(images) == 100
assert len(masks) == 100
assert len(polygons) == 100

print("\nSUCCESS: 100 complete Mapillary Vistas samples extracted.")
print("Dataset archive remains untouched at:")
print(zip_path)

