import os

output_root = "/content/mapillary_eval"

image_out = os.path.join(output_root, "images")
mask_out = os.path.join(output_root, "masks")
polygon_out = os.path.join(output_root, "polygons")

def count_files(folder, extension):
    if not os.path.exists(folder):
        return 0
    return len([
        f for f in os.listdir(folder)
        if f.lower().endswith(extension)
    ])

image_count = count_files(image_out, ".jpg")
mask_count = count_files(mask_out, ".png")
polygon_count = count_files(polygon_out, ".json")

print("Mapillary subset verification")
print("=" * 40)

print("Images  :", image_count)
print("Masks   :", mask_count)
print("Polygons:", polygon_count)

print("\nDirectories:")
print("Images :", os.path.exists(image_out))
print("Masks  :", os.path.exists(mask_out))
print("Polygons:", os.path.exists(polygon_out))

if image_count == 100 and mask_count == 100 and polygon_count == 100:
    print("\nSUCCESS: 100 complete samples are ready.")
elif image_count == 0 and mask_count == 0 and polygon_count == 0:
    print("\nNO FILES EXTRACTED.")
    print("The previous extraction was interrupted before files were written.")
else:
    print("\nPARTIAL EXTRACTION.")
    print("We will safely complete the missing files.")

# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 27: ANALYZE OBSTACLE DISTRIBUTION
# ============================================================

import os
import numpy as np
from PIL import Image
from collections import Counter

mask_dir = "/content/mapillary_eval/masks"

# Obstacle classes defined in Step 23
obstacle_ids = set(OBSTACLE_CLASSES.keys())

results = []

for filename in sorted(os.listdir(mask_dir)):

    if not filename.lower().endswith(".png"):
        continue

    mask_path = os.path.join(mask_dir, filename)

    mask = np.array(Image.open(mask_path))

    total_pixels = mask.size

    # Count obstacle pixels
    obstacle_mask = np.isin(mask, list(obstacle_ids))

    obstacle_pixels = np.sum(obstacle_mask)

    obstacle_percentage = (
        obstacle_pixels / total_pixels
    ) * 100

    # Which obstacle classes occur?
    present_ids = sorted(
        set(np.unique(mask))
        & obstacle_ids
    )

    results.append({
        "filename": filename,
        "total_pixels": total_pixels,
        "obstacle_pixels": int(obstacle_pixels),
        "obstacle_percentage": obstacle_percentage,
        "num_obstacle_classes": len(present_ids),
        "obstacle_class_ids": present_ids
    })

# ------------------------------------------------------------
# Summary
# ------------------------------------------------------------

print("MAPILLARY VISTAS — OBSTACLE DISTRIBUTION")
print("=" * 60)

print("Images analyzed:", len(results))

obstacle_percentages = [
    r["obstacle_percentage"]
    for r in results
]

images_with_obstacles = sum(
    r["obstacle_pixels"] > 0
    for r in results
)

images_without_obstacles = (
    len(results) - images_with_obstacles
)

total_obstacle_pixels = sum(
    r["obstacle_pixels"]
    for r in results
)

total_pixels = sum(
    r["total_pixels"]
    for r in results
)

overall_obstacle_percentage = (
    total_obstacle_pixels / total_pixels
) * 100

print("\nImages containing obstacles :", images_with_obstacles)
print("Images without obstacles    :", images_without_obstacles)

print(
    "\nTotal obstacle pixels:",
    total_obstacle_pixels
)

print(
    "Total pixels:",
    total_pixels
)

print(
    "Overall obstacle pixel percentage:",
    f"{overall_obstacle_percentage:.3f}%"
)

print(
    "\nAverage obstacle percentage/image:",
    f"{np.mean(obstacle_percentages):.3f}%"
)

print(
    "Minimum obstacle percentage:",
    f"{np.min(obstacle_percentages):.3f}%"
)

print(
    "Maximum obstacle percentage:",
    f"{np.max(obstacle_percentages):.3f}%"
)

# ------------------------------------------------------------
# Count obstacle classes across the subset
# ------------------------------------------------------------

class_counter = Counter()

for r in results:
    for class_id in r["obstacle_class_ids"]:
        class_counter[class_id] += 1

print("\n--- OBSTACLE CLASS IMAGE FREQUENCY ---")

for class_id, count in class_counter.most_common():

    print(
        f"{class_id:3d} | "
        f"{OBSTACLE_CLASSES[class_id]:25s} | "
        f"{count:3d} images"
    )

# ------------------------------------------------------------
# Show images with highest obstacle coverage
# ------------------------------------------------------------

print("\n--- TOP 10 IMAGES BY OBSTACLE COVERAGE ---")

top_images = sorted(
    results,
    key=lambda x: x["obstacle_percentage"],
    reverse=True
)[:10]

for r in top_images:

    print(
        f"{r['filename']} | "
        f"{r['obstacle_percentage']:.2f}% | "
        f"{r['num_obstacle_classes']} classes"
    )

