# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 30: YOLOv8n-SEG INFERENCE ON 100-IMAGE SUBSET
# ============================================================

import os
import time
import numpy as np
from PIL import Image

IMAGE_DIR = "/content/mapillary_eval/images"

image_files = sorted([
    os.path.join(IMAGE_DIR, f)
    for f in os.listdir(IMAGE_DIR)
    if f.lower().endswith((".jpg", ".jpeg", ".png"))
])

print("Images found:", len(image_files))

# Fixed experiment settings
IMAGE_SIZE = 640
CONF_THRESHOLD = 0.25

print("Image size:", IMAGE_SIZE)
print("Confidence threshold:", CONF_THRESHOLD)

# ------------------------------------------------------------
# Run inference
# ------------------------------------------------------------

prediction_results = []
latencies_ms = []

for i, image_path in enumerate(image_files):

    start_time = time.perf_counter()

    result = model.predict(
        source=image_path,
        imgsz=IMAGE_SIZE,
        conf=CONF_THRESHOLD,
        device=0,
        verbose=False
    )[0]

    end_time = time.perf_counter()

    latency_ms = (end_time - start_time) * 1000

    prediction_results.append(result)
    latencies_ms.append(latency_ms)

    if (i + 1) % 10 == 0:
        print(
            f"Processed {i + 1:3d}/{len(image_files)} | "
            f"Latency: {latency_ms:.2f} ms"
        )

# ------------------------------------------------------------
# Summary
# ------------------------------------------------------------

avg_latency_ms = np.mean(latencies_ms)
median_latency_ms = np.median(latencies_ms)
fps = 1000.0 / avg_latency_ms

print("\n" + "=" * 60)
print("INFERENCE COMPLETE")
print("=" * 60)

print("Images processed:", len(prediction_results))
print(f"Average latency: {avg_latency_ms:.2f} ms/image")
print(f"Median latency:  {median_latency_ms:.2f} ms/image")
print(f"Approx. FPS:     {fps:.2f}")
print("Confidence:", CONF_THRESHOLD)
print("Image size:", IMAGE_SIZE)

# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 31: INSPECT YOLO SEGMENTATION OUTPUT
# ============================================================

result = prediction_results[0]

print("Prediction object type:", type(result))

print("\nOriginal image:")
print("Path:", result.path)
print("Original shape:", result.orig_shape)

print("\nDetected boxes:")
if result.boxes is not None:
    print("Number of detections:", len(result.boxes))
    print("Classes:", result.boxes.cls.cpu().numpy().astype(int).tolist())
    print("Confidences:", result.boxes.conf.cpu().numpy().round(3).tolist())
else:
    print("No boxes returned.")

print("\nSegmentation masks:")
if result.masks is not None:
    print("Mask tensor shape:", tuple(result.masks.data.shape))
    print("Mask dtype:", result.masks.data.dtype)
else:
    print("NO SEGMENTATION MASKS RETURNED.")

# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 32: CONVERT YOLO MASKS → BINARY OBSTACLE MASKS
# ============================================================

import os
import numpy as np
from PIL import Image

PRED_MASK_DIR = "/content/mapillary_eval/predicted_obstacle_masks"

os.makedirs(PRED_MASK_DIR, exist_ok=True)

# COCO IDs that are considered obstacles in our experiment
OBSTACLE_COCO_IDS = {
    0,   # person
    1,   # bicycle
    2,   # car
    3,   # motorcycle
    5,   # bus
    7,   # truck
    10,  # fire hydrant
    12,  # parking meter
    13,  # bench
}

predicted_mask_paths = []
total_predicted_obstacle_pixels = 0

for i, result in enumerate(prediction_results):

    # Original image dimensions: (height, width)
    orig_h, orig_w = result.orig_shape

    # Start with an empty binary obstacle mask
    binary_mask = np.zeros(
        (orig_h, orig_w),
        dtype=np.uint8
    )

    if result.masks is not None and result.boxes is not None:

        classes = result.boxes.cls.cpu().numpy().astype(int)
        masks = result.masks.data.cpu().numpy()

        for class_id, instance_mask in zip(classes, masks):

            # Only use our predefined obstacle classes
            if class_id not in OBSTACLE_COCO_IDS:
                continue

            # Convert mask to PIL for resizing
            mask_img = Image.fromarray(
                (instance_mask * 255).astype(np.uint8)
            )

            # Resize to original image dimensions
            mask_img = mask_img.resize(
                (orig_w, orig_h),
                Image.Resampling.NEAREST
            )

            resized_mask = np.array(mask_img)

            # Add this instance to binary obstacle mask
            binary_mask[resized_mask > 127] = 255

    # Save binary mask
    image_name = os.path.splitext(
        os.path.basename(result.path)
    )[0]

    output_path = os.path.join(
        PRED_MASK_DIR,
        image_name + "_obstacle.png"
    )

    Image.fromarray(binary_mask).save(output_path)

    predicted_mask_paths.append(output_path)

    total_predicted_obstacle_pixels += np.sum(
        binary_mask > 0
    )

    if (i + 1) % 10 == 0:
        print(
            f"Processed {i + 1:3d}/{len(prediction_results)} | "
            f"Predicted obstacle pixels: "
            f"{total_predicted_obstacle_pixels:,}"
        )

print("\n" + "=" * 60)
print("BINARY PREDICTION MASK GENERATION COMPLETE")
print("=" * 60)

print("Images processed:", len(predicted_mask_paths))
print("Prediction mask directory:", PRED_MASK_DIR)
print(
    "Total predicted obstacle pixels:",
    f"{total_predicted_obstacle_pixels:,}"
)

