# ============================================================
# MODULE 3 — MAPILLARY VISTAS
# STEP 34: CALCULATE BINARY OBSTACLE SEGMENTATION METRICS
# ============================================================

import os
import numpy as np
from PIL import Image

GT_BINARY_DIR = "/content/mapillary_eval/gt_binary_masks"
PRED_MASK_DIR = "/content/mapillary_eval/predicted_obstacle_masks"

gt_files = sorted([
    f for f in os.listdir(GT_BINARY_DIR)
    if f.lower().endswith(".png")
])

# ------------------------------------------------------------
# Global pixel-level confusion matrix
# ------------------------------------------------------------

TP = 0
FP = 0
FN = 0
TN = 0

evaluated_pixels = 0
ignored_pixels = 0

per_image_results = []

for filename in gt_files:

    gt_path = os.path.join(
        GT_BINARY_DIR,
        filename
    )

    # Prediction filename:
    # original.png -> original_obstacle.png
    stem = os.path.splitext(filename)[0]

    pred_filename = stem + "_obstacle.png"

    pred_path = os.path.join(
        PRED_MASK_DIR,
        pred_filename
    )

    gt = np.array(
        Image.open(gt_path),
        dtype=np.uint8
    )

    pred = np.array(
        Image.open(pred_path),
        dtype=np.uint8
    )

    # --------------------------------------------------------
    # Valid pixels only
    # --------------------------------------------------------

    valid = gt != 128

    gt_obstacle = gt == 255
    pred_obstacle = pred > 0

    # Confusion matrix
    image_tp = np.sum(
        valid & gt_obstacle & pred_obstacle
    )

    image_fp = np.sum(
        valid & (~gt_obstacle) & pred_obstacle
    )

    image_fn = np.sum(
        valid & gt_obstacle & (~pred_obstacle)
    )

    image_tn = np.sum(
        valid & (~gt_obstacle) & (~pred_obstacle)
    )

    image_evaluated = np.sum(valid)
    image_ignored = np.sum(~valid)

    TP += image_tp
    FP += image_fp
    FN += image_fn
    TN += image_tn

    evaluated_pixels += image_evaluated
    ignored_pixels += image_ignored

    # --------------------------------------------------------
    # Per-image obstacle IoU
    # --------------------------------------------------------

    intersection = image_tp
    union = (
        image_tp
        + image_fp
        + image_fn
    )

    if union > 0:
        image_iou = intersection / union
    else:
        image_iou = np.nan

    per_image_results.append({
        "filename": filename,
        "TP": int(image_tp),
        "FP": int(image_fp),
        "FN": int(image_fn),
        "TN": int(image_tn),
        "evaluated_pixels": int(image_evaluated),
        "ignored_pixels": int(image_ignored),
        "obstacle_IoU": image_iou,
    })

# ------------------------------------------------------------
# Global obstacle metrics
# ------------------------------------------------------------

obstacle_iou = (
    TP / (TP + FP + FN)
    if (TP + FP + FN) > 0
    else 0
)

precision = (
    TP / (TP + FP)
    if (TP + FP) > 0
    else 0
)

recall = (
    TP / (TP + FN)
    if (TP + FN) > 0
    else 0
)

f1 = (
    2 * precision * recall / (precision + recall)
    if (precision + recall) > 0
    else 0
)

# ------------------------------------------------------------
# Non-obstacle IoU
# ------------------------------------------------------------

non_obstacle_iou = (
    TN / (TN + FP + FN)
    if (TN + FP + FN) > 0
    else 0
)

# Binary mIoU = mean of obstacle and non-obstacle IoU
binary_miou = (
    obstacle_iou + non_obstacle_iou
) / 2

# Pixel accuracy
pixel_accuracy = (
    (TP + TN) / evaluated_pixels
    if evaluated_pixels > 0
    else 0
)

# ------------------------------------------------------------
# Dataset-level obstacle prevalence
# ------------------------------------------------------------

gt_obstacle_pixels = TP + FN
pred_obstacle_pixels = TP + FP

gt_obstacle_percentage = (
    100 * gt_obstacle_pixels / evaluated_pixels
    if evaluated_pixels > 0
    else 0
)

pred_obstacle_percentage = (
    100 * pred_obstacle_pixels / evaluated_pixels
    if evaluated_pixels > 0
    else 0
)

ignored_percentage = (
    100 * ignored_pixels
    / (evaluated_pixels + ignored_pixels)
    if (evaluated_pixels + ignored_pixels) > 0
    else 0
)

# ------------------------------------------------------------
# Print results
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("MAPILLARY VISTAS — BINARY OBSTACLE SEGMENTATION RESULTS")
print("=" * 70)

print("\nDataset:")
print("  Images evaluated:", len(gt_files))
print("  Evaluated pixels:", f"{evaluated_pixels:,}")
print("  Ignored pixels:", f"{ignored_pixels:,}")
print(f"  Ignored percentage: {ignored_percentage:.2f}%")

print("\nGround Truth / Prediction:")
print(
    "  GT obstacle pixels:",
    f"{gt_obstacle_pixels:,}",
    f"({gt_obstacle_percentage:.2f}%)"
)

print(
    "  Predicted obstacle pixels:",
    f"{pred_obstacle_pixels:,}",
    f"({pred_obstacle_percentage:.2f}%)"
)

print("\nConfusion Matrix:")
print("  TP:", f"{TP:,}")
print("  FP:", f"{FP:,}")
print("  FN:", f"{FN:,}")
print("  TN:", f"{TN:,}")

print("\nSegmentation Metrics:")
print(f"  Obstacle IoU:       {obstacle_iou:.4f} ({obstacle_iou*100:.2f}%)")
print(f"  Non-obstacle IoU:   {non_obstacle_iou:.4f} ({non_obstacle_iou*100:.2f}%)")
print(f"  Binary mIoU:        {binary_miou:.4f} ({binary_miou*100:.2f}%)")
print(f"  Precision:          {precision:.4f} ({precision*100:.2f}%)")
print(f"  Recall:             {recall:.4f} ({recall*100:.2f}%)")
print(f"  F1 Score:           {f1:.4f} ({f1*100:.2f}%)")
print(f"  Pixel Accuracy:     {pixel_accuracy:.4f} ({pixel_accuracy*100:.2f}%)")

print("\n" + "=" * 70)

