import os
import torch
import requests

BASE_DIR = "/content/places365_eval"
MODEL_FILE = os.path.join(BASE_DIR, "resnet50_places365.pth")

# Places365 ResNet-50 pretrained weights
MODEL_URL = (
    "http://places2.csail.mit.edu/models_places365/"
    "resnet50_places365.pth.tar"
)

print("=" * 60)
print("PLACES365 — PRETRAINED MODEL")
print("=" * 60)

if os.path.exists(MODEL_FILE):
    print("Model already exists.")
    print("Path:", MODEL_FILE)
    print("Size:", round(os.path.getsize(MODEL_FILE) / (1024**2), 2), "MB")
else:
    print("Downloading Places365 ResNet-50 model...")
    print("This may take a few minutes.")

    response = requests.get(
        MODEL_URL,
        stream=True,
        timeout=120
    )
    response.raise_for_status()

    total = int(response.headers.get("content-length", 0))
    downloaded = 0

    with open(MODEL_FILE, "wb") as f:
        for chunk in response.iter_content(chunk_size=1024 * 1024):
            if chunk:
                f.write(chunk)
                downloaded += len(chunk)

                if total:
                    percent = downloaded * 100 / total
                    print(
                        f"\rProgress: {percent:.1f}%",
                        end=""
                    )

    print("\nDownload complete.")

print("\nModel path:", MODEL_FILE)
print(
    "Model size:",
    round(os.path.getsize(MODEL_FILE) / (1024**2), 2),
    "MB"
)
print("File exists:", os.path.exists(MODEL_FILE))

# ============================================================
# MODULE 4 — LOAD & VERIFY PLACES365 MODEL
# ============================================================

import os
import torch
import torch.nn as nn
from torchvision import models

BASE_DIR = "/content/places365_eval"
MODEL_FILE = os.path.join(BASE_DIR, "resnet50_places365.pth")

print("=" * 60)
print("PLACES365 — MODEL LOADING")
print("=" * 60)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("Device:", device)

# ------------------------------------------------------------
# Create ResNet-50 architecture
# ------------------------------------------------------------
model = models.resnet50(weights=None)

# Places365 has exactly 365 output classes
model.fc = nn.Linear(model.fc.in_features, 365)

# ------------------------------------------------------------
# Load checkpoint
# ------------------------------------------------------------
checkpoint = torch.load(
    MODEL_FILE,
    map_location=device
)

print("Checkpoint type:", type(checkpoint))

# Places365 checkpoint usually contains a state_dict
if isinstance(checkpoint, dict) and "state_dict" in checkpoint:
    state_dict = checkpoint["state_dict"]
else:
    state_dict = checkpoint

# Remove possible "module." prefix
clean_state_dict = {}

for key, value in state_dict.items():
    new_key = key.replace("module.", "")
    clean_state_dict[new_key] = value

# Load weights
missing, unexpected = model.load_state_dict(
    clean_state_dict,
    strict=False
)

model = model.to(device)
model.eval()

print("\nModel loaded successfully.")
print("Output classes:", model.fc.out_features)
print("Missing keys:", len(missing))
print("Unexpected keys:", len(unexpected))

# ------------------------------------------------------------
# Dummy forward pass
# ------------------------------------------------------------
dummy = torch.randn(
    1, 3, 224, 224,
    device=device
)

with torch.no_grad():
    output = model(dummy)

print("\nDummy inference:")
print("Output shape:", tuple(output.shape))
print("Expected shape: (1, 365)")

# ------------------------------------------------------------
# Final verification
# ------------------------------------------------------------
assert output.shape == (1, 365)

print("\n" + "=" * 60)
print("PLACES365 MODEL VERIFICATION: PASSED")
print("=" * 60)

# ============================================================
# MODULE 4 — CHECK FOR EXISTING PLACES365 DATA
# ============================================================

import os
from pathlib import Path

print("=" * 60)
print("PLACES365 — DATASET AVAILABILITY CHECK")
print("=" * 60)

search_roots = [
    "/content",
    "/root/.cache",
    "/root/.cache/torch",
]

keywords = [
    "places365",
    "places_val",
    "val_256",
    "val_large",
    "places"
]

found = []

for root in search_roots:
    if not os.path.exists(root):
        continue

    for dirpath, dirnames, filenames in os.walk(root):
        # Avoid extremely large/unrelated cache trees
        dirnames[:] = [
            d for d in dirnames
            if d not in {
                "node_modules",
                ".git",
                "__pycache__"
            }
        ]

        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            name_lower = filename.lower()

            if any(k in name_lower for k in keywords):
                try:
                    size_mb = os.path.getsize(full_path) / (1024 ** 2)
                except:
                    size_mb = 0

                found.append(
                    (full_path, size_mb)
                )

# Remove duplicates
found = list(dict.fromkeys(found))

if found:
    print("\nPotential Places365 files found:")

    for path, size in found[:100]:
        print(f"{size:10.2f} MB  {path}")

    if len(found) > 100:
        print(f"\n...and {len(found)-100} more")
else:
    print("\nNo existing Places365 dataset files found.")

print("\nSearch completed.")

