# MODULE 4 — INSPECT PLACES365 VALIDATION ARCHIVE
# ============================================================

import os
import tarfile
from collections import Counter

ARCHIVE = "/content/places365_eval/val_256.tar"

print("=" * 60)
print("PLACES365 — ARCHIVE STRUCTURE")
print("=" * 60)

with tarfile.open(ARCHIVE, "r") as tar:

    members = tar.getmembers()

    print("Total archive entries:", len(members))

    # Count file extensions
    extensions = Counter()

    for m in members:
        if m.isfile():
            name = m.name.lower()

            if "." in name:
                ext = "." + name.rsplit(".", 1)[1]
            else:
                ext = "[no extension]"

            extensions[ext] += 1

    print("\nFile types:")
    for ext, count in extensions.most_common():
        print(f"{ext:15s}: {count}")

    # Show first 30 entries
    print("\nFirst 30 archive entries:")
    for m in members[:30]:
        print(m.name)

    # Count directories
    directories = [m for m in members if m.isdir()]

    print("\nDirectories:", len(directories))

    # Find image files
    image_extensions = {
        ".jpg", ".jpeg", ".png"
    }

    images = [
        m for m in members
        if m.isfile()
        and os.path.splitext(m.name.lower())[1]
        in image_extensions
    ]

    print("Image files:", len(images))

    # Show sample image paths
    print("\nSample image paths:")
    for m in images[:20]:
        print(m.name)

print("\nArchive inspection completed.")

