import os
import tarfile
import requests

BASE_DIR = "/content/places365_eval"

FILELIST_ARCHIVE = os.path.join(
    BASE_DIR,
    "filelist_places365-standard.tar"
)

LABEL_FILE = os.path.join(
    BASE_DIR,
    "places365_val.txt"
)

URL = (
    "https://data.csail.mit.edu/places/places365/"
    "filelist_places365-standard.tar"
)

print("=" * 60)
print("PLACES365 — OFFICIAL LABEL ARCHIVE")
print("=" * 60)

# ------------------------------------------------------------
# Download metadata archive
# ------------------------------------------------------------

if not os.path.exists(FILELIST_ARCHIVE):

    print("Downloading official Places365 metadata archive...")

    response = requests.get(
        URL,
        stream=True,
        timeout=120
    )
    response.raise_for_status()

    total = int(
        response.headers.get("content-length", 0)
    )
    downloaded = 0

    with open(FILELIST_ARCHIVE, "wb") as f:
        for chunk in response.iter_content(
            chunk_size=1024 * 1024
        ):
            if chunk:
                f.write(chunk)
                downloaded += len(chunk)

                if total:
                    percent = (
                        downloaded * 100 / total
                    )
                    print(
                        f"\rProgress: {percent:.1f}%",
                        end=""
                    )

    print("\nDownload complete.")

else:
    print("Metadata archive already exists.")

print(
    "\nArchive size:",
    round(
        os.path.getsize(FILELIST_ARCHIVE) / (1024 ** 2),
        2
    ),
    "MB"
)

# ------------------------------------------------------------
# Inspect archive
# ------------------------------------------------------------

print("\nInspecting archive...")

with tarfile.open(
    FILELIST_ARCHIVE,
    "r"
) as tar:

    members = tar.getmembers()

    print("Archive entries:", len(members))

    print("\nRelevant entries:")

    for member in members:
        if (
            "places365_val.txt" in member.name
            or "val" in member.name.lower()
        ):
            print(member.name)

    # Find exact validation label file
    val_members = [
        m for m in members
        if os.path.basename(m.name)
        == "places365_val.txt"
    ]

    if len(val_members) == 0:
        raise FileNotFoundError(
            "places365_val.txt was not found in the archive."
        )

    val_member = val_members[0]

    print(
        "\nExtracting:",
        val_member.name
    )

    extracted = tar.extractfile(val_member)

    if extracted is None:
        raise RuntimeError(
            "Could not read places365_val.txt"
        )

    data = extracted.read()

    with open(
        LABEL_FILE,
        "wb"
    ) as f:
        f.write(data)

# ------------------------------------------------------------
# Read labels
# ------------------------------------------------------------

with open(
    LABEL_FILE,
    "r",
    encoding="utf-8"
) as f:

    lines = [
        line.strip()
        for line in f
        if line.strip()
    ]

