# ============================================================
# MODULE 4 — PLACES365 CLASS DISTRIBUTION VERIFICATION
# ============================================================

from collections import Counter

LABEL_FILE = "/content/places365_eval/places365_val.txt"

# ------------------------------------------------------------
# Read filename -> class ID mapping
# ------------------------------------------------------------

records = []

with open(
    LABEL_FILE,
    "r",
    encoding="utf-8"
) as f:

    for line in f:
        parts = line.strip().split()

        if len(parts) == 2:
            filename = parts[0]
            class_id = int(parts[1])

            records.append(
                (filename, class_id)
            )

# ------------------------------------------------------------
# Count images per class
# ------------------------------------------------------------

class_counts = Counter(
    class_id
    for _, class_id in records
)

print("=" * 60)
print("PLACES365 — CLASS DISTRIBUTION")
print("=" * 60)

print("Total labeled images:", len(records))
print("Unique class IDs:", len(class_counts))

print(
    "Minimum images/class:",
    min(class_counts.values())
)

print(
    "Maximum images/class:",
    max(class_counts.values())
)

# ------------------------------------------------------------
# Verify class IDs
# ------------------------------------------------------------

expected_classes = set(range(365))
actual_classes = set(class_counts.keys())

missing_classes = sorted(
    expected_classes - actual_classes
)

extra_classes = sorted(
    actual_classes - expected_classes
)

print("\nMissing class IDs:", missing_classes)
print("Unexpected class IDs:", extra_classes)

# ------------------------------------------------------------
# Distribution check
# ------------------------------------------------------------

wrong_counts = {
    class_id: count
    for class_id, count in class_counts.items()
    if count != 100
}

print(
    "\nClasses with count != 100:",
    len(wrong_counts)
)

if wrong_counts:
    print(wrong_counts)

# ------------------------------------------------------------
# Assertions
# ------------------------------------------------------------

assert len(records) == 36500
assert len(class_counts) == 365
assert min(class_counts.values()) == 100
assert max(class_counts.values()) == 100
assert not missing_classes
assert not extra_classes
assert not wrong_counts

print("\n" + "=" * 60)
print("PLACES365 DISTRIBUTION: VERIFIED")
print("=" * 60)

print(
    "365 classes × 100 images =",
    sum(class_counts.values())
)

