# CREATE FIXED 100-IMAGE VALIDATION SUBSET
# ============================================================

import os
import random
import shutil
import tarfile
import csv

BASE_DIR = "/content/places365_eval"

ARCHIVE = os.path.join(
    BASE_DIR,
    "val_256.tar"
)

LABEL_FILE = os.path.join(
    BASE_DIR,
    "places365_val.txt"
)

CLASS_FILE = os.path.join(
    BASE_DIR,
    "categories_places365.txt"
)

SUBSET_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100"
)

IMAGE_DIR = os.path.join(
    SUBSET_DIR,
    "images"
)

CSV_FILE = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.csv"
)

SEED = 42
N_IMAGES = 100

os.makedirs(IMAGE_DIR, exist_ok=True)

print("=" * 60)
print("PLACES365 — EXP-001 SUBSET CREATION")
print("=" * 60)

# ------------------------------------------------------------
# Load class names
# ------------------------------------------------------------

class_names = []

with open(
    CLASS_FILE,
    "r",
    encoding="utf-8"
) as f:

    for line in f:
        parts = line.strip().split()

        if len(parts) >= 2:
            # Format:
            # /a/airfield 0
            class_path = parts[0]
            class_id = int(parts[-1])

            class_name = class_path.lstrip("/")

            class_names.append(
                class_name
            )

assert len(class_names) == 365

# ------------------------------------------------------------
# Load validation labels
# ------------------------------------------------------------

records = []

with open(
    LABEL_FILE,
    "r",
    encoding="utf-8"
) as f:

    for line in f:

        parts = line.strip().split()

        if len(parts) == 2:

            filename = parts[0]
            class_id = int(parts[1])

            records.append(
                (filename, class_id)
            )

assert len(records) == 36500

# ------------------------------------------------------------
# Fixed random subset
# ------------------------------------------------------------

random.seed(SEED)

selected = random.sample(
    records,
    N_IMAGES
)

# Sort by filename for reproducibility
selected = sorted(
    selected,
    key=lambda x: x[0]
)

print("Random seed:", SEED)
print("Requested images:", N_IMAGES)
print("Selected images:", len(selected))

# ------------------------------------------------------------
# Extract only selected images
# ------------------------------------------------------------

selected_names = {
    filename
    for filename, _ in selected
}

extracted_count = 0

print("\nExtracting selected images...")

with tarfile.open(
    ARCHIVE,
    "r"
) as tar:

    for member in tar:

        if not member.isfile():
            continue

        basename = os.path.basename(
            member.name
        )

        if basename in selected_names:

            source = tar.extractfile(member)

            if source is None:
                continue

            destination = os.path.join(
                IMAGE_DIR,
                basename
            )

            with open(
                destination,
                "wb"
            ) as out:

                shutil.copyfileobj(
                    source,
                    out
                )

            extracted_count += 1

print(
    "Images extracted:",
    extracted_count
)

assert extracted_count == N_IMAGES

# ------------------------------------------------------------
# Create ground-truth CSV
# ------------------------------------------------------------

with open(
    CSV_FILE,
    "w",
    newline="",
    encoding="utf-8"
) as f:

    writer = csv.writer(f)

    writer.writerow([
        "filename",
        "ground_truth_class_id",
        "ground_truth_class_name"
    ])

    for filename, class_id in selected:

        writer.writerow([
            filename,
            class_id,
            class_names[class_id]
        ])

# ------------------------------------------------------------
# Verify files
# ------------------------------------------------------------

actual_images = [
    f for f in os.listdir(IMAGE_DIR)
    if f.lower().endswith(".jpg")
]

print("\n" + "=" * 60)
print("SUBSET VERIFICATION")
print("=" * 60)

print("Image directory:", IMAGE_DIR)
print("CSV:", CSV_FILE)
print("Images on disk:", len(actual_images))
print(
    "CSV entries:",
    len(selected)
)

assert len(actual_images) == N_IMAGES

print("\nFirst 10 selected images:")

for filename, class_id in selected[:10]:

    print(
        filename,
        "->",
        class_id,
        "->",
        class_names[class_id]
    )

print("\n" + "=" * 60)
print("PLACES365 EXP-001 SUBSET: READY")
print("=" * 60)

# ============================================================
# MODULE 4 — PLACES365 EXP-001 IMAGE INTEGRITY CHECK
# ============================================================

import os
import csv
from PIL import Image
from collections import Counter

BASE_DIR = "/content/places365_eval/EXP_001_subset_100"

IMAGE_DIR = os.path.join(
    BASE_DIR,
    "images"
)

CSV_FILE = os.path.join(
    BASE_DIR,
    "EXP_001_ground_truth.csv"
)

print("=" * 60)
print("PLACES365 — EXP-001 IMAGE INTEGRITY CHECK")
print("=" * 60)

# ------------------------------------------------------------
# Load CSV
# ------------------------------------------------------------

records = []

with open(
    CSV_FILE,
    "r",
    encoding="utf-8"
) as f:

    reader = csv.DictReader(f)

    for row in reader:
        records.append(row)

print("CSV records:", len(records))

# ------------------------------------------------------------
# Verify every image
# ------------------------------------------------------------

valid_images = 0
corrupt_images = []
dimensions = Counter()
class_counts = Counter()

for row in records:

    filename = row["filename"]
    class_id = int(
        row["ground_truth_class_id"]
    )

    image_path = os.path.join(
        IMAGE_DIR,
        filename
    )

    # Check class ID
    if not 0 <= class_id < 365:
        print(
            "INVALID CLASS ID:",
            filename,
            class_id
        )
        continue

    class_counts[class_id] += 1

    # Check file
    if not os.path.exists(image_path):

        corrupt_images.append(
            (filename, "FILE_MISSING")
        )
        continue

    try:

        with Image.open(image_path) as img:

            # Verify image contents
            img.verify()

        # Re-open after verify
        with Image.open(image_path) as img:

            width, height = img.size

            dimensions[
                (width, height)
            ] += 1

        valid_images += 1

    except Exception as e:

        corrupt_images.append(
            (filename, str(e))
        )

# ------------------------------------------------------------
# Results
# ------------------------------------------------------------

print("\nValid images:", valid_images)
print("Corrupt/missing:", len(corrupt_images))

print("\nUnique image dimensions:")

for dim, count in dimensions.most_common():
    print(
        f"{dim[0]} × {dim[1]} : {count} images"
    )

print("\nUnique ground-truth classes:", len(class_counts))

print(
    "Minimum images/class in subset:",
    min(class_counts.values())
)

print(
    "Maximum images/class in subset:",
    max(class_counts.values())
)

if corrupt_images:
    print("\nProblem files:")
    for item in corrupt_images[:20]:
        print(item)

# ------------------------------------------------------------
# Assertions
# ------------------------------------------------------------

assert len(records) == 100
assert valid_images == 100
assert len(corrupt_images) == 0

for class_id in class_counts:
    assert 0 <= class_id < 365

print("\n" + "=" * 60)
print("PLACES365 EXP-001 IMAGE INTEGRITY: PASSED")
print("=" * 60)

# ============================================================
# MODULE 4 — PLACES365 5-IMAGE INFERENCE SANITY TEST
# ============================================================

import os
import csv
import torch
from PIL import Image
from torchvision import transforms

BASE_DIR = "/content/places365_eval"

IMAGE_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100",
    "images"
)

CSV_FILE = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100",
    "EXP_001_ground_truth.csv"
)

CLASS_FILE = os.path.join(
    BASE_DIR,
    "categories_places365.txt"
)

MODEL_FILE = os.path.join(
    BASE_DIR,
    "resnet50_places365.pth"
)

device = torch.device(
    "cuda" if torch.cuda.is_available()
    else "cpu"
)

# ------------------------------------------------------------
# Load class names
# ------------------------------------------------------------

class_names = []

with open(
    CLASS_FILE,
    "r",
    encoding="utf-8"
) as f:

    for line in f:

        parts = line.strip().split()

        if len(parts) >= 2:

            class_path = parts[0]
            class_id = int(parts[-1])

            class_names.append(
                class_path.lstrip("/")
            )

assert len(class_names) == 365

# ------------------------------------------------------------
# Load ground truth
# ------------------------------------------------------------

records = []

with open(
    CSV_FILE,
    "r",
    encoding="utf-8"
) as f:

    reader = csv.DictReader(f)

    for row in reader:
        records.append(row)

# ------------------------------------------------------------
# Places365 preprocessing
# ------------------------------------------------------------

transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[
            0.485,
            0.456,
            0.406
        ],
        std=[
            0.229,
            0.224,
            0.225
        ]
    )
])

# ------------------------------------------------------------
# Run 5 images
# ------------------------------------------------------------

model.eval()

print("=" * 60)
print("PLACES365 — 5-IMAGE SANITY TEST")
print("=" * 60)

with torch.no_grad():

    for row in records[:5]:

        filename = row["filename"]

        gt_id = int(
            row["ground_truth_class_id"]
        )

        image_path = os.path.join(
            IMAGE_DIR,
            filename
        )

        image = Image.open(
            image_path
        ).convert("RGB")

        tensor = transform(
            image
        ).unsqueeze(0).to(device)

        output = model(tensor)

        probabilities = torch.softmax(
            output,
            dim=1
        )

        top5_prob, top5_idx = torch.topk(
            probabilities,
            k=5,
            dim=1
        )

        top5_prob = top5_prob[0].cpu().tolist()
        top5_idx = top5_idx[0].cpu().tolist()

        print("\nImage:", filename)
        print(
            "Ground truth:",
            gt_id,
            "->",
            class_names[gt_id]
        )

        print("Top-5 predictions:")

        for rank, (
            pred_id,
            prob
        ) in enumerate(
            zip(top5_idx, top5_prob),
            start=1
        ):

            print(
                f"  {rank}. "
                f"{pred_id:3d} -> "
                f"{class_names[pred_id]:35s} "
                f"{prob * 100:.2f}%"
            )

        print(
            "Output shape:",
            tuple(output.shape)
        )

print("\n" + "=" * 60)
print("PLACES365 SANITY TEST COMPLETED")
print("=" * 60)

