import os
import glob

print("=" * 60)
print("VIZWIZ-CAPTIONS — SETUP CHECK")
print("=" * 60)

# Search common locations
search_roots = [
    "/content",
    "/content/vizwiz_eval",
    "/content/datasets"
]

patterns = [
    "*vizwiz*",
    "*VizWiz*",
    "*caption*",
    "*Caption*"
]

found = []

for root in search_roots:

    if not os.path.exists(root):
        continue

    for pattern in patterns:

        matches = glob.glob(
            os.path.join(
                root,
                "**",
                pattern
            ),
            recursive=True
        )

        for path in matches:

            if path not in found:
                found.append(path)

print("\nPotential existing VizWiz/caption files:")
print("-" * 60)

if found:

    for path in found[:100]:
        print(path)

else:

    print("No existing VizWiz/caption files found.")

print("\nCreating working directory...")

BASE_DIR = "/content/vizwiz_eval"

os.makedirs(
    BASE_DIR,
    exist_ok=True
)

print(
    "Working directory:",
    BASE_DIR
)

print("\n" + "=" * 60)
print("SETUP CHECK COMPLETE")
print("=" * 60)

