# MODULE 5 — FIND VIZWIZ DOWNLOAD LINKS
# ============================================================

from bs4 import BeautifulSoup
import os

BASE_DIR = "/content/vizwiz_eval"

HTML_FILE = os.path.join(
    BASE_DIR,
    "vizwiz_dataset_page.html"
)

print("=" * 60)
print("VIZWIZ-CAPTIONS — DOWNLOAD LINK EXTRACTION")
print("=" * 60)

with open(
    HTML_FILE,
    "r",
    encoding="utf-8"
) as f:
    html = f.read()

soup = BeautifulSoup(
    html,
    "html.parser"
)

links = []

for a in soup.find_all("a", href=True):

    text = a.get_text(
        " ",
        strip=True
    )

    href = a["href"]

    combined = (
        text + " " + href
    ).lower()

    if any(
        keyword in combined
        for keyword in [
            "caption",
            "vizwiz",
            ".zip",
            ".json"
        ]
    ):

        links.append(
            (text, href)
        )

# Remove duplicates
unique_links = []

for item in links:

    if item not in unique_links:
        unique_links.append(item)

print(
    f"\nRelevant links found: "
    f"{len(unique_links)}\n"
)

for i, (text, href) in enumerate(
    unique_links,
    start=1
):

    print(
        f"[{i}] Text: {text}"
    )

    print(
        f"    URL : {href}"
    )

print("\n" + "=" * 60)
print("LINK EXTRACTION COMPLETE")
print("=" * 60)

