import os
import requests
import zipfile

BASE_DIR = "/content/vizwiz_eval"

URL = (
    "https://vizwiz.cs.colorado.edu/"
    "VizWiz_final/caption/annotations.zip"
)

ZIP_FILE = os.path.join(
    BASE_DIR,
    "caption_annotations.zip"
)

print("=" * 60)
print("VIZWIZ-CAPTIONS — ANNOTATION DOWNLOAD")
print("=" * 60)

print("\nDownloading:")
print(URL)

response = requests.get(
    URL,
    stream=True,
    timeout=60
)

print(
    "HTTP status:",
    response.status_code
)

response.raise_for_status()

total_size = int(
    response.headers.get(
        "content-length",
        0
    )
)

downloaded = 0

with open(
    ZIP_FILE,
    "wb"
) as f:

    for chunk in response.iter_content(
        chunk_size=1024 * 1024
    ):

        if chunk:

            f.write(chunk)

            downloaded += len(chunk)

            if total_size:

                percent = (
                    downloaded
                    / total_size
                    * 100
                )

                print(
                    f"\rDownloaded: "
                    f"{downloaded / (1024**2):.1f} MB "
                    f"/ "
                    f"{total_size / (1024**2):.1f} MB "
                    f"({percent:.1f}%)",
                    end=""
                )

print("\n")

print(
    "Saved:",
    ZIP_FILE
)

print(
    "Size:",
    os.path.getsize(ZIP_FILE)
    / (1024**2),
    "MB"
)

# ------------------------------------------------------------
# Inspect archive
# ------------------------------------------------------------

print("\nInspecting archive...")

with zipfile.ZipFile(
    ZIP_FILE,
    "r"
) as z:

    members = z.namelist()

print(
    "Total archive entries:",
    len(members)
)

print("\nArchive contents:")

for member in members:

    print(
        f"  {member}"
    )

print("\n" + "=" * 60)
print("ANNOTATION ARCHIVE INSPECTION COMPLETE")
print("=" * 60)

