if isinstance(data, dict):

    # Find likely record-containing key
    for key, value in data.items():

        if isinstance(value, list) and len(value) > 0:

            print(
                "\nRecord container:",
                key
            )

            first_record = value[0]

            print(
                "\nRecord type:",
                type(first_record).__name__
            )

            if isinstance(first_record, dict):

                print(
                    "\nRecord keys:"
                )

                for k in first_record.keys():

                    print(
                        f"  {k}"
                    )

                print(
                    "\nFirst record:"
                )

                print(
                    json.dumps(
                        first_record,
                        indent=2,
                        ensure_ascii=False
                    )
                )

            break

elif isinstance(data, list) and len(data) > 0:

    first_record = data[0]

    print(
        json.dumps(
            first_record,
            indent=2,
            ensure_ascii=False
        )
    )

print("\n" + "=" * 60)
print("VALIDATION ANNOTATION INSPECTION COMPLETE")
print("=" * 60)

# ============================================================
# MODULE 5 — VERIFY VIZWIZ CAPTION STRUCTURE
# ============================================================

import os
import json
from collections import Counter

BASE_DIR = "/content/vizwiz_eval"

VAL_FILE = os.path.join(
    BASE_DIR,
    "annotations",
    "val.json"
)

print("=" * 60)
print("VIZWIZ-CAPTIONS — CAPTION STRUCTURE VERIFICATION")
print("=" * 60)

with open(
    VAL_FILE,
    "r",
    encoding="utf-8"
) as f:

    data = json.load(f)

images = data["images"]
annotations = data["annotations"]

print(
    "\nImages:",
    len(images)
)

print(
    "Annotations:",
    len(annotations)
)

# ------------------------------------------------------------
# Inspect annotation structure
# ------------------------------------------------------------

print("\nFirst 3 annotation records:")
print("-" * 60)

for ann in annotations[:3]:

    print(
        json.dumps(
            ann,
            indent=2,
            ensure_ascii=False
        )
    )

    print("-" * 60)

# ------------------------------------------------------------
# Count annotations per image
# ------------------------------------------------------------

annotation_counts = Counter()

for ann in annotations:

    annotation_counts[
        ann["image_id"]
    ] += 1

count_distribution = Counter(
    annotation_counts.values()
)

print(
    "\nCaptions per image distribution:"
)

for count, number_images in sorted(
    count_distribution.items()
):

    print(
        f"  {count} captions: "
        f"{number_images} images"
    )

# ------------------------------------------------------------
# Verify all images have references
# ------------------------------------------------------------

image_ids = {
    image["id"]
    for image in images
}

annotation_image_ids = set(
    annotation_counts.keys()
)

missing_caption_images = (
    image_ids
    - annotation_image_ids
)

extra_annotation_images = (
    annotation_image_ids
    - image_ids
)

print(
    "\nImages without captions:",
    len(missing_caption_images)
)

print(
    "Annotations referencing unknown images:",
    len(extra_annotation_images)
)

# ------------------------------------------------------------
# Show all captions for one image
# ------------------------------------------------------------

if images:

    sample_image = images[0]

    sample_id = sample_image["id"]

    sample_filename = (
        sample_image["file_name"]
    )

    print("\n" + "-" * 60)
    print("SAMPLE IMAGE")
    print("-" * 60)

    print(
        "Image ID:",
        sample_id
    )

    print(
        "Filename:",
        sample_filename
    )

    print(
        "Text detected:",
        sample_image.get(
            "text_detected"
        )
    )

    sample_annotations = [
        ann
        for ann in annotations
        if ann["image_id"] == sample_id
    ]

    print(
        "\nReference captions:",
        len(sample_annotations)
    )

    for i, ann in enumerate(
        sample_annotations,
        start=1
    ):

        print(
            f"{i}. {ann.get('caption', ann)}"
        )

print("\n" + "=" * 60)
print("CAPTION STRUCTURE VERIFICATION COMPLETE")
print("=" * 60)

# ============================================================
# MODULE 5 — SELECT FIXED VIZWIZ VALIDATION SUBSET
# ============================================================

import os
import json
import random
import csv

BASE_DIR = "/content/vizwiz_eval"

VAL_FILE = os.path.join(
    BASE_DIR,
    "annotations",
    "val.json"
)

SUBSET_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100"
)

os.makedirs(
    SUBSET_DIR,
    exist_ok=True
)

GROUND_TRUTH_FILE = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.json"
)

GROUND_TRUTH_CSV = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.csv"
)

print("=" * 60)
print("VIZWIZ-CAPTIONS — SELECT 100-IMAGE SUBSET")
print("=" * 60)

# ------------------------------------------------------------
# Load annotations
# ------------------------------------------------------------

with open(
    VAL_FILE,
    "r",
    encoding="utf-8"
) as f:

    data = json.load(f)

images = data["images"]
annotations = data["annotations"]

print(
    "\nTotal validation images:",
    len(images)
)

# ------------------------------------------------------------
# Build caption lookup
# ------------------------------------------------------------

captions_by_image = {}

for ann in annotations:

    image_id = ann["image_id"]

    captions_by_image.setdefault(
        image_id,
        []
    ).append(
        ann["caption"]
    )

# ------------------------------------------------------------
# Fixed random subset
# ------------------------------------------------------------

random.seed(42)

selected_images = random.sample(
    images,
    100
)

# Sort by filename for reproducibility
selected_images = sorted(
    selected_images,
    key=lambda x: x["file_name"]
)

# ------------------------------------------------------------
# Build ground-truth records
# ------------------------------------------------------------

records = []

for image in selected_images:

    image_id = image["id"]

    captions = captions_by_image[
        image_id
    ]

    assert len(captions) == 5

    records.append({
        "image_id": image_id,
        "file_name": image["file_name"],
        "vizwiz_url": image.get(
            "vizwiz_url",
            ""
        ),
        "text_detected": image.get(
            "text_detected",
            None
        ),
        "reference_captions": captions
    })

# ------------------------------------------------------------
# Verify
# ------------------------------------------------------------

assert len(records) == 100

assert all(
    len(r["reference_captions"]) == 5
    for r in records
)

# ------------------------------------------------------------
# Save JSON
# ------------------------------------------------------------

with open(
    GROUND_TRUTH_FILE,
    "w",
    encoding="utf-8"
) as f:

    json.dump(
        records,
        f,
        indent=2,
        ensure_ascii=False
    )

# ------------------------------------------------------------
# Save CSV
# ------------------------------------------------------------

with open(
    GROUND_TRUTH_CSV,
    "w",
    newline="",
    encoding="utf-8"
) as f:

    writer = csv.writer(f)

    writer.writerow([
        "image_id",
        "file_name",
        "text_detected",
        "caption_1",
        "caption_2",
        "caption_3",
        "caption_4",
        "caption_5"
    ])

    for record in records:

        writer.writerow([
            record["image_id"],
            record["file_name"],
            record["text_detected"],
            *record["reference_captions"]
        ])

# ------------------------------------------------------------
# Display sample
# ------------------------------------------------------------

print(
    "\nSelected images:",
    len(records)
)

print(
    "\nFirst 10 selected images:"
)

for record in records[:10]:

    print(
        f"{record['file_name']} "
        f"-> ID {record['image_id']}"
    )

print("\nExample reference captions:")

example = records[0]

print(
    "\nImage:",
    example["file_name"]
)

for i, caption in enumerate(
    example["reference_captions"],
    start=1
):

    print(
        f"{i}. {caption}"
    )

print("\nSaved files:")

print(
    "JSON:",
    GROUND_TRUTH_FILE
)

print(
    "CSV :",
    GROUND_TRUTH_CSV
)

print("\n" + "=" * 60)
print("100-IMAGE SUBSET SELECTION COMPLETE")
print("=" * 60)

# ============================================================
# MODULE 5 — DOWNLOAD 100 VIZWIZ VALIDATION IMAGES
# ============================================================

import os
import json
import requests
import time

BASE_DIR = "/content/vizwiz_eval"

SUBSET_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100"
)

IMAGE_DIR = os.path.join(
    SUBSET_DIR,
    "images"
)

GROUND_TRUTH_FILE = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.json"
)

os.makedirs(
    IMAGE_DIR,
    exist_ok=True
)

print("=" * 60)
print("VIZWIZ-CAPTIONS — DOWNLOAD 100 IMAGES")
print("=" * 60)

# ------------------------------------------------------------
# Load selected records
# ------------------------------------------------------------

with open(
    GROUND_TRUTH_FILE,
    "r",
    encoding="utf-8"
) as f:

    records = json.load(f)

print(
    "\nImages to download:",
    len(records)
)

# ------------------------------------------------------------
# Download
# ------------------------------------------------------------

downloaded = 0
skipped = 0
failed = []

session = requests.Session()

for index, record in enumerate(
    records,
    start=1
):

    filename = record["file_name"]

    output_path = os.path.join(
        IMAGE_DIR,
        filename
    )

    # Already downloaded
    if (
        os.path.exists(output_path)
        and os.path.getsize(output_path) > 0
    ):

        skipped += 1

        print(
            f"[{index}/100] "
            f"Already exists: "
            f"{filename}"
        )

        continue

    url = record["vizwiz_url"]

    try:

        response = session.get(
            url,
            timeout=60
        )

        response.raise_for_status()

        with open(
            output_path,
            "wb"
        ) as f:

            f.write(
                response.content
            )

        # Basic file check
        if (
            os.path.getsize(output_path)
            == 0
        ):

            raise ValueError(
                "Downloaded file is empty"
            )

        downloaded += 1

        print(
            f"[{index}/100] "
            f"Downloaded: "
            f"{filename}"
        )

    except Exception as e:

        failed.append({
            "filename": filename,
            "url": url,
            "error": repr(e)
        })

        print(
            f"[{index}/100] FAILED: "
            f"{filename} -> {e}"
        )

    # Small delay to avoid aggressive requests
    time.sleep(0.05)

# ------------------------------------------------------------
# Final verification
# ------------------------------------------------------------

existing_files = []

for record in records:

    path = os.path.join(
        IMAGE_DIR,
        record["file_name"]
    )

    if (
        os.path.exists(path)
        and os.path.getsize(path) > 0
    ):

        existing_files.append(
            record["file_name"]
        )

print("\n" + "=" * 60)
print("DOWNLOAD SUMMARY")
print("=" * 60)

print(
    "Expected images :",
    len(records)
)

print(
    "Downloaded       :",
    downloaded
)

print(
    "Already existed  :",
    skipped
)

print(
    "Failed downloads :",
    len(failed)
)

print(
    "Valid files      :",
    len(existing_files)
)

if failed:

    print("\nFailed files:")

    for item in failed:

        print(
            f"  {item['filename']}"
        )

else:

    print(
        "\nAll 100 images downloaded successfully."
    )

print(
    "\nImage directory:",
    IMAGE_DIR
)

print("\n" + "=" * 60)
print("IMAGE DOWNLOAD COMPLETE")
print("=" * 60)

