import os
import json
import io
from datasets import load_dataset
from PIL import Image

BASE_DIR = "/content/vizwiz_eval"

SUBSET_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100"
)

IMAGE_DIR = os.path.join(
    SUBSET_DIR,
    "images"
)

GROUND_TRUTH_FILE = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.json"
)

os.makedirs(IMAGE_DIR, exist_ok=True)

print("=" * 60)
print("VIZWIZ-CAPTIONS — SAVE 100 IMAGES")
print("=" * 60)

# ------------------------------------------------------------
# Load our previously selected 100 records
# ------------------------------------------------------------

with open(
    GROUND_TRUTH_FILE,
    "r",
    encoding="utf-8"
) as f:
    records = json.load(f)

print("\nTarget images:", len(records))

# Map selected IDs to filenames
target_ids = {
    str(record["id"]): record["file_name"]
    for record in records
}

print("Target IDs:", len(target_ids))

# ------------------------------------------------------------
# Load Hugging Face dataset
# ------------------------------------------------------------

print("\nLoading Hugging Face dataset...")

ds = load_dataset(
    "mm-eval/VizWiz-Captions",
    split="val",
    streaming=True
)

print("Dataset loaded.")

# ------------------------------------------------------------
# Find and save exact images
# ------------------------------------------------------------

found_ids = set()
saved = 0

print("\nSearching validation dataset...")

for item in ds:

    image_id = str(item["id"])

    if image_id not in target_ids:
        continue

    filename = target_ids[image_id]

    output_path = os.path.join(
        IMAGE_DIR,
        filename
    )

    # Image is stored inside media[0]
    image = item["media"][0]

    if not isinstance(image, Image.Image):
        image = Image.fromarray(image)

    # Save as JPEG
    image = image.convert("RGB")

    image.save(
        output_path,
        format="JPEG",
        quality=95
    )

    found_ids.add(image_id)
    saved += 1

    print(
        f"[{saved}/{len(target_ids)}] "
        f"Saved {filename} "
        f"(ID {image_id}) "
        f"{image.size}"
    )

    # Stop once all 100 are found
    if len(found_ids) == len(target_ids):
        break

# ------------------------------------------------------------
# Verification
# ------------------------------------------------------------

missing_ids = set(target_ids.keys()) - found_ids

valid_files = []

for record in records:

    path = os.path.join(
        IMAGE_DIR,
        record["file_name"]
    )

    if (
        os.path.exists(path)
        and os.path.getsize(path) > 0
    ):
        valid_files.append(
            record["file_name"]
        )

print("\n" + "=" * 60)
print("SAVE SUMMARY")
print("=" * 60)

print("Expected images :", len(records))
print("Found in HF     :", len(found_ids))
print("Missing IDs     :", len(missing_ids))
print("Valid files     :", len(valid_files))

if missing_ids:

    print("\nMissing IDs:")
    for image_id in sorted(missing_ids):
        print(
            image_id,
            "->",
            target_ids[image_id]
        )

else:
    print("\n✅ ALL 100 IMAGES SAVED SUCCESSFULLY.")

print("\nImage directory:")
print(IMAGE_DIR)

print("\n" + "=" * 60)
print("VIZWIZ IMAGE EXTRACTION COMPLETE")
print("=" * 60)

