# ============================================================
# MODULE 5 — VIZWIZ IMAGE INTEGRITY CHECK
# ============================================================

import os
import json
from PIL import Image

BASE_DIR = "/content/vizwiz_eval"
SUBSET_DIR = os.path.join(BASE_DIR, "EXP_001_subset_100")
IMAGE_DIR = os.path.join(SUBSET_DIR, "images")
GROUND_TRUTH_FILE = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.json"
)

with open(GROUND_TRUTH_FILE, "r", encoding="utf-8") as f:
    records = json.load(f)

print("=" * 60)
print("VIZWIZ-CAPTIONS — IMAGE INTEGRITY CHECK")
print("=" * 60)

valid = []
corrupt = []
missing = []
dimensions = []

for record in records:

    filename = record["file_name"]
    path = os.path.join(IMAGE_DIR, filename)

    # --------------------------------------------------------
    # Check file existence
    # --------------------------------------------------------

    if not os.path.exists(path):
        missing.append(filename)
        continue

    try:

        # Verify image structure
        with Image.open(path) as img:

            img.verify()

        # Re-open after verify because verify() invalidates
        # the image object
        with Image.open(path) as img:

            width, height = img.size
            mode = img.mode

        valid.append(filename)

        dimensions.append({
            "file_name": filename,
            "width": width,
            "height": height,
            "mode": mode
        })

    except Exception as e:

        corrupt.append({
            "file_name": filename,
            "error": str(e)
        })

# ------------------------------------------------------------
# Dimension statistics
# ------------------------------------------------------------

widths = [x["width"] for x in dimensions]
heights = [x["height"] for x in dimensions]

print("\nExpected images :", len(records))
print("Valid images    :", len(valid))
print("Missing images  :", len(missing))
print("Corrupt images  :", len(corrupt))

if dimensions:

    print("\nDimension statistics:")
    print("Minimum width   :", min(widths))
    print("Maximum width   :", max(widths))
    print("Minimum height  :", min(heights))
    print("Maximum height  :", max(heights))

    unique_dimensions = sorted(
        set(
            (x["width"], x["height"])
            for x in dimensions
        )
    )

    print("Unique dimensions:", len(unique_dimensions))

    print("\nFirst 10 dimensions:")

    for item in dimensions[:10]:

        print(
            f"{item['file_name']} -> "
            f"{item['width']}x{item['height']} "
            f"{item['mode']}"
        )

# ------------------------------------------------------------
# Report problems
# ------------------------------------------------------------

if missing:

    print("\n❌ Missing files:")

    for filename in missing:
        print(filename)

if corrupt:

    print("\n❌ Corrupt files:")

    for item in corrupt:
        print(
            item["file_name"],
            "->",
            item["error"]
        )

# ------------------------------------------------------------
# Final status
# ------------------------------------------------------------

print("\n" + "=" * 60)

if len(valid) == 100 and not missing and not corrupt:

    print("✅ IMAGE INTEGRITY CHECK PASSED")
    print("✅ 100/100 images are readable.")

else:

    print("❌ IMAGE INTEGRITY CHECK FAILED")

print("=" * 60)

