# MODULE 5 — BLIP FULL 100-IMAGE CAPTION GENERATION

import os
import time
import json
import csv
import torch
from PIL import Image

BASE_DIR = "/content/vizwiz_eval"
SUBSET_DIR = os.path.join(BASE_DIR, "EXP_001_subset_100")
IMAGE_DIR = os.path.join(SUBSET_DIR, "images")
GT_JSON = os.path.join(SUBSET_DIR, "EXP_001_ground_truth.json")

RESULTS_DIR = os.path.join(BASE_DIR, "EXP_001_results")
os.makedirs(RESULTS_DIR, exist_ok=True)

PRED_JSON = os.path.join(RESULTS_DIR, "EXP_001_predictions.json")
PRED_CSV = os.path.join(RESULTS_DIR, "EXP_001_predictions.csv")

with open(GT_JSON, "r") as f:
    ground_truth = json.load(f)

print("="*70)
print("VIZWIZ-CAPTIONS — BLIP FULL 100-IMAGE GENERATION")
print("="*70)

print("\nImages to process:", len(ground_truth))
print("Model:", "Salesforce/blip-image-captioning-base")
print("Device:", device)
print("Generation parameters:")
print("  max_new_tokens =", 50)
print("  num_beams      =", 3)

predictions = []
latencies = []

for i, item in enumerate(ground_truth, 1):

    filename = item["file_name"]
    image_id = item["image_id"]
    image_path = os.path.join(IMAGE_DIR, filename)

    image = Image.open(image_path).convert("RGB")

    inputs = processor(images=image, return_tensors="pt")
    inputs = {k: v.to(device) for k, v in inputs.items()}

    if torch.cuda.is_available():
        torch.cuda.synchronize()

    start = time.perf_counter()

    with torch.no_grad():
        output_ids = model.generate(
            **inputs,
            max_new_tokens=50,
            num_beams=3
        )

    if torch.cuda.is_available():
        torch.cuda.synchronize()

    elapsed = time.perf_counter() - start
    latency_ms = elapsed * 1000

    caption = processor.decode(
        output_ids[0],
        skip_special_tokens=True
    ).strip()

    latencies.append(latency_ms)

    predictions.append({
        "file_name": filename,
        "image_id": image_id,
        "generated_caption": caption,
        "latency_ms": latency_ms
    })

    if i <= 5 or i % 10 == 0:
        print(
            f"[{i:3d}/100] "
            f"{filename} | "
            f"{latency_ms:.2f} ms | "
            f"{caption}"
        )

# Save JSON
with open(PRED_JSON, "w") as f:
    json.dump(predictions, f, indent=2)

# Save CSV
with open(PRED_CSV, "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(
        f,
        fieldnames=[
            "file_name",
            "image_id",
            "generated_caption",
            "latency_ms"
        ]
    )
    writer.writeheader()
    writer.writerows(predictions)

# Timing summary
import statistics

avg_latency = statistics.mean(latencies)
median_latency = statistics.median(latencies)
fps = 1000.0 / avg_latency

print("\n" + "="*70)
print("CAPTION GENERATION COMPLETE")
print("="*70)

print(f"\nImages processed : {len(predictions)}/100")
print(f"Average latency  : {avg_latency:.2f} ms/image")
print(f"Median latency   : {median_latency:.2f} ms/image")
print(f"Approx. FPS      : {fps:.2f}")

print("\nPrediction JSON:")
print(PRED_JSON)

print("\nPrediction CSV:")
print(PRED_CSV)

print("\n" + "="*70)
print("100/100 CAPTIONS GENERATED SUCCESSFULLY")
print("="*70)

# MODULE 5 — CAPTION / REFERENCE INTEGRITY CHECK

import os
import json
import statistics

BASE_DIR = "/content/vizwiz_eval"
SUBSET_DIR = os.path.join(BASE_DIR, "EXP_001_subset_100")
RESULTS_DIR = os.path.join(BASE_DIR, "EXP_001_results")

GT_JSON = os.path.join(SUBSET_DIR, "EXP_001_ground_truth.json")
PRED_JSON = os.path.join(RESULTS_DIR, "EXP_001_predictions.json")

with open(GT_JSON, "r") as f:
    ground_truth = json.load(f)

with open(PRED_JSON, "r") as f:
    predictions = json.load(f)

print("="*70)
print("VIZWIZ-CAPTIONS — CAPTION / REFERENCE INTEGRITY CHECK")
print("="*70)

# ------------------------------------------------------------
# Basic counts
# ------------------------------------------------------------

print("\nGround-truth images :", len(ground_truth))
print("Predictions          :", len(predictions))

assert len(ground_truth) == 100
assert len(predictions) == 100

# ------------------------------------------------------------
# Ground-truth structure
# ------------------------------------------------------------

gt_ids = []
gt_files = []
reference_counts = []

for item in ground_truth:
    gt_ids.append(item["image_id"])
    gt_files.append(item["file_name"])

    refs = item.get("captions", [])

    reference_counts.append(len(refs))

print("\nReference captions per image:")
print("Minimum:", min(reference_counts))
print("Maximum:", max(reference_counts))
print("Unique counts:", sorted(set(reference_counts)))

# ------------------------------------------------------------
# Prediction structure
# ------------------------------------------------------------

pred_ids = [item["image_id"] for item in predictions]
pred_files = [item["file_name"] for item in predictions]

# ------------------------------------------------------------
# ID alignment
# ------------------------------------------------------------

gt_id_set = set(gt_ids)
pred_id_set = set(pred_ids)

missing_predictions = gt_id_set - pred_id_set
extra_predictions = pred_id_set - gt_id_set

duplicate_prediction_ids = [
    image_id for image_id in pred_id_set
    if pred_ids.count(image_id) > 1
]

print("\nID alignment:")
print("Missing prediction IDs :", len(missing_predictions))
print("Extra prediction IDs   :", len(extra_predictions))
print("Duplicate prediction IDs:", len(duplicate_prediction_ids))

# ------------------------------------------------------------
# Filename alignment
# ------------------------------------------------------------

gt_file_set = set(gt_files)
pred_file_set = set(pred_files)

missing_prediction_files = gt_file_set - pred_file_set
extra_prediction_files = pred_file_set - gt_file_set

print("\nFilename alignment:")
print("Missing prediction files :", len(missing_prediction_files))
print("Extra prediction files   :", len(extra_prediction_files))

# ------------------------------------------------------------
# Empty captions
# ------------------------------------------------------------

empty_predictions = [
    item["file_name"]
    for item in predictions
    if not item["generated_caption"].strip()
]

print("\nEmpty generated captions:", len(empty_predictions))

# ------------------------------------------------------------
# Reference caption quality
# ------------------------------------------------------------

empty_reference_sets = []

for item in ground_truth:
    refs = item.get("captions", [])

    if any(not str(ref).strip() for ref in refs):
        empty_reference_sets.append(item["file_name"])

print("Images with empty references:", len(empty_reference_sets))

# ------------------------------------------------------------
# Final validation
# ------------------------------------------------------------

passed = (
    len(ground_truth) == 100
    and len(predictions) == 100
    and min(reference_counts) == 5
    and max(reference_counts) == 5
    and len(missing_predictions) == 0
    and len(extra_predictions) == 0
    and len(duplicate_prediction_ids) == 0
    and len(missing_prediction_files) == 0
    and len(extra_prediction_files) == 0
    and len(empty_predictions) == 0
    and len(empty_reference_sets) == 0
)

print("\n" + "="*70)

if passed:
    print("CAPTION / REFERENCE INTEGRITY CHECK PASSED")
    print("100 predictions aligned with 100 images.")
    print("Each image has exactly 5 reference captions.")
else:
    print("CAPTION / REFERENCE INTEGRITY CHECK FAILED")
    print("Review the diagnostics above.")

print("="*70)

