# MODULE 5 — VIZWIZ CAPTION METRICS

import os
import json
import math
import statistics
import sys

from pycocotools.coco import COCO
from pycocoevalcap.eval import COCOEvalCap
from rouge_score import rouge_scorer

BASE_DIR = "/content/vizwiz_eval"
RESULTS_DIR = os.path.join(BASE_DIR, "EXP_001_results")

COCO_GT_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_coco_references.json"
)

COCO_PRED_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_coco_predictions.json"
)

PRED_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_predictions.json"
)

# ------------------------------------------------------------
# Load COCO references and predictions
# ------------------------------------------------------------

print("="*70)
print("VIZWIZ-CAPTIONS — CAPTION METRIC EVALUATION")
print("="*70)

print("\nLoading reference annotations...")
coco = COCO(COCO_GT_JSON)

print("Loading predictions...")
coco_result = coco.loadRes(COCO_PRED_JSON)

image_ids = coco.getImgIds()

print("\nImages:", len(image_ids))

# ------------------------------------------------------------
# COCO-style metrics
# ------------------------------------------------------------

print("\nRunning BLEU-1 through BLEU-4...")
print("Running METEOR...")
print("Running CIDEr-D...")
print("Running SPICE...")

coco_eval = COCOEvalCap(coco, coco_result)

# Evaluate only our fixed 100-image subset
coco_eval.params["image_id"] = image_ids

coco_eval.evaluate()

# ------------------------------------------------------------
# Extract scores
# ------------------------------------------------------------

scores = coco_eval.eval

print("\n" + "="*70)
print("COCO-STYLE METRICS")
print("="*70)

for metric, score in scores.items():
    print(f"{metric:10s}: {score:.6f}")

# ------------------------------------------------------------
# ROUGE-L
# ------------------------------------------------------------

print("\n" + "="*70)
print("ROUGE-L")
print("="*70)

with open(PRED_JSON, "r", encoding="utf-8") as f:
    predictions = json.load(f)

# Map image ID -> references
reference_map = {}

for image in coco.dataset["images"]:
    image_id = image["id"]

    annotations = coco.imgToAnns[image_id]

    reference_map[image_id] = [
        ann["caption"]
        for ann in annotations
    ]

rouge = rouge_scorer.RougeScorer(
    ["rougeL"],
    use_stemmer=True
)

rouge_scores = []

for pred in predictions:

    image_id = pred["image_id"]
    generated = pred["generated_caption"]

    references = reference_map[image_id]

    # Compute ROUGE-L against each human reference
    # and retain the best reference for this image.
    image_scores = []

    for reference in references:
        result = rouge.score(reference, generated)
        image_scores.append(result["rougeL"].fmeasure)

    rouge_scores.append(max(image_scores))

rouge_l = statistics.mean(rouge_scores)

print(f"ROUGE-L     : {rouge_l:.6f}")

# ------------------------------------------------------------
# Save complete metric results
# ------------------------------------------------------------

metric_results = {
    "dataset": "VizWiz-Captions",
    "experiment": "EXP_001",
    "num_images": 100,
    "references_per_image": 5,
    "total_references": 500,
    "model": "Salesforce/blip-image-captioning-base",
    "generation": {
        "max_new_tokens": 50,
        "num_beams": 3
    },
    "metrics": {
        "BLEU-1": float(scores.get("Bleu_1", float("nan"))),
        "BLEU-2": float(scores.get("Bleu_2", float("nan"))),
        "BLEU-3": float(scores.get("Bleu_3", float("nan"))),
        "BLEU-4": float(scores.get("Bleu_4", float("nan"))),
        "METEOR": float(scores.get("METEOR", float("nan"))),
        "ROUGE-L": float(rouge_l),
        "CIDEr-D": float(scores.get("CIDEr", float("nan"))),
        "SPICE": float(scores.get("SPICE", float("nan")))
    }
}

METRICS_JSON = os.path.join(
    RESULTS_DIR,
    "EXP_001_caption_metrics.json"
)

with open(METRICS_JSON, "w", encoding="utf-8") as f:
    json.dump(metric_results, f, indent=2)

# ------------------------------------------------------------
# Final summary
# ------------------------------------------------------------

print("\n" + "="*70)
print("VIZWIZ-CAPTIONS — METRIC SUMMARY")
print("="*70)

for name, value in metric_results["metrics"].items():
    print(f"{name:10s}: {value:.6f}")

print("\nSaved:")
print(METRICS_JSON)

print("\n" + "="*70)
print("CAPTION METRIC EVALUATION COMPLETE")
print("="*70)

# MODULE 5 — BLEU / CIDEr-D / SPICE
# METEOR is intentionally skipped because the installed
# pycocoevalcap METEOR wrapper is incompatible with this environment.

import os
import json

from pycocotools.coco import COCO
from pycocoevalcap.eval import COCOEvalCap

BASE_DIR = "/content/vizwiz_eval"
RESULTS_DIR = os.path.join(BASE_DIR, "EXP_001_results")

COCO_GT_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_coco_references.json"
)

COCO_PRED_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_coco_predictions.json"
)

print("="*70)
print("VIZWIZ-CAPTIONS — BLEU / CIDEr-D / SPICE")
print("="*70)

# Load COCO data
coco = COCO(COCO_GT_JSON)
coco_result = coco.loadRes(COCO_PRED_JSON)

image_ids = coco.getImgIds()

# Import scorers directly so METEOR is not executed
from pycocoevalcap.bleu.bleu import Bleu
from pycocoevalcap.cider.cider import Cider
from pycocoevalcap.spice.spice import Spice

gts = {}
res = {}

for image_id in image_ids:
    gts[image_id] = [
        ann["caption"]
        for ann in coco.imgToAnns[image_id]
    ]

    result = coco_result.imgToAnns[image_id][0]

    res[image_id] = [
        result["caption"]
    ]

print("\nImages:", len(image_ids))

# ------------------------------------------------------------
# BLEU
# ------------------------------------------------------------

print("\nComputing BLEU-1 through BLEU-4...")

bleu_scorer = Bleu(4)
bleu_score, bleu_scores = bleu_scorer.compute_score(gts, res)

print("\nBLEU results:")
for i, score in enumerate(bleu_score, 1):
    print(f"BLEU-{i}: {score:.6f}")

# ------------------------------------------------------------
# CIDEr-D
# ------------------------------------------------------------

print("\nComputing CIDEr-D...")

cider_scorer = Cider()
cider_score, cider_scores = cider_scorer.compute_score(gts, res)

print(f"CIDEr-D: {cider_score:.6f}")

# ------------------------------------------------------------
# SPICE
# ------------------------------------------------------------

print("\nComputing SPICE...")
print("SPICE may take some time because it uses Java/Stanford CoreNLP.")

spice_scorer = Spice()
spice_score, spice_scores = spice_scorer.compute_score(gts, res)

print(f"SPICE: {spice_score:.6f}")

# ------------------------------------------------------------
# Save partial results
# ------------------------------------------------------------

partial_results = {
    "dataset": "VizWiz-Captions",
    "experiment": "EXP_001",
    "num_images": 100,
    "references_per_image": 5,
    "total_references": 500,
    "model": "Salesforce/blip-image-captioning-base",
    "generation": {
        "max_new_tokens": 50,
        "num_beams": 3
    },
    "metrics": {
        "BLEU-1": float(bleu_score[0]),
        "BLEU-2": float(bleu_score[1]),
        "BLEU-3": float(bleu_score[2]),
        "BLEU-4": float(bleu_score[3]),
        "CIDEr-D": float(cider_score),
        "SPICE": float(spice_score)
    },
    "meteor_status": "not evaluated due to pycocoevalcap METEOR compatibility error"
}

PARTIAL_JSON = os.path.join(
    RESULTS_DIR,
    "EXP_001_metrics_partial.json"
)

with open(PARTIAL_JSON, "w") as f:
    json.dump(partial_results, f, indent=2)

print("\n" + "="*70)
print("BLEU / CIDEr-D / SPICE COMPLETE")
print("="*70)

print("\nSaved:")
print(PARTIAL_JSON)

# MODULE 5 — METEOR + ROUGE-L
# Uses NLTK METEOR instead of the incompatible pycocoevalcap
# METEOR Java wrapper.

import os
import json
import statistics
import nltk

from nltk.translate.meteor_score import meteor_score
from rouge_score import rouge_scorer

BASE_DIR = "/content/vizwiz_eval"
SUBSET_DIR = os.path.join(BASE_DIR, "EXP_001_subset_100")
RESULTS_DIR = os.path.join(BASE_DIR, "EXP_001_results")

GT_JSON = os.path.join(
    SUBSET_DIR, "EXP_001_ground_truth.json"
)

PRED_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_predictions.json"
)

with open(GT_JSON, "r", encoding="utf-8") as f:
    ground_truth = json.load(f)

with open(PRED_JSON, "r", encoding="utf-8") as f:
    predictions = json.load(f)

print("="*70)
print("VIZWIZ-CAPTIONS — METEOR + ROUGE-L")
print("="*70)

# ------------------------------------------------------------
# METEOR
# ------------------------------------------------------------

print("\nComputing METEOR using NLTK...")

meteor_values = []

for gt_item, pred_item in zip(ground_truth, predictions):

    # Verify alignment
    assert gt_item["image_id"] == pred_item["image_id"]

    references = gt_item["reference_captions"]
    prediction = pred_item["generated_caption"]

    # NLTK expects tokenized strings
    reference_tokens = [
        nltk.word_tokenize(ref.lower())
        for ref in references
    ]

    prediction_tokens = nltk.word_tokenize(
        prediction.lower()
    )

    # Compute against all 5 references and retain
    # the highest score for this image.
    scores = [
        meteor_score(
            [ref_tokens],
            prediction_tokens
        )
        for ref_tokens in reference_tokens
    ]

    meteor_values.append(max(scores))

meteor = statistics.mean(meteor_values)

print(f"METEOR: {meteor:.6f}")

# ------------------------------------------------------------
# ROUGE-L
# ------------------------------------------------------------

print("\nComputing ROUGE-L...")

rouge = rouge_scorer.RougeScorer(
    ["rougeL"],
    use_stemmer=True
)

rouge_values = []

for gt_item, pred_item in zip(ground_truth, predictions):

    assert gt_item["image_id"] == pred_item["image_id"]

    references = gt_item["reference_captions"]
    prediction = pred_item["generated_caption"]

    image_scores = []

    for reference in references:

        result = rouge.score(
            reference,
            prediction
        )

        image_scores.append(
            result["rougeL"].fmeasure
        )

    # Best-reference ROUGE-L
    rouge_values.append(max(image_scores))

rouge_l = statistics.mean(rouge_values)

print(f"ROUGE-L: {rouge_l:.6f}")

# ------------------------------------------------------------
# Save results
# ------------------------------------------------------------

remaining_metrics = {
    "METEOR": float(meteor),
    "ROUGE-L": float(rouge_l),
    "meteor_implementation": "nltk.translate.meteor_score",
    "meteor_aggregation": "maximum over 5 references per image",
    "rouge_implementation": "rouge-score",
    "rouge_aggregation": "maximum ROUGE-L F1 over 5 references per image"
}

METRICS_JSON = os.path.join(
    RESULTS_DIR,
    "EXP_001_meteor_rouge.json"
)

with open(METRICS_JSON, "w", encoding="utf-8") as f:
    json.dump(remaining_metrics, f, indent=2)

print("\nSaved:")
print(METRICS_JSON)

print("\n" + "="*70)
print("METEOR + ROUGE-L COMPLETE")
print("="*70)

