# MODULE 5 — OPTIMIZED METEOR + ROUGE-L

import os
import json
import statistics
import nltk

from nltk.translate.meteor_score import meteor_score
from rouge_score import rouge_scorer

BASE_DIR = "/content/vizwiz_eval"
SUBSET_DIR = os.path.join(BASE_DIR, "EXP_001_subset_100")
RESULTS_DIR = os.path.join(BASE_DIR, "EXP_001_results")

GT_JSON = os.path.join(
    SUBSET_DIR, "EXP_001_ground_truth.json"
)

PRED_JSON = os.path.join(
    RESULTS_DIR, "EXP_001_predictions.json"
)

with open(GT_JSON, "r", encoding="utf-8") as f:
    ground_truth = json.load(f)

with open(PRED_JSON, "r", encoding="utf-8") as f:
    predictions = json.load(f)

print("=" * 70)
print("VIZWIZ-CAPTIONS — OPTIMIZED METEOR + ROUGE-L")
print("=" * 70)

# ------------------------------------------------------------
# Pre-tokenize everything once
# ------------------------------------------------------------

print("\nTokenizing captions...")

tokenized_references = {}
tokenized_predictions = {}

for gt_item, pred_item in zip(ground_truth, predictions):

    image_id = gt_item["image_id"]

    tokenized_references[image_id] = [
        nltk.word_tokenize(ref.lower())
        for ref in gt_item["reference_captions"]
    ]

    tokenized_predictions[image_id] = nltk.word_tokenize(
        pred_item["generated_caption"].lower()
    )

print("Tokenization complete.")

# ------------------------------------------------------------
# METEOR
# ------------------------------------------------------------

print("\nComputing METEOR...")

meteor_values = []

for i, gt_item in enumerate(ground_truth):

    image_id = gt_item["image_id"]

    refs = tokenized_references[image_id]
    pred = tokenized_predictions[image_id]

    scores = [
        meteor_score([ref], pred)
        for ref in refs
    ]

    meteor_values.append(max(scores))

    if (i + 1) % 10 == 0:
        print(f"  METEOR: {i + 1}/100")

meteor = statistics.mean(meteor_values)

print(f"\nMETEOR: {meteor:.6f}")

# ------------------------------------------------------------
# ROUGE-L
# ------------------------------------------------------------

print("\nComputing ROUGE-L...")

rouge = rouge_scorer.RougeScorer(
    ["rougeL"],
    use_stemmer=True
)

rouge_values = []

for i, gt_item in enumerate(ground_truth):

    image_id = gt_item["image_id"]

    references = gt_item["reference_captions"]
    prediction = predictions[i]["generated_caption"]

    image_scores = []

    for reference in references:

        result = rouge.score(
            reference,
            prediction
        )

        image_scores.append(
            result["rougeL"].fmeasure
        )

    rouge_values.append(max(image_scores))

    if (i + 1) % 10 == 0:
        print(f"  ROUGE-L: {i + 1}/100")

rouge_l = statistics.mean(rouge_values)

print(f"\nROUGE-L: {rouge_l:.6f}")

# ------------------------------------------------------------
# Save
# ------------------------------------------------------------

remaining_metrics = {
    "METEOR": float(meteor),
    "ROUGE-L": float(rouge_l),

    "meteor_implementation":
        "nltk.translate.meteor_score",

    "meteor_aggregation":
        "maximum over 5 references per image",

    "rouge_implementation":
        "rouge-score",

    "rouge_aggregation":
        "maximum ROUGE-L F1 over 5 references per image"
}

METRICS_JSON = os.path.join(
    RESULTS_DIR,
    "EXP_001_meteor_rouge.json"
)

with open(METRICS_JSON, "w", encoding="utf-8") as f:
    json.dump(
        remaining_metrics,
        f,
        indent=2
    )

print("\nSaved:")
print(METRICS_JSON)

print("\n" + "=" * 70)
print("METEOR + ROUGE-L COMPLETE")
print("=" * 70)

