import os
import subprocess
import tempfile

SPICE_JAR = "/usr/local/lib/python3.13/dist-packages/pycocoevalcap/spice/spice-1.0.jar"

print("=" * 70)
print("SPICE JAVA RUNTIME TEST")
print("=" * 70)

# Minimal valid SPICE input
test_input = [
    {
        "image_id": 1,
        "test": "a cat sitting on a table",
        "refs": [
            "a cat is sitting on a table",
            "a cat sits on a table"
        ]
    }
]

with tempfile.TemporaryDirectory() as tmp:

    input_file = os.path.join(tmp, "input.json")
    output_file = os.path.join(tmp, "output.json")

    import json

    with open(input_file, "w", encoding="utf-8") as f:
        json.dump(test_input, f)

    cmd = [
        "java",
        "-Xmx8G",
        "-jar",
        SPICE_JAR,
        input_file,
        "-cache",
        tmp,
        "-out",
        output_file,
        "-subset",
        "-silent"
    ]

    print("\nRunning:")
    print(" ".join(cmd))

    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        timeout=120
    )

    print("\nReturn code:", result.returncode)

    print("\n--- STDOUT ---")
    print(result.stdout if result.stdout else "(empty)")

    print("\n--- STDERR ---")
    print(result.stderr if result.stderr else "(empty)")

    print("\nOutput file exists:", os.path.exists(output_file))

print("\n" + "=" * 70)
print("SPICE JAVA TEST COMPLETE")
print("=" * 70)

import os
import subprocess
import tempfile
import json

SPICE_JAR = "/usr/local/lib/python3.13/dist-packages/pycocoevalcap/spice/spice-1.0.jar"

print("=" * 70)
print("SPICE JAVA 21 COMPATIBILITY TEST")
print("=" * 70)

test_input = [
    {
        "image_id": 1,
        "test": "a cat sitting on a table",
        "refs": [
            "a cat is sitting on a table",
            "a cat sits on a table"
        ]
    }
]

with tempfile.TemporaryDirectory() as tmp:

    input_file = os.path.join(tmp, "input.json")
    output_file = os.path.join(tmp, "output.json")

    with open(input_file, "w", encoding="utf-8") as f:
        json.dump(test_input, f)

    cmd = [
        "java",
        "--add-opens=java.base/java.lang=ALL-UNNAMED",
        "-Xmx8G",
        "-jar",
        SPICE_JAR,
        input_file,
        "-cache",
        tmp,
        "-out",
        output_file,
        "-subset",
        "-silent"
    ]

    print("\nRunning Java 21 compatibility test...")

    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        timeout=120
    )

    print("\nReturn code:", result.returncode)

    print("\n--- STDOUT ---")
    print(result.stdout if result.stdout else "(empty)")

    print("\n--- STDERR ---")
    print(result.stderr if result.stderr else "(empty)")

    print("\nOutput file exists:", os.path.exists(output_file))

    if os.path.exists(output_file):
        print("\n--- SPICE OUTPUT ---")
        with open(output_file, "r", encoding="utf-8") as f:
            print(f.read())

print("\n" + "=" * 70)
print("COMPATIBILITY TEST COMPLETE")
print("=" * 70)

