# 100 samples, fixed seed = 42

import os
import json
import random
import io
import pandas as pd
from PIL import Image
from huggingface_hub import hf_hub_download

OUT_DIR = "/content/ocr_eval/icdar2015"
os.makedirs(OUT_DIR, exist_ok=True)

REPO_ID = "MiXaiLL76/ICDAR2015_OCR"
SEED = 42
TARGET_N = 100

print("=" * 70)
print("LOADING ICDAR 2015 TEST SPLIT")
print("=" * 70)

parquet_path = hf_hub_download(
    repo_id=REPO_ID,
    filename="data/test-00000-of-00001.parquet",
    repo_type="dataset"
)

df = pd.read_parquet(parquet_path)

print("Total test samples:", len(df))
print("Columns:", list(df.columns))

# Reproducible random selection
rng = random.Random(SEED)
selected_indices = rng.sample(range(len(df)), TARGET_N)

subset = df.iloc[selected_indices].reset_index(drop=True)

print("Selected samples:", len(subset))
print("Random seed:", SEED)

# Save images + ground truth
image_dir = os.path.join(OUT_DIR, "images")
os.makedirs(image_dir, exist_ok=True)

records = []

for i, row in subset.iterrows():
    image_data = row["image"]

    if isinstance(image_data, dict):
        image_bytes = image_data["bytes"]
    else:
        image_bytes = image_data

    image = Image.open(io.BytesIO(image_bytes)).convert("RGB")

    image_path = os.path.join(image_dir, f"icdar2015_{i:04d}.png")
    image.save(image_path)

    records.append({
        "sample_id": i,
        "image_path": image_path,
        "ground_truth": str(row["text"])
    })

ground_truth_df = pd.DataFrame(records)

csv_path = os.path.join(
    OUT_DIR,
    "EXP_001_ground_truth.csv"
)

json_path = os.path.join(
    OUT_DIR,
    "EXP_001_ground_truth.json"
)

ground_truth_df.to_csv(csv_path, index=False)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(records, f, ensure_ascii=False, indent=2)

