# MODULE 6 — ICDAR 2015 OCR EVALUATION
# EasyOCR on the fixed 100-image test subset

import os
import json
import time
import pandas as pd
import easyocr

GT_CSV = "/content/ocr_eval/icdar2015/EXP_001_ground_truth.csv"
RESULT_DIR = "/content/ocr_eval/icdar2015/EXP_001_results"
os.makedirs(RESULT_DIR, exist_ok=True)

df = pd.read_csv(GT_CSV)

print("=" * 70)
print("INITIALIZING EASYOCR")
print("=" * 70)

reader = easyocr.Reader(
    ["en"],
    gpu=True,
    verbose=True
)

print("EasyOCR initialized.")
print("GPU requested: True")

results = []

print("\n" + "=" * 70)
print("RUNNING OCR — 100 ICDAR 2015 TEST CROPS")
print("=" * 70)

for idx, row in df.iterrows():

    image_path = row["image_path"]
    ground_truth = str(row["ground_truth"])

    start = time.perf_counter()

    ocr_output = reader.readtext(
        image_path,
        detail=1,
        paragraph=False
    )

    elapsed_ms = (time.perf_counter() - start) * 1000

    # Keep all detected text regions
    detections = []

    for detection in ocr_output:
        box, text_value, confidence = detection

        detections.append({
            "text": str(text_value),
            "confidence": float(confidence),
            "box": [[int(point[0]), int(point[1])] for point in box]
        })

    # Combine detected regions into one prediction.
    # For word crops, normally there should be one main text region.
    prediction = " ".join(
        item["text"] for item in detections
    ).strip()

    results.append({
        "sample_id": int(row["sample_id"]),
        "image_path": image_path,
        "ground_truth": ground_truth,
        "prediction": prediction,
        "detections": detections,
        "latency_ms": elapsed_ms
    })

    if (idx + 1) % 10 == 0 or idx == 0:
        print(
            f"[{idx + 1:3d}/100] "
            f"GT={ground_truth!r} | "
            f"PRED={prediction!r} | "
            f"{elapsed_ms:.2f} ms"
        )

results_json = os.path.join(
    RESULT_DIR,
    "EXP_001_predictions.json"
)

results_csv = os.path.join(
    RESULT_DIR,
    "EXP_001_predictions.csv"
)

with open(results_json, "w", encoding="utf-8") as f:
    json.dump(results, f, ensure_ascii=False, indent=2)

# Flatten the main fields for CSV
csv_rows = []

for r in results:
    csv_rows.append({
        "sample_id": r["sample_id"],
        "image_path": r["image_path"],
        "ground_truth": r["ground_truth"],
        "prediction": r["prediction"],
        "latency_ms": r["latency_ms"],
        "num_detections": len(r["detections"]),
        "mean_confidence": (
            sum(x["confidence"] for x in r["detections"])
            / len(r["detections"])
            if r["detections"] else 0.0
        )
    })

pd.DataFrame(csv_rows).to_csv(
    results_csv,
    index=False
)

latencies = [r["latency_ms"] for r in results]

print("\n" + "=" * 70)
print("OCR RUN COMPLETE")
print("=" * 70)

print("Images processed:", len(results))
print(f"Average latency: {sum(latencies) / len(latencies):.2f} ms/image")
print(f"Median latency : {pd.Series(latencies).median():.2f} ms/image")
print(f"Approx FPS     : {1000 / (sum(latencies) / len(latencies)):.2f}")

print("\nSaved:")
print(" ", results_json)
print(" ", results_csv)

print("=" * 70)

# MODULE 6 — ICDAR 2015 OCR METRICS

import os
import json
import re
import pandas as pd

RESULTS_CSV = (
    "/content/ocr_eval/icdar2015/EXP_001_results/"
    "EXP_001_predictions.csv"
)

df = pd.read_csv(RESULTS_CSV)

print("=" * 70)
print("ICDAR 2015 OCR METRICS")
print("=" * 70)

# Levenshtein distance
def levenshtein_distance(a, b):
    a = str(a)
    b = str(b)

    prev = list(range(len(b) + 1))

    for i, ca in enumerate(a, start=1):
        curr = [i]

        for j, cb in enumerate(b, start=1):
            insertion = curr[j - 1] + 1
            deletion = prev[j] + 1
            substitution = prev[j - 1] + (ca != cb)

            curr.append(
                min(insertion, deletion, substitution)
            )

        prev = curr

    return prev[-1]


exact_matches = 0
case_insensitive_matches = 0

total_edit_distance = 0
total_gt_characters = 0

normalized_similarities = []

for _, row in df.iterrows():

    gt = str(row["ground_truth"])
    pred = str(row["prediction"])

    # Exact match
    if pred == gt:
        exact_matches += 1

    # Case-insensitive exact match
    if pred.lower() == gt.lower():
        case_insensitive_matches += 1

    # Character-level distance
    distance = levenshtein_distance(gt, pred)

    total_edit_distance += distance
    total_gt_characters += len(gt)

    # Normalized similarity
    if len(gt) > 0:
        similarity = max(
            0.0,
            1.0 - (distance / len(gt))
        )
    else:
        similarity = 1.0 if pred == "" else 0.0

    normalized_similarities.append(similarity)

n = len(df)

exact_accuracy = exact_matches / n
case_insensitive_accuracy = case_insensitive_matches / n

cer = (
    total_edit_distance / total_gt_characters
    if total_gt_characters > 0
    else 0.0
)

normalized_similarity = sum(
    normalized_similarities
) / len(normalized_similarities)

print(f"Samples:                         {n}")
print(f"Exact-match accuracy:            {exact_accuracy:.4f} ({exact_accuracy*100:.2f}%)")
print(f"Case-insensitive exact accuracy: {case_insensitive_accuracy:.4f} ({case_insensitive_accuracy*100:.2f}%)")
print(f"Character Error Rate (CER):      {cer:.4f} ({cer*100:.2f}%)")
print(f"Normalized edit similarity:      {normalized_similarity:.4f} ({normalized_similarity*100:.2f}%)")

print("\nExamples of errors:")

error_df = df[
    df["ground_truth"].astype(str)
    != df["prediction"].astype(str)
].copy()

for _, row in error_df.head(15).iterrows():
    print(
        f"GT={row['ground_truth']!r} | "
        f"PRED={row['prediction']!r}"
    )

# Save metrics
metrics = {
    "dataset": "ICDAR 2015",
    "split": "test",
    "num_samples": int(n),
    "exact_match_accuracy": exact_accuracy,
    "case_insensitive_exact_match_accuracy": case_insensitive_accuracy,
    "character_error_rate": cer,
    "normalized_edit_similarity": normalized_similarity,
    "total_edit_distance": int(total_edit_distance),
    "total_ground_truth_characters": int(total_gt_characters)
}

metrics_path = (
    "/content/ocr_eval/icdar2015/EXP_001_results/"
    "EXP_001_metrics.json"
)

with open(metrics_path, "w", encoding="utf-8") as f:
    json.dump(metrics, f, indent=2)

print("\nSaved metrics:")
print(metrics_path)

print("=" * 70)

# MODULE 6 — ICDAR 2015 METRICS (CORRECTED EMPTY-PREDICTION HANDLING)

import os
import json
import math
import pandas as pd

RESULTS_CSV = (
    "/content/ocr_eval/icdar2015/EXP_001_results/"
    "EXP_001_predictions.csv"
)

df = pd.read_csv(RESULTS_CSV)

print("=" * 70)
print("ICDAR 2015 OCR METRICS — CORRECTED")
print("=" * 70)

def levenshtein_distance(a, b):
    a = str(a)
    b = str(b)

    prev = list(range(len(b) + 1))

    for i, ca in enumerate(a, start=1):
        curr = [i]

        for j, cb in enumerate(b, start=1):
            insertion = curr[j - 1] + 1
            deletion = prev[j] + 1
            substitution = prev[j - 1] + (ca != cb)

            curr.append(
                min(insertion, deletion, substitution)
            )

        prev = curr

    return prev[-1]


exact_matches = 0
case_insensitive_matches = 0
total_edit_distance = 0
total_gt_characters = 0
normalized_similarities = []

for _, row in df.iterrows():

    gt = str(row["ground_truth"])

    # IMPORTANT: NaN prediction means EasyOCR detected no text.
    raw_pred = row["prediction"]

    if pd.isna(raw_pred):
        pred = ""
    else:
        pred = str(raw_pred)

    if pred == gt:
        exact_matches += 1

    if pred.lower() == gt.lower():
        case_insensitive_matches += 1

    distance = levenshtein_distance(gt, pred)

    total_edit_distance += distance
    total_gt_characters += len(gt)

    similarity = max(
        0.0,
        1.0 - (distance / len(gt))
    ) if len(gt) > 0 else (
        1.0 if pred == "" else 0.0
    )

    normalized_similarities.append(similarity)

n = len(df)

exact_accuracy = exact_matches / n
case_insensitive_accuracy = case_insensitive_matches / n

cer = total_edit_distance / total_gt_characters

normalized_similarity = (
    sum(normalized_similarities)
    / len(normalized_similarities)
)

empty_predictions = sum(
    pd.isna(x) or str(x).strip() == ""
    for x in df["prediction"]
)

print(f"Samples:                         {n}")
print(f"Empty predictions:               {empty_predictions}")
print(f"Exact-match accuracy:            {exact_accuracy:.4f} ({exact_accuracy*100:.2f}%)")
print(f"Case-insensitive exact accuracy: {case_insensitive_accuracy:.4f} ({case_insensitive_accuracy*100:.2f}%)")
print(f"Character Error Rate (CER):      {cer:.4f} ({cer*100:.2f}%)")
print(f"Normalized edit similarity:      {normalized_similarity:.4f} ({normalized_similarity*100:.2f}%)")

metrics = {
    "dataset": "ICDAR 2015",
    "split": "test",
    "num_samples": int(n),
    "empty_predictions": int(empty_predictions),
    "exact_match_accuracy": exact_accuracy,
    "case_insensitive_exact_match_accuracy": case_insensitive_accuracy,
    "character_error_rate": cer,
    "normalized_edit_similarity": normalized_similarity,
    "total_edit_distance": int(total_edit_distance),
    "total_ground_truth_characters": int(total_gt_characters),
    "metric_note": (
        "Empty/NaN predictions are treated as empty strings. "
        "CER is corpus-level total edit distance divided by "
        "total ground-truth characters."
    )
}

metrics_path = (
    "/content/ocr_eval/icdar2015/EXP_001_results/"
    "EXP_001_metrics_corrected.json"
)

with open(metrics_path, "w", encoding="utf-8") as f:
    json.dump(metrics, f, indent=2)

print("\nSaved:")
print(metrics_path)

print("=" * 70)

