# MODULE 6 — COCO-TEXT OFFICIAL SOURCE INSPECTION

import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin

URL = "https://bgshih.github.io/cocotext/"

print("=" * 70)
print("OFFICIAL COCO-TEXT PROJECT PAGE")
print("=" * 70)

r = requests.get(URL, timeout=30)
print("HTTP status:", r.status_code)

soup = BeautifulSoup(r.text, "html.parser")

print("\nLinks found:")
for a in soup.find_all("a", href=True):
    href = urljoin(URL, a["href"])
    text = " ".join(a.get_text(" ", strip=True).split())

    if (
        "zip" in href.lower()
        or "json" in href.lower()
        or "download" in text.lower()
        or "annotation" in text.lower()
        or "coco" in href.lower()
    ):
        print(f"  {text or '[no text]'}")
        print(f"    {href}")

print("\nPage text excerpt:")
page_text = soup.get_text("\n", strip=True)
print(page_text[:12000])

print("=" * 70)

# MODULE 6 — COCO-TEXT OFFICIAL JS ENDPOINT DISCOVERY

import re
import requests
from urllib.parse import urljoin

URL = "https://bgshih.github.io/cocotext/"

print("=" * 70)
print("INSPECTING COCO-TEXT JAVASCRIPT BUNDLE")
print("=" * 70)

html = requests.get(URL, timeout=30).text

scripts = re.findall(
    r'<script[^>]+src=["\']([^"\']+)["\']',
    html,
    flags=re.IGNORECASE
)

print("JavaScript files found:", len(scripts))

for src in scripts:
    script_url = urljoin(URL, src)

    try:
        r = requests.get(script_url, timeout=30)

        print(f"\n{script_url}")
        print("  HTTP:", r.status_code)
        print("  Size:", len(r.content), "bytes")

        text = r.text

        # Look for likely dataset/download/API references
        patterns = [
            r'https?://[^"\']+',
            r'[^"\']+\.zip',
            r'[^"\']+\.json',
            r'[^"\']+\.txt',
            r'[^"\']+api[^"\']*',
            r'[^"\']+download[^"\']*'
        ]

        matches = set()

        for pattern in patterns:
            for match in re.findall(pattern, text, flags=re.IGNORECASE):
                if len(match) < 500:
                    matches.add(match)

        if matches:
            print("  Candidate references:")
            for match in sorted(matches):
                print("   ", match[:400])
        else:
            print("  No obvious dataset endpoints found.")

    except Exception as e:
        print("  ERROR:", type(e).__name__, str(e)[:200])

print("=" * 70)

# MODULE 6 — COCO-TEXT V2 ANNOTATIONS

import os
import zipfile
import requests

BASE_DIR = "/content/ocr_eval/cocotext"
os.makedirs(BASE_DIR, exist_ok=True)

URL = (
    "https://github.com/bgshih/cocotext/"
    "releases/download/dl/cocotext.v2.zip"
)

ZIP_PATH = os.path.join(BASE_DIR, "cocotext.v2.zip")
EXTRACT_DIR = os.path.join(BASE_DIR, "annotations")

print("=" * 70)
print("DOWNLOADING COCO-TEXT V2 ANNOTATIONS")
print("=" * 70)

r = requests.get(URL, timeout=120)

print("HTTP status:", r.status_code)
print("Downloaded bytes:", len(r.content))

if r.status_code != 200:
    raise RuntimeError(
        f"COCO-Text download failed with HTTP {r.status_code}"
    )

with open(ZIP_PATH, "wb") as f:
    f.write(r.content)

print("Saved:", ZIP_PATH)

with zipfile.ZipFile(ZIP_PATH, "r") as z:
    members = z.namelist()

    print("\nArchive members:", len(members))
    for name in members[:30]:
        print(" ", name)

    os.makedirs(EXTRACT_DIR, exist_ok=True)
    z.extractall(EXTRACT_DIR)

print("\nExtracted to:", EXTRACT_DIR)

print("\nExtracted files:")
for root, dirs, files in os.walk(EXTRACT_DIR):
    for name in files:
        path = os.path.join(root, name)
        print(" ", path)

print("=" * 70)

