# MODULE 6 — COCO-TEXT V2 EVALUATION MANIFEST
# 100 legible English text instances, seed = 42

import json
import os
import random
import pandas as pd

BASE_DIR = "/content/ocr_eval/cocotext"

JSON_PATH = os.path.join(
    BASE_DIR,
    "annotations",
    "cocotext.v2.json"
)

MANIFEST_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100"
)

os.makedirs(MANIFEST_DIR, exist_ok=True)

SEED = 42
TARGET_N = 100

print("=" * 70)
print("COCO-TEXT V2 — BUILDING EVALUATION MANIFEST")
print("=" * 70)

with open(JSON_PATH, "r", encoding="utf-8") as f:
    data = json.load(f)

images = data["imgs"]
annotations = data["anns"]

# Keep only:
# - English
# - legible
# - non-empty text
# - non-whitespace text
# - machine-printed text
eligible = []

for ann_id, ann in annotations.items():

    text = str(ann.get("utf8_string", ""))

    if (
        ann.get("language") == "english"
        and ann.get("legibility") == "legible"
        and ann.get("class") == "machine printed"
        and text.strip() != ""
    ):
        image_id = ann["image_id"]

        if image_id in images:
            eligible.append({
                "annotation_id": int(ann_id),
                "image_id": int(image_id),
                "file_name": images[image_id]["file_name"],
                "width": images[image_id]["width"],
                "height": images[image_id]["height"],
                "bbox": ann["bbox"],
                "text": text,
                "language": ann["language"],
                "legibility": ann["legibility"],
                "class": ann["class"]
            })

print("Eligible annotations:", len(eligible))

if len(eligible) < TARGET_N:
    raise RuntimeError(
        f"Only {len(eligible)} eligible annotations found."
    )

rng = random.Random(SEED)
selected = rng.sample(eligible, TARGET_N)

manifest_df = pd.DataFrame(selected)

csv_path = os.path.join(
    MANIFEST_DIR,
    "EXP_001_ground_truth.csv"
)

json_path = os.path.join(
    MANIFEST_DIR,
    "EXP_001_ground_truth.json"
)

manifest_df.to_csv(csv_path, index=False)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(
        selected,
        f,
        ensure_ascii=False,
        indent=2
    )

print("Selected:", len(selected))
print("Random seed:", SEED)

print("\nFirst 15 selected instances:")
print(
    manifest_df[
        [
            "annotation_id",
            "image_id",
            "file_name",
            "text",
            "bbox"
        ]
    ].head(15).to_string(index=False)
)

print("\nUnique source images:", manifest_df["image_id"].nunique())

print("\nSaved:")
print(" ", csv_path)
print(" ", json_path)

print("=" * 70)

