import json
import os
from collections import Counter

JSON_PATH = (
    "/content/ocr_eval/cocotext/annotations/"
    "cocotext.v2.json"
)

with open(JSON_PATH, "r", encoding="utf-8") as f:
    data = json.load(f)

images = data["imgs"]
annotations = data["anns"]

print("=" * 70)
print("COCO-TEXT FILTER DIAGNOSTIC")
print("=" * 70)

# Key-type check
first_image_key = next(iter(images))
first_ann_key = next(iter(annotations))
first_ann = annotations[first_ann_key]

print("Image key example:", first_image_key, type(first_image_key))
print("Annotation key example:", first_ann_key, type(first_ann_key))
print("Annotation image_id:", first_ann["image_id"], type(first_ann["image_id"]))

# Count each filter independently
counts = Counter()

for ann in annotations.values():

    text = str(ann.get("utf8_string", ""))

    if ann.get("language") == "english":
        counts["english"] += 1

    if ann.get("legibility") == "legible":
        counts["legible"] += 1

    if ann.get("class") == "machine printed":
        counts["machine_printed"] += 1

    if text.strip() != "":
        counts["nonempty"] += 1

    if (
        ann.get("language") == "english"
        and ann.get("legibility") == "legible"
        and ann.get("class") == "machine printed"
        and text.strip() != ""
    ):
        counts["all_text_filters"] += 1

        image_id = ann["image_id"]

        if image_id in images:
            counts["all_filters_image_int"] += 1

        if str(image_id) in images:
            counts["all_filters_image_str"] += 1

print("\nFilter counts:")
for key, value in counts.items():
    print(f"  {key:30s}: {value}")

print("=" * 70)

