# MODULE 6 — DOWNLOAD REQUIRED COCO 2014 IMAGES
# Only the 99 images needed by the fixed COCO-Text manifest

import os
import time
import requests
import pandas as pd

BASE_DIR = "/content/ocr_eval/cocotext"
MANIFEST_CSV = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "EXP_001_ground_truth.csv"
)

IMAGE_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_subset_100",
    "images"
)

os.makedirs(IMAGE_DIR, exist_ok=True)

df = pd.read_csv(MANIFEST_CSV)

unique_images = df[
    ["image_id", "file_name"]
].drop_duplicates()

BASE_URL = "http://images.cocodataset.org/train2014/"

print("=" * 70)
print("DOWNLOADING REQUIRED COCO 2014 IMAGES")
print("=" * 70)

print("Manifest instances:", len(df))
print("Unique source images:", len(unique_images))

downloaded = 0
existing = 0
failed = []

for i, row in enumerate(
    unique_images.itertuples(index=False),
    start=1
):
    image_id = int(row.image_id)
    file_name = str(row.file_name)

    output_path = os.path.join(
        IMAGE_DIR,
        file_name
    )

    if os.path.exists(output_path):
        existing += 1
        continue

    url = BASE_URL + file_name

    try:
        response = requests.get(
            url,
            timeout=60
        )

        if response.status_code == 200:
            with open(output_path, "wb") as f:
                f.write(response.content)

            downloaded += 1

        else:
            failed.append({
                "image_id": image_id,
                "file_name": file_name,
                "status": response.status_code
            })

    except Exception as e:
        failed.append({
            "image_id": image_id,
            "file_name": file_name,
            "status": type(e).__name__
        })

    if i % 10 == 0 or i == len(unique_images):
        print(
            f"[{i:3d}/{len(unique_images)}] "
            f"downloaded={downloaded}, "
            f"existing={existing}, "
            f"failed={len(failed)}"
        )

print("\n" + "=" * 70)
