# MODULE 6 — COCO-TEXT TEXT-REGION CROPS

import os
import json
import pandas as pd
from PIL import Image

BASE_DIR = "/content/ocr_eval/cocotext"

MANIFEST_CSV = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "EXP_001_ground_truth.csv"
)

IMAGE_DIR = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "images"
)

CROP_DIR = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "text_crops"
)

os.makedirs(CROP_DIR, exist_ok=True)

df = pd.read_csv(MANIFEST_CSV)

records = []
invalid = 0

print("=" * 70)
print("CROPPING COCO-TEXT ANNOTATED REGIONS")
print("=" * 70)

for _, row in df.iterrows():

    image_path = os.path.join(
        IMAGE_DIR,
        str(row["file_name"])
    )

    try:
        with Image.open(image_path) as img:
            img = img.convert("RGB")

            image_width, image_height = img.size

            x, y, w, h = [
                float(v)
                for v in json.loads(
                    str(row["bbox"])
                    .replace("'", '"')
                )
            ]

            # Convert floating-point annotation to integer crop bounds
            left = max(0, int(round(x)))
            top = max(0, int(round(y)))
            right = min(
                image_width,
                int(round(x + w))
            )
            bottom = min(
                image_height,
                int(round(y + h))
            )

            if right <= left or bottom <= top:
                invalid += 1
                continue

            crop = img.crop(
                (left, top, right, bottom)
            )

            crop_name = (
                f"cocotext_{int(row['annotation_id']):06d}.png"
            )

            crop_path = os.path.join(
                CROP_DIR,
                crop_name
            )

            crop.save(crop_path)

            records.append({
                "annotation_id": int(row["annotation_id"]),
                "image_id": int(row["image_id"]),
                "file_name": str(row["file_name"]),
                "crop_path": crop_path,
                "ground_truth": str(row["text"]),
                "bbox_x": x,
                "bbox_y": y,
                "bbox_w": w,
                "bbox_h": h,
                "crop_width": right - left,
                "crop_height": bottom - top
            })

    except Exception as e:
        invalid += 1
        print(
            f"ERROR annotation {row['annotation_id']}: "
            f"{type(e).__name__}: {e}"
        )

crop_df = pd.DataFrame(records)

CROP_CSV = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "EXP_001_crops.csv"
)

CROP_JSON = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "EXP_001_crops.json"
)

crop_df.to_csv(CROP_CSV, index=False)

with open(CROP_JSON, "w", encoding="utf-8") as f:
    json.dump(
        records,
        f,
        ensure_ascii=False,
        indent=2
    )

print("\nTotal manifest instances:", len(df))
print("Valid crops:", len(records))
print("Invalid crops:", invalid)

if records:
    print(
        "Unique source images:",
        crop_df["image_id"].nunique()
    )

    print("\nFirst 15 crops:")
    print(
        crop_df[
            [
                "annotation_id",
                "ground_truth",
                "crop_width",
                "crop_height"
            ]
        ].head(15).to_string(index=False)
    )

print("\nSaved:")
print(" ", CROP_CSV)
print(" ", CROP_JSON)

print("=" * 70)

# MODULE 6 — COCO-TEXT OCR EVALUATION
# EasyOCR on the fixed 100 annotated text crops

import os
import json
import time
import pandas as pd
import easyocr

CROP_CSV = (
    "/content/ocr_eval/cocotext/EXP_001_subset_100/"
    "EXP_001_crops.csv"
)

RESULT_DIR = (
    "/content/ocr_eval/cocotext/EXP_001_results"
)

os.makedirs(RESULT_DIR, exist_ok=True)

df = pd.read_csv(CROP_CSV)

print("=" * 70)
print("INITIALIZING EASYOCR")
print("=" * 70)

reader = easyocr.Reader(
    ["en"],
    gpu=True,
    verbose=True
)

print("EasyOCR initialized.")
print("GPU requested: True")

results = []

print("\n" + "=" * 70)
print("RUNNING OCR — 100 COCO-TEXT CROPS")
print("=" * 70)

for idx, row in df.iterrows():

    image_path = row["crop_path"]
    ground_truth = str(row["ground_truth"])

    start = time.perf_counter()

    ocr_output = reader.readtext(
        image_path,
        detail=1,
        paragraph=False
    )

    elapsed_ms = (
        time.perf_counter() - start
    ) * 1000

    detections = []

    for detection in ocr_output:
        box, text_value, confidence = detection

        detections.append({
            "text": str(text_value),
            "confidence": float(confidence),
            "box": [
                [int(point[0]), int(point[1])]
                for point in box
            ]
        })

    prediction = " ".join(
        item["text"] for item in detections
    ).strip()

    results.append({
        "annotation_id": int(row["annotation_id"]),
        "image_id": int(row["image_id"]),
        "ground_truth": ground_truth,
        "prediction": prediction,
        "detections": detections,
        "latency_ms": elapsed_ms
    })

    if (idx + 1) % 10 == 0 or idx == 0:
        print(
            f"[{idx + 1:3d}/100] "
            f"GT={ground_truth!r} | "
            f"PRED={prediction!r} | "
            f"{elapsed_ms:.2f} ms"
        )

results_json = os.path.join(
    RESULT_DIR,
    "EXP_001_predictions.json"
)

results_csv = os.path.join(
    RESULT_DIR,
    "EXP_001_predictions.csv"
)

with open(results_json, "w", encoding="utf-8") as f:
    json.dump(
        results,
        f,
        ensure_ascii=False,
        indent=2
    )

csv_rows = []

for r in results:
    csv_rows.append({
        "annotation_id": r["annotation_id"],
        "image_id": r["image_id"],
        "ground_truth": r["ground_truth"],
        "prediction": r["prediction"],
        "latency_ms": r["latency_ms"],
        "num_detections": len(r["detections"]),
        "mean_confidence": (
            sum(
                x["confidence"]
                for x in r["detections"]
            ) / len(r["detections"])
            if r["detections"]
            else 0.0
        )
    })

pd.DataFrame(csv_rows).to_csv(
    results_csv,
    index=False
)

latencies = [r["latency_ms"] for r in results]

print("\n" + "=" * 70)
print("OCR RUN COMPLETE")
print("=" * 70)

print("Instances processed:", len(results))
print(
    f"Average latency: "
    f"{sum(latencies) / len(latencies):.2f} ms/instance"
)
print(
    f"Median latency : "
    f"{pd.Series(latencies).median():.2f} ms/instance"
)
print(
    f"Approx FPS     : "
    f"{1000 / (sum(latencies) / len(latencies)):.2f}"
)

print("\nSaved:")
print(" ", results_json)
print(" ", results_csv)

print("=" * 70)

# MODULE 6 — COCO-TEXT OCR METRICS

import json
import os
import pandas as pd

RESULTS_CSV = (
    "/content/ocr_eval/cocotext/EXP_001_results/"
    "EXP_001_predictions.csv"
)

df = pd.read_csv(RESULTS_CSV)

print("=" * 70)
print("COCO-TEXT OCR METRICS")
print("=" * 70)

def levenshtein_distance(a, b):
    a = str(a)
    b = str(b)

    prev = list(range(len(b) + 1))

    for i, ca in enumerate(a, start=1):
        curr = [i]

        for j, cb in enumerate(b, start=1):
            insertion = curr[j - 1] + 1
            deletion = prev[j] + 1
            substitution = prev[j - 1] + (ca != cb)

            curr.append(
                min(insertion, deletion, substitution)
            )

        prev = curr

    return prev[-1]


exact_matches = 0
case_insensitive_matches = 0
total_edit_distance = 0
total_gt_characters = 0
normalized_similarities = []

for _, row in df.iterrows():

    gt = str(row["ground_truth"])

    raw_pred = row["prediction"]

    if pd.isna(raw_pred):
        pred = ""
    else:
        pred = str(raw_pred)

    if pred == gt:
        exact_matches += 1

    if pred.lower() == gt.lower():
        case_insensitive_matches += 1

    distance = levenshtein_distance(gt, pred)

    total_edit_distance += distance
    total_gt_characters += len(gt)

    similarity = max(
        0.0,
        1.0 - (distance / len(gt))
    ) if len(gt) > 0 else (
        1.0 if pred == "" else 0.0
    )

    normalized_similarities.append(similarity)

n = len(df)

exact_accuracy = exact_matches / n
case_insensitive_accuracy = case_insensitive_matches / n

cer = (
    total_edit_distance
    / total_gt_characters
)

normalized_similarity = (
    sum(normalized_similarities)
    / len(normalized_similarities)
)

empty_predictions = sum(
    pd.isna(x) or str(x).strip() == ""
    for x in df["prediction"]
)

print(f"Samples:                         {n}")
print(f"Empty predictions:               {empty_predictions}")
print(f"Exact-match accuracy:            {exact_accuracy:.4f} ({exact_accuracy*100:.2f}%)")
print(f"Case-insensitive exact accuracy: {case_insensitive_accuracy:.4f} ({case_insensitive_accuracy*100:.2f}%)")
print(f"Character Error Rate (CER):      {cer:.4f} ({cer*100:.2f}%)")
print(f"Normalized edit similarity:      {normalized_similarity:.4f} ({normalized_similarity*100:.2f}%)")

print("\nExamples of errors:")

error_df = df[
    df["ground_truth"].astype(str)
    != df["prediction"].fillna("").astype(str)
].copy()

for _, row in error_df.head(15).iterrows():
    pred = "" if pd.isna(row["prediction"]) else str(row["prediction"])

    print(
        f"GT={row['ground_truth']!r} | "
        f"PRED={pred!r}"
    )

metrics = {
    "dataset": "COCO-Text v2",
    "num_samples": int(n),
    "selection_seed": 42,
    "filter": {
        "language": "english",
        "legibility": "legible",
        "class": "machine printed",
        "non_empty_text": True
    },
    "exact_match_accuracy": exact_accuracy,
    "case_insensitive_exact_match_accuracy": (
        case_insensitive_accuracy
    ),
    "character_error_rate": cer,
    "normalized_edit_similarity": normalized_similarity,
    "empty_predictions": int(empty_predictions),
    "total_edit_distance": int(total_edit_distance),
    "total_ground_truth_characters": int(
        total_gt_characters
    )
}

metrics_path = (
    "/content/ocr_eval/cocotext/EXP_001_results/"
    "EXP_001_metrics.json"
)

with open(metrics_path, "w", encoding="utf-8") as f:
    json.dump(metrics, f, ensure_ascii=False, indent=2)

print("\nSaved:")
print(metrics_path)

print("=" * 70)

