# MODULE 7 — OPENSTREETMAP LANDMARK / POI EVALUATION DATASET
#
# Fixed evaluation area:
# Hyderabad, India
#
# Categories represent common navigation queries:
# hospitals, schools, banks, pharmacies, restaurants, fuel stations

import os
import json
import time
import requests
import pandas as pd

BASE_DIR = "/content/osm_eval"

RESULT_DIR = os.path.join(
    BASE_DIR,
    "EXP_001_results"
)

os.makedirs(RESULT_DIR, exist_ok=True)

OVERPASS_URL = "https://overpass-api.de/api/interpreter"

# Fixed Hyderabad bounding box
SOUTH = 17.35
WEST = 78.40
NORTH = 17.45
EAST = 78.55

CATEGORIES = {
    "hospital": '["amenity"="hospital"]',
    "school": '["amenity"="school"]',
    "bank": '["amenity"="bank"]',
    "pharmacy": '["amenity"="pharmacy"]',
    "restaurant": '["amenity"="restaurant"]',
    "fuel": '["amenity"="fuel"]'
}

print("=" * 70)
print("OPENSTREETMAP LANDMARK EVALUATION DATASET")
print("=" * 70)

all_records = []

for category, tag_filter in CATEGORIES.items():

    print(f"\nQuerying: {category}")

    query = f"""
    [out:json][timeout:60];
    (
      node{tag_filter}({SOUTH},{WEST},{NORTH},{EAST});
      way{tag_filter}({SOUTH},{WEST},{NORTH},{EAST});
      relation{tag_filter}({SOUTH},{WEST},{NORTH},{EAST});
    );
    out center;
    """

    try:
        response = requests.post(
            OVERPASS_URL,
            data=query,
            headers={
                "User-Agent": "Colab-OSM-Evaluation/1.0"
            },
            timeout=90
        )

        print("  HTTP:", response.status_code)

        if not response.ok:
            print("  Query failed:", response.text[:300])
            continue

        data = response.json()
        elements = data.get("elements", [])

        print("  Elements:", len(elements))

        for element in elements:

            tags = element.get("tags", {})

            if element["type"] == "node":
                lat = element.get("lat")
                lon = element.get("lon")
            else:
                center = element.get("center", {})
                lat = center.get("lat")
                lon = center.get("lon")

            all_records.append({
                "category": category,
                "osm_type": element.get("type"),
                "osm_id": element.get("id"),
                "name": tags.get("name", ""),
                "latitude": lat,
                "longitude": lon,
                "amenity": tags.get("amenity", ""),
                "operator": tags.get("operator", ""),
                "phone": tags.get("phone", ""),
                "website": tags.get("website", "")
            })

        # Be polite to the public Overpass service
        time.sleep(2)

    except Exception as e:
        print(
            "  ERROR:",
            type(e).__name__,
            str(e)
        )

landmarks_df = pd.DataFrame(all_records)

csv_path = os.path.join(
    RESULT_DIR,
    "EXP_001_osm_landmarks.csv"
)

json_path = os.path.join(
    RESULT_DIR,
    "EXP_001_osm_landmarks.json"
)

landmarks_df.to_csv(
    csv_path,
    index=False
)

landmarks_df.to_json(
    json_path,
    orient="records",
    force_ascii=False,
    indent=2
)

print("\n" + "=" * 70)
print("LANDMARK DATASET COMPLETE")
print("=" * 70)

print("Total OSM elements:", len(landmarks_df))

if len(landmarks_df) > 0:
    print("\nElements by category:")
    print(
        landmarks_df["category"]
        .value_counts()
        .to_string()
    )

    print("\nNamed elements:")
    print(
        (landmarks_df["name"].astype(str).str.strip() != "")
        .sum()
    )

    print("\nFirst 20 records:")
    print(
        landmarks_df[
            [
                "category",
                "osm_type",
                "osm_id",
                "name",
                "latitude",
                "longitude"
            ]
        ].head(20).to_string(index=False)
    )

print("\nSaved:")
print(" ", csv_path)
print(" ", json_path)

print("=" * 70)

