TARGET_N = 100

df = pd.read_csv(LANDMARK_CSV)

# Keep only named POIs with valid coordinates
eligible = df[
    (df["name"].fillna("").astype(str).str.strip() != "")
    & df["latitude"].notna()
    & df["longitude"].notna()
].copy()

print("=" * 70)
print("OSM LANDMARK BENCHMARK")
print("=" * 70)

print("Named POIs available:", len(eligible))

if len(eligible) < TARGET_N:
    raise RuntimeError(
        f"Only {len(eligible)} named POIs available."
    )

# Fixed reproducible selection
sampled = (
    eligible
    .sample(
        n=TARGET_N,
        random_state=SEED
    )
    .reset_index(drop=True)
)

sampled.insert(
    0,
    "query_id",
    range(1, TARGET_N + 1)
)

# Query text that a navigation assistant could receive
sampled["query"] = sampled.apply(
    lambda row:
        f"Find the nearest {row['category']} "
        f"named {row['name']}",
    axis=1
)

csv_path = os.path.join(
    BENCHMARK_DIR,
    "EXP_001_landmark_queries.csv"
)

json_path = os.path.join(
    BENCHMARK_DIR,
    "EXP_001_landmark_queries.json"
)

sampled.to_csv(
    csv_path,
    index=False
)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(
        sampled.to_dict(orient="records"),
        f,
        ensure_ascii=False,
        indent=2
    )

print("Selected queries:", len(sampled))
print("Random seed:", SEED)

print("\nQueries by category:")
print(
    sampled["category"]
    .value_counts()
    .to_string()
)

print("\nFirst 20 benchmark queries:")
print(
    sampled[
        [
            "query_id",
            "category",
            "name",
            "latitude",
            "longitude",
            "query"
        ]
    ].head(20).to_string(index=False)
)

print("\nSaved:")
print(" ", csv_path)
print(" ", json_path)

print("=" * 70)

# MODULE 7 — OSM LANDMARK RETRIEVAL EVALUATION
#
# For each benchmark POI, query OSM in a local radius around
# its ground-truth coordinates and check whether the target
# landmark can be recovered by category + name.

import os
import json
import time
import re
import requests
import pandas as pd

BENCHMARK_CSV = (
    "/content/osm_eval/EXP_001_benchmark/"
    "EXP_001_landmark_queries.csv"
)

RESULT_DIR = "/content/osm_eval/EXP_001_results"
os.makedirs(RESULT_DIR, exist_ok=True)

OVERPASS_URL = "https://overpass-api.de/api/interpreter"

df = pd.read_csv(BENCHMARK_CSV)

print("=" * 70)
print("OSM LANDMARK RETRIEVAL EVALUATION")
print("=" * 70)

print("Benchmark queries:", len(df))

# Category -> OSM tag
TAG_MAP = {
    "hospital": '["amenity"="hospital"]',
    "school": '["amenity"="school"]',
    "bank": '["amenity"="bank"]',
    "pharmacy": '["amenity"="pharmacy"]',
    "restaurant": '["amenity"="restaurant"]',
    "fuel": '["amenity"="fuel"]'
}

def normalize_name(text):
    text = str(text).lower().strip()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return " ".join(text.split())

results = []

for idx, row in df.iterrows():

    category = str(row["category"])
    target_name = str(row["name"])
    target_id = int(row["osm_id"])
    lat = float(row["latitude"])
    lon = float(row["longitude"])

    tag_filter = TAG_MAP[category]

    # Small local search area around the known target.
    delta = 0.01

    south = lat - delta
    west = lon - delta
    north = lat + delta
    east = lon + delta

    query = f"""
    [out:json][timeout:30];
    (
      node{tag_filter}({south},{west},{north},{east});
      way{tag_filter}({south},{west},{north},{east});
      relation{tag_filter}({south},{west},{north},{east});
    );
    out center;
    """

    start = time.perf_counter()

    try:
        response = requests.post(
            OVERPASS_URL,
            data=query,
            headers={
                "User-Agent": "Colab-OSM-Evaluation/1.0"
            },
            timeout=60
        )

        latency_ms = (
            time.perf_counter() - start
        ) * 1000

        if not response.ok:
            results.append({
                "query_id": int(row["query_id"]),
                "target_osm_id": target_id,
                "target_name": target_name,
                "category": category,
                "status": "api_error",
                "http_status": response.status_code,
                "candidate_count": 0,
                "target_id_found": False,
                "exact_name_found": False,
                "latency_ms": latency_ms
            })
            continue

        data = response.json()
        elements = data.get("elements", [])

        target_id_found = False
        exact_name_found = False
        normalized_target = normalize_name(target_name)

        candidate_names = []

        for element in elements:

            osm_id = int(element["id"])
            tags = element.get("tags", {})
            name = tags.get("name", "")

            candidate_names.append(str(name))

            if osm_id == target_id:
                target_id_found = True

            if (
                normalize_name(name)
                == normalized_target
            ):
                exact_name_found = True

        results.append({
            "query_id": int(row["query_id"]),
            "target_osm_id": target_id,
            "target_name": target_name,
            "category": category,
            "status": "success",
            "http_status": response.status_code,
            "candidate_count": len(elements),
            "target_id_found": target_id_found,
            "exact_name_found": exact_name_found,
            "latency_ms": latency_ms,
            "candidate_names": candidate_names[:50]
        })

    except Exception as e:

        latency_ms = (
            time.perf_counter() - start
        ) * 1000

        results.append({
            "query_id": int(row["query_id"]),
            "target_osm_id": target_id,
            "target_name": target_name,
            "category": category,
            "status": "exception",
            "http_status": None,
            "candidate_count": 0,
            "target_id_found": False,
            "exact_name_found": False,
            "latency_ms": latency_ms,
            "error": str(e)
        })

    if (idx + 1) % 10 == 0 or idx == 0:
        print(
            f"[{idx + 1:3d}/100] "
            f"{category} | {target_name}"
        )

    # Respect public API
    time.sleep(1)

results_df = pd.DataFrame(results)

csv_path = os.path.join(
    RESULT_DIR,
    "EXP_001_landmark_retrieval.csv"
)

json_path = os.path.join(
    RESULT_DIR,
    "EXP_001_landmark_retrieval.json"
)

results_df.to_csv(
    csv_path,
    index=False
)

results_df.to_json(
    json_path,
    orient="records",
    force_ascii=False,
    indent=2
)

print("\n" + "=" * 70)
print("RETRIEVAL EVALUATION COMPLETE")
print("=" * 70)

print("Queries evaluated:", len(results_df))

print("\nStatus:")
print(
    results_df["status"]
    .value_counts()
    .to_string()
)

successful = results_df[
    results_df["status"] == "success"
]

if len(successful) > 0:
    print("\nTarget OSM ID retrieval:")
    print(
        f"{successful['target_id_found'].sum()}/"
        f"{len(successful)}"
    )

    print("\nExact normalized-name retrieval:")
    print(
        f"{successful['exact_name_found'].sum()}/"
        f"{len(successful)}"
    )

print("\nSaved:")
print(" ", csv_path)
print(" ", json_path)

print("=" * 70)

