# MODULE 7 — RETRY FAILED OSM QUERIES
#
# Retry only API errors/exceptions using a second public
# Overpass endpoint and a slower request interval.

import os
import json
import time
import re
import requests
import pandas as pd

RESULT_PATH = (
    "/content/osm_eval/EXP_001_results/"
    "EXP_001_landmark_retrieval.csv"
)

RETRY_CSV = (
    "/content/osm_eval/EXP_001_results/"
    "EXP_001_landmark_retrieval_retry.csv"
)

RETRY_JSON = (
    "/content/osm_eval/EXP_001_results/"
    "EXP_001_landmark_retrieval_retry.json"
)

df = pd.read_csv(RESULT_PATH)

failed = df[df["status"].isin(["api_error", "exception"])].copy()

print("=" * 70)
print("OSM FAILED-QUERY RETRY")
print("=" * 70)

print("Failed queries to retry:", len(failed))

# Alternate Overpass endpoint
OVERPASS_URL = "https://overpass.kumi.systems/api/interpreter"

TAG_MAP = {
    "hospital": '["amenity"="hospital"]',
    "school": '["amenity"="school"]',
    "bank": '["amenity"="bank"]',
    "pharmacy": '["amenity"="pharmacy"]',
    "restaurant": '["amenity"="restaurant"]',
    "fuel": '["amenity"="fuel"]'
}

def normalize_name(text):
    text = str(text).lower().strip()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return " ".join(text.split())

retry_results = []

for i, (_, row) in enumerate(failed.iterrows(), start=1):

    category = str(row["category"])
    target_name = str(row["target_name"])
    target_id = int(row["target_osm_id"])

    # Recover coordinates from the original benchmark
    benchmark = pd.read_csv(
        "/content/osm_eval/EXP_001_benchmark/"
        "EXP_001_landmark_queries.csv"
    )

    source = benchmark[
        benchmark["query_id"] == int(row["query_id"])
    ].iloc[0]

    lat = float(source["latitude"])
    lon = float(source["longitude"])

    delta = 0.01

    south = lat - delta
    west = lon - delta
    north = lat + delta
    east = lon + delta

    tag_filter = TAG_MAP[category]

    query = f"""
    [out:json][timeout:30];
    (
      node{tag_filter}({south},{west},{north},{east});
      way{tag_filter}({south},{west},{north},{east});
      relation{tag_filter}({south},{west},{north},{east});
    );
    out center;
    """

    start = time.perf_counter()

    try:
        response = requests.post(
            OVERPASS_URL,
            data=query,
            headers={
                "User-Agent": "Colab-OSM-Evaluation/1.0"
            },
            timeout=60
        )

        latency_ms = (
            time.perf_counter() - start
        ) * 1000

        if not response.ok:

            retry_results.append({
                "query_id": int(row["query_id"]),
                "target_osm_id": target_id,
                "target_name": target_name,
                "category": category,
                "status": "retry_api_error",
                "http_status": response.status_code,
                "candidate_count": 0,
                "target_id_found": False,
                "exact_name_found": False,
                "latency_ms": latency_ms
            })

        else:

            data = response.json()
            elements = data.get("elements", [])

            normalized_target = normalize_name(
                target_name
            )

            target_id_found = False
            exact_name_found = False
            candidate_names = []

            for element in elements:

                osm_id = int(element["id"])
                tags = element.get("tags", {})
                name = tags.get("name", "")

                candidate_names.append(str(name))

                if osm_id == target_id:
                    target_id_found = True

                if (
                    normalize_name(name)
                    == normalized_target
                ):
                    exact_name_found = True

            retry_results.append({
                "query_id": int(row["query_id"]),
                "target_osm_id": target_id,
                "target_name": target_name,
                "category": category,
                "status": "success",
                "http_status": response.status_code,
                "candidate_count": len(elements),
                "target_id_found": target_id_found,
                "exact_name_found": exact_name_found,
                "latency_ms": latency_ms,
                "candidate_names": candidate_names[:50]
            })

    except Exception as e:

        latency_ms = (
            time.perf_counter() - start
        ) * 1000

        retry_results.append({
            "query_id": int(row["query_id"]),
            "target_osm_id": target_id,
            "target_name": target_name,
            "category": category,
            "status": "retry_exception",
            "http_status": None,
            "candidate_count": 0,
            "target_id_found": False,
            "exact_name_found": False,
            "latency_ms": latency_ms,
            "error": str(e)
        })

    if i % 10 == 0 or i == 1:
        print(
            f"[{i:3d}/{len(failed)}] "
            f"{category} | {target_name}"
        )

    # Slow down requests to reduce rate limiting.
    time.sleep(3)

retry_df = pd.DataFrame(retry_results)

retry_df.to_csv(
    RETRY_CSV,
    index=False
)

retry_df.to_json(
    RETRY_JSON,
    orient="records",
    force_ascii=False,
    indent=2
)

print("\n" + "=" * 70)
print("RETRY COMPLETE")
print("=" * 70)

print("Retry rows:", len(retry_df))

print("\nStatus:")
print(
    retry_df["status"]
    .value_counts()
    .to_string()
)

successful = retry_df[
    retry_df["status"] == "success"
]

if len(successful) > 0:
    print("\nRetry target retrieval:")
    print(
        f"{successful['target_id_found'].sum()}/"
        f"{len(successful)}"
    )

print("\nSaved:")
print(" ", RETRY_CSV)
print(" ", RETRY_JSON)

print("=" * 70)

