# MODULE 7 — OSM FINAL EVALUATION SUMMARY
#
# Reports the observed retrieval results without treating
# API failures as retrieval failures.

import os
import json
import pandas as pd

RESULT_PATH = (
    "/content/osm_eval/EXP_001_results/"
    "EXP_001_landmark_retrieval.csv"
)

OUT_DIR = "/content/osm_eval/EXP_001_results"
os.makedirs(OUT_DIR, exist_ok=True)

df = pd.read_csv(RESULT_PATH)

successful = df[df["status"] == "success"].copy()
api_errors = df[df["status"] == "api_error"]
exceptions = df[df["status"] == "exception"]

summary = {
    "experiment_id": "EXP_001",
    "dataset": "OpenStreetMap",
    "region": "Hyderabad, India",
    "benchmark_queries": 100,

    "retrieval_api": "Overpass API",

    "total_queries": int(len(df)),
    "successful_queries": int(len(successful)),
    "api_errors": int(len(api_errors)),
    "exceptions": int(len(exceptions)),

    "target_id_retrieved_successful_only": (
        int(successful["target_id_found"].sum())
        if len(successful) else 0
    ),

    "exact_name_retrieved_successful_only": (
        int(successful["exact_name_found"].sum())
        if len(successful) else 0
    ),

    "target_id_retrieval_rate_successful_only": (
        float(successful["target_id_found"].mean())
        if len(successful) else None
    ),

    "exact_name_retrieval_rate_successful_only": (
        float(successful["exact_name_found"].mean())
        if len(successful) else None
    ),

    "api_success_rate": (
        float(len(successful) / len(df))
        if len(df) else None
    ),

    "original_osm_landmark_count": 1664,

    "methodological_note": (
        "Retrieval accuracy is reported only over successfully "
        "completed Overpass queries. API errors and network "
        "exceptions are not counted as retrieval failures."
    )
}

json_path = os.path.join(
    OUT_DIR,
    "EXP_001_final_summary.json"
)

csv_path = os.path.join(
    OUT_DIR,
    "EXP_001_final_summary.csv"
)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(summary, f, indent=2)

pd.DataFrame([summary]).to_csv(
    csv_path,
    index=False
)

print("=" * 70)
print("MODULE 7 — OSM FINAL SUMMARY")
print("=" * 70)

print(f"Benchmark queries:       {summary['total_queries']}")
print(f"Successful queries:      {summary['successful_queries']}")
print(f"API errors:              {summary['api_errors']}")
print(f"Network exceptions:      {summary['exceptions']}")

print(
    f"\nTarget ID retrieval "
    f"(successful queries only): "
    f"{summary['target_id_retrieved_successful_only']}/"
    f"{summary['successful_queries']}"
)

print(
    f"Exact name retrieval "
    f"(successful queries only): "
    f"{summary['exact_name_retrieved_successful_only']}/"
    f"{summary['successful_queries']}"
)

print(
    f"\nOverpass API success rate: "
    f"{summary['api_success_rate'] * 100:.2f}%"
)

print("\nSaved:")
print(" ", json_path)
print(" ", csv_path)

print("=" * 70)

