import requests
import numpy as np
from PIL import Image
from io import BytesIO

BASE = "https://huggingface.co/datasets/dangth2004/KITTI-Depth-Estimation/resolve/main/"

# Known RGB sequence from the repository tree
rgb_dir = (
    "raw_data/2011_09_26/"
    "2011_09_26_drive_0001_sync/image_02/data/"
)

gt_dir = (
    "data_depth_annotated/train/"
    "2011_09_26_drive_0001_sync/"
    "proj_depth/groundtruth/image_02/"
)

print("=" * 70)
print("KITTI RGB ↔ GROUND-TRUTH DEPTH PAIR CHECK")
print("=" * 70)

# Inspect directory contents through HF API
for label, path in [("RGB", rgb_dir), ("GT DEPTH", gt_dir)]:
    url = (
        "https://huggingface.co/api/datasets/"
        "dangth2004/KITTI-Depth-Estimation/tree/main/"
        + path
        + "?recursive=false"
    )

    r = requests.get(
        url,
        timeout=30,
        headers={"User-Agent": "Mozilla/5.0"}
    )

    print(f"\n{label} directory HTTP:", r.status_code)

    if r.ok:
        entries = r.json()
        files = [
            x["path"] for x in entries
            if x.get("type") == "file"
        ]

        print("Files found:", len(files))
        print("First 10:")
        for f in files[:10]:
            print(" ", f)

        if label == "RGB":
            rgb_files = files
        else:
            gt_files = files
    else:
        print(r.text[:500])

# Find common frame names
rgb_names = {
    f.rsplit("/", 1)[-1]
    for f in rgb_files
}

gt_names = {
    f.rsplit("/", 1)[-1]
    for f in gt_files
}

common = sorted(rgb_names & gt_names)

print("\n" + "-" * 70)
print("PAIRING")
print("-" * 70)
print("RGB frames:", len(rgb_names))
print("GT depth frames:", len(gt_names))
print("Common filenames:", len(common))
print("First common frames:", common[:10])

# Download one paired example
if common:
    frame = common[0]

    rgb_url = BASE + rgb_dir + frame
    gt_url = BASE + gt_dir + frame

    print("\n" + "-" * 70)
    print("SAMPLE FRAME:", frame)
    print("-" * 70)

    rgb_r = requests.get(
        rgb_url,
        timeout=30,
        headers={"User-Agent": "Mozilla/5.0"}
    )
    gt_r = requests.get(
        gt_url,
        timeout=30,
        headers={"User-Agent": "Mozilla/5.0"}
    )

    print("RGB HTTP:", rgb_r.status_code)
    print("GT HTTP:", gt_r.status_code)

    if rgb_r.ok and gt_r.ok:
        rgb = Image.open(BytesIO(rgb_r.content))
        gt = Image.open(BytesIO(gt_r.content))

        rgb_arr = np.array(rgb)
        gt_arr = np.array(gt)

        print("RGB format:", rgb.format)
        print("RGB size:", rgb.size)
        print("RGB dtype:", rgb_arr.dtype)
        print("RGB shape:", rgb_arr.shape)

        print("\nGT format:", gt.format)
        print("GT size:", gt.size)
        print("GT dtype:", gt_arr.dtype)
        print("GT shape:", gt_arr.shape)
        print("GT min:", gt_arr.min())
        print("GT max:", gt_arr.max())
        print("GT nonzero:", np.count_nonzero(gt_arr))
        print("GT nonzero %:", round(
            100 * np.count_nonzero(gt_arr) / gt_arr.size, 2
        ))

print("\n" + "=" * 70)

import requests
from collections import defaultdict

DATASET = "dangth2004/KITTI-Depth-Estimation"

API_BASE = (
    f"https://huggingface.co/api/datasets/{DATASET}/tree/main/"
)

print("=" * 70)
print("KITTI DEPTH — COUNT ALL RGB/GT PAIRS")
print("=" * 70)

# Get all repository entries
url = API_BASE + "?recursive=true&expand=false"

r = requests.get(
    url,
    timeout=60,
    headers={"User-Agent": "Mozilla/5.0"}
)

print("Repository tree HTTP:", r.status_code)

if not r.ok:
    print(r.text[:1000])
    raise RuntimeError("Could not retrieve repository tree.")

entries = r.json()

rgb_files = []
gt_files = []

for item in entries:
    if item.get("type") != "file":
        continue

    path = item.get("path", "")

    if "/image_02/data/" in path and path.endswith(".png"):
        rgb_files.append(path)

    elif "/groundtruth/image_02/" in path and path.endswith(".png"):
        gt_files.append(path)

print("RGB files found:", len(rgb_files))
print("GT depth files found:", len(gt_files))

# Match by sequence + frame filename
def pair_key(path):
    parts = path.split("/")

    sequence = next(
        (p for p in parts if p.endswith("_sync")),
        None
    )

    frame = parts[-1]

    return (sequence, frame)

rgb_map = {
    pair_key(p): p
    for p in rgb_files
}

gt_map = {
    pair_key(p): p
    for p in gt_files
}

common_keys = sorted(
    set(rgb_map.keys()) & set(gt_map.keys())
)

print("\n" + "-" * 70)
print("PAIRING RESULTS")
print("-" * 70)
print("Unique RGB keys:", len(rgb_map))
print("Unique GT keys:", len(gt_map))
print("Exact RGB↔GT pairs:", len(common_keys))

# Sequence-level statistics
sequence_counts = defaultdict(int)

for sequence, frame in common_keys:
    sequence_counts[sequence] += 1

print("\nSequences with paired frames:", len(sequence_counts))

print("\nPairs per sequence:")
for sequence, count in sorted(sequence_counts.items()):
    print(f"  {sequence}: {count}")

# Show first 20 complete pairs
print("\n" + "-" * 70)
print("FIRST 20 COMPLETE PAIRS")
print("-" * 70)

for i, (sequence, frame) in enumerate(common_keys[:20], 1):
    print(f"[{i:02d}] {sequence} | {frame}")

print("\n" + "=" * 70)

import requests
from collections import defaultdict

DATASET = "dangth2004/KITTI-Depth-Estimation"
API = f"https://huggingface.co/api/datasets/{DATASET}/tree/main/"

HEADERS = {"User-Agent": "Mozilla/5.0"}

def list_dir(path):
    url = API + path
    r = requests.get(
        url,
        params={"recursive": "false"},
        timeout=30,
        headers=HEADERS
    )
    if not r.ok:
        print("ERROR", r.status_code, path)
        return []
    return r.json()

print("=" * 70)
print("KITTI DEPTH — COMPLETE DIRECTORY INVENTORY")
print("=" * 70)

# 1. Raw-data root
raw_entries = list_dir("raw_data")

print("\nraw_data entries:", len(raw_entries))

sequences = []

for item in raw_entries:
    if item.get("type") == "directory":
        sequences.append(item["path"])

print("Top-level raw-data directories:", len(sequences))

# The repository uses:
# raw_data/YYYY_MM_DD/DRIVE_sync/image_02/data/
date_dirs = []

for path in sequences:
    if path.startswith("raw_data/"):
        date_dirs.append(path)

# 2. Enumerate date directories
all_drive_dirs = []

for date_dir in date_dirs:
    entries = list_dir(date_dir)

    for item in entries:
        if (
            item.get("type") == "directory"
            and item["path"].endswith("_sync")
        ):
            all_drive_dirs.append(item["path"])

print("Drive directories found:", len(all_drive_dirs))

# 3. Enumerate image_02/data directories
rgb_files = []

for i, drive in enumerate(all_drive_dirs, 1):
    image_dir = drive + "/image_02/data"
    entries = list_dir(image_dir)

    for item in entries:
        if (
            item.get("type") == "file"
            and item["path"].endswith(".png")
        ):
            rgb_files.append(item["path"])

print("RGB image files found:", len(rgb_files))

# 4. Enumerate annotated GT directories from known structure
gt_root_entries = list_dir("data_depth_annotated/train")

gt_drive_dirs = [
    item["path"]
    for item in gt_root_entries
    if item.get("type") == "directory"
]

print("GT drive directories found:", len(gt_drive_dirs))

gt_files = []

for drive in gt_drive_dirs:
    gt_dir = drive + "/proj_depth/groundtruth/image_02"
    entries = list_dir(gt_dir)

    for item in entries:
        if (
            item.get("type") == "file"
            and item["path"].endswith(".png")
        ):
            gt_files.append(item["path"])

print("GT depth files found:", len(gt_files))

# 5. Match sequence + frame number
def key(path):
    parts = path.split("/")
    drive = next(
        (p for p in parts if p.endswith("_sync")),
        None
    )
    frame = parts[-1]
    return (drive, frame)

rgb_map = {key(p): p for p in rgb_files}
gt_map = {key(p): p for p in gt_files}

common = sorted(set(rgb_map) & set(gt_map))

print("\n" + "-" * 70)
print("FINAL PAIR COUNT")
print("-" * 70)
print("RGB frames:", len(rgb_map))
print("GT frames:", len(gt_map))
print("Exact RGB ↔ GT pairs:", len(common))

seq_counts = defaultdict(int)

for drive, frame in common:
    seq_counts[drive] += 1

print("\nSequences with paired frames:", len(seq_counts))

for drive, count in sorted(seq_counts.items()):
    print(f"  {drive}: {count}")

print("\nFirst 20 paired frames:")
for i, (drive, frame) in enumerate(common[:20], 1):
    print(f"[{i:02d}] {drive} | {frame}")

print("\n" + "=" * 70)

import os
import json
import csv
import random

BASE_DIR = "/content/module8_eval"
SUBSET_DIR = os.path.join(BASE_DIR, "EXP_001_subset_100")

os.makedirs(SUBSET_DIR, exist_ok=True)

SEED = 42
TARGET_N = 100

# Reconstruct paired paths from the variables created in the previous cell.
# rgb_map and gt_map contain exact sequence+frame matches.

common_keys = sorted(
    set(rgb_map.keys()) & set(gt_map.keys())
)

assert len(common_keys) >= TARGET_N, (
    f"Only {len(common_keys)} paired frames available."
)

# Fixed reproducible selection
rng = random.Random(SEED)
selected = rng.sample(common_keys, TARGET_N)

# Keep deterministic ordering in the saved manifest
selected = sorted(selected)

records = []

for idx, (drive, frame) in enumerate(selected, start=1):
    rgb_path = rgb_map[(drive, frame)]
    gt_path = gt_map[(drive, frame)]

    records.append({
        "sample_index": idx,
        "sequence": drive,
        "frame": frame,
        "rgb_path": rgb_path,
        "gt_depth_path": gt_path
    })

# Save JSON
json_path = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.json"
)

with open(json_path, "w") as f:
    json.dump(
        {
            "dataset": "KITTI Depth",
            "split": "training_annotated",
            "seed": SEED,
            "num_images": TARGET_N,
            "records": records
        },
        f,
        indent=2
    )

# Save CSV
csv_path = os.path.join(
    SUBSET_DIR,
    "EXP_001_ground_truth.csv"
)

with open(csv_path, "w", newline="") as f:
    writer = csv.DictWriter(
        f,
        fieldnames=records[0].keys()
    )
    writer.writeheader()
    writer.writerows(records)

print("=" * 70)
print("KITTI DEPTH — FIXED 100-IMAGE SUBSET")
print("=" * 70)

print("Seed:", SEED)
print("Total paired frames available:", len(common_keys))
print("Selected images:", len(records))

print("\nFirst 20 selected samples:")
for r in records[:20]:
    print(
        f"[{r['sample_index']:03d}] "
        f"{r['sequence']} | {r['frame']}"
    )

print("\nSaved:")
print(json_path)
print(csv_path)

print("\n" + "=" * 70)

import os
import json
import requests
from PIL import Image
from io import BytesIO

BASE_URL = (
    "https://huggingface.co/datasets/"
    "dangth2004/KITTI-Depth-Estimation/resolve/main/"
)

RGB_DIR = os.path.join(SUBSET_DIR, "images")
GT_DIR = os.path.join(SUBSET_DIR, "depth_gt")

os.makedirs(RGB_DIR, exist_ok=True)
os.makedirs(GT_DIR, exist_ok=True)

with open(json_path, "r") as f:
    manifest = json.load(f)

records = manifest["records"]

print("=" * 70)
print("KITTI DEPTH — DOWNLOADING FIXED 100-IMAGE SUBSET")
print("=" * 70)

session = requests.Session()
session.headers.update({"User-Agent": "Mozilla/5.0"})

downloaded = []
failed = []

for i, rec in enumerate(records, 1):

    rgb_out = os.path.join(
        RGB_DIR,
        f"{rec['sample_index']:03d}.png"
    )

    gt_out = os.path.join(
        GT_DIR,
        f"{rec['sample_index']:03d}.png"
    )

    try:
        # RGB
        rgb_url = BASE_URL + rec["rgb_path"]
        r_rgb = session.get(rgb_url, timeout=60)
        r_rgb.raise_for_status()

        rgb = Image.open(BytesIO(r_rgb.content)).convert("RGB")
        rgb.save(rgb_out)

        # Ground truth depth
        gt_url = BASE_URL + rec["gt_depth_path"]
        r_gt = session.get(gt_url, timeout=60)
        r_gt.raise_for_status()

        gt = Image.open(BytesIO(r_gt.content))

        if gt.mode != "I;16":
            # Preserve the uint16 depth values if PIL reports another
            # compatible mode.
            gt_arr = __import__("numpy").array(gt)
            if gt_arr.dtype != __import__("numpy").uint16:
                raise ValueError(
                    f"Unexpected GT dtype: {gt_arr.dtype}"
                )
            gt.save(gt_out)
        else:
            gt.save(gt_out)

        downloaded.append(rec["sample_index"])

        if i <= 10 or i % 10 == 0:
            print(
                f"[{i:03d}/100] "
                f"{rec['sequence']} | {rec['frame']} | OK"
            )

    except Exception as e:
        failed.append({
            "sample_index": rec["sample_index"],
            "error": str(e)
        })
        print(
            f"[{i:03d}/100] "
            f"{rec['sequence']} | {rec['frame']} | FAILED: {e}"
        )

print("\n" + "-" * 70)
print("DOWNLOAD SUMMARY")
print("-" * 70)
print("RGB + GT pairs downloaded:", len(downloaded))
print("Failed pairs:", len(failed))

if failed:
    print("\nFailures:")
    for item in failed:
        print(item)

print("\nRGB directory:", RGB_DIR)
print("GT directory:", GT_DIR)

print("\n" + "=" * 70)

import os
import json
import numpy as np
from PIL import Image

print("=" * 70)
print("KITTI DEPTH — SUBSET INTEGRITY CHECK")
print("=" * 70)

image_files = sorted([
    f for f in os.listdir(RGB_DIR)
    if f.endswith(".png")
])

gt_files = sorted([
    f for f in os.listdir(GT_DIR)
    if f.endswith(".png")
])

print("RGB files:", len(image_files))
print("GT files:", len(gt_files))

valid = 0
invalid = []
widths = []
heights = []
gt_nonzero_ratios = []
gt_max_values = []
gt_min_positive = []

for name in image_files:
    try:
        rgb = np.array(
            Image.open(os.path.join(RGB_DIR, name))
        )

        gt = np.array(
            Image.open(os.path.join(GT_DIR, name))
        )

        if rgb.ndim != 3 or rgb.shape[2] != 3:
            raise ValueError(f"RGB shape {rgb.shape}")

        if gt.ndim != 2:
            raise ValueError(f"GT shape {gt.shape}")

        if rgb.shape[:2] != gt.shape:
            raise ValueError(
                f"Size mismatch: RGB={rgb.shape[:2]}, GT={gt.shape}"
            )

        if gt.dtype != np.uint16:
            raise ValueError(
                f"GT dtype is {gt.dtype}, expected uint16"
            )

        positive = gt[gt > 0]

        if len(positive) == 0:
            raise ValueError("GT contains no positive depth")

        valid += 1
        heights.append(rgb.shape[0])
        widths.append(rgb.shape[1])
        gt_nonzero_ratios.append(
            100.0 * len(positive) / gt.size
        )
        gt_max_values.append(int(gt.max()))
        gt_min_positive.append(int(positive.min()))

    except Exception as e:
        invalid.append((name, str(e)))

print("\n" + "-" * 70)
print("RESULT")
print("-" * 70)

print("Valid pairs:", valid)
print("Invalid pairs:", len(invalid))

if invalid:
    print("\nInvalid files:")
    for item in invalid[:20]:
        print(item)

print("\nImage dimensions:")
print("  Unique widths:", sorted(set(widths)))
print("  Unique heights:", sorted(set(heights)))

print("\nGround-truth depth encoding:")
print("  dtype:", "uint16")
print("  Minimum positive stored value:",
      min(gt_min_positive))
print("  Maximum stored value:",
      max(gt_max_values))
print("  Mean nonzero coverage:",
      round(float(np.mean(gt_nonzero_ratios)), 2), "%")
print("  Minimum nonzero coverage:",
      round(float(np.min(gt_nonzero_ratios)), 2), "%")
print("  Maximum nonzero coverage:",
      round(float(np.max(gt_nonzero_ratios)), 2), "%")

# Examine the first valid depth map in more detail
sample_gt = np.array(
    Image.open(os.path.join(GT_DIR, image_files[0]))
)

positive = sample_gt[sample_gt > 0]

print("\nFirst sample:", image_files[0])
print("  GT shape:", sample_gt.shape)
print("  GT dtype:", sample_gt.dtype)
print("  Positive pixels:", len(positive))
print("  Stored min:", int(positive.min()))
print("  Stored max:", int(positive.max()))
print("  Stored median:", float(np.median(positive)))

print("\n" + "=" * 70)

import numpy as np
from PIL import Image
import os

print("=" * 70)
print("KITTI DEPTH — DEPTH SCALE VERIFICATION")
print("=" * 70)

# KITTI depth PNGs are commonly stored as integer depth values.
# We will inspect whether values are consistent with a millimeter-like
# scale by converting the stored values using candidate divisors.

DIVISORS = [1.0, 256.0, 1000.0]

all_positive = []

for name in sorted(os.listdir(GT_DIR)):
    if not name.endswith(".png"):
        continue

    gt = np.array(
        Image.open(os.path.join(GT_DIR, name)),
        dtype=np.uint16
    )

    positive = gt[gt > 0].astype(np.float64)

    if len(positive):
        all_positive.append(positive)

all_positive = np.concatenate(all_positive)

print("Total positive depth samples:", len(all_positive))
print("Stored-value statistics:")
print("  min:", float(all_positive.min()))
print("  median:", float(np.median(all_positive)))
print("  mean:", float(np.mean(all_positive)))
print("  max:", float(all_positive.max()))

print("\nCandidate physical-depth scales:")

for divisor in DIVISORS:
    depth_m = all_positive / divisor

    print(
        f"\n  divisor={divisor:g}"
        f"\n    min:    {depth_m.min():.4f} m"
        f"\n    median: {np.median(depth_m):.4f} m"
        f"\n    mean:   {np.mean(depth_m):.4f} m"
        f"\n    max:    {depth_m.max():.4f} m"
    )

# Inspect a representative frame at several image locations
sample_name = "001.png"
sample = np.array(
    Image.open(os.path.join(GT_DIR, sample_name)),
    dtype=np.uint16
)

h, w = sample.shape

points = [
    ("center", h // 2, w // 2),
    ("lower-center", int(h * 0.75), w // 2),
    ("lower-left", int(h * 0.75), int(w * 0.25)),
    ("lower-right", int(h * 0.75), int(w * 0.75)),
]

print("\n" + "-" * 70)
print("REPRESENTATIVE STORED VALUES —", sample_name)
print("-" * 70)

for label, y, x in points:
    value = int(sample[y, x])
    print(
        f"{label:15s} pixel=({x},{y}) "
        f"stored={value}"
    )

print("\n" + "=" * 70)

import os
