print("=" * 70)

stats = []

for name in sorted(os.listdir(GT_DIR)):
    if not name.endswith(".png"):
        continue

    gt = np.array(
        Image.open(os.path.join(GT_DIR, name)),
        dtype=np.uint16
    )

    positive = gt[gt > 0].astype(np.float64)

    depth_m = positive / 256.0

    stats.append({
        "file": name,
        "valid_pixels": len(positive),
        "coverage_pct": 100.0 * len(positive) / gt.size,
        "min_m": float(depth_m.min()),
        "median_m": float(np.median(depth_m)),
        "mean_m": float(np.mean(depth_m)),
        "max_m": float(depth_m.max())
    })

print("Images checked:", len(stats))

print("\nPer-image metric-depth range:")
print(
    "  Minimum image median:",
    round(min(x["median_m"] for x in stats), 3), "m"
)
print(
    "  Maximum image median:",
    round(max(x["median_m"] for x in stats), 3), "m"
)
print(
    "  Minimum image max:",
    round(min(x["max_m"] for x in stats), 3), "m"
)
print(
    "  Maximum image max:",
    round(max(x["max_m"] for x in stats), 3), "m"
)

print("\nFirst 10 images:")
for x in stats[:10]:
    print(
        f"{x['file']} | "
        f"coverage={x['coverage_pct']:.2f}% | "
        f"median={x['median_m']:.2f}m | "
        f"max={x['max_m']:.2f}m"
    )

# Save the verified scale information
scale_record = {
    "dataset": "KITTI Depth",
    "depth_storage_dtype": "uint16",
    "depth_scale_divisor": 256.0,
    "metric_unit": "meters",
    "num_images": len(stats),
    "aggregate_positive_pixels": int(
        sum(x["valid_pixels"] for x in stats)
    ),
    "images": stats
}

scale_path = os.path.join(
    RESULT_DIR,
    "EXP_001_depth_scale_verification.json"
)

with open(scale_path, "w") as f:
    import json
    json.dump(scale_record, f, indent=2)

print("\nSaved:", scale_path)
print("\n" + "=" * 70)

