print("Input:", sample_path)
print("Image size:", image.size)

inputs = processor(
    images=image,
    return_tensors="pt"
)

inputs = {
    k: v.to(device)
    for k, v in inputs.items()
}

# Warm-up
with torch.no_grad():
    _ = model(**inputs)

torch.cuda.synchronize() if device.type == "cuda" else None

# Timed inference
start = time.perf_counter()

with torch.no_grad():
    outputs = model(**inputs)

torch.cuda.synchronize() if device.type == "cuda" else None

elapsed_ms = (time.perf_counter() - start) * 1000

pred = outputs.predicted_depth

print("\nRaw model output:")
print("  Type:", type(pred))
print("  Shape:", tuple(pred.shape))
print("  Dtype:", pred.dtype)
print("  Device:", pred.device)

pred_np = pred.detach().float().cpu().numpy()

print("\nRaw depth statistics:")
print("  Min:", float(np.min(pred_np)))
print("  Max:", float(np.max(pred_np)))
print("  Mean:", float(np.mean(pred_np)))
print("  Median:", float(np.median(pred_np)))
print("  Finite:", bool(np.isfinite(pred_np).all()))

print("\nTiming:")
print("  Inference latency:", round(elapsed_ms, 2), "ms")

