import os
import time
import numpy as np
import torch
from PIL import Image

print("=" * 70)
print("MODULE 8 — UNIDEPTH V2 METRIC-DEPTH SANITY TEST")
print("=" * 70)

sample_path = os.path.join(RGB_DIR, "001.png")
image = Image.open(sample_path).convert("RGB")

print("Input:", sample_path)
print("Image size:", image.size)

# UniDepth expects a tensor in [C,H,W].
# Convert RGB image to float tensor in [0,1].
image_np = np.asarray(image).astype(np.float32) / 255.0

image_tensor = torch.from_numpy(
    image_np
).permute(2, 0, 1).unsqueeze(0).to(device)

# Warm-up
with torch.no_grad():
    prediction = model_metric.infer(
        image_tensor
    )

if device.type == "cuda":
    torch.cuda.synchronize()

start = time.perf_counter()

with torch.no_grad():
    prediction = model_metric.infer(
        image_tensor
    )

if device.type == "cuda":
    torch.cuda.synchronize()

elapsed_ms = (time.perf_counter() - start) * 1000

print("\nPrediction keys:")
print(list(prediction.keys()))

for key, value in prediction.items():
    if torch.is_tensor(value):
        print(
            f"  {key}: shape={tuple(value.shape)}, "
            f"dtype={value.dtype}, device={value.device}"
        )
    else:
        print(
            f"  {key}: type={type(value)}"
        )

# Inspect the metric depth output if present
if "depth" in prediction:
    depth = prediction["depth"]

    depth_np = depth.detach().float().cpu().numpy()

    print("\nMetric depth output:")
    print("  Shape:", depth_np.shape)
    print("  Min:", float(np.nanmin(depth_np)))
    print("  Max:", float(np.nanmax(depth_np)))
    print("  Mean:", float(np.nanmean(depth_np)))
    print("  Median:", float(np.nanmedian(depth_np)))
    print("  Finite:", bool(np.isfinite(depth_np).all()))

print("\nInference latency:")
print(" ", round(elapsed_ms, 2), "ms")

print("\n" + "=" * 70)

import os
import json
import numpy as np
import torch
from PIL import Image

print("=" * 70)
print("MODULE 8 — SINGLE-IMAGE KITTI DEPTH METRIC TEST")
print("=" * 70)

sample_id = "001.png"

# -----------------------------
# Load RGB
# -----------------------------
image_path = os.path.join(RGB_DIR, sample_id)
image = Image.open(image_path).convert("RGB")

image_np = np.asarray(image).astype(np.float32) / 255.0
image_tensor = (
    torch.from_numpy(image_np)
    .permute(2, 0, 1)
    .unsqueeze(0)
    .to(device)
)

# -----------------------------
# Model inference
# -----------------------------
with torch.no_grad():
    prediction = model_metric.infer(image_tensor)

pred_depth = (
    prediction["depth"]
    .squeeze()
    .detach()
    .float()
    .cpu()
    .numpy()
)

# -----------------------------
# Load KITTI GT
# Stored value / 256 = meters
# -----------------------------
gt_raw = np.array(
    Image.open(os.path.join(GT_DIR, sample_id)),
    dtype=np.uint16
)

gt_depth = gt_raw.astype(np.float32) / 256.0

# -----------------------------
# Valid KITTI pixels
# -----------------------------
valid = (
    np.isfinite(gt_depth)
    & np.isfinite(pred_depth)
    & (gt_depth > 0)
    & (pred_depth > 0)
)

gt = gt_depth[valid]
pred = pred_depth[valid]

print("Image:", sample_id)
print("RGB shape:", image_np.shape)
print("Prediction shape:", pred_depth.shape)
print("GT shape:", gt_depth.shape)

print("\nValid pixels:", len(gt))
print(
    "Valid coverage:",
    round(100.0 * valid.mean(), 2),
    "%"
)

# -----------------------------
# Standard depth metrics
# -----------------------------
abs_rel = np.mean(np.abs(gt - pred) / gt)

sq_rel = np.mean(
    ((gt - pred) ** 2) / gt
)

rmse = np.sqrt(
    np.mean((gt - pred) ** 2)
)

rmse_log = np.sqrt(
    np.mean(
        (np.log(gt) - np.log(pred)) ** 2
    )
)

ratio = np.maximum(
    gt / pred,
    pred / gt
)

delta1 = np.mean(ratio < 1.25)
delta2 = np.mean(ratio < 1.25 ** 2)
delta3 = np.mean(ratio < 1.25 ** 3)

mae = np.mean(np.abs(gt - pred))

print("\n" + "-" * 70)
print("DEPTH METRICS")
print("-" * 70)

print(f"MAE:       {mae:.4f} m")
print(f"Abs Rel:   {abs_rel:.4f}")
print(f"Sq Rel:    {sq_rel:.4f}")
print(f"RMSE:      {rmse:.4f} m")
print(f"RMSE log:  {rmse_log:.4f}")
print(f"δ < 1.25:  {delta1:.4f}")
print(f"δ < 1.25²: {delta2:.4f}")
print(f"δ < 1.25³: {delta3:.4f}")

print("\nDepth ranges:")
print(
    f"GT:   {gt.min():.2f}–{gt.max():.2f} m"
)
print(
    f"Pred: {pred.min():.2f}–{pred.max():.2f} m"
)

print("\n" + "=" * 70)

import os
import csv
import json
import time
import numpy as np
import torch
from PIL import Image

print("=" * 70)
print("MODULE 8 — FULL 100-IMAGE KITTI DEPTH EVALUATION")
print("=" * 70)

results = []

total_start = time.perf_counter()

for i in range(1, 101):

    sample_id = f"{i:03d}.png"

    image_path = os.path.join(RGB_DIR, sample_id)
    gt_path = os.path.join(GT_DIR, sample_id)

    image = Image.open(image_path).convert("RGB")

    image_np = (
        np.asarray(image).astype(np.float32) / 255.0
    )

    image_tensor = (
        torch.from_numpy(image_np)
        .permute(2, 0, 1)
        .unsqueeze(0)
        .to(device)
    )

    # Synchronize before timing
    if device.type == "cuda":
        torch.cuda.synchronize()

    start = time.perf_counter()

    with torch.no_grad():
        prediction = model_metric.infer(
            image_tensor
        )

    if device.type == "cuda":
        torch.cuda.synchronize()

    latency_ms = (
        time.perf_counter() - start
    ) * 1000.0

    pred_depth = (
        prediction["depth"]
        .squeeze()
        .detach()
        .float()
        .cpu()
        .numpy()
    )

    # KITTI stored depth -> meters
    gt_raw = np.array(
        Image.open(gt_path),
        dtype=np.uint16
    )

    gt_depth = (
        gt_raw.astype(np.float32) / 256.0
    )

    valid = (
        np.isfinite(gt_depth)
        & np.isfinite(pred_depth)
        & (gt_depth > 0)
        & (pred_depth > 0)
    )

    gt = gt_depth[valid]
    pred = pred_depth[valid]

    if len(gt) == 0:
        print(
            f"[{i:03d}/100] {sample_id} | "
            "NO VALID PIXELS"
        )
        continue

    abs_rel = np.mean(
        np.abs(gt - pred) / gt
    )

    sq_rel = np.mean(
        ((gt - pred) ** 2) / gt
    )

    rmse = np.sqrt(
        np.mean((gt - pred) ** 2)
    )

    rmse_log = np.sqrt(
        np.mean(
            (np.log(gt) - np.log(pred)) ** 2
        )
    )

    ratio = np.maximum(
        gt / pred,
        pred / gt
    )

    delta1 = np.mean(ratio < 1.25)
    delta2 = np.mean(ratio < 1.25 ** 2)
    delta3 = np.mean(ratio < 1.25 ** 3)

    mae = np.mean(np.abs(gt - pred))

    results.append({
        "sample_index": i,
        "file": sample_id,
        "valid_pixels": int(len(gt)),
        "valid_coverage_pct": float(
            100.0 * valid.mean()
        ),
        "mae_m": float(mae),
        "abs_rel": float(abs_rel),
        "sq_rel": float(sq_rel),
        "rmse_m": float(rmse),
        "rmse_log": float(rmse_log),
        "delta1": float(delta1),
        "delta2": float(delta2),
        "delta3": float(delta3),
        "latency_ms": float(latency_ms)
    })

    if i <= 10 or i % 10 == 0:
        print(
            f"[{i:03d}/100] "
            f"AbsRel={abs_rel:.4f} | "
            f"RMSE={rmse:.2f}m | "
            f"δ1={delta1:.4f} | "
            f"{latency_ms:.1f} ms"
        )

total_elapsed = time.perf_counter() - total_start

print("\n" + "-" * 70)
print("RUN COMPLETE")
print("-" * 70)

print("Images evaluated:", len(results))
print(
    "Total elapsed:",
    round(total_elapsed, 2),
    "seconds"
)

# ---------------------------------------------------------
# Aggregate metrics: mean over images
# ---------------------------------------------------------

metric_keys = [
    "mae_m",
    "abs_rel",
    "sq_rel",
    "rmse_m",
    "rmse_log",
    "delta1",
    "delta2",
    "delta3"
]

summary = {}

for key in metric_keys:
    summary[key] = float(
        np.mean([r[key] for r in results])
    )

latencies = np.array([
    r["latency_ms"]
    for r in results
])

summary["avg_latency_ms"] = float(
    np.mean(latencies)
)

summary["median_latency_ms"] = float(
    np.median(latencies)
)

summary["fps"] = float(
    1000.0 / summary["avg_latency_ms"]
)

summary["num_images"] = len(results)
summary["seed"] = 42
summary["model"] = MODEL_ID
summary["depth_scale_divisor"] = 256.0
summary["gt_unit"] = "meters"

# ---------------------------------------------------------
# Save outputs
# ---------------------------------------------------------

pred_json = os.path.join(
    RESULT_DIR,
    "EXP_001_predictions.json"
)

pred_csv = os.path.join(
    RESULT_DIR,
    "EXP_001_predictions.csv"
)

summary_json = os.path.join(
    RESULT_DIR,
    "EXP_001_summary.json"
)

with open(pred_json, "w") as f:
    json.dump(results, f, indent=2)

with open(pred_csv, "w", newline="") as f:
    writer = csv.DictWriter(
        f,
        fieldnames=results[0].keys()
    )
    writer.writeheader()
    writer.writerows(results)

with open(summary_json, "w") as f:
    json.dump(summary, f, indent=2)

print("\nAggregate metrics:")
for key in metric_keys:
    print(f"  {key}: {summary[key]:.6f}")

print("\nTiming:")
print(
    f"  Average:  {summary['avg_latency_ms']:.2f} ms"
)
print(
    f"  Median:   {summary['median_latency_ms']:.2f} ms"
)
print(
    f"  FPS:      {summary['fps']:.2f}"
)

print("\nSaved:")
print(pred_json)
print(pred_csv)
print(summary_json)

print("\n" + "=" * 70)

