# ============================================================
# REAL-WORLD VALIDATION — DOWNLOAD INTERNET STREET IMAGES
# Source: Cityscapes public example images
# ============================================================

import os
import requests
import pandas as pd
from bs4 import BeautifulSoup
from PIL import Image
from io import BytesIO

BASE_DIR = "/content/real_world_eval"
IMG_DIR = f"{BASE_DIR}/images"

os.makedirs(IMG_DIR, exist_ok=True)

URL = "https://www.cityscapes-dataset.com/examples/"

print("Downloading Cityscapes public example page...")
r = requests.get(URL, timeout=30)
r.raise_for_status()

soup = BeautifulSoup(r.text, "html.parser")

image_urls = []
for img in soup.find_all("img"):
    src = img.get("src")
    if not src:
        continue

    if src.startswith("//"):
        src = "https:" + src
    elif src.startswith("/"):
        src = "https://www.cityscapes-dataset.com" + src

    if src.lower().endswith((".png", ".jpg", ".jpeg")):
        image_urls.append(src)

# Remove duplicates while preserving order
image_urls = list(dict.fromkeys(image_urls))

print("Candidate images found:", len(image_urls))

downloaded = []

for url in image_urls:
    if len(downloaded) >= 50:
        break

    try:
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()

        img = Image.open(BytesIO(resp.content)).convert("RGB")

        idx = len(downloaded) + 1
        image_id = f"RW_{idx:03d}"
        filename = f"{image_id}.jpg"
        path = os.path.join(IMG_DIR, filename)

        img.save(path, quality=95)

        downloaded.append({
            "image_id": image_id,
            "filename": filename,
            "category": "outdoor_road",
            "source": "Cityscapes",
            "source_url": url,
            "ground_truth_source": "Cityscapes public example page",
            "width": img.width,
            "height": img.height
        })

        print(f"[{len(downloaded):02d}/50] {filename} | {img.size}")

    except Exception as e:
        print("FAILED:", url, "|", str(e)[:120])

manifest_path = f"{BASE_DIR}/REAL_WORLD_MASTER_MANIFEST.csv"

df = pd.DataFrame(downloaded)
df.to_csv(manifest_path, index=False)

print()
print("=" * 60)
print("DOWNLOAD COMPLETE")
print("=" * 60)
print("Images downloaded:", len(downloaded))
print("Manifest:", manifest_path)
print("Image directory:", IMG_DIR)

