    url = f"https://huggingface.co/api/datasets/{repo}/tree/main?recursive=true&expand=false"
    r = requests.get(url, timeout=30)

    print("HTTP:", r.status_code)

    if r.status_code != 200:
        print("ERROR:", r.text[:300])
        continue

    files = r.json()

    print("Total entries:", len(files))

    # Show representative image/depth files
    image_files = []
    depth_files = []

    for item in files:
        path = item.get("path", "")
        lower = path.lower()

        if lower.endswith((".jpg", ".jpeg", ".png")):
            if any(x in lower for x in ["depth", "gt", "disp", "velodyne"]):
                depth_files.append(path)
            else:
                image_files.append(path)

    print("Image-like files:", len(image_files))
    print("Depth/GT-like files:", len(depth_files))

    print("\nFirst 10 image files:")
    for x in image_files[:10]:
        print(" ", x)

    print("\nFirst 10 depth/GT files:")
    for x in depth_files[:10]:
        print(" ", x)

