r.raise_for_status()
files = r.json()

print("Total entries returned:", len(files))

# Classify files
jpg_files = []
png_files = []
rgb_candidates = []
depth_candidates = []

for item in files:
    path = item.get("path", "")
    lower = path.lower()

    if lower.endswith((".jpg", ".jpeg")):
        jpg_files.append(path)

    if lower.endswith(".png"):
        png_files.append(path)

    if any(x in lower for x in [
        "image_02/data",
        "image_03/data",
        "image_02/",
        "image_03/"
    ]):
        if lower.endswith((".jpg", ".jpeg", ".png")):
            rgb_candidates.append(path)

    if any(x in lower for x in [
        "groundtruth",
        "depth",
        "proj_depth"
    ]):
        if lower.endswith(".png"):
            depth_candidates.append(path)

print()
print("JPG/JPEG files       :", len(jpg_files))
print("PNG files            :", len(png_files))
