# ============================================================
# KITTI MIRROR — PAGINATED REPOSITORY INSPECTION
# ============================================================

import requests

repo = "dangth2004/KITTI-Depth-Estimation"

all_files = []
cursor = None

print("=" * 70)
print("KITTI REPOSITORY PAGINATED INVENTORY")
print("=" * 70)

for page in range(20):
    url = f"https://huggingface.co/api/datasets/{repo}/tree/main"

    params = {
        "recursive": "true",
        "expand": "false",
        "limit": 1000
    }

    if cursor:
        params["cursor"] = cursor

    r = requests.get(url, params=params, timeout=60)

    print(f"Page {page + 1}: HTTP {r.status_code}")

    if r.status_code != 200:
        print(r.text[:500])
        break

    data = r.json()

    if isinstance(data, dict):
        print("Unexpected response:", data)
        break

    all_files.extend(data)

    # Hugging Face pagination cursor
    cursor = r.headers.get("x-linked-next")

    if not cursor or len(data) == 0:
        break

print()
print("Total entries collected:", len(all_files))

jpg_files = []
jpeg_files = []
png_files = []

for item in all_files:
    path = item.get("path", "")
    lower = path.lower()

    if lower.endswith(".jpg"):
        jpg_files.append(path)
    elif lower.endswith(".jpeg"):
        jpeg_files.append(path)
    elif lower.endswith(".png"):
        png_files.append(path)

print("JPG files :", len(jpg_files))
print("JPEG files:", len(jpeg_files))
print("PNG files :", len(png_files))

print("\nFirst 20 JPG/JPEG files:")
for p in (jpg_files + jpeg_files)[:20]:
    print(" ", p)

print("\nFirst 20 PNG files:")
for p in png_files[:20]:
    print(" ", p)

print("\nRepresentative directories:")
dirs = sorted(set(
    "/".join(p.split("/")[:5])
    for p in [x.get("path", "") for x in all_files]
    if "/" in p
))

for d in dirs[:50]:
    print(" ", d)

