import os
import requests
from tqdm.auto import tqdm

BASE_DIR = "/content/real_world_eval"
COCO_DIR = f"{BASE_DIR}/coco2017"
os.makedirs(COCO_DIR, exist_ok=True)

URL = "http://images.cocodataset.org/annotations/annotations_trainval2017.zip"
ZIP_PATH = f"{COCO_DIR}/annotations_trainval2017.zip"

print("=" * 70)
print("DOWNLOADING COCO 2017 ANNOTATIONS")
print("=" * 70)

if not os.path.exists(ZIP_PATH):
    r = requests.get(URL, stream=True, timeout=60)
    print("HTTP:", r.status_code)
    r.raise_for_status()

    total = int(r.headers.get("content-length", 0))

    with open(ZIP_PATH, "wb") as f:
        with tqdm(
            total=total,
            unit="B",
            unit_scale=True,
            desc="COCO annotations"
        ) as pbar:
            for chunk in r.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    f.write(chunk)
                    pbar.update(len(chunk))

    print("Downloaded:", ZIP_PATH)
else:
    print("Already downloaded:", ZIP_PATH)

print("Size: %.2f MB" % (os.path.getsize(ZIP_PATH) / 1024 / 1024))

