import os
import json
import random
import pandas as pd

BASE_DIR = "/content/real_world_eval"
COCO_DIR = f"{BASE_DIR}/coco2017"
VAL_ANN = f"{COCO_DIR}/annotations/instances_val2017.json"

SEED = 42
N_IMAGES = 50

with open(VAL_ANN, "r") as f:
    coco = json.load(f)

images = coco["images"]
annotations = coco["annotations"]

# Images with at least one annotation
annotated_ids = sorted(set(a["image_id"] for a in annotations))

# Reproducible selection
rng = random.Random(SEED)
selected_ids = rng.sample(annotated_ids, N_IMAGES)

# Keep deterministic ordering
selected_ids = sorted(selected_ids)

image_lookup = {img["id"]: img for img in images}

category_lookup = {
    c["id"]: c["name"]
    for c in coco["categories"]
}

rows = []

for idx, image_id in enumerate(selected_ids, start=1):
    img = image_lookup[image_id]

    anns = [
        a for a in annotations
        if a["image_id"] == image_id
    ]

    category_names = sorted(set(
        category_lookup[a["category_id"]]
        for a in anns
    ))

    rows.append({
        "image_id": f"RW_{idx:03d}",
        "coco_image_id": image_id,
        "filename": img["file_name"],
        "width": img["width"],
        "height": img["height"],
        "num_annotations": len(anns),
        "categories": "|".join(category_names),
        "source": "COCO 2017 validation",
        "source_url": img["coco_url"],
        "ground_truth_source": "COCO 2017 instances_val2017.json"
    })

df = pd.DataFrame(rows)

manifest_path = f"{BASE_DIR}/REAL_WORLD_COCO_MANIFEST.csv"
df.to_csv(manifest_path, index=False)

print("=" * 70)
print("COCO REAL-WORLD SUBSET")
print("=" * 70)
print("Seed:", SEED)
print("Selected images:", len(df))
print("Manifest:", manifest_path)

print("\nSelected images:")
print(df[[
    "image_id",
    "coco_image_id",
    "filename",
    "num_annotations",
    "categories"
]].to_string(index=False))

