# REAL-WORLD VALIDATION — DOWNLOAD 50 COCO IMAGES
# ============================================================

import os
import requests
import pandas as pd
from PIL import Image
from io import BytesIO
from tqdm.auto import tqdm

BASE_DIR = "/content/real_world_eval"
IMG_DIR = f"{BASE_DIR}/images"
MANIFEST = f"{BASE_DIR}/REAL_WORLD_COCO_MANIFEST.csv"

os.makedirs(IMG_DIR, exist_ok=True)

df = pd.read_csv(MANIFEST)

print("=" * 70)
print("DOWNLOADING COCO 2017 REAL-WORLD IMAGES")
print("=" * 70)

results = []

for _, row in tqdm(
    df.iterrows(),
    total=len(df),
    desc="COCO images"
):
    image_id = row["image_id"]
    filename = row["filename"]
    url = row["source_url"]

    path = os.path.join(IMG_DIR, filename)

    try:
        if not os.path.exists(path):
            r = requests.get(url, timeout=60)
            r.raise_for_status()

            img = Image.open(BytesIO(r.content)).convert("RGB")
            img.save(path, quality=95)
        else:
            img = Image.open(path).convert("RGB")

        results.append({
            "image_id": image_id,
            "filename": filename,
            "status": "ok",
            "width": img.width,
            "height": img.height,
            "bytes": os.path.getsize(path)
        })

    except Exception as e:
        results.append({
            "image_id": image_id,
            "filename": filename,
            "status": "failed",
            "width": None,
            "height": None,
            "bytes": None,
            "error": str(e)
        })

download_df = pd.DataFrame(results)

download_df.to_csv(
    f"{BASE_DIR}/REAL_WORLD_COCO_DOWNLOAD_STATUS.csv",
    index=False
)

print()
print("=" * 70)
print("DOWNLOAD SUMMARY")
print("=" * 70)
print("Requested:", len(df))
print("Successful:", (download_df["status"] == "ok").sum())
print("Failed:", (download_df["status"] == "failed").sum())

print("\nDownloaded image dimensions:")
print(
    download_df[download_df["status"] == "ok"]
    [["width", "height"]]
    .value_counts()
    .head(20)
)

print("\nStatus file:")
print(f"{BASE_DIR}/REAL_WORLD_COCO_DOWNLOAD_STATUS.csv")

# ============================================================
# REAL-WORLD VALIDATION — COCO IMAGE + GT INTEGRITY CHECK
# ============================================================

import os
import json
import pandas as pd
from PIL import Image

BASE_DIR = "/content/real_world_eval"
COCO_DIR = f"{BASE_DIR}/coco2017"
IMG_DIR = f"{BASE_DIR}/images"

VAL_ANN = f"{COCO_DIR}/annotations/instances_val2017.json"
MANIFEST = f"{BASE_DIR}/REAL_WORLD_COCO_MANIFEST.csv"

with open(VAL_ANN, "r") as f:
    coco = json.load(f)

df = pd.read_csv(MANIFEST)

image_lookup = {x["id"]: x for x in coco["images"]}
category_lookup = {x["id"]: x["name"] for x in coco["categories"]}

selected_coco_ids = set(df["coco_image_id"].astype(int))

annotations = [
    a for a in coco["annotations"]
    if a["image_id"] in selected_coco_ids
]

# Build annotation lookup
ann_by_image = {}

for ann in annotations:
    ann_by_image.setdefault(ann["image_id"], []).append({
        "annotation_id": ann["id"],
        "category_id": ann["category_id"],
        "category": category_lookup[ann["category_id"]],
        "bbox": ann["bbox"],
        "area": ann["area"],
        "iscrowd": ann["iscrowd"],
        "segmentation": ann["segmentation"]
    })

records = []
invalid_images = []

for _, row in df.iterrows():

    image_id = int(row["coco_image_id"])
    filename = row["filename"]
    path = os.path.join(IMG_DIR, filename)

    try:
        img = Image.open(path)
        img.verify()

        # Re-open after verify
        img = Image.open(path)

        valid = (
            img.width == int(row["width"]) and
            img.height == int(row["height"])
        )

    except Exception:
        valid = False

    anns = ann_by_image.get(image_id, [])

    if not valid or len(anns) == 0:
        invalid_images.append(row["image_id"])

    records.append({
        "image_id": row["image_id"],
        "coco_image_id": image_id,
        "filename": filename,
        "width": int(row["width"]),
        "height": int(row["height"]),
        "num_annotations": len(anns),
        "categories": sorted(
            set(a["category"] for a in anns)
        ),
        "valid_image": valid,
        "annotations": anns
    })

gt_json = f"{BASE_DIR}/annotations/REAL_WORLD_COCO_GT_50.json"

with open(gt_json, "w") as f:
    json.dump(records, f, indent=2)

print("=" * 70)
print("COCO REAL-WORLD INTEGRITY CHECK")
print("=" * 70)

print("Images expected       :", len(df))
print("Images checked        :", len(records))
print("Valid images          :", sum(x["valid_image"] for x in records))
print("Invalid images        :", len(invalid_images))
print("Total selected GT anns:", len(annotations))
print("Images with GT        :", len(ann_by_image))

print()
print("Unique object classes:",
      len(set(
          a["category"]
          for x in records
          for a in x["annotations"]
      )))

print()
print("Invalid image IDs:", invalid_images)

print()
print("Ground truth saved:")
print(gt_json)

assert len(records) == 50
assert len(invalid_images) == 0
assert len(annotations) > 0

print()
print("INTEGRITY CHECK PASSED")

# ============================================================
# REAL-WORLD VALIDATION — MODEL 1 OBJECT DETECTION
# ============================================================

import os
import glob
import json
import time
import pandas as pd
import torch

from ultralytics import YOLO

BASE_DIR = "/content/real_world_eval"
IMG_DIR = f"{BASE_DIR}/images"
GT_JSON = f"{BASE_DIR}/annotations/REAL_WORLD_COCO_GT_50.json"
RESULT_DIR = f"{BASE_DIR}/results/model1"

os.makedirs(RESULT_DIR, exist_ok=True)

# ------------------------------------------------------------
# Locate existing YOLO weights
# ------------------------------------------------------------

weight_candidates = []

for root in [
    "/content",
    "/root/.cache",
    "/usr/local/lib/python3.13/dist-packages"
]:
    if os.path.exists(root):
        for pattern in [
            "**/*.pt",
            "**/*.onnx"
        ]:
            weight_candidates.extend(
                glob.glob(
                    os.path.join(root, pattern),
                    recursive=True
                )
            )

# Prefer common YOLO detection checkpoints
preferred = [
    x for x in weight_candidates
    if any(
        name in os.path.basename(x).lower()
        for name in ["yolov8n", "yolo11n", "yolov8s", "yolo11s"]
    )
]

print("=" * 70)
print("MODEL 1 — REAL-WORLD OBJECT DETECTION")
print("=" * 70)

print("CUDA available:", torch.cuda.is_available())

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))

print()
print("YOLO weight candidates found:", len(weight_candidates))

for p in preferred[:20]:
    print(" ", p)

if not preferred:
    raise FileNotFoundError(
        "No YOLO detection weights found in the current Colab."
    )

# Use the first preferred checkpoint
MODEL_PATH = preferred[0]

print()
print("Selected model:", MODEL_PATH)

model = YOLO(MODEL_PATH)

# ------------------------------------------------------------
# Run inference
# ------------------------------------------------------------

image_files = sorted(
    glob.glob(os.path.join(IMG_DIR, "*.jpg"))
)

print()
print("Images:", len(image_files))

predictions = []
latencies = []

for idx, image_path in enumerate(image_files, start=1):

    filename = os.path.basename(image_path)

    start = time.perf_counter()

    result = model.predict(
        source=image_path,
        conf=0.25,
        iou=0.7,
        verbose=False,
        device=0 if torch.cuda.is_available() else "cpu"
    )[0]

    elapsed_ms = (time.perf_counter() - start) * 1000
    latencies.append(elapsed_ms)

    detections = []

    if result.boxes is not None:
        for box in result.boxes:
            cls_id = int(box.cls.item())
            conf = float(box.conf.item())
            xyxy = box.xyxy[0].tolist()

            detections.append({
                "class_id": cls_id,
                "class_name": model.names[cls_id],
                "confidence": conf,
                "bbox_xyxy": xyxy
            })

    predictions.append({
        "image_id": os.path.splitext(filename)[0],
        "filename": filename,
        "num_predictions": len(detections),
        "detections": detections,
        "latency_ms": elapsed_ms
    })

    print(
        f"[{idx:02d}/50] {filename} | "
        f"detections={len(detections)} | "
        f"{elapsed_ms:.2f} ms"
    )

# ------------------------------------------------------------
# Save raw predictions
# ------------------------------------------------------------

pred_json = f"{RESULT_DIR}/EXP_001_predictions.json"
pred_csv = f"{RESULT_DIR}/EXP_001_predictions.csv"

with open(pred_json, "w") as f:
    json.dump(predictions, f, indent=2)

flat_rows = []

for item in predictions:
    for det in item["detections"]:
        flat_rows.append({
            "image_id": item["image_id"],
            "filename": item["filename"],
            "class_id": det["class_id"],
            "class_name": det["class_name"],
            "confidence": det["confidence"],
            "x1": det["bbox_xyxy"][0],
            "y1": det["bbox_xyxy"][1],
            "x2": det["bbox_xyxy"][2],
            "y2": det["bbox_xyxy"][3],
            "latency_ms": item["latency_ms"]
        })

pd.DataFrame(flat_rows).to_csv(pred_csv, index=False)

print()
print("=" * 70)
print("MODEL 1 INFERENCE COMPLETE")
print("=" * 70)
print("Images evaluated:", len(predictions))
print("Total detections:",
      sum(x["num_predictions"] for x in predictions))
print("Average latency: %.2f ms" %
      (sum(latencies) / len(latencies)))
print("Median latency : %.2f ms" %
      pd.Series(latencies).median())
print("FPS: %.2f" %
      (1000 / (sum(latencies) / len(latencies))))

print()
print("Predictions JSON:", pred_json)
print("Predictions CSV :", pred_csv)

