# ============================================================
# MODEL 1 — REAL-WORLD OBJECT DETECTION METRICS
# COCO GT vs YOLOv8n predictions
# ============================================================

import os
import json
import numpy as np
import pandas as pd

BASE_DIR = "/content/real_world_eval"

GT_JSON = f"{BASE_DIR}/annotations/REAL_WORLD_COCO_GT_50.json"
PRED_JSON = f"{BASE_DIR}/results/model1/EXP_001_predictions.json"
OUT_DIR = f"{BASE_DIR}/results/model1"

with open(GT_JSON, "r") as f:
    gt_records = json.load(f)

with open(PRED_JSON, "r") as f:
    predictions = json.load(f)

pred_by_file = {
    x["filename"]: x["detections"]
    for x in predictions
}

# COCO class names -> YOLO COCO class IDs use matching names
# This avoids relying on numeric IDs from different annotation formats.

def xywh_to_xyxy(box):
    x, y, w, h = box
    return [
        x,
        y,
        x + w,
        y + h
    ]

def box_iou(a, b):
    ax1, ay1, ax2, ay2 = a
    bx1, by1, bx2, by2 = b

    ix1 = max(ax1, bx1)
    iy1 = max(ay1, by1)
    ix2 = min(ax2, bx2)
    iy2 = min(ay2, by2)

    iw = max(0.0, ix2 - ix1)
    ih = max(0.0, iy2 - iy1)

    inter = iw * ih

    area_a = max(0.0, ax2 - ax1) * max(0.0, ay2 - ay1)
    area_b = max(0.0, bx2 - bx1) * max(0.0, by2 - by1)

    union = area_a + area_b - inter

    if union <= 0:
        return 0.0

    return inter / union


def evaluate_at_iou(iou_threshold):

    total_tp = 0
    total_fp = 0
    total_fn = 0

    per_image = []

    for record in gt_records:

        filename = record["filename"]

        gt_objects = [
            {
                "category": ann["category"],
                "bbox": xywh_to_xyxy(ann["bbox"])
            }
            for ann in record["annotations"]
            if ann["iscrowd"] == 0
        ]

        pred_objects = pred_by_file.get(filename, [])

        # Sort predictions by confidence
        pred_objects = sorted(
            pred_objects,
            key=lambda x: x["confidence"],
            reverse=True
        )

        matched_gt = set()

        tp = 0
        fp = 0

        for pred in pred_objects:

            best_iou = 0.0
            best_gt = None

            for gi, gt in enumerate(gt_objects):

                if gi in matched_gt:
                    continue

                if pred["class_name"] != gt["category"]:
                    continue

                iou = box_iou(
                    pred["bbox_xyxy"],
                    gt["bbox"]
                )

                if iou > best_iou:
                    best_iou = iou
                    best_gt = gi

            if best_gt is not None and best_iou >= iou_threshold:
                matched_gt.add(best_gt)
                tp += 1
            else:
                fp += 1

        fn = len(gt_objects) - len(matched_gt)

        total_tp += tp
        total_fp += fp
        total_fn += fn

        per_image.append({
            "image_id": record["image_id"],
            "filename": filename,
            "gt": len(gt_objects),
            "predictions": len(pred_objects),
            "tp": tp,
            "fp": fp,
            "fn": fn
        })

    precision = (
        total_tp / (total_tp + total_fp)
        if total_tp + total_fp > 0 else 0.0
    )

    recall = (
        total_tp / (total_tp + total_fn)
        if total_tp + total_fn > 0 else 0.0
    )

    f1 = (
        2 * precision * recall / (precision + recall)
        if precision + recall > 0 else 0.0
    )

    return {
        "iou_threshold": iou_threshold,
        "TP": total_tp,
        "FP": total_fp,
        "FN": total_fn,
        "precision": precision,
        "recall": recall,
        "f1": f1,
        "per_image": per_image
    }


results = {}

for threshold in [0.50, 0.75]:

    results[str(threshold)] = evaluate_at_iou(threshold)

# ------------------------------------------------------------
# Print results
# ------------------------------------------------------------

print("=" * 70)
print("MODEL 1 — REAL-WORLD DETECTION RESULTS")
print("=" * 70)

for threshold in [0.50, 0.75]:

    r = results[str(threshold)]

    print()
    print(f"IoU threshold: {threshold:.2f}")
    print("TP:", r["TP"])
    print("FP:", r["FP"])
    print("FN:", r["FN"])
    print("Precision: %.4f (%.2f%%)" %
          (r["precision"], r["precision"] * 100))
    print("Recall   : %.4f (%.2f%%)" %
          (r["recall"], r["recall"] * 100))
    print("F1       : %.4f (%.2f%%)" %
          (r["f1"], r["f1"] * 100))

# ------------------------------------------------------------
# Save summary
# ------------------------------------------------------------

summary = {
    "experiment_id": "EXP_001",
    "task": "Real-world object detection",
    "dataset": "COCO 2017 validation",
    "subset_size": 50,
    "seed": 42,
    "model": "YOLOv8n",
    "confidence_threshold": 0.25,
    "iou_nms_threshold": 0.70,
    "latency_avg_ms": float(
        np.mean([x["latency_ms"] for x in predictions])
    ),
    "latency_median_ms": float(
        np.median([x["latency_ms"] for x in predictions])
    ),
    "fps": float(
        1000 / np.mean([x["latency_ms"] for x in predictions])
    ),
    "metrics": {
        "IoU_0.50": {
            k: v for k, v in results["0.5"].items()
            if k != "per_image"
        },
        "IoU_0.75": {
            k: v for k, v in results["0.75"].items()
            if k != "per_image"
        }
    }
}

summary_json = f"{OUT_DIR}/EXP_001_real_world_summary.json"
summary_csv = f"{OUT_DIR}/EXP_001_real_world_summary.csv"

with open(summary_json, "w") as f:
    json.dump(summary, f, indent=2)

rows = []

for threshold in [0.50, 0.75]:
    r = results[str(threshold)]

    rows.append({
        "iou_threshold": threshold,
        "TP": r["TP"],
        "FP": r["FP"],
        "FN": r["FN"],
        "precision": r["precision"],
        "recall": r["recall"],
        "f1": r["f1"]
    })

pd.DataFrame(rows).to_csv(summary_csv, index=False)

print()
print("Summary JSON:", summary_json)
print("Summary CSV :", summary_csv)

