# REAL-WORLD VALIDATION — MODEL 2 ASSET CHECK
# ============================================================

import os

print("=" * 70)
print("MODEL 2 — CHECKING AVAILABLE ASSETS")
print("=" * 70)

for root, dirs, files in os.walk("/content"):
    # Keep output manageable
    if any(x in root for x in [
        "sample_data",
        ".config",
        "real_world_eval"
    ]):
        continue

    relevant = [
        f for f in files
        if f.lower().endswith((
            ".pt", ".pth", ".onnx",
            ".json", ".csv", ".zip"
        ))
    ]

    if relevant:
        print("\n", root)
        for f in relevant[:20]:
            print("  ", f)

