# ============================================================
# RESET REAL-WORLD TEST INPUTS
# Keep the downloaded benchmark datasets separate.
# ============================================================

import os
import shutil

BASE_DIR = "/content/real_world_eval"
IMG_DIR = f"{BASE_DIR}/images"

# Move current COCO images out of the real-world input folder
COCO_REAL_DIR = f"{BASE_DIR}/coco2017_realworld_separate"
os.makedirs(COCO_REAL_DIR, exist_ok=True)

moved = 0

for filename in os.listdir(IMG_DIR):
    src = os.path.join(IMG_DIR, filename)

    if os.path.isfile(src):
        dst = os.path.join(COCO_REAL_DIR, filename)
        shutil.move(src, dst)
        moved += 1

print("=" * 60)
print("REAL-WORLD TEST RESET")
print("=" * 60)
print("COCO images moved out:", moved)
print("Real-world input folder:", IMG_DIR)
print("Current input images:", len(os.listdir(IMG_DIR)))
print()
print("COCO images remain available at:")
print(COCO_REAL_DIR)

# ============================================================
# REAL-WORLD INTERNET PHOTO COLLECTION
# Source: Wikimedia Commons
# ============================================================

import os
import json
import requests
import pandas as pd
from PIL import Image
from io import BytesIO
from tqdm.auto import tqdm

BASE_DIR = "/content/real_world_eval"
IMG_DIR = f"{BASE_DIR}/images"
SOURCE_DIR = f"{BASE_DIR}/internet_sources"

os.makedirs(IMG_DIR, exist_ok=True)
os.makedirs(SOURCE_DIR, exist_ok=True)

API = "https://commons.wikimedia.org/w/api.php"

# Actual real-world photo categories
search_groups = {
    "outdoor_road": [
        "road traffic",
        "street traffic",
        "city street",
    ],
    "indoor": [
        "interior room",
        "indoor room",
        "office interior",
    ],
    "text_heavy": [
        "street sign",
        "shop sign",
        "menu sign",
    ],
    "people_objects": [
        "people street",
        "everyday objects",
    ],
    "navigation_poi": [
        "landmark",
        "building exterior",
        "train station",
    ],
    "mixed": [
        "street scene",
        "daily life",
        "public place",
    ],
}

target_counts = {
    "outdoor_road": 15,
    "indoor": 10,
    "text_heavy": 10,
    "people_objects": 5,
    "navigation_poi": 5,
    "mixed": 5,
}

def commons_search(query, limit=30):
    params = {
        "action": "query",
        "format": "json",
        "generator": "search",
        "gsrsearch": query,
        "gsrnamespace": 6,
        "gsrlimit": limit,
        "prop": "imageinfo",
        "iiprop": "url|mime|size|extmetadata",
        "iiurlwidth": 1200,
    }

    r = requests.get(API, params=params, timeout=30)
    r.raise_for_status()

    data = r.json()
    pages = data.get("query", {}).get("pages", {})

    return list(pages.values())


records = []
used_titles = set()

print("=" * 70)
print("DOWNLOADING REAL-WORLD INTERNET PHOTOS")
print("=" * 70)

for group, target in target_counts.items():

    collected = 0

    print(f"\n--- {group}: target {target} ---")

    for query in search_groups[group]:

        if collected >= target:
            break

        try:
            pages = commons_search(
                query,
                limit=max(30, target * 4)
            )
        except Exception as e:
            print("Search failed:", query, str(e)[:100])
            continue

        for page in pages:

            if collected >= target:
                break

            title = page.get("title", "")

            if title in used_titles:
                continue

            info = page.get("imageinfo", [])
            if not info:
                continue

            ii = info[0]

            mime = ii.get("mime", "")
            if not mime.startswith("image/"):
                continue

            url = ii.get("thumburl") or ii.get("url")
            original_url = ii.get("url")

            if not url:
                continue

            try:
                response = requests.get(
                    url,
                    timeout=30
                )
                response.raise_for_status()

                img = Image.open(
                    BytesIO(response.content)
                ).convert("RGB")

                # Reject tiny thumbnails
                if img.width < 500 or img.height < 300:
                    continue

                idx = len(records) + 1
                image_id = f"RW_{idx:03d}"
                filename = f"{image_id}.jpg"

                path = os.path.join(
                    IMG_DIR,
                    filename
                )

                img.save(
                    path,
                    "JPEG",
                    quality=95
                )

                metadata = ii.get(
                    "extmetadata",
                    {}
                )

                record = {
                    "image_id": image_id,
                    "filename": filename,
                    "category": group,
                    "search_query": query,
                    "commons_title": title,
                    "source": "Wikimedia Commons",
                    "source_page": f"https://commons.wikimedia.org/wiki/{title.replace(' ', '_')}",
                    "image_url": original_url,
                    "download_url": url,
                    "width": img.width,
                    "height": img.height,
                    "license": metadata.get(
                        "LicenseShortName",
                        {}
                    ).get("value", ""),
                    "artist": metadata.get(
                        "Artist",
                        {}
                    ).get("value", ""),
                    "description": metadata.get(
                        "ImageDescription",
                        {}
                    ).get("value", ""),
                }

                records.append(record)
                used_titles.add(title)
                collected += 1

                print(
                    f"[{len(records):02d}/50] "
                    f"{image_id} | "
                    f"{group} | "
                    f"{img.width}x{img.height}"
                )

            except Exception:
                continue


manifest = pd.DataFrame(records)

manifest_path = (
    f"{BASE_DIR}/internet_sources/"
    "REAL_WORLD_INTERNET_MANIFEST.csv"
)

json_path = (
    f"{BASE_DIR}/internet_sources/"
    "REAL_WORLD_INTERNET_MANIFEST.json"
)

manifest.to_csv(
    manifest_path,
    index=False
)

with open(json_path, "w") as f:
    json.dump(
        records,
        f,
        indent=2,
        ensure_ascii=False
    )

print()
print("=" * 70)
print("COLLECTION COMPLETE")
print("=" * 70)
print("Images downloaded:", len(records))
print("Target:", 50)

if len(records):
    print("\nCategory counts:")
    print(manifest["category"].value_counts())

print()
print("Manifest CSV :", manifest_path)
print("Manifest JSON:", json_path)
print("Image folder  :", IMG_DIR)

