import requests
import re
from bs4 import BeautifulSoup

headers = {
    "User-Agent": (
        "Mozilla/5.0 (X11; Linux x86_64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/140.0 Safari/537.36"
    )
}

queries = [
    "traffic street",
    "people walking street",
    "indoor room",
    "restaurant",
    "road sign",
    "storefront",
    "landmark",
    "car road",
]

print("=" * 70)
print("WIKIMEDIA COMMONS — REAL-WORLD IMAGE SEARCH TEST")
print("=" * 70)

for query in queries:
    url = "https://commons.wikimedia.org/w/index.php"
    params = {
        "search": query,
        "title": "Special:MediaSearch",
        "go": "Go",
        "type": "image",
    }

    try:
        r = requests.get(
            url,
            params=params,
            headers=headers,
            timeout=20
        )

        print(f"\n[{query}]")
        print("HTTP:", r.status_code)
        print("Bytes:", len(r.content))
        print("URL:", r.url)

        if r.status_code == 200:
            soup = BeautifulSoup(r.text, "html.parser")

            images = soup.find_all("img")

            valid = []
            for img in images:
                src = img.get("src", "")
                if src and ("upload.wikimedia.org" in src):
                    if src.startswith("//"):
                        src = "https:" + src
                    valid.append(src)

            print("Direct Wikimedia images found:", len(valid))

            for x in valid[:3]:
                print(" ", x[:180])

    except Exception as e:
        print("ERROR:", type(e).__name__, e)

print("\n" + "=" * 70)

