# ============================================================
# REAL-WORLD EVAL — COLLECT 50 GENUINE WEB PHOTOS
# Source: Wikimedia Commons
# ============================================================

import os
import re
import json
import hashlib
import requests
import pandas as pd
from bs4 import BeautifulSoup
from urllib.parse import urljoin, unquote
from PIL import Image
from io import BytesIO

BASE = "/content/real_world_eval"
IMG_DIR = os.path.join(BASE, "images")
os.makedirs(IMG_DIR, exist_ok=True)

headers = {
    "User-Agent": (
        "Mozilla/5.0 (X11; Linux x86_64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/140.0 Safari/537.36"
    )
}

# ------------------------------------------------------------
# Real-world categories
# ------------------------------------------------------------

categories = {
    "road_traffic": [
        "traffic street",
        "urban road cars",
        "busy road pedestrians",
        "highway traffic",
        "intersection traffic",
    ],
    "indoor_scene": [
        "living room interior",
        "office interior",
        "kitchen interior",
        "restaurant interior",
        "classroom interior",
    ],
    "objects_people": [
        "people walking street",
        "person bicycle street",
        "person carrying bag",
        "people shopping",
        "dog street",
    ],
    "text_ocr": [
        "storefront sign",
        "street sign",
        "restaurant sign",
        "shop sign",
        "advertising sign",
    ],
    "landmark_navigation": [
        "famous landmark",
        "city landmark",
        "train station",
        "airport terminal",
        "city square",
    ],
    "depth_distance": [
        "street perspective cars",
        "road perspective pedestrians",
        "indoor room perspective",
        "corridor perspective",
        "street vehicles distance",
    ],
}

# Target 50 images total
target_per_category = {
    "road_traffic": 10,
    "indoor_scene": 8,
    "objects_people": 8,
    "text_ocr": 8,
    "landmark_navigation": 8,
    "depth_distance": 8,
}

def commons_search(query):
    """Return Wikimedia Commons File-page URLs."""
    url = "https://commons.wikimedia.org/w/index.php"
    params = {
        "search": query,
        "title": "Special:MediaSearch",
        "go": "Go",
        "type": "image",
    }

    r = requests.get(
        url,
        params=params,
        headers=headers,
        timeout=30
    )
    r.raise_for_status()

    soup = BeautifulSoup(r.text, "html.parser")

    links = []
    for a in soup.find_all("a", href=True):
        href = a["href"]

        if "/wiki/File:" in href:
            full = urljoin(
                "https://commons.wikimedia.org",
                href
            )

            if full not in links:
                links.append(full)

    return links


def resolve_original_image(file_page):
    """Resolve a Commons File page to an original image URL."""
    r = requests.get(
        file_page,
        headers=headers,
        timeout=30
    )
    r.raise_for_status()

    soup = BeautifulSoup(r.text, "html.parser")

    # Preferred: original/full-resolution media link
    candidates = []

    for a in soup.find_all("a", href=True):
        href = a["href"]

        if "upload.wikimedia.org" in href:
            full = urljoin(file_page, href)

            if full not in candidates:
                candidates.append(full)

    # Fallback: image elements
    for img in soup.find_all("img", src=True):
        src = img["src"]

        if "upload.wikimedia.org" in src:
            full = urljoin(file_page, src)

            if full not in candidates:
                candidates.append(full)

    # Prefer common image formats
    image_candidates = []

    for url in candidates:
        low = url.lower().split("?")[0]

        if low.endswith((
            ".jpg", ".jpeg", ".png",
            ".webp", ".tif", ".tiff"
        )):
            image_candidates.append(url)

    if image_candidates:
        return image_candidates[0]

    return None


def download_image(url):
    """Download and validate an image."""
    r = requests.get(
        url,
        headers=headers,
        timeout=40
    )
    r.raise_for_status()

    image = Image.open(BytesIO(r.content))
    image.load()

    # Convert unsupported modes safely
    if image.mode not in ("RGB", "L"):
        image = image.convert("RGB")

    return image


print("=" * 70)
print("REAL-WORLD INTERNET PHOTO COLLECTION")
print("Source: Wikimedia Commons")
print("Target: 50 genuine web photographs")
print("=" * 70)

records = []
used_files = set()
used_hashes = set()

image_counter = 0

for category, queries in categories.items():

    target = target_per_category[category]
    collected = 0

    print(f"\n[{category}] target={target}")

    for query in queries:

        if collected >= target:
            break

        try:
            file_pages = commons_search(query)
        except Exception as e:
            print("  Search error:", query, type(e).__name__, e)
            continue

        print(
            f"  Query: {query} | "
            f"file pages={len(file_pages)}"
        )

        for file_page in file_pages:

            if collected >= target:
                break

            if file_page in used_files:
                continue

            try:
                image_url = resolve_original_image(file_page)

                if not image_url:
                    continue

                image = download_image(image_url)

                width, height = image.size

                # Reject tiny images
                if width < 256 or height < 256:
                    continue

                # Pixel hash for duplicate detection
                small = image.convert("RGB").resize((32, 32))
                digest = hashlib.sha256(
                    small.tobytes()
                ).hexdigest()

                if digest in used_hashes:
                    continue

                image_counter += 1

                filename = (
                    f"RW_{image_counter:03d}.jpg"
                )

                filepath = os.path.join(
                    IMG_DIR,
                    filename
                )

                image.convert("RGB").save(
                    filepath,
                    "JPEG",
                    quality=95
                )

                used_files.add(file_page)
                used_hashes.add(digest)

                records.append({
                    "image_id": f"RW_{image_counter:03d}",
                    "filename": filename,
                    "category": category,
                    "search_query": query,
                    "source": "Wikimedia Commons",
                    "source_file_page": file_page,
                    "source_image_url": image_url,
                    "width": width,
                    "height": height,
                })

                collected += 1

                print(
                    f"    ✓ {filename} "
                    f"{width}x{height}"
                )

            except Exception:
                continue

    print(
        f"  Collected for {category}: "
        f"{collected}/{target}"
    )

# ------------------------------------------------------------
# Save master manifest
# ------------------------------------------------------------

manifest_path = os.path.join(
    BASE,
    "REAL_WORLD_MASTER_MANIFEST.csv"
)

df = pd.DataFrame(records)
df.to_csv(manifest_path, index=False)

json_path = os.path.join(
    BASE,
    "REAL_WORLD_MASTER_MANIFEST.json"
)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(
        records,
        f,
        indent=2,
        ensure_ascii=False
    )

print("\n" + "=" * 70)
print("COLLECTION COMPLETE")
print("=" * 70)
print("Total images:", len(df))
print("Image directory:", IMG_DIR)
print("Manifest:", manifest_path)
print("JSON manifest:", json_path)

if len(df):
    print("\nImages by category:")
    print(df["category"].value_counts().to_string())

    print("\nFirst 10 images:")
    print(
        df[
            [
                "image_id",
                "filename",
                "category",
                "width",
                "height"
            ]
        ].head(10).to_string(index=False)
    )

