import os
import json
import time
import hashlib
import requests
import pandas as pd
from bs4 import BeautifulSoup
from urllib.parse import urljoin
from PIL import Image
from io import BytesIO

BASE = "/content/real_world_eval"
IMG_DIR = os.path.join(BASE, "images")
os.makedirs(IMG_DIR, exist_ok=True)

headers = {
    "User-Agent": (
        "Mozilla/5.0 (X11; Linux x86_64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/140.0 Safari/537.36"
    )
}

# Existing file pages that were already successfully discovered.
# These are genuine Wikimedia Commons photographs/files, not benchmark data.
file_pages = [
    "https://commons.wikimedia.org/wiki/File:Kabukicho_red_gate_and_colorful_neon_street_signs_at_night,_Shinjuku,_Tokyo,_Japan.jpg",
    "https://commons.wikimedia.org/wiki/File:Malaysia_Traffic-signs_Regulatory-sign-05.jpg",
    "https://commons.wikimedia.org/wiki/File:Vyhrazen%C3%BD_j%C3%ADzdn%C3%AD_pruh_pro_cyklisty.jpg",
    "https://commons.wikimedia.org/wiki/File:Malaysia_Traffic-signs_Warning-sign-31.jpg",
    "https://commons.wikimedia.org/wiki/File:Malaysia_Traffic-signs_Regulatory-sign-12.jpg",
    "https://commons.wikimedia.org/wiki/File:Road_sign_at_Lewis_Pass_NZ.jpg",
    "https://commons.wikimedia.org/wiki/File:M%C3%BCnster,_Freiherr-vom-Stein-Haus_--_2021_--_9042-6.jpg",
    "https://commons.wikimedia.org/wiki/File:Colorful_neon_street_signs_in_Kabukich%C5%8D,_Shinjuku,_Tokyo.jpg",
    "https://commons.wikimedia.org/wiki/File:Ermitage_road_sign_2.jpg",
    "https://commons.wikimedia.org/wiki/File:Right_turn_road_sign_with_speed_limit.jpg",
]

def resolve_original(file_page):
    r = requests.get(
        file_page,
        headers=headers,
        timeout=30
    )
    r.raise_for_status()

    soup = BeautifulSoup(r.text, "html.parser")

    # Commons pages normally expose the original file through
    # a full-resolution upload.wikimedia.org link.
    candidates = []

    for a in soup.find_all("a", href=True):
        href = a["href"]

        if "upload.wikimedia.org" in href:
            full = urljoin(file_page, href)

            if full not in candidates:
                candidates.append(full)

    for img in soup.find_all("img", src=True):
        src = img["src"]

        if "upload.wikimedia.org" in src:
            full = urljoin(file_page, src)

            if full not in candidates:
                candidates.append(full)

    for url in candidates:
        low = url.lower().split("?")[0]

        if low.endswith((
            ".jpg", ".jpeg", ".png",
            ".webp", ".tif", ".tiff"
        )):
            return url

    return None


records = []
used_hashes = set()

# Start numbering after existing files.
existing = [
    x for x in os.listdir(IMG_DIR)
    if x.lower().endswith((".jpg", ".jpeg", ".png", ".webp"))
]

counter = len(existing)

print("=" * 70)
print("RATE-LIMIT SAFE WIKIMEDIA DOWNLOAD")
print("=" * 70)
print("Existing images:", len(existing))
print("File pages to resolve:", len(file_pages))

for idx, file_page in enumerate(file_pages, 1):

    print(f"\n[{idx}/{len(file_pages)}]")

    try:
        print("Resolving:", file_page)

        image_url = resolve_original(file_page)

        if not image_url:
            print("  No original image URL found.")
            time.sleep(3)
            continue

        print("  Original URL found")

        time.sleep(3)

        r = requests.get(
            image_url,
            headers=headers,
            timeout=45
        )
        r.raise_for_status()

        image = Image.open(BytesIO(r.content))
        image.load()

        if image.mode not in ("RGB", "L"):
            image = image.convert("RGB")

        width, height = image.size

        if width < 256 or height < 256:
            print("  Rejected: too small")
            time.sleep(3)
            continue

        # Duplicate detection
        small = image.convert("RGB").resize((32, 32))
        digest = hashlib.sha256(
            small.tobytes()
        ).hexdigest()

        if digest in used_hashes:
            print("  Rejected: duplicate")
            time.sleep(3)
            continue

        counter += 1

        filename = f"RW_{counter:03d}.jpg"
        filepath = os.path.join(IMG_DIR, filename)

        image.convert("RGB").save(
            filepath,
            "JPEG",
            quality=95
        )

        used_hashes.add(digest)

        records.append({
            "image_id": f"RW_{counter:03d}",
            "filename": filename,
            "source": "Wikimedia Commons",
            "source_file_page": file_page,
            "source_image_url": image_url,
            "width": width,
            "height": height,
        })

        print(
            f"  ✓ SAVED {filename} "
            f"{width}x{height}"
        )

        time.sleep(3)

    except Exception as e:
        print(
            "  ERROR:",
            type(e).__name__,
            str(e)[:200]
        )
        time.sleep(5)

# Save newly resolved records separately
out_csv = os.path.join(
    BASE,
    "WIKIMEDIA_RESOLVED_IMAGES.csv"
)

pd.DataFrame(records).to_csv(
    out_csv,
    index=False
)

print("\n" + "=" * 70)
print("DONE")
print("=" * 70)
print("New images:", len(records))
print("Total image files now:", len([
    x for x in os.listdir(IMG_DIR)
    if x.lower().endswith(".jpg")
]))
print("Manifest:", out_csv)

