# ============================================================
# REAL-WORLD EVAL — IMAGE QUALITY / DUPLICATE CHECK
# ============================================================

import os
import hashlib
import pandas as pd
from PIL import Image, ImageDraw, ImageFont

BASE = "/content/real_world_eval"
IMG_DIR = os.path.join(BASE, "images")

manifest_path = os.path.join(
    BASE,
    "REAL_WORLD_MASTER_MANIFEST.csv"
)

df = pd.read_csv(manifest_path)

print("=" * 70)
print("REAL-WORLD PHOTO COLLECTION VALIDATION")
print("=" * 70)

valid = []
invalid = []
hashes = {}

for _, row in df.iterrows():

    path = os.path.join(
        IMG_DIR,
        row["filename"]
    )

    try:
        img = Image.open(path)
        img.verify()

        # Reopen after verify
        img = Image.open(path)
        img.load()

        digest = hashlib.sha256(
            img.convert("RGB").resize((32, 32)).tobytes()
        ).hexdigest()

        if digest in hashes:
            invalid.append(
                (row["filename"], "duplicate")
            )
        else:
            hashes[digest] = row["filename"]
            valid.append(row["filename"])

    except Exception as e:
        invalid.append(
            (row["filename"], str(e))
        )

print("Manifest records:", len(df))
print("Valid images:", len(valid))
print("Invalid/duplicate:", len(invalid))

if invalid:
    print("\nInvalid/duplicate files:")
    for item in invalid:
        print(" ", item)

# ------------------------------------------------------------
# Contact sheet
# ------------------------------------------------------------

thumb_w = 260
thumb_h = 200
cols = 4

rows = (len(valid) + cols - 1) // cols

sheet = Image.new(
    "RGB",
    (cols * thumb_w, rows * thumb_h),
    "white"
)

draw = ImageDraw.Draw(sheet)

for i, filename in enumerate(valid):

    path = os.path.join(
        IMG_DIR,
        filename
    )

    img = Image.open(path).convert("RGB")
    img.thumbnail((thumb_w - 10, thumb_h - 35))

    x = (i % cols) * thumb_w
    y = (i // cols) * thumb_h

    px = x + (thumb_w - img.width) // 2
    py = y + 5

    sheet.paste(img, (px, py))

    label = filename

    # Add category
    match = df[df["filename"] == filename]

    if len(match):
        label += " | " + match.iloc[0]["category"]

    draw.text(
        (x + 5, y + thumb_h - 25),
        label,
        fill="black"
    )

contact_path = os.path.join(
    BASE,
    "REAL_WORLD_CONTACT_SHEET.jpg"
)

sheet.save(
    contact_path,
    "JPEG",
    quality=92
)

print("\nContact sheet:")
print(contact_path)

print("\nCategory distribution:")
print(
    df["category"]
    .value_counts()
    .to_string()
)

print("=" * 70)

