# REAL-WORLD EVAL — MODEL ENVIRONMENT INVENTORY
# ============================================================

import os
import importlib.util
import torch

print("=" * 70)
print("REAL-WORLD MODEL ENVIRONMENT INVENTORY")
print("=" * 70)

print("\nPyTorch:")
print(torch.__version__)

print("\nCUDA available:", torch.cuda.is_available())

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))

packages = [
    "ultralytics",
    "transformers",
    "torchvision",
    "easyocr",
    "cv2",
    "PIL",
    "numpy",
    "pandas",
]

print("\nPackages:")

for pkg in packages:
    spec = importlib.util.find_spec(pkg)

    if spec is None:
        print(f"  ✗ {pkg}")
    else:
        try:
            module = __import__(pkg)
            version = getattr(module, "__version__", "installed")
            print(f"  ✓ {pkg} ({version})")
        except Exception:
            print(f"  ✓ {pkg}")

print("\nImportant checkpoint/file search:")

search_roots = [
    "/content",
    "/root/.cache/huggingface",
    "/root/.cache/torch",
]

extensions = (
    ".pt",
    ".pth",
    ".bin",
    ".safetensors",
)

found = set()

for root in search_roots:

    if not os.path.exists(root):
        continue

    for dirpath, dirnames, filenames in os.walk(root):

        # Avoid enormous irrelevant directories
        dirnames[:] = [
            d for d in dirnames
            if d not in {
                "node_modules",
                ".git",
                "__pycache__",
            }
        ]

        for filename in filenames:

            if filename.lower().endswith(extensions):

                path = os.path.join(
                    dirpath,
                    filename
                )

                if path not in found:
                    found.add(path)

                    print(" ", path)

print("\nTotal model/checkpoint files found:", len(found))

print("\n" + "=" * 70)

