# REAL-WORLD EVAL — RESTORE PLACES365 MODEL 4
# ============================================================

import os
import requests

BASE = "/content/real_world_eval"
MODEL_DIR = os.path.join(BASE, "models")
os.makedirs(MODEL_DIR, exist_ok=True)

places_ckpt = os.path.join(
    MODEL_DIR,
    "resnet50_places365.pth"
)

# Official Places365 model URL used for the ResNet-50 Places365
# pretrained checkpoint.
url = (
    "http://places2.csail.mit.edu/models_places365/"
    "resnet50_places365.pth.tar"
)

print("=" * 70)
print("RESTORING MODEL 4 — PLACES365 RESNET-50")
print("=" * 70)

if os.path.exists(places_ckpt):
    print("Checkpoint already exists:")
    print(places_ckpt)
else:
    print("Downloading Places365 ResNet-50 checkpoint...")
    print("URL:", url)

    r = requests.get(
        url,
        stream=True,
        timeout=120
    )

    print("HTTP status:", r.status_code)
    r.raise_for_status()

    total = int(r.headers.get("content-length", 0))
    downloaded = 0

    temp_path = places_ckpt + ".download"

    with open(temp_path, "wb") as f:
        for chunk in r.iter_content(chunk_size=1024 * 1024):
            if chunk:
                f.write(chunk)
                downloaded += len(chunk)

                if total:
                    pct = downloaded * 100 / total
                    print(
                        f"\rDownloaded: "
                        f"{downloaded / 1024**2:.1f} MB "
                        f"({pct:.1f}%)",
                        end=""
                    )

    print()

    os.replace(temp_path, places_ckpt)

print("\nCheckpoint:")
print(places_ckpt)

print(
    "Size:",
    f"{os.path.getsize(places_ckpt) / 1024**2:.2f} MB"
)

print("\n✓ Model 4 checkpoint ready")
print("=" * 70)

