# ============================================================
# MODEL 8 — LOCATE UNIDEPTH CUSTOM LOADER
# ============================================================

import os
import sys
import glob

print("=" * 70)
print("LOCATING UNIDEPTH V2 CUSTOM LOADER")
print("=" * 70)

# Search Python paths for UniDepth source
search_roots = [
    "/usr/local/lib/python3.13/dist-packages",
    "/root/.cache",
    "/content",
]

matches = []

for root in search_roots:
    if not os.path.exists(root):
        continue

    for dirpath, dirnames, filenames in os.walk(root):

        # Avoid irrelevant large directories
        dirnames[:] = [
            d for d in dirnames
            if d not in {
                "node_modules",
                ".git",
                "__pycache__",
            }
        ]

        for filename in filenames:
            low = filename.lower()

            if (
                "unidepth" in low
                or low in {
                    "inference.py",
                    "infer.py",
                    "model.py",
                }
            ):
                path = os.path.join(dirpath, filename)

                if path not in matches:
                    matches.append(path)

print("\nPotential UniDepth files:")

for path in matches[:100]:
    print(path)

print("\nTotal matches:", len(matches))

# Inspect the cached config
