import torch

from PIL import Image
from collections import defaultdict

warnings.filterwarnings("ignore")

BASE = "/content/real_world_eval"
IMG_DIR = os.path.join(BASE, "images")
MANIFEST = os.path.join(
    BASE,
    "REAL_WORLD_UNIFIED_EVAL_MANIFEST.csv"
)
RESULTS = os.path.join(BASE, "results_combined")
os.makedirs(RESULTS, exist_ok=True)

df = pd.read_csv(MANIFEST)

device = "cuda" if torch.cuda.is_available() else "cpu"

print("=" * 80)
print("COMBINED REAL-WORLD INFERENCE — MODELS 1–8")
print("=" * 80)
print("Images:", len(df))
print("Device:", device)
print("=" * 80)

# ============================================================
# Load models
# ============================================================

from ultralytics import YOLO
from transformers import (
    BlipProcessor,
    BlipForConditionalGeneration,
)
import easyocr

# Model 1
m1 = YOLO("/content/yolov8n.pt")

# Model 3
m3 = YOLO("yolov8n-seg.pt")

# Model 4
# Places365 checkpoint will be loaded below using the same
# torchvision architecture and Places365 class mapping.
import torchvision.models as tv_models
import torch.nn as nn

places_ckpt = (
    "/content/real_world_eval/models/"
    "resnet50_places365.pth"
)

m4 = tv_models.resnet50(num_classes=365)

checkpoint = torch.load(
    places_ckpt,
    map_location="cpu",
    weights_only=False
)

if isinstance(checkpoint, dict):
    state = checkpoint.get(
        "state_dict",
        checkpoint.get("model", checkpoint)
    )
else:
    state = checkpoint

# Remove possible DataParallel prefix
clean_state = {}

for k, v in state.items():
    clean_state[k.replace("module.", "")] = v

m4.load_state_dict(
    clean_state,
    strict=False
)

m4 = m4.to(device)
m4.eval()

# Model 5
processor5 = BlipProcessor.from_pretrained(
    "Salesforce/blip-image-captioning-base"
)

m5 = BlipForConditionalGeneration.from_pretrained(
    "Salesforce/blip-image-captioning-base"
)

m5 = m5.to(device)
m5.eval()

# Model 6
reader6 = easyocr.Reader(
    ["en"],
    gpu=torch.cuda.is_available(),
    verbose=False
)

# Model 8
from unidepth.models import UniDepthV2

m8 = UniDepthV2.from_pretrained(
    "lpiccinelli/unidepth-v2-vits14"
)

m8 = m8.to(device)
m8.eval()

print("\n✓ Models initialized")

# ============================================================
# Helper
# ============================================================

def load_image(filename):
    path = os.path.join(IMG_DIR, filename)
    return Image.open(path).convert("RGB")


def sync_cuda():
    if torch.cuda.is_available():
        torch.cuda.synchronize()


# ============================================================
# Result containers
# ============================================================

results = defaultdict(list)

timing = defaultdict(list)

# ============================================================
# MODEL 1 — OBJECT DETECTION
# ============================================================

print("\n" + "=" * 80)
print("MODEL 1 — OBJECT DETECTION")
print("=" * 80)

subset = df[df["model1_object_detection"]]

for _, row in subset.iterrows():

    image_id = row["image_id"]
    filename = row["filename"]

    path = os.path.join(IMG_DIR, filename)

    sync_cuda()
    t0 = time.perf_counter()

    pred = m1.predict(
        source=path,
        imgsz=640,
        conf=0.25,
        verbose=False
    )[0]

    sync_cuda()
    elapsed = time.perf_counter() - t0

    detections = []

    if pred.boxes is not None:
        for i in range(len(pred.boxes)):

            cls_id = int(
                pred.boxes.cls[i].item()
            )

            detections.append({
                "class_id": cls_id,
                "class_name": m1.names[cls_id],
                "confidence": float(
                    pred.boxes.conf[i].item()
                ),
                "bbox_xyxy": [
                    float(x)
                    for x in pred.boxes.xyxy[i].tolist()
                ]
            })

    results["model1"].append({
        "image_id": image_id,
        "filename": filename,
        "detections": detections,
        "num_detections": len(detections),
        "latency_ms": elapsed * 1000
    })

    timing["model1"].append(elapsed)

print("Images:", len(subset))
print(
    "Avg latency:",
    f"{np.mean(timing['model1']) * 1000:.2f} ms"
)

# ============================================================
# MODEL 2 — ROAD SCENE
#
# No independent real-world Model-2 checkpoint/GT was preserved
# in this runtime. We therefore record the applicable images
# for downstream road-scene analysis without fabricating output.
# ============================================================

print("\n" + "=" * 80)
