print("\nFirst 5 captions:")
for x in m5[:5]:
    print(
        x["image_id"],
        "->",
        x.get("caption")
    )

empty_captions = sum(
    not str(x.get("caption", "")).strip()
    for x in m5
)

print("Empty captions:", empty_captions)

# ------------------------------------------------------------
# MODEL 6
# ------------------------------------------------------------

m6 = load_json("model6_predictions.json")

print("\nMODEL 6 — OCR")
