# ============================================================
# REAL-WORLD VALIDATION — MODEL 4 LABELS + MODEL 8 QC
# ============================================================

import os
import json
import urllib.request
import numpy as np
import pandas as pd

BASE = "/content/real_world_eval"
RESULTS = os.path.join(BASE, "results_combined")

# ------------------------------------------------------------
# MODEL 4 — download official Places365 category names
# ------------------------------------------------------------

CATEGORIES_URL = (
    "https://raw.githubusercontent.com/csailvision/"
    "places365/master/categories_places365.txt"
)

categories_path = os.path.join(
    BASE,
    "places365_categories.txt"
)

try:
    urllib.request.urlretrieve(
        CATEGORIES_URL,
        categories_path
    )
    print("Downloaded Places365 category mapping.")
except Exception as e:
    print("Download failed:", repr(e))

# Parse categories
categories = []

with open(categories_path, "r", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue

        # Format is typically:
        # /abbey 0
        parts = line.rsplit(" ", 1)

        if len(parts) == 2:
            name = parts[0].lstrip("/")
            idx = int(parts[1])
            categories.append((idx, name))

categories = sorted(categories)

print("Places365 categories:", len(categories))

# ------------------------------------------------------------
# Attach names to saved Model 4 predictions
# ------------------------------------------------------------

with open(
    os.path.join(RESULTS, "model4_predictions.json"),
    "r",
    encoding="utf-8"
) as f:
    m4 = json.load(f)

print("\n" + "=" * 80)
print("MODEL 4 — REAL-WORLD SCENE PREDICTIONS")
print("=" * 80)

for x in m4[:10]:

    readable = []

    for p in x.get("top5", []):
        cid = int(p["class_id"])

        if 0 <= cid < len(categories):
            name = categories[cid][1]
        else:
            name = "UNKNOWN"

        readable.append(
            f"{name} ({p['confidence']:.4f})"
        )

    print(x["image_id"], "=>")
    for r in readable:
        print("   ", r)

# ------------------------------------------------------------
# MODEL 8 — depth QC
# ------------------------------------------------------------

with open(
    os.path.join(RESULTS, "model8_predictions.json"),
    "r",
    encoding="utf-8"
) as f:
    m8 = json.load(f)

rows = []

for x in m8:

    d = x.get("depth_summary")

    if not isinstance(d, dict):
        continue

    rows.append({
        "image_id": x["image_id"],
        "min_m": d.get("min_m"),
        "median_m": d.get("median_m"),
        "mean_m": d.get("mean_m"),
        "max_m": d.get("max_m"),
        "latency_ms": x.get("latency_ms")
    })

df = pd.DataFrame(rows)

print("\n" + "=" * 80)
print("MODEL 8 — DEPTH RANGE SUMMARY")
print("=" * 80)

print(df.to_string(index=False))

print("\nStatistics across the 23 images:")
print(
    df[
        ["min_m", "median_m", "mean_m", "max_m", "latency_ms"]
    ].describe().round(3)
)

print("\n" + "=" * 80)
print("QC COMPLETE")
print("=" * 80)

# ============================================================
# REAL-WORLD EVALUATION REPORT V1
# ============================================================

import os
import json
import pandas as pd
from datetime import datetime

BASE = "/content/real_world_eval"
RESULTS = os.path.join(BASE, "results_combined")
REPORT_DIR = os.path.join(BASE, "REAL_WORLD_REPORT_V1")

os.makedirs(REPORT_DIR, exist_ok=True)

# ------------------------------------------------------------
# Load combined summary
# ------------------------------------------------------------

with open(
    os.path.join(RESULTS, "REAL_WORLD_COMBINED_001_summary.json"),
    "r",
    encoding="utf-8"
) as f:
    combined = json.load(f)

# ------------------------------------------------------------
# Load individual model outputs
# ------------------------------------------------------------

model_data = {}

for i in range(1, 9):
    path = os.path.join(
        RESULTS,
        f"model{i}_predictions.json"
    )

    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as f:
            model_data[i] = json.load(f)

# ------------------------------------------------------------
# Build report
# ------------------------------------------------------------

report = {
    "report_id": "REAL_WORLD_REPORT_V1",
    "created_at": datetime.now().isoformat(),
    "source": "genuine internet photographs",
    "source_platform": "Unsplash CDN",
    "total_images": 34,

    "evaluation_purpose": (
        "Functional real-world inference pilot. "
        "The images are not accompanied by independent ground truth, "
        "so quantitative accuracy metrics are not claimed unless "
        "independent reference annotations exist."
    ),

    "models": {}
}

# ------------------------------------------------------------
# Model 1
# ------------------------------------------------------------

m1 = model_data.get(1, [])

report["models"]["model1_object_detection"] = {
    "records": len(m1),
    "total_detections": sum(
        len(x.get("detections", []))
        for x in m1
    ),
    "quantitative_accuracy": "not available",
    "reason": "No independent bounding-box ground truth for the web photographs."
}

# ------------------------------------------------------------
# Model 2
# ------------------------------------------------------------

m2 = model_data.get(2, [])

report["models"]["model2_road_scene"] = {
    "records": len(m2),
    "inference_status": "not executed",
    "quantitative_accuracy": "not available",
    "reason": "Requires an actual road-scene model and independent ground-truth annotations."
}

# ------------------------------------------------------------
# Model 3
# ------------------------------------------------------------

m3 = model_data.get(3, [])

report["models"]["model3_obstacle_segmentation"] = {
    "records": len(m3),
    "total_detections": sum(
        len(x.get("detections", []))
        for x in m3
    ),
    "quantitative_accuracy": "not available",
    "reason": (
        "No manually validated obstacle/non-obstacle masks. "
        "The current real-world run records segmentation-model detections."
    )
}

# ------------------------------------------------------------
# Model 4
# ------------------------------------------------------------

m4 = model_data.get(4, [])

report["models"]["model4_scene_recognition"] = {
    "records": len(m4),
    "classes": 365,
    "quantitative_accuracy": "not available",
    "reason": "No independent human/reference scene labels for these photographs."
}

# ------------------------------------------------------------
# Model 5
# ------------------------------------------------------------

m5 = model_data.get(5, [])

empty_captions = sum(
    1 for x in m5
    if not str(x.get("caption", "")).strip()
)

report["models"]["model5_captioning"] = {
    "records": len(m5),
    "nonempty_captions": len(m5) - empty_captions,
    "empty_captions": empty_captions,
    "quantitative_accuracy": "not available",
    "reason": "No independent human reference captions."
}

# ------------------------------------------------------------
# Model 6
# ------------------------------------------------------------

m6 = model_data.get(6, [])

ocr_regions = sum(
    len(x.get("ocr", x.get("detections", [])))
    for x in m6
)

report["models"]["model6_ocr"] = {
    "records": len(m6),
    "ocr_regions": ocr_regions,
    "quantitative_accuracy": "not available",
    "reason": "No manually transcribed ground-truth text for the web photographs."
}

# ------------------------------------------------------------
# Model 7
# ------------------------------------------------------------

m7 = model_data.get(7, [])

report["models"]["model7_navigation"] = {
    "records": len(m7),
    "inference_status": "not executed",
    "quantitative_accuracy": "not available",
    "reason": "Requires independent GPS/POI ground truth."
}

# ------------------------------------------------------------
# Model 8
# ------------------------------------------------------------

m8 = model_data.get(8, [])

valid_depth = sum(
    1 for x in m8
    if isinstance(x.get("depth_summary"), dict)
)

report["models"]["model8_depth"] = {
    "records": len(m8),
    "valid_depth_outputs": valid_depth,
    "quantitative_accuracy": "not available",
    "reason": (
        "No independently measured object distances or depth maps. "
        "Raw predicted depth ranges are therefore not accuracy measurements."
    ),
    "quality_note": (
        "Several images contain extreme predicted depth values; "
        "mean/max depth should not be interpreted as ground-truth accuracy."
    )
}

# ------------------------------------------------------------
# Timing
# ------------------------------------------------------------

timing_path = os.path.join(
    RESULTS,
    "combined_timing_summary.json"
)

if os.path.exists(timing_path):
    with open(timing_path, "r", encoding="utf-8") as f:
        timing = json.load(f)
else:
    timing = {}

report["timing"] = timing

# ------------------------------------------------------------
# Save JSON
# ------------------------------------------------------------

json_path = os.path.join(
    REPORT_DIR,
    "REAL_WORLD_REPORT_V1.json"
)

with open(
    json_path,
    "w",
    encoding="utf-8"
) as f:
    json.dump(report, f, indent=2)

# ------------------------------------------------------------
# Save CSV summary
# ------------------------------------------------------------

rows = []

for model_name, data in report["models"].items():

    rows.append({
        "model": model_name,
        "records": data.get("records"),
        "inference_status": data.get(
            "inference_status",
            "executed"
        ),
        "quantitative_accuracy": data.get(
            "quantitative_accuracy"
        ),
        "reason": data.get("reason"),
        "quality_note": data.get("quality_note", "")
    })

csv_path = os.path.join(
    REPORT_DIR,
    "REAL_WORLD_REPORT_V1.csv"
)

pd.DataFrame(rows).to_csv(
    csv_path,
    index=False
)

# ------------------------------------------------------------
# Human-readable TXT report
# ------------------------------------------------------------

txt_path = os.path.join(
    REPORT_DIR,
    "REAL_WORLD_REPORT_V1.txt"
)

with open(txt_path, "w", encoding="utf-8") as f:

    f.write("=" * 80 + "\n")
    f.write("REAL-WORLD EVALUATION REPORT V1\n")
    f.write("=" * 80 + "\n\n")

    f.write("Source: genuine internet photographs\n")
    f.write("Platform: Unsplash CDN\n")
    f.write("Images: 34\n\n")

    f.write(
        "Purpose: functional real-world inference pilot.\n"
        "The photographs do not have independent ground truth, so\n"
        "accuracy metrics are not claimed for these web images.\n\n"
    )

    for model_name, data in report["models"].items():

        f.write("-" * 80 + "\n")
        f.write(model_name.upper() + "\n")
        f.write("-" * 80 + "\n")

        for key, value in data.items():
            f.write(f"{key}: {value}\n")

        f.write("\n")

    f.write("=" * 80 + "\n")
    f.write("END OF REPORT\n")
    f.write("=" * 80 + "\n")

print("=" * 80)
print("REAL-WORLD REPORT V1 CREATED")
print("=" * 80)

print("JSON :", json_path)
print("CSV  :", csv_path)
print("TXT  :", txt_path)

print("\nModel summary:")

for model_name, data in report["models"].items():
    print(
        f"{model_name}: "
        f"{data.get('records', 0)} records | "
        f"accuracy={data.get('quantitative_accuracy')}"
    )

print("\n" + "=" * 80)
print("REPORT COMPLETE")
print("=" * 80)

