# ============================================================

import os

ROOT = "/content"

TARGET_TERMS = [
    "yolov8",
    "yolo",
    "coco",
    "object",
    "detection",
]

EXCLUDE_TERMS = [
    "module8",
    "depth",
    "unidepth",
    "kitti",
]

matches = []

for root, dirs, files in os.walk(ROOT):

    # Skip known irrelevant trees
    dirs[:] = [
        d for d in dirs
        if d not in {
            "node_modules",
            ".git",
            "__pycache__",
        }
    ]

    for f in files:

        path = os.path.join(root, f)
        low = path.lower()

        if any(x in low for x in EXCLUDE_TERMS):
            continue

        if any(x in low for x in TARGET_TERMS):
            matches.append(path)

matches = sorted(set(matches))

print("=" * 80)
print("TARGETED MODULE 1 SEARCH")
print("=" * 80)

print("Matches:", len(matches))

for p in matches[:250]:
    print(p)

print("=" * 80)
print("END SEARCH")
print("=" * 80)

