import os
import json
import random
import pandas as pd

SEED = 42
N = 1000

BASE = "/content/real_world_eval/coco2017"
ANN = os.path.join(
    BASE,
    "annotations",
    "instances_val2017.json"
)

OUT = "/content/module1_eval_1000"
SUBSET = os.path.join(OUT, "EXP_002_subset_1000")

os.makedirs(SUBSET, exist_ok=True)

assert os.path.exists(ANN), f"Missing annotation file: {ANN}"
assert os.path.exists("/content/yolov8n.pt"), "Missing YOLOv8n checkpoint"

# ------------------------------------------------------------
# Load COCO validation annotations
# ------------------------------------------------------------

with open(ANN, "r", encoding="utf-8") as f:
    coco = json.load(f)

images = coco["images"]
annotations = coco["annotations"]
categories = coco["categories"]

print("=" * 80)
print("MODULE 1 — COCO 2017 VALIDATION INVENTORY")
print("=" * 80)

print("Images:", len(images))
print("Annotations:", len(annotations))
print("Categories:", len(categories))

assert len(images) == 5000, (
    f"Expected 5000 COCO val images, found {len(images)}"
)

assert len(categories) == 80, (
    f"Expected 80 categories, found {len(categories)}"
)

# ------------------------------------------------------------
# Fixed seed 42
# ------------------------------------------------------------

rng = random.Random(SEED)

selected = rng.sample(images, N)

selected = sorted(
    selected,
    key=lambda x: x["id"]
)

# ------------------------------------------------------------
# Build annotation lookup
# ------------------------------------------------------------

ann_by_image = {}

for ann in annotations:
    image_id = ann["image_id"]
    ann_by_image.setdefault(image_id, []).append(ann)

# ------------------------------------------------------------
# Build manifest
# ------------------------------------------------------------

rows = []

for idx, img in enumerate(selected, start=1):

    image_id = img["id"]
    anns = ann_by_image.get(image_id, [])

    rows.append({
        "subset_index": idx,
        "image_id": image_id,
        "filename": img["file_name"],
        "width": img["width"],
        "height": img["height"],
        "num_annotations": len(anns)
    })

manifest = pd.DataFrame(rows)

# ------------------------------------------------------------
# Integrity checks
# ------------------------------------------------------------

assert len(manifest) == N
assert manifest["image_id"].nunique() == N
assert manifest["filename"].nunique() == N

# Check that none of the old 50 real-world images are being
# accidentally treated as this benchmark subset.
old_realworld_dir = (
    "/content/real_world_eval/coco2017_realworld_separate"
)

old_files = set()

if os.path.isdir(old_realworld_dir):
    old_files = {
        f for f in os.listdir(old_realworld_dir)
        if f.lower().endswith(".jpg")
    }

overlap = set(manifest["filename"]) & old_files

print("\nIntegrity:")
print("Unique image IDs:", manifest["image_id"].nunique())
print("Unique filenames:", manifest["filename"].nunique())
print("Overlap with separate real-world COCO set:", len(overlap))

assert len(overlap) == 0, (
    "Benchmark subset overlaps the separate real-world COCO set."
)

# ------------------------------------------------------------
# Save manifest
# ------------------------------------------------------------

csv_path = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.csv"
)

json_path = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.json"
)

manifest.to_csv(csv_path, index=False)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(
        {
            "experiment_id": "EXP_002",
            "module": "Module 1 — Object Detection",
            "dataset": "COCO 2017 validation",
            "seed": SEED,
            "target_images": N,
            "images": rows
        },
        f,
        indent=2
    )

print("\n" + "=" * 80)
print("EXP_002 MANIFEST CREATED")
print("=" * 80)

print("Dataset:", "COCO 2017 validation")
print("Seed:", SEED)
print("Images:", len(manifest))
print("Annotations represented:", int(manifest["num_annotations"].sum()))
print("CSV:", csv_path)
print("JSON:", json_path)

print("\nFirst 10:")
print(manifest.head(10).to_string(index=False))

print("\nLast 10:")
print(manifest.tail(10).to_string(index=False))

print("=" * 80)
print("MANIFEST READY — NO INFERENCE RUN YET")
