# ============================================================
# MODULE 1 — CORRECTED 1,000 IMAGE MANIFEST
# EXP_002
# Excludes the separate 50-image real-world COCO set
# ============================================================

import os
import json
import random
import pandas as pd

SEED = 42
N = 1000

BASE = "/content/real_world_eval/coco2017"
ANN = os.path.join(BASE, "annotations", "instances_val2017.json")

OUT = "/content/module1_eval_1000"
SUBSET = os.path.join(OUT, "EXP_002_subset_1000")

os.makedirs(SUBSET, exist_ok=True)

# ------------------------------------------------------------
# Load COCO annotations
# ------------------------------------------------------------

with open(ANN, "r", encoding="utf-8") as f:
    coco = json.load(f)

images = coco["images"]
annotations = coco["annotations"]

# ------------------------------------------------------------
# Identify images used in the separate real-world experiment
# ------------------------------------------------------------

realworld_dir = (
    "/content/real_world_eval/coco2017_realworld_separate"
)

excluded_filenames = {
    f for f in os.listdir(realworld_dir)
    if f.lower().endswith(".jpg")
}

excluded_ids = {
    int(os.path.splitext(f)[0])
    for f in excluded_filenames
    if os.path.splitext(f)[0].isdigit()
}

print("=" * 80)
print("MODULE 1 — CORRECTED SUBSET")
print("=" * 80)

print("Total COCO val images:", len(images))
print("Excluded real-world images:", len(excluded_ids))

# ------------------------------------------------------------
# Candidate pool
# ------------------------------------------------------------

eligible = [
    img for img in images
    if img["id"] not in excluded_ids
]

print("Eligible images:", len(eligible))

assert len(eligible) >= N

# ------------------------------------------------------------
# Deterministic sampling
# ------------------------------------------------------------

rng = random.Random(SEED)

selected = rng.sample(eligible, N)

selected = sorted(
    selected,
    key=lambda x: x["id"]
)

# ------------------------------------------------------------
# Annotation lookup
# ------------------------------------------------------------

ann_by_image = {}

for ann in annotations:
    ann_by_image.setdefault(
        ann["image_id"],
        []
    ).append(ann)

# ------------------------------------------------------------
# Build manifest
# ------------------------------------------------------------

rows = []

for idx, img in enumerate(selected, start=1):

    image_id = img["id"]
    anns = ann_by_image.get(image_id, [])

    rows.append({
        "subset_index": idx,
        "image_id": image_id,
        "filename": img["file_name"],
        "width": img["width"],
        "height": img["height"],
        "num_annotations": len(anns)
    })

manifest = pd.DataFrame(rows)

# ------------------------------------------------------------
# Final integrity checks
# ------------------------------------------------------------

assert len(manifest) == N
assert manifest["image_id"].nunique() == N
assert manifest["filename"].nunique() == N

overlap_ids = (
    set(manifest["image_id"]) &
    excluded_ids
)

overlap_files = (
    set(manifest["filename"]) &
    excluded_filenames
)

print("\nFinal integrity:")
print("Images:", len(manifest))
print("Unique IDs:", manifest["image_id"].nunique())
print("Unique filenames:", manifest["filename"].nunique())
print("Excluded-ID overlap:", len(overlap_ids))
print("Excluded-file overlap:", len(overlap_files))
print(
    "Total GT annotations:",
    int(manifest["num_annotations"].sum())
)

assert len(overlap_ids) == 0
assert len(overlap_files) == 0

# ------------------------------------------------------------
# Save
# ------------------------------------------------------------

csv_path = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.csv"
)

json_path = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.json"
)

manifest.to_csv(
    csv_path,
    index=False
)

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(
        {
            "experiment_id": "EXP_002",
            "module": "Module 1 — Object Detection",
            "dataset": "COCO 2017 validation",
            "seed": SEED,
            "target_images": N,
            "excluded_real_world_images": len(excluded_ids),
            "images": rows
        },
        f,
        indent=2
    )

print("\n" + "=" * 80)
print("EXP_002 MANIFEST READY")
print("=" * 80)

print("CSV :", csv_path)
print("JSON:", json_path)

print("\nFirst 5:")
print(manifest.head().to_string(index=False))

print("\nLast 5:")
print(manifest.tail().to_string(index=False))

print("=" * 80)
print("NO INFERENCE RUN YET")
print("=" * 80)

# ============================================================
# MODULE 1 — YOLOv8n INFERENCE
# EXP_002 — 1,000 IMAGES
# ============================================================

import os
import json
import time
import numpy as np
import pandas as pd
import torch
from PIL import Image
from ultralytics import YOLO

# ------------------------------------------------------------
# Paths
# ------------------------------------------------------------

BASE = "/content/real_world_eval/coco2017"
SUBSET = "/content/module1_eval_1000/EXP_002_subset_1000"
RESULTS = "/content/module1_eval_1000/EXP_002_results"

os.makedirs(RESULTS, exist_ok=True)

MANIFEST = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.csv"
)

ANN = os.path.join(
    BASE,
    "annotations",
    "instances_val2017.json"
)

MODEL_PATH = "/content/yolov8n.pt"

# ------------------------------------------------------------
# Load data
# ------------------------------------------------------------

manifest = pd.read_csv(MANIFEST)

with open(ANN, "r", encoding="utf-8") as f:
    coco = json.load(f)

ann_by_image = {}

for ann in coco["annotations"]:
    ann_by_image.setdefault(
        ann["image_id"],
        []
    ).append(ann)

# COCO category IDs
categories = {
    c["id"]: c["name"]
    for c in coco["categories"]
}

print("=" * 80)
print("MODULE 1 — YOLOv8n EXP_002")
print("=" * 80)

print("Images:", len(manifest))
print("Model:", MODEL_PATH)
print("GPU available:", torch.cuda.is_available())

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))

# ------------------------------------------------------------
# Load model
# ------------------------------------------------------------

model = YOLO(MODEL_PATH)

# ------------------------------------------------------------
# COCO category mapping
# YOLOv8 COCO class IDs use the standard 0-79 ordering.
# Build COCO category-id -> YOLO class-id mapping.
# ------------------------------------------------------------

# COCO category IDs are not contiguous.
# Standard COCO YOLO order is represented by the sorted
# category list used by Ultralytics.

sorted_categories = sorted(
    coco["categories"],
    key=lambda x: x["id"]
)

coco_id_to_yolo = {
    c["id"]: idx
    for idx, c in enumerate(sorted_categories)
}

# ------------------------------------------------------------
# Inference
# ------------------------------------------------------------

predictions = []

latencies = []

for i, row in manifest.iterrows():

    image_id = int(row["image_id"])
    filename = row["filename"]

    image_path = os.path.join(
        BASE,
        "images",
        "val2017",
        filename
    )

    if not os.path.exists(image_path):
        # fallback: download location used by the earlier setup
        image_path = os.path.join(
            "/content/real_world_eval/coco2017_realworld_separate",
            filename
        )

    if not os.path.exists(image_path):
        predictions.append({
            "image_id": image_id,
            "filename": filename,
            "status": "missing_image",
            "detections": []
        })
        continue

    start = time.perf_counter()

    result = model.predict(
        source=image_path,
        imgsz=640,
        conf=0.25,
        verbose=False,
        device=0 if torch.cuda.is_available() else "cpu"
    )[0]

    latency_ms = (
        time.perf_counter() - start
    ) * 1000.0

    latencies.append(latency_ms)

    detections = []

    if result.boxes is not None:

        boxes = result.boxes

        xyxy = boxes.xyxy.cpu().numpy()
        conf = boxes.conf.cpu().numpy()
        cls = boxes.cls.cpu().numpy().astype(int)

        for b, c, k in zip(
            xyxy,
            conf,
            cls
        ):
            detections.append({
                "class_id": int(k),
                "class_name": model.names.get(
                    int(k),
                    str(k)
                ),
                "confidence": float(c),
                "bbox_xyxy": [
                    float(v) for v in b
                ]
            })

    predictions.append({
        "image_id": image_id,
        "filename": filename,
        "status": "ok",
        "latency_ms": float(latency_ms),
        "detections": detections
    })

    if (i + 1) % 100 == 0:
        print(
            f"[{i+1:4d}/{len(manifest)}] "
            f"avg latency so far: "
            f"{np.mean(latencies):.2f} ms"
        )

# ------------------------------------------------------------
# Save predictions
# ------------------------------------------------------------

pred_json = os.path.join(
    RESULTS,
    "EXP_002_predictions.json"
)

with open(
    pred_json,
    "w",
    encoding="utf-8"
) as f:
    json.dump(
        predictions,
        f,
        indent=2
    )

# Flat CSV
csv_rows = []

for p in predictions:

    for d in p.get("detections", []):

        csv_rows.append({
            "image_id": p["image_id"],
            "filename": p["filename"],
            "class_id": d["class_id"],
            "class_name": d["class_name"],
            "confidence": d["confidence"],
            "x1": d["bbox_xyxy"][0],
            "y1": d["bbox_xyxy"][1],
            "x2": d["bbox_xyxy"][2],
            "y2": d["bbox_xyxy"][3],
            "latency_ms": p.get("latency_ms")
        })

pred_csv = os.path.join(
    RESULTS,
    "EXP_002_predictions.csv"
)

pd.DataFrame(csv_rows).to_csv(
    pred_csv,
    index=False
)

# ------------------------------------------------------------
# Timing summary
# ------------------------------------------------------------

valid_latencies = np.asarray(
    latencies,
    dtype=float
)

timing = {
    "images_total": len(manifest),
    "images_inferred": len(valid_latencies),
    "images_missing": len(manifest) - len(valid_latencies),
    "avg_latency_ms": float(valid_latencies.mean())
        if len(valid_latencies) else None,
    "median_latency_ms": float(np.median(valid_latencies))
        if len(valid_latencies) else None,
    "fps": float(1000.0 / valid_latencies.mean())
        if len(valid_latencies) else None
}

timing_path = os.path.join(
    RESULTS,
    "EXP_002_timing.json"
)

with open(
    timing_path,
    "w",
    encoding="utf-8"
) as f:
    json.dump(
        timing,
        f,
        indent=2
    )

# ------------------------------------------------------------
# Summary
# ------------------------------------------------------------

total_detections = sum(
    len(p.get("detections", []))
    for p in predictions
)

print("\n" + "=" * 80)
print("MODULE 1 EXP_002 INFERENCE COMPLETE")
print("=" * 80)

print("Images:", len(manifest))
print("Inferred:", len(valid_latencies))
print("Missing:", timing["images_missing"])
print("Total detections:", total_detections)

print(
    "Average latency:",
    f"{timing['avg_latency_ms']:.2f} ms"
)

print(
    "Median latency:",
    f"{timing['median_latency_ms']:.2f} ms"
)

print(
    "Approx FPS:",
    f"{timing['fps']:.2f}"
)

print("\nPredictions:", pred_json)
print("CSV:", pred_csv)
print("Timing:", timing_path)

print("=" * 80)

# ============================================================
# MODULE 1 — DOWNLOAD EXACT EXP_002 IMAGES
# ============================================================

import os
import time
import requests
import pandas as pd
from concurrent.futures import ThreadPoolExecutor, as_completed

SUBSET = "/content/module1_eval_1000/EXP_002_subset_1000"
IMAGE_DIR = os.path.join(SUBSET, "images")
MANIFEST = os.path.join(SUBSET, "EXP_002_ground_truth.csv")

os.makedirs(IMAGE_DIR, exist_ok=True)

manifest = pd.read_csv(MANIFEST)

print("=" * 80)
print("MODULE 1 — DOWNLOADING EXACT 1,000 COCO IMAGES")
print("=" * 80)

print("Target images:", len(manifest))
print("Destination:", IMAGE_DIR)

# ------------------------------------------------------------
# Download one image
# ------------------------------------------------------------

def download_one(filename):

    out = os.path.join(
        IMAGE_DIR,
        filename
    )

    if os.path.exists(out) and os.path.getsize(out) > 0:
        return filename, "already_present"

    url = (
        "http://images.cocodataset.org/"
        "val2017/"
        + filename
    )

    try:
        r = requests.get(
            url,
            timeout=30
        )

        if r.status_code != 200:
            return filename, f"http_{r.status_code}"

        with open(out, "wb") as f:
            f.write(r.content)

        if os.path.getsize(out) == 0:
            return filename, "empty_file"

        return filename, "downloaded"

    except Exception as e:
        return filename, f"error:{type(e).__name__}"

# ------------------------------------------------------------
# Parallel download
# ------------------------------------------------------------

results = []

start = time.perf_counter()

with ThreadPoolExecutor(max_workers=16) as executor:

    futures = [
        executor.submit(
            download_one,
            filename
        )
        for filename in manifest["filename"]
    ]

    for i, future in enumerate(
        as_completed(futures),
        start=1
    ):

        filename, status = future.result()
        results.append((filename, status))

        if i % 100 == 0:
            print(
                f"[{i:4d}/{len(manifest)}] "
                f"elapsed={time.perf_counter()-start:.1f}s"
            )

# ------------------------------------------------------------
# Verification
# ------------------------------------------------------------

status_counts = pd.Series(
    [x[1] for x in results]
).value_counts()

print("\n" + "=" * 80)
print("DOWNLOAD STATUS")
print("=" * 80)

print(status_counts.to_string())

missing = []
invalid = []

for filename in manifest["filename"]:

    path = os.path.join(
        IMAGE_DIR,
        filename
    )

    if not os.path.exists(path):
        missing.append(filename)
        continue

    if os.path.getsize(path) == 0:
        invalid.append(filename)

print("\nVerification:")
print("Expected:", len(manifest))
print("Present:", len(manifest) - len(missing) - len(invalid))
print("Missing:", len(missing))
print("Empty:", len(invalid))

if missing:
    print("\nFirst missing:")
    print(missing[:20])

if invalid:
    print("\nInvalid/empty:")
    print(invalid[:20])

assert len(missing) == 0, (
    f"{len(missing)} images are missing."
)

assert len(invalid) == 0, (
    f"{len(invalid)} images are empty."
)

print("\n" + "=" * 80)
print("ALL 1,000 EXP_002 IMAGES VERIFIED")
print("=" * 80)

# ============================================================
# MODULE 1 — YOLOv8n INFERENCE
# EXP_002 — 1,000 VERIFIED IMAGES
# ============================================================

import os
import json
import time
import numpy as np
import pandas as pd
import torch
from ultralytics import YOLO

SUBSET = "/content/module1_eval_1000/EXP_002_subset_1000"
IMAGE_DIR = os.path.join(SUBSET, "images")
RESULTS = "/content/module1_eval_1000/EXP_002_results"

MANIFEST = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.csv"
)

MODEL_PATH = "/content/yolov8n.pt"

os.makedirs(RESULTS, exist_ok=True)

manifest = pd.read_csv(MANIFEST)

print("=" * 80)
print("MODULE 1 — YOLOv8n EXP_002")
print("=" * 80)

print("Images:", len(manifest))
print("Image directory:", IMAGE_DIR)
print("Model:", MODEL_PATH)
print("GPU:", torch.cuda.get_device_name(0))

# ------------------------------------------------------------
# Verify files before inference
# ------------------------------------------------------------

missing = [
    f for f in manifest["filename"]
    if not os.path.exists(os.path.join(IMAGE_DIR, f))
]

assert len(missing) == 0, (
    f"{len(missing)} images are missing before inference."
)

# ------------------------------------------------------------
# Load model
# ------------------------------------------------------------

model = YOLO(MODEL_PATH)

# ------------------------------------------------------------
# Run inference
# ------------------------------------------------------------

predictions = []
latencies = []

start_all = time.perf_counter()

for i, row in manifest.iterrows():

    image_id = int(row["image_id"])
    filename = row["filename"]

    image_path = os.path.join(
        IMAGE_DIR,
        filename
    )

    start = time.perf_counter()

    result = model.predict(
        source=image_path,
        imgsz=640,
        conf=0.25,
        verbose=False,
        device=0
    )[0]

    latency_ms = (
        time.perf_counter() - start
    ) * 1000.0

    latencies.append(latency_ms)

    detections = []

    if result.boxes is not None:

        xyxy = result.boxes.xyxy.cpu().numpy()
        conf = result.boxes.conf.cpu().numpy()
        cls = result.boxes.cls.cpu().numpy().astype(int)

        for box, score, class_id in zip(
            xyxy,
            conf,
            cls
        ):

            detections.append({
                "class_id": int(class_id),
                "class_name": model.names.get(
                    int(class_id),
                    str(class_id)
                ),
                "confidence": float(score),
                "bbox_xyxy": [
                    float(v) for v in box
                ]
            })

    predictions.append({
        "image_id": image_id,
        "filename": filename,
        "status": "ok",
        "latency_ms": float(latency_ms),
        "detections": detections
    })

    if (i + 1) % 100 == 0:

        elapsed = time.perf_counter() - start_all

        print(
            f"[{i+1:4d}/{len(manifest)}] "
            f"elapsed={elapsed:.1f}s | "
            f"avg latency={np.mean(latencies):.2f} ms"
        )

# ------------------------------------------------------------
# Save predictions
# ------------------------------------------------------------

pred_json = os.path.join(
    RESULTS,
    "EXP_002_predictions.json"
)

with open(
    pred_json,
    "w",
    encoding="utf-8"
) as f:
    json.dump(
        predictions,
        f,
        indent=2
    )

# Flat CSV
csv_rows = []

for p in predictions:

    for d in p["detections"]:

        csv_rows.append({
            "image_id": p["image_id"],
            "filename": p["filename"],
            "class_id": d["class_id"],
            "class_name": d["class_name"],
            "confidence": d["confidence"],
            "x1": d["bbox_xyxy"][0],
            "y1": d["bbox_xyxy"][1],
            "x2": d["bbox_xyxy"][2],
            "y2": d["bbox_xyxy"][3],
            "latency_ms": p["latency_ms"]
        })

pred_csv = os.path.join(
    RESULTS,
    "EXP_002_predictions.csv"
)

pd.DataFrame(csv_rows).to_csv(
    pred_csv,
    index=False
)

# ------------------------------------------------------------
# Timing
# ------------------------------------------------------------

latencies = np.asarray(
    latencies,
    dtype=float
)

timing = {
    "images_total": len(manifest),
    "images_inferred": len(latencies),
    "avg_latency_ms": float(np.mean(latencies)),
    "median_latency_ms": float(np.median(latencies)),
    "fps": float(1000.0 / np.mean(latencies)),
    "total_runtime_seconds": float(
        time.perf_counter() - start_all
    )
}

timing_path = os.path.join(
    RESULTS,
    "EXP_002_timing.json"
)

with open(
    timing_path,
    "w",
    encoding="utf-8"
) as f:
    json.dump(
        timing,
        f,
        indent=2
    )

# ------------------------------------------------------------
# Final output
# ------------------------------------------------------------

total_detections = sum(
    len(p["detections"])
    for p in predictions
)

print("\n" + "=" * 80)
print("MODULE 1 EXP_002 INFERENCE COMPLETE")
print("=" * 80)

print("Images:", len(manifest))
print("Inferred:", len(latencies))
print("Total detections:", total_detections)
print(
    "Average latency:",
    f"{timing['avg_latency_ms']:.2f} ms"
)
print(
    "Median latency:",
    f"{timing['median_latency_ms']:.2f} ms"
)
print(
    "Approx FPS:",
    f"{timing['fps']:.2f}"
)
print(
    "Total runtime:",
    f"{timing['total_runtime_seconds']:.1f} s"
)

print("\nPredictions:", pred_json)
print("CSV:", pred_csv)
print("Timing:", timing_path)

print("=" * 80)

# ============================================================
# MODULE 1 — EXP_002 ACCURACY METRICS
# COCO 2017 VAL — 1,000 IMAGES
# ============================================================

import os
import json
import numpy as np
import pandas as pd
from collections import defaultdict

SUBSET = "/content/module1_eval_1000/EXP_002_subset_1000"
RESULTS = "/content/module1_eval_1000/EXP_002_results"

MANIFEST = os.path.join(
    SUBSET,
    "EXP_002_ground_truth.csv"
)

PRED_JSON = os.path.join(
    RESULTS,
    "EXP_002_predictions.json"
)

ANN = "/content/real_world_eval/coco2017/annotations/instances_val2017.json"

# ------------------------------------------------------------
# Load
# ------------------------------------------------------------

manifest = pd.read_csv(MANIFEST)

with open(PRED_JSON, "r", encoding="utf-8") as f:
    predictions = json.load(f)

with open(ANN, "r", encoding="utf-8") as f:
    coco = json.load(f)

# ------------------------------------------------------------
# Ground-truth lookup
# ------------------------------------------------------------

gt_by_image = defaultdict(list)

for ann in coco["annotations"]:
    gt_by_image[ann["image_id"]].append(ann)

# COCO category IDs -> contiguous YOLO class IDs
sorted_categories = sorted(
    coco["categories"],
    key=lambda x: x["id"]
)

coco_to_yolo = {
    c["id"]: idx
    for idx, c in enumerate(sorted_categories)
}

# ------------------------------------------------------------
# IoU
# ------------------------------------------------------------

def box_iou(a, b):

    ax1, ay1, ax2, ay2 = a
    bx1, by1, bx2, by2 = b

    ix1 = max(ax1, bx1)
    iy1 = max(ay1, by1)
    ix2 = min(ax2, bx2)
    iy2 = min(ay2, by2)

    iw = max(0.0, ix2 - ix1)
    ih = max(0.0, iy2 - iy1)

    inter = iw * ih

    area_a = max(0.0, ax2 - ax1) * max(0.0, ay2 - ay1)
    area_b = max(0.0, bx2 - bx1) * max(0.0, by2 - by1)

    union = area_a + area_b - inter

    if union <= 0:
        return 0.0

    return inter / union

# ------------------------------------------------------------
# Match predictions to GT
# ------------------------------------------------------------

def evaluate_at_iou(iou_threshold):

    TP = 0
    FP = 0
    FN = 0

    per_class = defaultdict(
        lambda: {
            "tp": 0,
            "fp": 0,
            "fn": 0
        }
    )

    for pred_record in predictions:

        image_id = int(pred_record["image_id"])

        gt = gt_by_image.get(
            image_id,
            []
        )

        gt_items = []

        for ann in gt:

            x, y, w, h = ann["bbox"]

            gt_box = [
                float(x),
                float(y),
                float(x + w),
                float(y + h)
            ]

            cls = coco_to_yolo[
                ann["category_id"]
            ]

            gt_items.append({
                "box": gt_box,
                "class_id": cls,
                "matched": False
            })

        preds = sorted(
            pred_record.get("detections", []),
            key=lambda x: x["confidence"],
            reverse=True
        )

        for pred in preds:

            pcls = int(pred["class_id"])
            pbox = pred["bbox_xyxy"]

            best_iou = 0.0
            best_idx = None

            for j, g in enumerate(gt_items):

                if g["matched"]:
                    continue

                if g["class_id"] != pcls:
                    continue

                iou = box_iou(
                    pbox,
                    g["box"]
                )

                if iou > best_iou:
                    best_iou = iou
                    best_idx = j

            if (
                best_idx is not None
                and best_iou >= iou_threshold
            ):

                gt_items[best_idx]["matched"] = True

                TP += 1
                per_class[pcls]["tp"] += 1

            else:

                FP += 1
                per_class[pcls]["fp"] += 1

        for g in gt_items:

            if not g["matched"]:

                FN += 1
                per_class[
                    g["class_id"]
                ]["fn"] += 1

    precision = (
        TP / (TP + FP)
        if TP + FP > 0
        else 0.0
    )

    recall = (
        TP / (TP + FN)
        if TP + FN > 0
        else 0.0
    )

    f1 = (
        2 * precision * recall /
        (precision + recall)
        if precision + recall > 0
        else 0.0
    )

    return {
        "iou_threshold": iou_threshold,
        "tp": TP,
        "fp": FP,
        "fn": FN,
        "precision": precision,
        "recall": recall,
        "f1": f1,
        "per_class": dict(per_class)
    }

# ------------------------------------------------------------
# Evaluate IoU 0.50 and 0.75
# ------------------------------------------------------------

metrics_50 = evaluate_at_iou(0.50)
metrics_75 = evaluate_at_iou(0.75)

# ------------------------------------------------------------
# Save summary
# ------------------------------------------------------------

summary = {
    "experiment_id": "EXP_002",
    "module": "Module 1 — Object Detection",
    "dataset": "COCO 2017 validation",
    "images": len(manifest),
    "seed": 42,
    "metrics": {
        "iou_0.50": {
            k: v
            for k, v in metrics_50.items()
            if k != "per_class"
        },
        "iou_0.75": {
            k: v
            for k, v in metrics_75.items()
            if k != "per_class"
        }
    }
}

summary_path = os.path.join(
    RESULTS,
    "EXP_002_summary.json"
)

with open(
    summary_path,
    "w",
    encoding="utf-8"
) as f:
    json.dump(
        summary,
        f,
        indent=2
    )

# ------------------------------------------------------------
# Print
# ------------------------------------------------------------

print("=" * 80)
print("MODULE 1 — EXP_002 ACCURACY")
print("=" * 80)

for name, m in [
    ("IoU 0.50", metrics_50),
    ("IoU 0.75", metrics_75)
]:

    print("\n" + name)
    print("-" * 40)
    print("TP:", m["tp"])
    print("FP:", m["fp"])
    print("FN:", m["fn"])
    print(
        "Precision:",
        f"{m['precision'] * 100:.2f}%"
    )
    print(
        "Recall:",
        f"{m['recall'] * 100:.2f}%"
    )
    print(
        "F1:",
        f"{m['f1'] * 100:.2f}%"
    )

print("\nSummary:", summary_path)
print("=" * 80)

