# ============================================================
# MODULE 2 — READ GTA5 ZIP DIRECTORY VIA HTTP RANGE
# ============================================================

import requests
import struct

BASE = "https://download.visinf.tu-darmstadt.de/data/from_games/data/"

urls = {
    "images": BASE + "01_images.zip",
    "labels": BASE + "01_labels.zip",
}

print("=" * 80)
print("MODULE 2 — GTA5 ZIP CENTRAL DIRECTORY")
print("=" * 80)


def get_zip_directory(url):
    # Get total file size from Content-Range
    r = requests.get(
        url,
        headers={
            "Range": "bytes=0-0",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=30
    )

    content_range = r.headers.get("Content-Range")

    if not content_range:
        raise RuntimeError("Server did not return Content-Range")

    total_size = int(content_range.split("/")[-1])

    # EOCD is within the final 65,536 + 22 bytes
    tail_size = min(total_size, 65558)
    start = total_size - tail_size

    r = requests.get(
        url,
        headers={
            "Range": f"bytes={start}-{total_size-1}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=120
    )

    data = r.content

    # EOCD signature
    sig = b"PK\x05\x06"
    pos = data.rfind(sig)

    if pos == -1:
        raise RuntimeError("ZIP end-of-central-directory not found")

    eocd = data[pos:pos + 22]

    (
        signature,
        disk_num,
        cd_start_disk,
        disk_entries,
        total_entries,
        cd_size,
        cd_offset,
        comment_len
    ) = struct.unpack("<4sHHHHIIH", eocd)

    print("Total archive size :", total_size)
    print("ZIP entries        :", total_entries)
    print("Central directory  :", cd_size, "bytes")
    print("Directory offset   :", cd_offset)

    # Fetch central directory
    r = requests.get(
        url,
        headers={
            "Range": f"bytes={cd_offset}-{cd_offset + cd_size - 1}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=120
    )

    cd = r.content

    files = []
    p = 0

    while p < len(cd):

        if cd[p:p+4] != b"PK\x01\x02":
            break

        # Central directory fixed header
        fields = struct.unpack(
            "<4s6H3I5H2I",
            cd[p:p+46]
        )

        (
            signature,
            ver_made,
            ver_needed,
            flags,
            compression,
            mod_time,
            mod_date,
            crc32,
            compressed_size,
            uncompressed_size,
            filename_len,
            extra_len,
            comment_len,
            disk_start,
            internal_attr,
            external_attr,
            local_offset
        ) = fields

        start_name = p + 46
        end_name = start_name + filename_len

        filename = cd[start_name:end_name].decode(
            "utf-8",
            errors="replace"
        )

        files.append({
            "filename": filename,
            "compressed_size": compressed_size,
            "uncompressed_size": uncompressed_size,
            "compression": compression,
            "local_offset": local_offset,
        })

        p = end_name + extra_len + comment_len

    return total_size, files


for name, url in urls.items():

    print("\n" + "-" * 70)
    print(name.upper())
    print("-" * 70)

    try:
        total_size, files = get_zip_directory(url)

        print("\nParsed files:", len(files))

        print("\nFirst 20 files:")
        for x in files[:20]:
            print(
                x["filename"],
                "|",
                round(x["uncompressed_size"] / (1024**2), 3),
                "MB"
            )

        print("\nLast 10 files:")
        for x in files[-10:]:
            print(
                x["filename"],
                "|",
                round(x["uncompressed_size"] / (1024**2), 3),
                "MB"
            )

    except Exception as e:
        print("FAILED:", repr(e))

print("\n" + "=" * 80)

# ============================================================
# MODULE 2 — VERIFY GTA5 IMAGE/LABEL NAME ALIGNMENT
# ============================================================

import requests
import struct

IMAGE_ZIP = (
    "https://download.visinf.tu-darmstadt.de/"
    "data/from_games/data/01_images.zip"
)

LABEL_ZIP = (
    "https://download.visinf.tu-darmstadt.de/"
    "data/from_games/data/01_labels.zip"
)

print("=" * 80)
print("MODULE 2 — GTA5 IMAGE/LABEL ALIGNMENT CHECK")
print("=" * 80)


def read_range(url, start, end):
    r = requests.get(
        url,
        headers={
            "Range": f"bytes={start}-{end}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=60
    )

    if r.status_code not in (200, 206):
        raise RuntimeError(
            f"HTTP {r.status_code}"
        )

    return r.content


def inspect_zip_start(url):
    # Read beginning of ZIP
    data = read_range(url, 0, 200000)

    pos = data.find(b"PK\x03\x04")

    if pos == -1:
        raise RuntimeError(
            "Could not find ZIP local-file header"
        )

    # Local ZIP header:
    # signature, version, flags, compression,
    # time, date, crc, compressed size,
    # uncompressed size, filename length,
    # extra length
    header = data[pos:pos + 30]

    fields = struct.unpack(
        "<4s5H3I2H",
        header
    )

    (
        signature,
        version,
        flags,
        compression,
        mod_time,
        mod_date,
        crc32,
        compressed_size,
        uncompressed_size,
        filename_len,
        extra_len
    ) = fields

    name_start = pos + 30
    name_end = name_start + filename_len

    filename = data[
        name_start:name_end
    ].decode(
        "utf-8",
        errors="replace"
    )

    return {
        "filename": filename,
        "compression": compression,
        "compressed_size": compressed_size,
        "uncompressed_size": uncompressed_size,
        "local_header_offset": pos,
        "data_offset": (
            name_end + extra_len
        )
    }


for name, url in [
    ("IMAGE ZIP", IMAGE_ZIP),
    ("LABEL ZIP", LABEL_ZIP),
]:

    print("\n" + "-" * 70)
    print(name)
    print("-" * 70)

    try:
        info = inspect_zip_start(url)

        print("First filename       :", info["filename"])
        print("Compression method   :", info["compression"])
        print(
            "Compressed size      :",
            info["compressed_size"]
        )
        print(
            "Uncompressed size    :",
            info["uncompressed_size"]
        )
        print(
            "Local header offset  :",
            info["local_header_offset"]
        )
        print(
            "Data offset          :",
            info["data_offset"]
        )

    except Exception as e:
        print("FAILED:", repr(e))

print("\n" + "=" * 80)

