os.makedirs(LABEL_DIR, exist_ok=True)

CSV_PATH = os.path.join(
    SUBSET_DIR,
    "EXP_002_ground_truth.csv"
)

df = pd.read_csv(CSV_PATH)

IMAGE_ZIP = (
    "https://download.visinf.tu-darmstadt.de/"
    "data/from_games/data/01_images.zip"
)

LABEL_ZIP = (
    "https://download.visinf.tu-darmstadt.de/"
    "data/from_games/data/01_labels.zip"
)

print("=" * 80)
print("MODULE 2 — DOWNLOADING 1,000 GTA5 IMAGE/LABEL PAIRS")
print("=" * 80)
print("Target pairs:", len(df))


def get_zip_entries(url):
    """
    Read ZIP central directory using HTTP range requests.
    Handles the current archives' standard/ZIP64 layout.
    """

    # Get total archive size
    r = requests.get(
        url,
        headers={
            "Range": "bytes=0-0",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=60
    )

    content_range = r.headers.get("Content-Range")

    if not content_range:
        raise RuntimeError(
            "Could not determine archive size"
        )

    total_size = int(
        content_range.split("/")[-1]
    )

    # Fetch tail for EOCD
    tail_size = min(total_size, 65558)
    tail_start = total_size - tail_size

    r = requests.get(
        url,
        headers={
            "Range":
                f"bytes={tail_start}-{total_size-1}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=120
    )

    tail = r.content

    # Standard EOCD
    eocd_pos = tail.rfind(b"PK\x05\x06")

    if eocd_pos == -1:
        raise RuntimeError(
            "EOCD not found"
        )

    eocd = tail[
        eocd_pos:eocd_pos + 22
    ]

    (
        signature,
        disk_num,
        cd_start_disk,
        disk_entries,
        total_entries,
        cd_size_32,
        cd_offset_32,
        comment_len
    ) = struct.unpack(
        "<4sHHHHIIH",
        eocd
    )

    # ZIP64 if 32-bit fields are maxed out
    if (
        total_entries == 0xFFFF
        or cd_size_32 == 0xFFFFFFFF
        or cd_offset_32 == 0xFFFFFFFF
    ):

        # ZIP64 EOCD locator
        locator_pos = tail.rfind(
            b"PK\x06\x07",
            0,
            eocd_pos
        )

        if locator_pos == -1:
            raise RuntimeError(
                "ZIP64 locator not found"
            )

        (
            _sig,
            _disk,
            zip64_eocd_offset,
            _total_disks
        ) = struct.unpack(
            "<4sIQI",
            tail[
                locator_pos:
                locator_pos + 20
            ]
        )

        # Fetch ZIP64 EOCD
        z64 = requests.get(
            url,
            headers={
                "Range":
                    f"bytes={zip64_eocd_offset}-"
                    f"{zip64_eocd_offset + 100}",
                "User-Agent": "Mozilla/5.0"
            },
            timeout=60
        ).content

        if z64[:4] != b"PK\x06\x06":
            raise RuntimeError(
                "Invalid ZIP64 EOCD"
            )

        total_entries = struct.unpack(
            "<Q",
            z64[32:40]
        )[0]

        cd_size = struct.unpack(
            "<Q",
            z64[40:48]
        )[0]

        cd_offset = struct.unpack(
            "<Q",
            z64[48:56]
        )[0]

    else:
        cd_size = cd_size_32
        cd_offset = cd_offset_32

    # Fetch central directory
    r = requests.get(
        url,
        headers={
            "Range":
                f"bytes={cd_offset}-"
                f"{cd_offset + cd_size - 1}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=120
    )

    cd = r.content

    entries = {}

    p = 0

    while p < len(cd):

        if cd[p:p+4] != b"PK\x01\x02":
            break

        fields = struct.unpack(
            "<4s6H3I5H2I",
            cd[p:p+46]
        )

        (
            signature,
            ver_made,
            ver_needed,
            flags,
            compression,
            mod_time,
            mod_date,
            crc32,
            compressed_size,
            uncompressed_size,
            filename_len,
            extra_len,
            comment_len,
            disk_start,
            internal_attr,
            external_attr,
            local_offset
        ) = fields

        name_start = p + 46
        name_end = name_start + filename_len

        filename = cd[
            name_start:name_end
        ].decode(
            "utf-8",
            errors="replace"
        )

        # Handle ZIP64 extra fields when needed
        extra_start = name_end
        extra_end = (
            extra_start + extra_len
        )

        extra = cd[
            extra_start:extra_end
        ]

        if (
            compressed_size == 0xFFFFFFFF
            or uncompressed_size == 0xFFFFFFFF
            or local_offset == 0xFFFFFFFF
        ):
            ep = 0

            while ep + 4 <= len(extra):

                header_id, data_size = struct.unpack(
                    "<HH",
                    extra[ep:ep+4]
                )

                data = extra[
                    ep+4:
                    ep+4+data_size
                ]

                if header_id == 0x0001:

                    dp = 0

                    if uncompressed_size == 0xFFFFFFFF:
                        uncompressed_size = struct.unpack(
                            "<Q",
                            data[dp:dp+8]
                        )[0]
                        dp += 8

                    if compressed_size == 0xFFFFFFFF:
                        compressed_size = struct.unpack(
                            "<Q",
                            data[dp:dp+8]
                        )[0]
                        dp += 8

                    if local_offset == 0xFFFFFFFF:
                        local_offset = struct.unpack(
                            "<Q",
                            data[dp:dp+8]
                        )[0]

                    break

                ep += 4 + data_size

        entries[filename] = {
            "compressed_size": compressed_size,
            "uncompressed_size": uncompressed_size,
            "compression": compression,
            "local_offset": local_offset,
            "crc32": crc32,
        }

        p = extra_end + comment_len

    return entries


def extract_file(url, info):

    local_offset = info["local_offset"]

    # Read local file header
    header = requests.get(
        url,
        headers={
            "Range":
                f"bytes={local_offset}-"
                f"{local_offset + 4095}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=60
    ).content

    if header[:4] != b"PK\x03\x04":
        raise RuntimeError(
            "Invalid local file header"
        )

    (
        _sig,
        version,
        flags,
        compression,
        mod_time,
        mod_date,
        crc32,
        compressed_size,
        uncompressed_size,
        filename_len,
        extra_len
    ) = struct.unpack(
        "<4s5H3I2H",
        header[:30]
    )

    data_start = (
        local_offset +
        30 +
        filename_len +
        extra_len
    )

    data_end = (
        data_start +
        info["compressed_size"] -
        1
    )

    data = requests.get(
        url,
        headers={
            "Range":
                f"bytes={data_start}-{data_end}",
            "User-Agent": "Mozilla/5.0"
        },
        timeout=120
    ).content

    if compression == 0:
        return data

    if compression == 8:
        import zlib

        return zlib.decompress(
            data,
            -15
        )

    raise RuntimeError(
        f"Unsupported compression: {compression}"
    )


print("\nReading image ZIP directory...")
image_entries = get_zip_entries(IMAGE_ZIP)
print("Image entries:", len(image_entries))

print("\nReading label ZIP directory...")
label_entries = get_zip_entries(LABEL_ZIP)
print("Label entries:", len(label_entries))

print("\nStarting extraction...")

start_time = time.time()

downloaded = 0
failed = []

for i, row in df.iterrows():

    filename = row["image_filename"]

    image_archive_name = (
        f"images/{filename}"
    )

    label_archive_name = (
        f"labels/{filename}"
    )

    image_path = os.path.join(
        IMAGE_DIR,
        filename
    )

    label_path = os.path.join(
        LABEL_DIR,
        filename
    )

    try:

        if not os.path.exists(image_path):

            image_bytes = extract_file(
                IMAGE_ZIP,
                image_entries[image_archive_name]
            )

            with open(image_path, "wb") as f:
                f.write(image_bytes)

        if not os.path.exists(label_path):

            label_bytes = extract_file(
                LABEL_ZIP,
                label_entries[label_archive_name]
            )

            with open(label_path, "wb") as f:
                f.write(label_bytes)

        downloaded += 1

        if downloaded % 25 == 0:
            elapsed = time.time() - start_time

            print(
                f"[{downloaded:04d}/{len(df)}] "
                f"elapsed={elapsed:.1f}s"
            )

    except Exception as e:

        failed.append({
            "filename": filename,
            "error": repr(e)
        })

        print(
            "FAILED:",
            filename,
            "|",
            repr(e)
        )

elapsed = time.time() - start_time

print("\n" + "=" * 80)
print("DOWNLOAD COMPLETE")
print("=" * 80)

print("Expected pairs :", len(df))
print("Downloaded     :", downloaded)
print("Failed         :", len(failed))
print("Elapsed (sec)  :", round(elapsed, 2))

if failed:

    failed_path = os.path.join(
        SUBSET_DIR,
        "EXP_002_download_failures.json"
    )

    with open(failed_path, "w") as f:
        json.dump(
            failed,
            f,
            indent=2
        )

    print("\nFailures saved:")
    print(failed_path)

print("\nImages:", IMAGE_DIR)
print("Labels:", LABEL_DIR)

print("\n" + "=" * 80)

