from pathlib import Path
import random
import pandas as pd
import json

print("=" * 80)
print("MODULE 2 — REBUILDING EXP_002 MANIFEST")
print("=" * 80)

OUT_DIR = Path("/content/module2_eval_1000/EXP_002_subset_1000")
OUT_DIR.mkdir(parents=True, exist_ok=True)

IMAGE_ZIP = Path("/content/01_images.zip")
LABEL_ZIP = Path("/content/01_labels.zip")

# If the archives are elsewhere, locate them automatically
