import requests
from pathlib import Path
import time

OUT = Path("/content/gta5_archives")
OUT.mkdir(parents=True, exist_ok=True)

FILES = {
    "01_images.zip":
        "https://download.visinf.tu-darmstadt.de/data/from_games/data/01_images.zip",
    "01_labels.zip":
        "https://download.visinf.tu-darmstadt.de/data/from_games/data/01_labels.zip",
}

def download(url, dest):
    print(f"\nDownloading: {dest.name}")
    print("URL:", url)

    with requests.get(
        url,
        stream=True,
        timeout=60,
        headers={"User-Agent": "Mozilla/5.0"},
    ) as r:
        r.raise_for_status()

        total = int(r.headers.get("Content-Length", 0))
        received = 0
        start = time.time()

        with open(dest, "wb") as f:
            for chunk in r.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    f.write(chunk)
                    received += len(chunk)

                    if total:
                        pct = received / total * 100
                        print(
                            f"\r{received/1024**3:.2f}/"
                            f"{total/1024**3:.2f} GB "
                            f"({pct:.1f}%)",
                            end=""
                        )

    print()
    print("Saved:", dest)
    print("Size:", dest.stat().st_size / 1024**3, "GB")


for name, url in FILES.items():
    dest = OUT / name

    if dest.exists() and dest.stat().st_size > 0:
        print(f"\nAlready exists: {dest}")
        continue

    download(url, dest)

print("\n" + "=" * 80)
print("GTA5 ARCHIVE CHECK")
print("=" * 80)

for p in OUT.glob("*.zip"):
    print(f"{p.name}: {p.stat().st_size / 1024**3:.3f} GB")

