import zipfile
import numpy as np
import pandas as pd
import json
from pathlib import Path

# ============================================================
# MODULE 2 — BDD100K DRIVABLE-AREA EXP_002
# CREATE FIXED 1,000-SAMPLE SUBSET
# ============================================================

ZIP_PATH = "/content/bdd100k_drivable/bdd100k_drivable.zip"

OUT_DIR = Path("/content/module2_eval_1000/EXP_002_subset_1000")
OUT_DIR.mkdir(parents=True, exist_ok=True)

CSV_PATH = OUT_DIR / "EXP_002_ground_truth.csv"
JSON_PATH = OUT_DIR / "EXP_002_ground_truth.json"

SEED = 42
TARGET = 1000

IMAGE_MEMBER = "segmentation/dataset/image_180_320.npy"
LABEL_MEMBER = "segmentation/dataset/label_180_320.npy"

print("=" * 80)
print("MODULE 2 — BDD100K DRIVABLE-AREA EXP_002")
print("=" * 80)

# ------------------------------------------------------------
# Load arrays
# ------------------------------------------------------------

with zipfile.ZipFile(ZIP_PATH, "r") as z:

    with z.open(IMAGE_MEMBER) as f:
        images = np.load(f)

    with z.open(LABEL_MEMBER) as f:
        labels = np.load(f)

print("Total samples:", len(images))
print("Image shape:", images.shape)
print("Label shape:", labels.shape)

assert len(images) == len(labels)
assert len(images) >= TARGET

# ------------------------------------------------------------
# Validate samples
# ------------------------------------------------------------

valid_indices = []

for i in range(len(images)):

    img = images[i]
    lbl = labels[i]

    if img.size == 0 or lbl.size == 0:
        continue

    if not np.isfinite(img).all():
        continue

    if not np.isfinite(lbl).all():
        continue

    valid_indices.append(i)

print("Valid samples:", len(valid_indices))

assert len(valid_indices) >= TARGET

# ------------------------------------------------------------
# Fixed random selection
# ------------------------------------------------------------

rng = np.random.default_rng(SEED)

selected_indices = rng.choice(
    valid_indices,
    size=TARGET,
    replace=False
)

selected_indices = np.sort(selected_indices)

assert len(selected_indices) == TARGET
assert len(set(selected_indices)) == TARGET

# ------------------------------------------------------------
# Build manifest
# ------------------------------------------------------------

records = []

for subset_index, source_index in enumerate(selected_indices, start=1):

    records.append({
        "subset_index": subset_index,
        "sample_id": int(source_index + 1),
        "source_index": int(source_index),
        "image_filename": f"bdd100k_{source_index + 1:05d}.npy",
        "label_filename": f"bdd100k_{source_index + 1:05d}.npy",
        "image_shape": list(images[source_index].shape),
        "label_shape": list(labels[source_index].shape),
        "dataset": "BDD100K",
        "task": "drivable_area_segmentation",
        "seed": SEED
    })

df = pd.DataFrame(records)

# ------------------------------------------------------------
# Integrity checks
# ------------------------------------------------------------

assert len(df) == 1000
assert df["subset_index"].is_unique
assert df["sample_id"].is_unique
assert df["source_index"].is_unique
assert df["image_filename"].is_unique
assert df["label_filename"].is_unique

# Verify labels in selected subset
selected_labels = np.unique(
    labels[selected_indices]
)

print()
print("Selected label values:", selected_labels)

assert set(selected_labels).issubset({0, 1, 2})

# ------------------------------------------------------------
# Save
# ------------------------------------------------------------

df.to_csv(CSV_PATH, index=False)

with open(JSON_PATH, "w") as f:
    json.dump(
        {
            "experiment": "EXP_002",
            "dataset": "BDD100K",
            "task": "drivable_area_segmentation",
            "target_images": TARGET,
            "seed": SEED,
            "total_available": len(images),
            "valid_available": len(valid_indices),
            "image_shape": [180, 320, 3],
            "label_shape": [180, 320],
            "label_values": [0, 1, 2],
            "records": records
        },
        f,
        indent=2
    )

# ------------------------------------------------------------
# Report
# ------------------------------------------------------------

print()
