# MODULE 2 — FIND AND INSPECT SEGMENTATION CHECKPOINTS
# ============================================================

from pathlib import Path
import os
import torch

print("=" * 80)
print("MODULE 2 — SEARCHING FOR SEGMENTATION CHECKPOINTS")
print("=" * 80)

ROOTS = [
    Path("/content"),
    Path("/content/real_world_eval"),
    Path("/content/module2_eval_1000"),
]

EXTENSIONS = {
    ".pt", ".pth", ".ckpt", ".bin", ".onnx"
}

matches = []

seen = set()

for root in ROOTS:
    if not root.exists():
        continue

    for p in root.rglob("*"):
        if not p.is_file():
            continue

        if p.suffix.lower() not in EXTENSIONS:
            continue

        key = str(p.resolve())

        if key in seen:
            continue

        seen.add(key)
        matches.append(p)

# Remove obvious Module 1 / detection-only checkpoints
segmentation_candidates = []

for p in matches:
    name = p.name.lower()
    path_str = str(p).lower()

    if (
        "seg" in name
        or "segment" in name
        or "deeplab" in name
        or "unet" in name
        or "drivable" in name
        or "road" in name
        or "lane" in name
        or "cityscapes" in name
        or "bdd" in name
    ):
        segmentation_candidates.append(p)

print()
print("All model files found:", len(matches))

for p in matches:
    try:
        size_mb = p.stat().st_size / (1024 ** 2)
    except:
        size_mb = -1

    print(f"{size_mb:8.2f} MB  {p}")

print()
print("=" * 80)
print("SEGMENTATION CANDIDATES")
print("=" * 80)

if not segmentation_candidates:
    print("No dedicated segmentation checkpoint found.")
else:
    for p in segmentation_candidates:
        try:
            size_mb = p.stat().st_size / (1024 ** 2)
        except:
            size_mb = -1

        print(f"{size_mb:8.2f} MB  {p}")

print()
print("=" * 80)
print("CHECKPOINT INSPECTION")
print("=" * 80)

# Inspect PyTorch checkpoints that look relevant.
for path in segmentation_candidates:

    if path.suffix.lower() not in {".pt", ".pth", ".ckpt"}:
        continue

    print()
    print("-" * 80)
    print("CHECKPOINT:", path)

    try:
        obj = torch.load(
            path,
            map_location="cpu",
            weights_only=False
        )

        print("Loaded type:", type(obj))

        if isinstance(obj, dict):

            print("Dictionary keys:")
            print(list(obj.keys())[:50])

            for key in [
                "task",
                "arch",
                "model",
                "num_classes",
                "n_classes",
                "classes",
                "class_names",
                "names",
                "dataset",
                "data"
            ]:
                if key in obj:
                    value = obj[key]

                    if isinstance(value, dict):
                        print(f"{key}: dict ({len(value)} entries)")
                    else:
                        print(f"{key}: {value}")

        elif hasattr(obj, "model"):
            print("Object has .model:", type(obj.model))

        # Ultralytics-style model inspection
        if hasattr(obj, "task"):
            print("Task:", obj.task)

        if hasattr(obj, "names"):
            print("Names:", obj.names)

    except Exception as e:
        print("Inspection failed:", repr(e))

print()
print("=" * 80)
print("SEARCH / INSPECTION COMPLETE")
print("=" * 80)

