# ============================================================
# MODULE 2 — HYBRIDNETS SEGMENTATION OUTPUT INSPECTION
# ============================================================

import zipfile
import numpy as np
import torch

ZIP_PATH = "/content/bdd100k_drivable/bdd100k_drivable.zip"
IMAGE_MEMBER = "segmentation/dataset/image_180_320.npy"

print("=" * 80)
print("MODULE 2 — SEGMENTATION OUTPUT INSPECTION")
print("=" * 80)

# Load source images
with zipfile.ZipFile(ZIP_PATH, "r") as z:
    with z.open(IMAGE_MEMBER) as f:
        images = np.load(f)

print("Dataset shape:", images.shape)

# Use one sample from the EXP_002 source pool
img = images[14]

print("Sample shape:", img.shape)
print("Sample dtype:", img.dtype)

# Convert HWC uint8 -> BCHW float
x = torch.from_numpy(img).permute(2, 0, 1).float() / 255.0

# HybridNets expects its normal model input resolution
x = torch.nn.functional.interpolate(
    x.unsqueeze(0),
    size=(384, 640),
    mode="bilinear",
    align_corners=False
)

x = x.to(device)

print("Model input:", tuple(x.shape))

# Inference
with torch.no_grad():
    output = model(x)

print()
print("Output type:", type(output))

if isinstance(output, (tuple, list)):

    print("Number of outputs:", len(output))

    for i, item in enumerate(output):

        if torch.is_tensor(item):
            print(
                f"output[{i}] "
                f"shape={tuple(item.shape)} "
                f"dtype={item.dtype}"
            )

        elif isinstance(item, (tuple, list)):
            print(
                f"output[{i}] "
                f"type={type(item)} "
                f"length={len(item)}"
            )

        elif isinstance(item, dict):
            print(
                f"output[{i}] "
                f"dict keys={list(item.keys())}"
            )

        else:
            print(
                f"output[{i}] "
                f"type={type(item)}"
            )

elif torch.is_tensor(output):

    print("Output shape:", tuple(output.shape))

elif isinstance(output, dict):

    print("Output keys:", list(output.keys()))

else:

    print("Output:", output)

print()
print("=" * 80)
print("OUTPUT INSPECTION COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 2 — EXP_002 HYBRIDNETS INFERENCE + EVALUATION
# ============================================================

import os
import json
import zipfile
import time
import numpy as np
import pandas as pd
import torch
import torch.nn.functional as F
from pathlib import Path

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

ZIP_PATH = "/content/bdd100k_drivable/bdd100k_drivable.zip"

OUT_DIR = Path("/content/module2_eval_1000/EXP_002_results")
OUT_DIR.mkdir(parents=True, exist_ok=True)

GT_CSV = (
    "/content/module2_eval_1000/"
    "EXP_002_subset_1000/"
    "EXP_002_ground_truth.csv"
)

# ------------------------------------------------------------
# CONFIG
# ------------------------------------------------------------

N_TARGET = 1000
MODEL_INPUT_H = 384
MODEL_INPUT_W = 640

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

model = model.to(device)
model.eval()

# ------------------------------------------------------------
# LOAD MANIFEST
# ------------------------------------------------------------

print("=" * 80)
print("MODULE 2 — HYBRIDNETS EXP_002")
print("=" * 80)

df = pd.read_csv(GT_CSV)

assert len(df) == 1000, (
    f"Expected 1000 manifest rows, found {len(df)}"
)

print("Dataset              : BDD100K")
print("Task                 : Drivable-area segmentation")
print("Images               :", len(df))
print("Model                : HybridNets")
print("Device               :", device)

if torch.cuda.is_available():
    print("GPU                  :", torch.cuda.get_device_name(0))

print()

# ------------------------------------------------------------
# LOAD ARRAYS FROM ZIP
# ------------------------------------------------------------

print("Loading BDD100K arrays...")

with zipfile.ZipFile(ZIP_PATH, "r") as z:

    with z.open(
        "segmentation/dataset/image_180_320.npy"
    ) as f:
        images = np.load(f)

    with z.open(
        "segmentation/dataset/label_180_320.npy"
    ) as f:
        labels = np.load(f)

print("Images array:", images.shape)
print("Labels array:", labels.shape)

assert images.shape[0] == labels.shape[0]

# ------------------------------------------------------------
# SOURCE INDICES
# ------------------------------------------------------------

source_indices = df["source_index"].astype(int).to_numpy()

assert len(source_indices) == 1000
assert len(np.unique(source_indices)) == 1000

# ------------------------------------------------------------
# WARMUP
# ------------------------------------------------------------

print()
print("GPU warmup...")

warmup_img = images[source_indices[0]]

warmup_x = (
    torch.from_numpy(warmup_img)
    .permute(2, 0, 1)
    .float()
    / 255.0
)

warmup_x = F.interpolate(
    warmup_x.unsqueeze(0),
    size=(MODEL_INPUT_H, MODEL_INPUT_W),
    mode="bilinear",
    align_corners=False
).to(device)

with torch.no_grad():
    for _ in range(3):
        _ = model(warmup_x)

if device.type == "cuda":
    torch.cuda.synchronize()

print("Warmup complete.")

# ------------------------------------------------------------
# INFERENCE
# ------------------------------------------------------------

predictions = []

latencies_ms = []

start_total = time.perf_counter()

print()
print("Starting inference...")

for i, source_index in enumerate(source_indices):

    img = images[source_index]

    x = (
        torch.from_numpy(img)
        .permute(2, 0, 1)
        .float()
        / 255.0
    )

    x = F.interpolate(
        x.unsqueeze(0),
        size=(MODEL_INPUT_H, MODEL_INPUT_W),
        mode="bilinear",
        align_corners=False
    ).to(device)

    if device.type == "cuda":
        torch.cuda.synchronize()

    t0 = time.perf_counter()

    with torch.no_grad():
        output = model(x)

    if device.type == "cuda":
        torch.cuda.synchronize()

    latency = (
        time.perf_counter() - t0
    ) * 1000.0

    latencies_ms.append(latency)

    # --------------------------------------------------------
    # SEGMENTATION HEAD
    # --------------------------------------------------------

    seg_logits = output[4]

    # (1,3,384,640) -> (1,384,640)
    pred = torch.argmax(
        seg_logits,
        dim=1
    )

    # Resize prediction to GT resolution
    pred = F.interpolate(
        pred.unsqueeze(1).float(),
        size=(180, 320),
        mode="nearest"
    )

    pred = (
        pred.squeeze(0)
        .squeeze(0)
        .cpu()
        .numpy()
        .astype(np.uint8)
    )

    assert pred.shape == (180, 320)

    predictions.append(pred)

    if (i + 1) % 100 == 0:

        elapsed = time.perf_counter() - start_total

        avg_latency = np.mean(latencies_ms)

        print(
            f"[{i+1:4d}/1000] "
            f"elapsed={elapsed:.1f}s | "
            f"avg latency={avg_latency:.2f} ms"
        )

total_runtime = time.perf_counter() - start_total

# ------------------------------------------------------------
# BASIC INTEGRITY
# ------------------------------------------------------------

assert len(predictions) == 1000
assert len(latencies_ms) == 1000

predictions = np.stack(predictions)

assert predictions.shape == (1000, 180, 320)

# ------------------------------------------------------------
# METRICS
# ------------------------------------------------------------

NUM_CLASSES = 3

confusion = np.zeros(
    (NUM_CLASSES, NUM_CLASSES),
    dtype=np.int64
)

for i, source_index in enumerate(source_indices):

    gt = labels[source_index].astype(np.int64)
    pred = predictions[i].astype(np.int64)

    valid = (
        (gt >= 0) &
        (gt < NUM_CLASSES)
    )

    gt_v = gt[valid]
    pred_v = pred[valid]

    cm = np.bincount(
        NUM_CLASSES * gt_v + pred_v,
        minlength=NUM_CLASSES ** 2
    ).reshape(NUM_CLASSES, NUM_CLASSES)

    confusion += cm

# ------------------------------------------------------------
# PER-CLASS METRICS
# ------------------------------------------------------------

class_metrics = {}

ious = []
dice_scores = []

for c in range(NUM_CLASSES):

    tp = confusion[c, c]

    fp = confusion[:, c].sum() - tp
    fn = confusion[c, :].sum() - tp

    union = tp + fp + fn

    if union > 0:
        iou = tp / union
    else:
        iou = None

    denom_dice = (
        2 * tp + fp + fn
    )

    if denom_dice > 0:
        dice = (
            2 * tp / denom_dice
        )
    else:
        dice = None

    if iou is not None:
        ious.append(iou)

    if dice is not None:
        dice_scores.append(dice)

    class_metrics[str(c)] = {
        "TP": int(tp),
        "FP": int(fp),
        "FN": int(fn),
        "IoU": None if iou is None else float(iou),
        "Dice": None if dice is None else float(dice),
    }

# ------------------------------------------------------------
# GLOBAL PIXEL ACCURACY
# ------------------------------------------------------------

total_pixels = confusion.sum()
correct_pixels = np.trace(confusion)

pixel_accuracy = (
    correct_pixels / total_pixels
    if total_pixels > 0
    else 0.0
)

mean_iou = (
    float(np.mean(ious))
    if ious
    else 0.0
)

mean_dice = (
    float(np.mean(dice_scores))
    if dice_scores
    else 0.0
)

# ------------------------------------------------------------
# TIMING
# ------------------------------------------------------------

avg_latency = float(
    np.mean(latencies_ms)
)

median_latency = float(
    np.median(latencies_ms)
)

p95_latency = float(
    np.percentile(latencies_ms, 95)
)

fps = (
    1000.0 / avg_latency
    if avg_latency > 0
    else 0.0
)

# ------------------------------------------------------------
# SAVE PREDICTIONS
# ------------------------------------------------------------

pred_path = (
    OUT_DIR /
    "EXP_002_predictions.npy"
)

np.save(
    pred_path,
    predictions
)

# ------------------------------------------------------------
# SAVE CONFUSION MATRIX
# ------------------------------------------------------------

cm_path = (
    OUT_DIR /
    "EXP_002_confusion_matrix.npy"
)

np.save(
    cm_path,
    confusion
)

# ------------------------------------------------------------
# SUMMARY
# ------------------------------------------------------------

summary = {
    "experiment": "EXP_002",
    "module": "Module 2",
    "dataset": "BDD100K",
    "task": "drivable_area_segmentation",

    "target_images": 1000,
    "inferred_images": 1000,

    "model": "HybridNets",
    "device": str(device),

    "input_size": [
        MODEL_INPUT_H,
        MODEL_INPUT_W
    ],

    "ground_truth_size": [
        180,
        320
    ],

    "num_classes": 3,
    "class_values": [0, 1, 2],

    "pixel_accuracy": float(pixel_accuracy),
    "mean_IoU": float(mean_iou),
    "mean_Dice": float(mean_dice),

    "per_class": class_metrics,

    "confusion_matrix": confusion.tolist(),

    "avg_latency_ms": avg_latency,
    "median_latency_ms": median_latency,
    "p95_latency_ms": p95_latency,
    "approx_fps": fps,
    "total_runtime_seconds": float(total_runtime),
}

summary_path = (
    OUT_DIR /
    "EXP_002_summary.json"
)

with open(
    summary_path,
    "w"
) as f:
    json.dump(
        summary,
        f,
        indent=2
    )

# ------------------------------------------------------------
# SAVE TIMING
# ------------------------------------------------------------

timing = {
    "images": 1000,
    "avg_latency_ms": avg_latency,
    "median_latency_ms": median_latency,
    "p95_latency_ms": p95_latency,
    "approx_fps": fps,
    "total_runtime_seconds": float(total_runtime),
    "latencies_ms": latencies_ms,
}

timing_path = (
    OUT_DIR /
    "EXP_002_timing.json"
)

with open(
    timing_path,
    "w"
) as f:
    json.dump(
        timing,
        f,
        indent=2
    )

# ------------------------------------------------------------
# FINAL REPORT
# ------------------------------------------------------------

print()
print("=" * 80)
print("MODULE 2 EXP_002 INFERENCE + EVALUATION COMPLETE")
print("=" * 80)

print("Images:", len(predictions))
print("Total runtime:", f"{total_runtime:.2f} s")

print()
print("TIMING")
print("-" * 40)
print("Average latency :", f"{avg_latency:.2f} ms")
print("Median latency  :", f"{median_latency:.2f} ms")
print("P95 latency     :", f"{p95_latency:.2f} ms")
print("Approx FPS      :", f"{fps:.2f}")

print()
print("SEGMENTATION METRICS")
print("-" * 40)
print(
    "Pixel Accuracy  :",
    f"{pixel_accuracy * 100:.2f}%"
)
print(
    "Mean IoU        :",
    f"{mean_iou * 100:.2f}%"
)
print(
    "Mean Dice       :",
    f"{mean_dice * 100:.2f}%"
)

print()
print("PER-CLASS METRICS")
print("-" * 40)

for c, m in class_metrics.items():

    print(
        f"Class {c}: "
        f"IoU={m['IoU'] * 100:.2f}% | "
        f"Dice={m['Dice'] * 100:.2f}% | "
        f"TP={m['TP']} | "
        f"FP={m['FP']} | "
        f"FN={m['FN']}"
    )

print()
print("CONFUSION MATRIX")
print("-" * 40)
print(confusion)

print()
print("FILES")
print("-" * 40)
print("Predictions:", pred_path)
print("Summary    :", summary_path)
print("Timing     :", timing_path)
print("Confusion  :", cm_path)

print("=" * 80)

# =============================================================================
# MODULE 2 — HYBRIDNETS SEGMENTATION SANITY CHECK
# =============================================================================

import os
import json
import numpy as np
import torch
import torch.nn.functional as F
from pathlib import Path

print("=" * 80)
print("MODULE 2 — HYBRIDNETS SEGMENTATION SANITY CHECK")
print("=" * 80)

# -------------------------------------------------------------------------
# Paths
# -------------------------------------------------------------------------
BASE = Path("/content/module2_eval_1000")
SUBSET = BASE / "EXP_002_subset_1000"
RESULTS = BASE / "EXP_002_results"

GT_JSON = SUBSET / "EXP_002_ground_truth.json"
PRED_PATH = RESULTS / "EXP_002_predictions.npy"

print("GT manifest :", GT_JSON)
print("Predictions :", PRED_PATH)

# -------------------------------------------------------------------------
# Load predictions
# -------------------------------------------------------------------------
pred = np.load(PRED_PATH)

print("\nPREDICTION ARRAY")
print("-" * 80)
print("Shape:", pred.shape)
print("Dtype:", pred.dtype)
print("Min  :", pred.min())
print("Max  :", pred.max())

# -------------------------------------------------------------------------
# Load BDD100K arrays
# -------------------------------------------------------------------------
ZIP_PATH = "/content/bdd100k_drivable/bdd100k_drivable.zip"

import zipfile

with zipfile.ZipFile(ZIP_PATH, "r") as z:
    img_bytes = z.read("segmentation/dataset/image_180_320.npy")
    lbl_bytes = z.read("segmentation/dataset/label_180_320.npy")

    import io
    images = np.load(io.BytesIO(img_bytes))
    labels = np.load(io.BytesIO(lbl_bytes))

print("\nSOURCE ARRAYS")
print("-" * 80)
print("Images:", images.shape, images.dtype)
print("Labels:", labels.shape, labels.dtype)

# -------------------------------------------------------------------------
# Reconstruct the exact EXP_002 source indices
# -------------------------------------------------------------------------
with open(GT_JSON, "r") as f:
    manifest = json.load(f)

if isinstance(manifest, dict):
    records = (
        manifest.get("records")
        or manifest.get("data")
        or manifest.get("samples")
        or manifest.get("annotations")
    )
else:
    records = manifest

if records is None:
    raise RuntimeError("Could not locate records in EXP_002_ground_truth.json")

source_indices = np.array(
    [int(r["source_index"]) for r in records],
    dtype=np.int64
)

gt = labels[source_indices]

print("\nEXACT EXP_002 DATA")
print("-" * 80)
print("Selected images:", len(source_indices))
print("GT shape:", gt.shape)
print("Prediction shape:", pred.shape)

assert len(source_indices) == 1000
assert gt.shape[0] == pred.shape[0]

# -------------------------------------------------------------------------
# Ground-truth label distribution
# -------------------------------------------------------------------------
gt_values, gt_counts = np.unique(gt, return_counts=True)

print("\nGROUND-TRUTH LABEL DISTRIBUTION")
print("-" * 80)

for value, count in zip(gt_values, gt_counts):
    print(
        f"Class {int(value)}: "
        f"{int(count):,} pixels "
        f"({100 * count / gt.size:.2f}%)"
    )

# -------------------------------------------------------------------------
# Prediction distribution
# -------------------------------------------------------------------------
pred_values, pred_counts = np.unique(pred, return_counts=True)

print("\nPREDICTION LABEL DISTRIBUTION")
print("-" * 80)

for value, count in zip(pred_values, pred_counts):
    print(
        f"Class {int(value)}: "
        f"{int(count):,} pixels "
        f"({100 * count / pred.size:.2f}%)"
    )

# -------------------------------------------------------------------------
# Per-image prediction distributions
# -------------------------------------------------------------------------
print("\nPER-IMAGE PREDICTION CHECK")
print("-" * 80)

for i in [0, 1, 2, 3, 4, 9, 99, 999]:
    vals, counts = np.unique(pred[i], return_counts=True)

    distribution = {
        int(v): int(c)
        for v, c in zip(vals, counts)
    }

    print(f"Image {i+1:4d}: {distribution}")

# -------------------------------------------------------------------------
# Confusion matrix independently recomputed
# -------------------------------------------------------------------------
print("\nINDEPENDENT CONFUSION MATRIX")
print("-" * 80)

cm = np.zeros((3, 3), dtype=np.int64)

flat_gt = gt.reshape(-1)
flat_pred = pred.reshape(-1)

valid = (
    (flat_gt >= 0) & (flat_gt < 3) &
    (flat_pred >= 0) & (flat_pred < 3)
)

np.add.at(
    cm,
    (flat_gt[valid], flat_pred[valid]),
    1
)

print(cm)

# -------------------------------------------------------------------------
# Pixel accuracy
# -------------------------------------------------------------------------
pixel_accuracy = np.trace(cm) / cm.sum()

print("\nPIXEL ACCURACY")
print("-" * 80)
print(f"{pixel_accuracy * 100:.4f}%")

# -------------------------------------------------------------------------
# IoU / Dice
# -------------------------------------------------------------------------
print("\nPER-CLASS IoU / DICE")
print("-" * 80)

ious = []
dices = []

for c in range(3):
    tp = cm[c, c]
    fp = cm[:, c].sum() - tp
    fn = cm[c, :].sum() - tp

    denom_iou = tp + fp + fn
    denom_dice = 2 * tp + fp + fn

    iou = tp / denom_iou if denom_iou else 0
    dice = 2 * tp / denom_dice if denom_dice else 0

    ious.append(iou)
    dices.append(dice)

    print(
        f"Class {c}: "
        f"IoU={iou*100:.4f}% | "
        f"Dice={dice*100:.4f}% | "
        f"TP={tp:,} | FP={fp:,} | FN={fn:,}"
    )

print("\nMean IoU :", f"{np.mean(ious)*100:.4f}%")
print("Mean Dice:", f"{np.mean(dices)*100:.4f}%")

# -------------------------------------------------------------------------
# Sanity warnings
# -------------------------------------------------------------------------
print("\nSANITY FLAGS")
print("-" * 80)

if pred.min() < 0 or pred.max() > 2:
    print("WARNING: Predictions contain labels outside [0, 1, 2].")
else:
    print("✓ Prediction labels are within [0, 1, 2].")

if pred.shape[1:] != gt.shape[1:]:
    print(
        "WARNING: Prediction and GT spatial dimensions differ: "
        f"{pred.shape[1:]} vs {gt.shape[1:]}"
    )
else:
    print("✓ Prediction and GT spatial dimensions match.")

pred_class_0_fraction = np.mean(pred == 0)
gt_class_0_fraction = np.mean(gt == 0)

print(
    f"Class-0 GT fraction   : {gt_class_0_fraction*100:.2f}%"
)
print(
    f"Class-0 pred fraction : {pred_class_0_fraction*100:.2f}%"
)

print("\n" + "=" * 80)
print("SANITY CHECK COMPLETE")
print("=" * 80)

# =============================================================================
# MODULE 2 — HYBRIDNETS RAW LOGIT + PREPROCESSING INSPECTION
# =============================================================================

import sys
import os
import json
import numpy as np
import torch
import torch.nn.functional as F
from pathlib import Path

print("=" * 80)
print("MODULE 2 — HYBRIDNETS RAW LOGIT + PREPROCESSING INSPECTION")
print("=" * 80)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)
if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))

# -------------------------------------------------------------------------
# Locate the cached HybridNets repository
# -------------------------------------------------------------------------
REPO = Path("/root/.cache/torch/hub/datvuthanh_hybridnets_main")

if not REPO.exists():
    raise FileNotFoundError(f"HybridNets repository not found: {REPO}")

sys.path.insert(0, str(REPO))

# Import the same model components used by the successful run
from backbone import HybridNetsBackbone

print("HybridNets repository:", REPO)

# -------------------------------------------------------------------------
# Locate checkpoint
# -------------------------------------------------------------------------
checkpoint_candidates = [
    Path("/root/.cache/torch/hub/checkpoints/hybridnets.pth"),
    Path("/content/hybridnets.pth"),
]

CHECKPOINT = next((p for p in checkpoint_candidates if p.exists()), None)

if CHECKPOINT is None:
    raise FileNotFoundError("HybridNets checkpoint not found.")

print("Checkpoint:", CHECKPOINT)
print("Checkpoint size MB:", CHECKPOINT.stat().st_size / 1024**2)

# -------------------------------------------------------------------------
# IMPORTANT:
# Use the SAME model-loading mechanism/configuration that produced the
# successful EXP_002 inference.
# -------------------------------------------------------------------------

# Try loading through torch.hub first.
import torch.hub

model = torch.hub.load(
    str(REPO),
    "hybridnets",
    pretrained=True,
    source="local",
    trust_repo=True,
)

model = model.to(device)
model.eval()

print("Model loaded:", type(model))

# -------------------------------------------------------------------------
# Load source arrays
# -------------------------------------------------------------------------
ZIP_PATH = "/content/bdd100k_drivable/bdd100k_drivable.zip"

import zipfile
import io

with zipfile.ZipFile(ZIP_PATH, "r") as z:
    images = np.load(
        io.BytesIO(
            z.read("segmentation/dataset/image_180_320.npy")
        )
    )

    labels = np.load(
        io.BytesIO(
            z.read("segmentation/dataset/label_180_320.npy")
        )
    )

print("\nSOURCE DATA")
print("-" * 80)
print("Images:", images.shape, images.dtype)
print("Labels:", labels.shape, labels.dtype)

# -------------------------------------------------------------------------
# Exact EXP_002 source indices
# -------------------------------------------------------------------------
GT_JSON = Path(
    "/content/module2_eval_1000/EXP_002_subset_1000/"
    "EXP_002_ground_truth.json"
)

with open(GT_JSON, "r") as f:
    manifest = json.load(f)

if isinstance(manifest, dict):
    records = (
        manifest.get("records")
        or manifest.get("data")
        or manifest.get("samples")
        or manifest.get("annotations")
    )
else:
    records = manifest

source_indices = [
    int(r["source_index"])
    for r in records
]

# Only inspect 5 samples.
CHECK_INDICES = [0, 1, 2, 3, 4]

# -------------------------------------------------------------------------
# Inspect preprocessing for each sample
# -------------------------------------------------------------------------
print("\n" + "=" * 80)
print("RAW MODEL OUTPUT INSPECTION")
print("=" * 80)

for check_i in CHECK_INDICES:

    source_i = source_indices[check_i]

    image = images[source_i]
    gt = labels[source_i]

    print("\n" + "-" * 80)
    print(
        f"Sample {check_i + 1}/5 | "
        f"EXP_002 source index={source_i}"
    )
    print("-" * 80)

    print("Original image:")
    print("  shape:", image.shape)
    print("  dtype:", image.dtype)
    print("  min:", image.min())
    print("  max:", image.max())
    print("  mean:", float(image.mean()))
    print("  std :", float(image.std()))

    # -------------------------------------------------------------
    # Standard image conversion
    # -------------------------------------------------------------
    x = torch.from_numpy(image.copy())

    # HWC -> CHW
    x = x.permute(2, 0, 1).float()

    print("\nBefore normalization:")
    print("  shape:", tuple(x.shape))
    print("  min:", float(x.min()))
    print("  max:", float(x.max()))
    print("  mean:", float(x.mean()))
    print("  std :", float(x.std()))

    # Resize exactly to the model input used in the previous run.
    x = x.unsqueeze(0)

    x = F.interpolate(
        x,
        size=(384, 640),
        mode="bilinear",
        align_corners=False,
    )

    print("\nAfter resize:")
    print("  shape:", tuple(x.shape))
    print("  min:", float(x.min()))
    print("  max:", float(x.max()))
    print("  mean:", float(x.mean()))
    print("  std :", float(x.std()))

    # -------------------------------------------------------------
    # IMPORTANT:
    # Run this first WITHOUT changing normalization.
    # This allows us to see exactly what the current pipeline gives.
    # -------------------------------------------------------------
    x_model = x / 255.0

    print("\nModel tensor (/255):")
    print("  shape:", tuple(x_model.shape))
    print("  min:", float(x_model.min()))
    print("  max:", float(x_model.max()))
    print("  mean:", float(x_model.mean()))
    print("  std :", float(x_model.std()))

    x_model = x_model.to(device)

    # -------------------------------------------------------------
    # Forward pass
    # -------------------------------------------------------------
    with torch.no_grad():
        output = model(x_model)

    print("\nModel output:")
    print("  type:", type(output))

    if isinstance(output, tuple):
        print("  tuple length:", len(output))

        for j, item in enumerate(output):
            if torch.is_tensor(item):
                print(
                    f"  output[{j}]: "
                    f"shape={tuple(item.shape)} "
                    f"dtype={item.dtype} "
                    f"min={float(item.min()):.6f} "
                    f"max={float(item.max()):.6f}"
                )
            elif isinstance(item, tuple):
                print(
                    f"  output[{j}]: tuple length={len(item)}"
                )
            else:
                print(
                    f"  output[{j}]: type={type(item)}"
                )

    # -------------------------------------------------------------
    # Find the segmentation tensor.
    # Successful previous run showed:
    # (1, 3, 384, 640)
    # -------------------------------------------------------------
    seg = None

    def find_seg_tensor(obj):
        if torch.is_tensor(obj):
            if obj.ndim == 4 and obj.shape[1] == 3:
                return obj

        if isinstance(obj, (tuple, list)):
            for child in obj:
                result = find_seg_tensor(child)
                if result is not None:
                    return result

        return None

    seg = find_seg_tensor(output)

    if seg is None:
        print("\nERROR: Could not locate 3-channel segmentation tensor.")
        continue

    print("\nSEGMENTATION LOGITS")
    print("-" * 80)
    print("Shape:", tuple(seg.shape))

    # -------------------------------------------------------------
    # Raw logits statistics
    # -------------------------------------------------------------
    for c in range(3):
        channel = seg[0, c]

        print(
            f"Channel {c}: "
            f"min={float(channel.min()):.6f}, "
            f"max={float(channel.max()):.6f}, "
            f"mean={float(channel.mean()):.6f}, "
            f"std={float(channel.std()):.6f}"
        )

    # -------------------------------------------------------------
    # Argmax directly at model resolution
    # -------------------------------------------------------------
    pred_384 = torch.argmax(seg, dim=1)

    vals, counts = torch.unique(
        pred_384,
        return_counts=True
    )

    print("\nARGMAX AT 384x640")
    for v, c in zip(vals.cpu().numpy(), counts.cpu().numpy()):
        print(
            f"Class {int(v)}: "
            f"{int(c):,} pixels "
            f"({100*c/pred_384.numel():.2f}%)"
        )

    # -------------------------------------------------------------
    # Resize logits back to GT resolution BEFORE argmax.
    # This is important: resizing logits and then argmax can differ
    # from argmax followed by mask resizing.
    # -------------------------------------------------------------
    seg_180 = F.interpolate(
        seg,
        size=(180, 320),
        mode="bilinear",
        align_corners=False,
    )

    pred_logits_resize = torch.argmax(
        seg_180,
        dim=1
    )[0].cpu().numpy().astype(np.uint8)

    vals, counts = np.unique(
        pred_logits_resize,
        return_counts=True
    )

    print("\nARGMAX AFTER LOGIT RESIZE TO 180x320")
    for v, c in zip(vals, counts):
        print(
            f"Class {int(v)}: "
            f"{int(c):,} pixels "
            f"({100*c/pred_logits_resize.size:.2f}%)"
        )

    # -------------------------------------------------------------
    # Ground-truth distribution for this image
    # -------------------------------------------------------------
    print("\nGROUND TRUTH")
    gt_vals, gt_counts = np.unique(
        gt,
        return_counts=True
    )

    for v, c in zip(gt_vals, gt_counts):
        print(
            f"Class {int(v)}: "
            f"{int(c):,} pixels "
            f"({100*c/gt.size:.2f}%)"
        )

print("\n" + "=" * 80)
print("RAW LOGIT / PREPROCESSING INSPECTION COMPLETE")
print("=" * 80)

