import requests
from bs4 import BeautifulSoup
from urllib.parse import unquote

print("=" * 80)
print("MODULE 3 — EXTRACTING MAPILLARY VISTAS SOURCE LINKS")
print("=" * 80)

queries = [
    "Mapillary Vistas dataset 1000 images annotations",
    "Mapillary Vistas v2 dataset download images annotations",
    "Mapillary Vistas instance segmentation dataset public",
]

seen = set()

for q in queries:
    print("\n" + "-" * 80)
    print("QUERY:", q)

    try:
        r = requests.get(
            "https://www.google.com/search",
            params={"q": q},
            timeout=30,
            headers={"User-Agent": "Mozilla/5.0"},
        )

        soup = BeautifulSoup(r.text, "html.parser")

        for a in soup.find_all("a", href=True):
            href = a["href"]

            if href.startswith("/url?q="):
                href = href.split("/url?q=", 1)[1].split("&", 1)[0]
                href = unquote(href)

            if href.startswith("http") and "google." not in href:
                if href not in seen:
                    seen.add(href)
                    print(href)

    except Exception as e:
        print("FAILED:", repr(e))

print("\n" + "=" * 80)
print("UNIQUE CANDIDATE URLS:", len(seen))
