import requests
from pathlib import Path

print("=" * 80)
print("MODULE 3 — OPEN IMAGES CLASS LABEL MAPPING")
print("=" * 80)

URL = "https://storage.googleapis.com/openimages/v6/oidv6-class-descriptions.csv"
OUT = Path("/content/module3_openimages/class-descriptions.csv")

r = requests.get(
    URL,
    timeout=60,
    headers={"User-Agent": "Mozilla/5.0"}
)

print("HTTP:", r.status_code)
print("Bytes:", len(r.content))

if r.status_code != 200:
    raise RuntimeError(f"Failed: HTTP {r.status_code}")

OUT.write_bytes(r.content)

print("Saved:", OUT)
print("Size:", OUT.stat().st_size)

