import pandas as pd
from pathlib import Path

print("=" * 80)
print("MODULE 3 — IDENTIFYING ROAD-OBSTACLE CLASSES")
print("=" * 80)

ANN = Path("/content/module3_openimages/validation-annotations-bbox.csv")
CLS = Path("/content/module3_openimages/class-descriptions.csv")

df = pd.read_csv(ANN)
classes = pd.read_csv(CLS)

classes.columns = ["LabelName", "DisplayName"]

merged = df.merge(
    classes,
    on="LabelName",
    how="left"
)

# Candidate road / obstacle terminology.
keywords = [
    "car",
    "vehicle",
    "truck",
    "bus",
    "van",
    "motorcycle",
    "motorbike",
    "bicycle",
    "person",
    "pedestrian",
    "traffic",
    "road",
    "street",
    "taxi",
    "trailer",
    "wheel",
    "scooter",
    "train",
    "animal",
    "dog",
    "cat",
    "horse"
]

pattern = "|".join(keywords)

candidates = (
    merged[
        merged["DisplayName"]
        .str.lower()
        .str.contains(pattern, na=False)
    ]
    .groupby(["LabelName", "DisplayName"])
    .agg(
        annotations=("ImageID", "size"),
        images=("ImageID", "nunique")
    )
    .sort_values("images", ascending=False)
    .reset_index()
)

print("\nROAD / OBSTACLE CANDIDATE CLASSES:")
print("-" * 80)

if len(candidates) == 0:
    print("No keyword-matched classes found.")
else:
    print(candidates.to_string(index=False))

print("\nTotal candidate classes:", len(candidates))

print("\n" + "=" * 80)
print("ROAD-OBSTACLE CLASS IDENTIFICATION COMPLETE")
print("=" * 80)

