import pandas as pd
import json
from pathlib import Path

# ============================================================
# MODULE 3 — REBUILD EXP_003 FIXED 1000-IMAGE MANIFEST
# ============================================================

ANN_PATH = Path("/content/module3_openimages/validation-annotations-bbox.csv")
CLASS_PATH = Path("/content/module3_openimages/class-descriptions.csv")

OUT_DIR = Path("/content/module3_eval_1000/EXP_003_subset_1000")
OUT_DIR.mkdir(parents=True, exist_ok=True)

SEED = 42
TARGET_IMAGES = 1000

print("=" * 80)
print("MODULE 3 — REBUILDING EXP_003 MANIFEST")
print("=" * 80)

# ------------------------------------------------------------
# Load annotations + class mapping
# ------------------------------------------------------------
ann = pd.read_csv(ANN_PATH)
classes = pd.read_csv(CLASS_PATH)

classes.columns = ["LabelName", "DisplayName"]

# ------------------------------------------------------------
# Road-obstacle classes identified previously
# ------------------------------------------------------------
obstacle_labels = {
    "/m/01g317",  # Person
    "/m/0k4j",    # Car
    "/m/083wq",   # Wheel
    "/m/01prls",  # Land vehicle
    "/m/0bt9lr",  # Dog
    "/m/07yv9",   # Vehicle
    "/m/01jfm_",  # Vehicle registration plate
    "/m/01yrx",   # Cat
    "/m/07r04",   # Truck
    "/m/03k3r",   # Horse
    "/m/0199g",   # Bicycle
    "/m/01bqk0",  # Bicycle wheel
    "/m/0jbk",    # Animal
    "/m/01lrl",   # Carnivore
    "/m/0h2r6",   # Van
    "/m/04_sv",   # Motorcycle
    "/m/01xq0k1", # Cattle
    "/m/03p3bw",  # Bicycle helmet
    "/m/07jdr",   # Train
    "/m/01bjv",   # Bus
    "/m/018p4k",  # Cart
    "/m/0qmmr",   # Wheelchair
    "/m/0pg52",   # Taxi
    "/m/01mqdt",  # Traffic sign
    "/m/015qff",  # Traffic light
}

# ------------------------------------------------------------
# Keep annotations belonging to obstacle classes
# ------------------------------------------------------------
candidate = ann[ann["LabelName"].isin(obstacle_labels)].copy()

# Attach human-readable class names
candidate = candidate.merge(
    classes,
    on="LabelName",
    how="left"
)

candidate["DisplayName"] = candidate["DisplayName"].fillna(
    candidate["LabelName"]
)

# ------------------------------------------------------------
# Candidate images
# ------------------------------------------------------------
candidate_images = sorted(candidate["ImageID"].unique())

print("Total annotation rows:", len(ann))
print("Obstacle annotation rows:", len(candidate))
print("Candidate images:", len(candidate_images))

if len(candidate_images) < TARGET_IMAGES:
    raise RuntimeError(
        f"Only {len(candidate_images)} candidate images available; "
        f"cannot create {TARGET_IMAGES}."
    )

# ------------------------------------------------------------
# Deterministic selection
# ------------------------------------------------------------
import numpy as np

rng = np.random.default_rng(SEED)

selected_images = rng.choice(
    candidate_images,
    size=TARGET_IMAGES,
    replace=False
)

# Keep deterministic ordering in manifest
selected_images = sorted(selected_images)

selected_set = set(selected_images)

subset = candidate[
    candidate["ImageID"].isin(selected_set)
].copy()

# ------------------------------------------------------------
# Stable sample IDs
# ------------------------------------------------------------
image_to_sample = {
    image_id: i + 1
    for i, image_id in enumerate(selected_images)
}

image_to_subset = {
    image_id: i + 1
    for i, image_id in enumerate(selected_images)
}

subset["sample_id"] = subset["ImageID"].map(image_to_sample)
subset["subset_index"] = subset["ImageID"].map(image_to_subset)

subset["dataset"] = "Open Images"
subset["task"] = "obstacle_detection"
subset["seed"] = SEED

# ------------------------------------------------------------
# Column order
# ------------------------------------------------------------
columns = [
    "subset_index",
    "sample_id",
    "ImageID",
    "LabelName",
    "DisplayName",
    "Confidence",
    "XMin",
    "XMax",
    "YMin",
    "YMax",
    "IsOccluded",
    "IsTruncated",
    "IsGroupOf",
    "IsDepiction",
    "IsInside",
    "dataset",
    "task",
    "seed",
]

subset = subset[columns].sort_values(
    ["subset_index", "LabelName", "XMin", "YMin"]
).reset_index(drop=True)

# ------------------------------------------------------------
# Integrity
# ------------------------------------------------------------
unique_images = subset["ImageID"].nunique()
unique_samples = subset["sample_id"].nunique()

assert unique_images == TARGET_IMAGES
assert unique_samples == TARGET_IMAGES
assert len(selected_images) == TARGET_IMAGES

# ------------------------------------------------------------
# Save CSV
# ------------------------------------------------------------
csv_path = OUT_DIR / "EXP_003_ground_truth.csv"
json_path = OUT_DIR / "EXP_003_ground_truth.json"

subset.to_csv(csv_path, index=False)

# JSON records
with open(json_path, "w") as f:
    json.dump(
        subset.to_dict(orient="records"),
        f,
        indent=2
    )

# ------------------------------------------------------------
# Report
# ------------------------------------------------------------
print()
print("=" * 80)
print("MODULE 3 — EXP_003 FIXED SUBSET")
print("=" * 80)

print(f"Dataset              : Open Images")
print(f"Task                 : Obstacle detection")
print(f"Available candidates : {len(candidate_images)}")
print(f"Target images        : {TARGET_IMAGES}")
print(f"Selected images      : {unique_images}")
print(f"Seed                 : {SEED}")

print()
print("Integrity:")
print(f"Unique ImageIDs      : {unique_images}")
print(f"Unique sample IDs    : {unique_samples}")
print(f"Total annotations    : {len(subset)}")

print()
print("Class distribution:")
print(
    subset.groupby("DisplayName")["ImageID"]
    .nunique()
    .sort_values(ascending=False)
    .to_string()
)

print()
print("First 10 selected images:")
print(
    subset[
        ["subset_index", "sample_id", "ImageID"]
    ].drop_duplicates()
    .head(10)
    .to_string(index=False)
)

print()
print("Last 10 selected images:")
print(
    subset[
        ["subset_index", "sample_id", "ImageID"]
    ].drop_duplicates()
    .tail(10)
    .to_string(index=False)
)

print()
print("Saved:")
print(csv_path)
print(json_path)

print()
print("=" * 80)
print("NO INFERENCE RUN YET")
print("=" * 80)

