print("MODULE 6 — ICDAR 2015 OCR LABEL INTEGRITY CHECK")
print("=" * 80)

all_rows = []

for split in ["train", "train_numbers", "test", "test_numbers"]:
    for i, item in enumerate(loaded_ds[split]):
        all_rows.append({
            "split": split,
            "index": i,
            "text": item["text"],
            "image": item["image"],
        })

print("Total rows:", len(all_rows))

# ------------------------------------------------------------
# TEXT CHECKS
# ------------------------------------------------------------

empty_text = []
non_string = []
text_lengths = []

for item in all_rows:
    text = item["text"]

    if not isinstance(text, str):
        non_string.append(item)

    elif text.strip() == "":
        empty_text.append(item)

    else:
        text_lengths.append(len(text.strip()))

print("\nTEXT INTEGRITY")
print("-" * 80)
print("Non-string labels :", len(non_string))
print("Empty labels      :", len(empty_text))
print("Valid labels      :", len(text_lengths))

if text_lengths:
    print("Min length        :", min(text_lengths))
    print("Max length        :", max(text_lengths))
    print("Mean length       :", sum(text_lengths) / len(text_lengths))

# ------------------------------------------------------------
# SAMPLE LABELS
# ------------------------------------------------------------

