print("-" * 80)

for item in all_rows[:20]:
    print(
        f"{item['split']:15s} "
        f"{item['index']:5d} : "
        f"{repr(item['text'])}"
    )

# ------------------------------------------------------------
# SPLIT SUMMARY
# ------------------------------------------------------------

print("\nSPLIT SUMMARY")
print("-" * 80)

for split in ["train", "train_numbers", "test", "test_numbers"]:

    rows = loaded_ds[split]

    valid = 0
    empty = 0

    for item in rows:
        text = item["text"]

        if isinstance(text, str) and text.strip():
            valid += 1
        else:
            empty += 1

    print(
        f"{split:15s} "
        f"rows={len(rows):5d} "
        f"valid={valid:5d} "
        f"empty/invalid={empty:5d}"
    )

print("\n" + "=" * 80)
