# ============================================================

print("=" * 80)
print("MODULE 6 — ICDAR 2015 OCR IMAGE INTEGRITY CHECK")
print("=" * 80)

bad_images = []
image_sizes = Counter()

for split in ["train", "train_numbers", "test", "test_numbers"]:

    for i, item in enumerate(loaded_ds[split]):

        image = item["image"]

        try:
            width, height = image.size

            if width <= 0 or height <= 0:
                bad_images.append((split, i, image.size))
            else:
                image_sizes[(width, height)] += 1

        except Exception as e:
            bad_images.append((split, i, str(e)))

print("Total images :", len(all_rows))
print("Bad images   :", len(bad_images))

print("\nMOST COMMON IMAGE SIZES")
print("-" * 80)

for size, count in image_sizes.most_common(15):
    print(f"{str(size):20s} : {count}")

if bad_images:
    print("\nBAD IMAGE EXAMPLES")
    print("-" * 80)

    for item in bad_images[:10]:
        print(item)

print("\n" + "=" * 80)

if bad_images:
    print("✗ IMAGE INTEGRITY FAILED")
else:
    print("✓ ALL OCR IMAGES ARE VALID")

print("=" * 80)

