import time
import torch

N = 10

print("=" * 80)
print("MODULE 6 — TrOCR 10-IMAGE BENCHMARK")
print("=" * 80)

predictions = []

start = time.time()

for i in range(N):

    item = loaded_ds["test"][i]
    image = item["image"]

    pixel_values = processor(
        images=image,
        return_tensors="pt"
    ).pixel_values.to(DEVICE)

    with torch.no_grad():
        generated_ids = model.generate(
            pixel_values,
            max_new_tokens=64
        )

    prediction = processor.batch_decode(
        generated_ids,
        skip_special_tokens=True
    )[0].strip()

    predictions.append({
        "index": i,
        "prediction": prediction,
        "ground_truth": item["text"]
    })

elapsed = time.time() - start

print("\nRESULT")
print("-" * 80)
print("Images :", N)
print("Time   :", f"{elapsed:.2f} sec")
print("Avg    :", f"{elapsed / N:.3f} sec/image")

print("\nSAMPLES")
print("-" * 80)

for item in predictions[:5]:
    print("ID        :", item["index"])
    print("Prediction:", repr(item["prediction"]))
    print("Reference :", repr(item["ground_truth"]))
    print("-" * 40)

