# ============================================================
# MODULE 6 — ICDAR 2015 FULL OCR INFERENCE
# ============================================================

import os
import json
import time
import torch

MODULE6_DIR = "/content/module6_ocr"
RESULTS_DIR = os.path.join(MODULE6_DIR, "ICDAR2015_results")
os.makedirs(RESULTS_DIR, exist_ok=True)

PREDICTION_FILE = os.path.join(
    RESULTS_DIR,
    "ICDAR2015_test_predictions.json"
)

N = len(loaded_ds["test"])

print("=" * 80)
print("MODULE 6 — ICDAR 2015 FULL OCR INFERENCE")
print("=" * 80)

print("Images :", N)
print("Model  :", MODEL_ID)
print("Device :", DEVICE)
print("Output :", PREDICTION_FILE)

predictions = []

start_time = time.time()

model.eval()

for i in range(N):

    item = loaded_ds["test"][i]
    image = item["image"]
    reference = item["text"]

    pixel_values = processor(
        images=image,
        return_tensors="pt"
    ).pixel_values.to(DEVICE)

    with torch.no_grad():
        generated_ids = model.generate(
            pixel_values,
            max_new_tokens=64
        )

    prediction = processor.batch_decode(
        generated_ids,
        skip_special_tokens=True
    )[0].strip()

    predictions.append({
        "sample_index": i,
        "prediction": prediction,
        "reference": reference
    })

    if (i + 1) % 100 == 0 or i == 0:
        elapsed = time.time() - start_time
        rate = (i + 1) / elapsed

        print(
            f"[{i + 1:4d}/{N}] "
            f"{rate:.2f} images/sec | "
            f"prediction={prediction!r}"
        )

elapsed = time.time() - start_time

# ------------------------------------------------------------
# Save predictions
# ------------------------------------------------------------

with open(PREDICTION_FILE, "w", encoding="utf-8") as f:
    json.dump(
        predictions,
        f,
        ensure_ascii=False,
        indent=2
    )

print("\n" + "=" * 80)
