# ============================================================
# MODULE 6 — ICDAR 2015 OCR METRICS
# ============================================================

import json
import os
import re

PREDICTION_FILE = "/content/module6_ocr/ICDAR2015_results/ICDAR2015_test_predictions.json"

with open(PREDICTION_FILE, "r", encoding="utf-8") as f:
    predictions = json.load(f)

print("=" * 80)
print("MODULE 6 — ICDAR 2015 OCR METRICS")
print("=" * 80)

# ------------------------------------------------------------
# Install / import jiwer
# ------------------------------------------------------------

try:
    from jiwer import wer, cer
except ImportError:
    import sys
    import subprocess

    subprocess.check_call([
        sys.executable,
        "-m",
        "pip",
        "install",
        "-q",
        "jiwer"
    ])

    from jiwer import wer, cer

# ------------------------------------------------------------
# Prepare text
# ------------------------------------------------------------

references = []
hypotheses = []

for item in predictions:
    reference = str(item["reference"]).strip()
    hypothesis = str(item["prediction"]).strip()

    references.append(reference)
    hypotheses.append(hypothesis)

# ------------------------------------------------------------
# Raw metrics
# ------------------------------------------------------------

raw_cer = cer(references, hypotheses)
raw_wer = wer(references, hypotheses)

# ------------------------------------------------------------
# Case-normalized metrics
# ------------------------------------------------------------

normalized_references = [
    re.sub(r"\s+", " ", x.lower()).strip()
    for x in references
]

normalized_hypotheses = [
    re.sub(r"\s+", " ", x.lower()).strip()
    for x in hypotheses
]

normalized_cer = cer(
    normalized_references,
    normalized_hypotheses
)

normalized_wer = wer(
    normalized_references,
    normalized_hypotheses
)

# ------------------------------------------------------------
# Exact match
# ------------------------------------------------------------

exact_matches = sum(
    r == h
    for r, h in zip(references, hypotheses)
)

case_insensitive_matches = sum(
    r == h
    for r, h in zip(
        normalized_references,
        normalized_hypotheses
    )
)

total = len(predictions)

exact_accuracy = exact_matches / total
case_insensitive_accuracy = case_insensitive_matches / total

# ------------------------------------------------------------
# Empty predictions
# ------------------------------------------------------------

empty_predictions = sum(
    len(x.strip()) == 0
    for x in hypotheses
)

# ------------------------------------------------------------
# Results
# ------------------------------------------------------------

print("\nRESULTS")
print("-" * 80)

print(f"Images                    : {total}")
print(f"Empty predictions         : {empty_predictions}")

print(f"\nRaw CER                   : {raw_cer:.6f}")
print(f"Raw WER                   : {raw_wer:.6f}")

print(f"\nCase-normalized CER       : {normalized_cer:.6f}")
print(f"Case-normalized WER       : {normalized_wer:.6f}")

print(f"\nExact-match accuracy      : {exact_accuracy:.6f}")
print(f"Case-insensitive accuracy: {case_insensitive_accuracy:.6f}")

print("\n" + "=" * 80)
print("✓ OCR METRICS CALCULATED")
print("=" * 80)

# ============================================================
# MODULE 6 — OCR ERROR SAMPLE INSPECTION
# ============================================================

print("=" * 80)
print("MODULE 6 — OCR ERROR SAMPLE INSPECTION")
print("=" * 80)

errors = []

for item in predictions:
    ref = str(item["reference"]).strip()
    pred = str(item["prediction"]).strip()

    if ref.lower() != pred.lower():
        errors.append(item)

print("Total errors:", len(errors))
print("Total correct:", len(predictions) - len(errors))

print("\nFIRST 20 ERRORS")
print("-" * 80)

for item in errors[:20]:
    print("Index     :", item["sample_index"])
    print("Prediction:", repr(item["prediction"]))
    print("Reference :", repr(item["reference"]))
    print("-" * 50)

print("=" * 80)
print("✓ OCR ERROR INSPECTION COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 6 — ICDAR 2015 FINAL RESULTS + INTEGRITY CHECK
# ============================================================

import os
import json
import re

MODULE6_DIR = "/content/module6_ocr"
RESULTS_DIR = os.path.join(MODULE6_DIR, "ICDAR2015_results")

PREDICTION_FILE = os.path.join(
    RESULTS_DIR,
    "ICDAR2015_test_predictions.json"
)

FINAL_FILE = os.path.join(
    RESULTS_DIR,
    "ICDAR2015_final_results.json"
)

# ------------------------------------------------------------
# Load predictions
# ------------------------------------------------------------

with open(PREDICTION_FILE, "r", encoding="utf-8") as f:
    predictions = json.load(f)

# ------------------------------------------------------------
# Recalculate metrics
# ------------------------------------------------------------

from jiwer import wer, cer

references = [
    str(x["reference"]).strip()
    for x in predictions
]

hypotheses = [
    str(x["prediction"]).strip()
    for x in predictions
]

normalized_references = [
    re.sub(r"\s+", " ", x.lower()).strip()
    for x in references
]

normalized_hypotheses = [
    re.sub(r"\s+", " ", x.lower()).strip()
    for x in hypotheses
]

raw_cer = cer(references, hypotheses)
raw_wer = wer(references, hypotheses)

normalized_cer = cer(
    normalized_references,
    normalized_hypotheses
)

normalized_wer = wer(
    normalized_references,
    normalized_hypotheses
)

exact_matches = sum(
    r == h
    for r, h in zip(references, hypotheses)
)

case_insensitive_matches = sum(
    r == h
    for r, h in zip(
        normalized_references,
        normalized_hypotheses
    )
)

empty_predictions = sum(
    len(x.strip()) == 0
    for x in hypotheses
)

total_images = len(predictions)

# ------------------------------------------------------------
# Error statistics
# ------------------------------------------------------------

case_insensitive_errors = [
    x for x in predictions
    if str(x["reference"]).strip().lower()
    != str(x["prediction"]).strip().lower()
]

# ------------------------------------------------------------
# Integrity checks
# ------------------------------------------------------------

indices = [
    x["sample_index"]
    for x in predictions
]

assert total_images == 2077
assert len(indices) == 2077
assert len(set(indices)) == 2077
assert indices == list(range(2077))

assert all("prediction" in x for x in predictions)
assert all("reference" in x for x in predictions)

assert empty_predictions == 0

# ------------------------------------------------------------
# Final results structure
# ------------------------------------------------------------

final_results = {
    "module": "Module 6",
    "experiment": "ICDAR2015_OCR",
    "dataset": "ICDAR2015_OCR",
    "source": "MiXaiLL76/ICDAR2015_OCR",
    "task": "OCR / text recognition",

    "model": {
        "name": "microsoft/trocr-base-printed",
        "device": DEVICE,
        "transformers_version": __import__(
            "transformers"
        ).__version__
    },

    "evaluation": {
        "split": "test",
        "images": total_images,
        "frozen_subset": True
    },

    "metrics": {
        "CER": float(raw_cer),
        "WER": float(raw_wer),
        "case_normalized_CER": float(normalized_cer),
        "case_normalized_WER": float(normalized_wer),
        "exact_match_accuracy": float(
            exact_matches / total_images
        ),
        "case_insensitive_accuracy": float(
            case_insensitive_matches / total_images
        )
    },

    "statistics": {
        "total_images": total_images,
        "empty_predictions": empty_predictions,
        "case_insensitive_errors": len(
            case_insensitive_errors
        ),
        "case_insensitive_correct": (
            total_images - len(case_insensitive_errors)
        )
    },

    "predictions": predictions,

    "integrity": {
        "expected_images": 2077,
        "actual_images": total_images,
        "unique_ids": len(set(indices)),
        "missing_predictions": 0,
        "extra_predictions": 0,
        "empty_predictions": empty_predictions
    }
}

# ------------------------------------------------------------
# Save
# ------------------------------------------------------------

with open(FINAL_FILE, "w", encoding="utf-8") as f:
    json.dump(
        final_results,
        f,
        ensure_ascii=False,
        indent=2
    )

# ------------------------------------------------------------
# Final report
# ------------------------------------------------------------

print("=" * 80)
print("MODULE 6 — ICDAR 2015 FINALIZATION + INTEGRITY CHECK")
print("=" * 80)

print("\nEVALUATION")
print("-" * 80)
