# ============================================================
# MODULE 7 — OSM LANDMARK + ROUTING API CHECK
# ============================================================

import requests
import time

OVERPASS_URL = "https://overpass-api.de/api/interpreter"
NOMINATIM_URL = "https://nominatim.openstreetmap.org/search"
ROUTING_URL = "https://router.project-osrm.org/route/v1/driving"

HEADERS = {
    "User-Agent": "Module7-Navigation-Evaluation/1.0"
}

print("=" * 80)
print("MODULE 7 — OSM LANDMARK + ROUTING API CHECK")
print("=" * 80)

# ------------------------------------------------------------
# 1. NOMINATIM — landmark/geocoding search
# ------------------------------------------------------------

print("\nNOMINATIM")
print("-" * 80)

params = {
    "q": "Bengaluru",
    "format": "json",
    "limit": 1,
}

try:
    start = time.time()

    r = requests.get(
        NOMINATIM_URL,
        params=params,
        headers=HEADERS,
        timeout=30,
    )

    elapsed = time.time() - start

    print("HTTP status :", r.status_code)
    print("Reachable   :", r.ok)
    print("Time        :", f"{elapsed:.2f} sec")

    if r.ok:
        data = r.json()
        print("Results     :", len(data))

        if data:
            print("Display name:", data[0].get("display_name"))
            print("Latitude    :", data[0].get("lat"))
            print("Longitude   :", data[0].get("lon"))

        print("✓ Nominatim is reachable")

except Exception as e:
    print("ERROR:", repr(e))


# ------------------------------------------------------------
# 2. OVERPASS — nearby OSM landmark query
# ------------------------------------------------------------

print("\nOVERPASS")
print("-" * 80)

# Bengaluru approximate center.
lat = 12.9716
lon = 77.5946

query = f"""
[out:json][timeout:25];
(
  node["tourism"](around:1000,{lat},{lon});
  node["historic"](around:1000,{lat},{lon});
  node["amenity"="place_of_worship"](around:1000,{lat},{lon});
);
out center;
"""

try:
    start = time.time()

    r = requests.post(
        OVERPASS_URL,
        data=query,
        headers=HEADERS,
        timeout=40,
    )

    elapsed = time.time() - start

    print("HTTP status :", r.status_code)
    print("Reachable   :", r.ok)
    print("Time        :", f"{elapsed:.2f} sec")

    if r.ok:
        data = r.json()
        elements = data.get("elements", [])

        print("Landmarks   :", len(elements))

        for item in elements[:5]:
            tags = item.get("tags", {})
            print(
                "  -",
                tags.get("name", "<unnamed>"),
                "|",
                tags.get("tourism")
                or tags.get("historic")
                or tags.get("amenity")
            )

        print("✓ Overpass is reachable")

except Exception as e:
    print("ERROR:", repr(e))


# ------------------------------------------------------------
# 3. OSRM — routing API
# ------------------------------------------------------------

print("\nOSRM ROUTING")
print("-" * 80)

# Simple test route.
start_lon, start_lat = 77.5946, 12.9716
end_lon, end_lat = 77.6101, 12.9352

route_url = (
    f"{ROUTING_URL}/"
    f"{start_lon},{start_lat};"
    f"{end_lon},{end_lat}"
)

route_params = {
    "overview": "false",
    "steps": "true",
}

try:
    start = time.time()

    r = requests.get(
        route_url,
        params=route_params,
        headers=HEADERS,
        timeout=30,
    )

    elapsed = time.time() - start

    print("HTTP status :", r.status_code)
    print("Reachable   :", r.ok)
    print("Time        :", f"{elapsed:.2f} sec")

    if r.ok:
        data = r.json()

        routes = data.get("routes", [])

        print("Routes      :", len(routes))

        if routes:
            route = routes[0]

            print(
                "Distance    :",
                f"{route['distance'] / 1000:.2f} km"
            )

            print(
                "Duration    :",
                f"{route['duration'] / 60:.1f} min"
            )

            print(
                "Steps       :",
                len(route.get("legs", [{}])[0].get("steps", []))
            )

        print("✓ OSRM routing is reachable")

except Exception as e:
    print("ERROR:", repr(e))


print("\n" + "=" * 80)
print("✓ MODULE 7 OSM API CONNECTIVITY CHECK COMPLETE")
print("=" * 80)

