import os
import json

MODULE7_DIR = "/content/module7_navigation"
RESULTS_DIR = f"{MODULE7_DIR}/OSM_results"

FROZEN_FILE = f"{RESULTS_DIR}/OSM_frozen_evaluation_subset.json"
BENCHMARK_FILE = f"{RESULTS_DIR}/OSM_10query_benchmark.json"

print("=" * 80)
print("MODULE 7 — NAVIGATION BENCHMARK INTEGRITY CHECK")
print("=" * 80)

# ------------------------------------------------------------
# Load files
# ------------------------------------------------------------

assert os.path.exists(FROZEN_FILE), "Frozen subset missing"
assert os.path.exists(BENCHMARK_FILE), "Benchmark output missing"

with open(FROZEN_FILE, "r", encoding="utf-8") as f:
    frozen = json.load(f)

with open(BENCHMARK_FILE, "r", encoding="utf-8") as f:
    benchmark = json.load(f)

frozen_landmarks = frozen["landmark_queries"]
frozen_routes = frozen["routing_queries"]

results = benchmark["results"]

expected_ids = (
    [x["id"] for x in frozen_landmarks] +
    [x["id"] for x in frozen_routes]
)

actual_ids = [x["id"] for x in results]

print("\nFROZEN SUBSET")
print("-" * 80)
print("Landmark queries :", len(frozen_landmarks))
print("Routing queries  :", len(frozen_routes))
print("Total queries    :", len(expected_ids))

print("\nBENCHMARK")
print("-" * 80)
print("Result entries   :", len(results))
print("Unique result IDs:", len(set(actual_ids)))

# ------------------------------------------------------------
# ID integrity
# ------------------------------------------------------------

missing = sorted(set(expected_ids) - set(actual_ids))
extra = sorted(set(actual_ids) - set(expected_ids))
duplicates = sorted(
    {
        x for x in actual_ids
        if actual_ids.count(x) > 1
    }
)

print("\nID ALIGNMENT")
print("-" * 80)
print("Missing IDs :", missing)
print("Extra IDs   :", extra)
print("Duplicates  :", duplicates)

assert len(results) == len(expected_ids)
assert len(set(actual_ids)) == len(actual_ids)
assert not missing
assert not extra
assert not duplicates

print("✓ Query IDs aligned")

# ------------------------------------------------------------
# Landmark integrity
# ------------------------------------------------------------

landmark_results = [
    x for x in results
    if x.get("task") == "landmark_retrieval"
]

print("\nLANDMARK RESULTS")
print("-" * 80)
print("Expected :", len(frozen_landmarks))
print("Actual   :", len(landmark_results))

assert len(landmark_results) == len(frozen_landmarks)

landmark_success = 0
landmark_zero = 0
landmark_errors = 0

for x in landmark_results:

    if "error" in x:
        landmark_errors += 1

    elif x.get("http_status") == 200:
        landmark_success += 1

        if x.get("landmark_count", 0) == 0:
            landmark_zero += 1

print("HTTP-successful queries :", landmark_success)
print("Zero named landmarks    :", landmark_zero)
print("Errors                  :", landmark_errors)

# ------------------------------------------------------------
# Routing integrity
# ------------------------------------------------------------

route_results = [
    x for x in results
    if x.get("task") == "routing"
]

print("\nROUTING RESULTS")
print("-" * 80)
print("Expected :", len(frozen_routes))
print("Actual   :", len(route_results))

assert len(route_results) == len(frozen_routes)

route_success = 0
route_failed = 0
route_errors = 0

for x in route_results:

    if "error" in x:
        route_errors += 1

    elif x.get("route_found") is True:
        route_success += 1

    else:
        route_failed += 1

print("Routes found :", route_success)
print("Routes failed:", route_failed)
print("Errors       :", route_errors)

# Every successful route must have a valid distance.
for x in route_results:
    if x.get("route_found") is True:
        assert x.get("distance_m") is not None
        assert x.get("distance_m") > 0

print("✓ Routing results structurally valid")

# ------------------------------------------------------------
# Overall integrity
# ------------------------------------------------------------

assert landmark_errors == 0
assert route_errors == 0
assert route_success == len(frozen_routes)

print("\n" + "=" * 80)
print("✓ MODULE 7 BENCHMARK INTEGRITY VERIFIED")
print("=" * 80)

