import os
import json
import statistics

MODULE7_DIR = "/content/module7_navigation"
RESULTS_DIR = f"{MODULE7_DIR}/OSM_results"

FROZEN_FILE = f"{RESULTS_DIR}/OSM_frozen_evaluation_subset.json"
BENCHMARK_FILE = f"{RESULTS_DIR}/OSM_10query_benchmark.json"
FINAL_FILE = f"{RESULTS_DIR}/OSM_final_results.json"

print("=" * 80)
print("MODULE 7 — OSM FINALIZATION + INTEGRITY CHECK")
print("=" * 80)

# ------------------------------------------------------------
# 1. LOAD FROZEN SUBSET
# ------------------------------------------------------------

with open(FROZEN_FILE, "r") as f:
    frozen = json.load(f)

print("\nFROZEN FILE STRUCTURE")
print("-" * 80)

if isinstance(frozen, dict):
    print("Top-level keys:", list(frozen.keys()))
else:
    print("Frozen object type:", type(frozen).__name__)

# Explicitly retrieve the two lists
landmark_queries = frozen.get("landmark_queries", [])
routing_queries = frozen.get("routing_queries", [])

# Safety for alternative naming
if not landmark_queries:
    landmark_queries = frozen.get("landmarks", [])

if not routing_queries:
    routing_queries = frozen.get("routes", [])

# ------------------------------------------------------------
# 2. LOAD BENCHMARK
# ------------------------------------------------------------

with open(BENCHMARK_FILE, "r") as f:
    benchmark = json.load(f)

if isinstance(benchmark, dict):
    results = benchmark.get("results", [])

    if not results:
        results = benchmark.get("queries", [])
else:
    results = benchmark

print("\n" + "=" * 80)
print("1. FROZEN EVALUATION SUBSET")
print("-" * 80)

print("Landmark queries :", len(landmark_queries))
print("Routing queries  :", len(routing_queries))
print("Total queries    :", len(landmark_queries) + len(routing_queries))

assert len(landmark_queries) == 5, (
    f"Expected 5 landmark queries, got {len(landmark_queries)}"
)

assert len(routing_queries) == 5, (
    f"Expected 5 routing queries, got {len(routing_queries)}"
)

# ------------------------------------------------------------
# 3. BUILD FROZEN ID SET
# ------------------------------------------------------------

frozen_ids = []

for q in landmark_queries + routing_queries:
    qid = q.get("id", q.get("query_id"))

    if qid is not None:
        frozen_ids.append(str(qid))

print("\nFROZEN IDs")
print("-" * 80)
print(frozen_ids)

# ------------------------------------------------------------
# 4. BENCHMARK IDs
# ------------------------------------------------------------

result_ids = []

for r in results:
    rid = r.get("id", r.get("query_id"))

    if rid is not None:
        result_ids.append(str(rid))

print("\n" + "=" * 80)
print("2. BENCHMARK RESULTS")
print("-" * 80)

print("Result entries :", len(results))

# ------------------------------------------------------------
# 5. ID ALIGNMENT
# ------------------------------------------------------------

frozen_set = set(frozen_ids)
result_set = set(result_ids)

missing_ids = sorted(frozen_set - result_set)
extra_ids = sorted(result_set - frozen_set)

duplicates = sorted({
    x for x in result_ids
    if result_ids.count(x) > 1
})

print("\n" + "=" * 80)
print("3. ID ALIGNMENT")
print("-" * 80)

print("Frozen IDs  :", len(frozen_set))
print("Result IDs  :", len(result_set))
print("Unique IDs  :", len(result_set))
print("Missing IDs :", missing_ids)
print("Extra IDs   :", extra_ids)
print("Duplicates  :", duplicates)

assert len(results) == 10
assert len(frozen_set) == 10
assert len(result_set) == 10
assert not missing_ids
assert not extra_ids
assert not duplicates

print("✓ IDs aligned")

# ------------------------------------------------------------
# 6. RESULT TYPE CLASSIFICATION
# ------------------------------------------------------------

landmark_ids = {
    str(q.get("id", q.get("query_id")))
    for q in landmark_queries
}

routing_ids = {
    str(q.get("id", q.get("query_id")))
    for q in routing_queries
}

landmark_results = [
    r for r in results
    if str(r.get("id", r.get("query_id"))) in landmark_ids
]

routing_results = [
    r for r in results
    if str(r.get("id", r.get("query_id"))) in routing_ids
]

print("\n" + "=" * 80)
print("4. RESULT TYPES")
print("-" * 80)

print("Landmark results :", len(landmark_results))
print("Routing results  :", len(routing_results))

assert len(landmark_results) == 5
assert len(routing_results) == 5

# ------------------------------------------------------------
# 7. SAFE LANDMARK COUNT
# ------------------------------------------------------------

def get_landmark_count(r):

    count = r.get("landmark_count")

    if isinstance(count, (int, float)):
        return int(count)

    if isinstance(count, str):
        try:
            return int(count)
        except ValueError:
            pass

    if isinstance(count, list):
        return len(count)

    landmarks = r.get("landmarks")

    if isinstance(landmarks, list):
        return len(landmarks)

    if isinstance(landmarks, dict):
        return len(landmarks)

    return None


landmark_counts = []

for r in landmark_results:

    count = get_landmark_count(r)

    if count is not None:
        landmark_counts.append(count)

print("\n" + "=" * 80)
print("5. LANDMARK RESULTS")
print("-" * 80)

print("Expected :", 5)
print("Actual   :", len(landmark_results))
print("Counts   :", landmark_counts)

if landmark_counts:
    print("Total named landmarks :", sum(landmark_counts))
    print(
        "Zero-landmark queries  :",
        sum(1 for x in landmark_counts if x == 0)
    )

# ------------------------------------------------------------
# 8. ROUTING RESULTS
# ------------------------------------------------------------

routes_found = 0
routes_failed = 0

route_distances = []
route_durations = []

for r in routing_results:

    route = r.get("route")

    if route is True:
        routes_found += 1

    elif isinstance(route, dict):
        routes_found += 1

    elif route:
        routes_found += 1

    else:
        routes_failed += 1

    distance = r.get("distance")

    if isinstance(distance, (int, float)):
        route_distances.append(float(distance))

    duration = r.get("duration")

    if isinstance(duration, (int, float)):
        route_durations.append(float(duration))

print("\n" + "=" * 80)
print("6. ROUTING RESULTS")
print("-" * 80)

print("Expected routes :", 5)
print("Actual results  :", len(routing_results))
print("Routes found    :", routes_found)
print("Routes failed   :", routes_failed)

if route_distances:
    print(
        "Average distance :",
        round(statistics.mean(route_distances), 2),
        "m"
    )

if route_durations:
    print(
        "Average duration :",
        round(statistics.mean(route_durations), 2),
        "sec"
    )

# ------------------------------------------------------------
# 9. FINAL DATA
# ------------------------------------------------------------

final_data = {
    "experiment": "MODULE_7",
    "dataset": "OpenStreetMap",
    "task": "GPS / Navigation",

    "evaluation_queries": 10,

    "landmark_queries": landmark_queries,
    "routing_queries": routing_queries,

    "results": results,

    "summary": {
        "landmark_results": len(landmark_results),
        "routing_results": len(routing_results),

        "landmark_counts": landmark_counts,

        "total_landmarks": (
            sum(landmark_counts)
            if landmark_counts else 0
        ),

        "zero_landmark_queries": (
            sum(1 for x in landmark_counts if x == 0)
            if landmark_counts else 0
        ),

        "routes_found": routes_found,
        "routes_failed": routes_failed,

        "average_route_distance_m": (
            statistics.mean(route_distances)
            if route_distances else None
        ),

        "average_route_duration_sec": (
            statistics.mean(route_durations)
            if route_durations else None
        )
    },

    "integrity": {
        "frozen_queries": 10,
        "result_entries": len(results),
        "unique_result_ids": len(result_set),
        "missing_ids": missing_ids,
        "extra_ids": extra_ids,
        "duplicates": duplicates
    }
}

# ------------------------------------------------------------
# 10. SAVE
# ------------------------------------------------------------

with open(FINAL_FILE, "w") as f:
    json.dump(final_data, f, indent=2)

# ------------------------------------------------------------
