import json
import os

MODULE7_DIR = "/content/module7_navigation"
RESULTS_DIR = f"{MODULE7_DIR}/OSM_results"

FROZEN_FILE = f"{RESULTS_DIR}/OSM_frozen_evaluation_subset.json"
BENCHMARK_FILE = f"{RESULTS_DIR}/OSM_10query_benchmark.json"
FINAL_FILE = f"{RESULTS_DIR}/OSM_final_results.json"

print("=" * 80)
print("MODULE 7 — OSM FINALIZATION + INTEGRITY CHECK")
print("=" * 80)

# ------------------------------------------------------------
# 1. LOAD FILES
# ------------------------------------------------------------

with open(FROZEN_FILE, "r") as f:
    frozen = json.load(f)

with open(BENCHMARK_FILE, "r") as f:
    benchmark = json.load(f)

landmark_queries = frozen.get("landmark_queries", [])
routing_queries = frozen.get("routing_queries", [])

results = benchmark.get("results", [])

# ------------------------------------------------------------
# 2. HANDLE POSSIBLE RESULT STRUCTURES
# ------------------------------------------------------------

if not results:
    if isinstance(benchmark, list):
        results = benchmark
    elif isinstance(benchmark, dict):
        for key in ["results", "benchmark_results", "entries"]:
            if isinstance(benchmark.get(key), list):
                results = benchmark[key]
                break

# ------------------------------------------------------------
# 3. FROZEN IDS
# ------------------------------------------------------------

frozen_ids = [
    q["id"]
    for q in landmark_queries + routing_queries
    if isinstance(q, dict) and "id" in q
]

result_ids = [
    r["id"]
    for r in results
    if isinstance(r, dict) and "id" in r
]

frozen_id_set = set(frozen_ids)
result_id_set = set(result_ids)

missing_ids = sorted(frozen_id_set - result_id_set)
extra_ids = sorted(result_id_set - frozen_id_set)

duplicates = sorted({
    x for x in result_ids
    if result_ids.count(x) > 1
})

print("\n" + "=" * 80)
print("1. FROZEN EVALUATION SUBSET")
print("-" * 80)

print("Landmark queries :", len(landmark_queries))
print("Routing queries  :", len(routing_queries))
print("Total queries    :", len(frozen_ids))

print("\nFROZEN IDs")
print("-" * 80)
print(frozen_ids)

# ------------------------------------------------------------
# 4. ID ALIGNMENT
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("2. BENCHMARK RESULTS")
print("-" * 80)

print("Result entries :", len(results))

print("\n" + "=" * 80)
print("3. ID ALIGNMENT")
print("-" * 80)

print("Frozen IDs  :", len(frozen_ids))
print("Result IDs  :", len(result_ids))
print("Unique IDs  :", len(result_id_set))
print("Missing IDs :", missing_ids)
print("Extra IDs   :", extra_ids)
print("Duplicates  :", duplicates)

assert not missing_ids
assert not extra_ids
assert not duplicates

print("✓ IDs aligned")

# ------------------------------------------------------------
# 5. RESULT TYPES
# ------------------------------------------------------------

landmark_results = [
    r for r in results
    if r.get("task") == "landmark"
]

routing_results = [
    r for r in results
    if r.get("task") == "routing"
]

print("\n" + "=" * 80)
print("4. RESULT TYPES")
print("-" * 80)

print("Landmark results :", len(landmark_results))
print("Routing results  :", len(routing_results))

assert len(landmark_results) == len(landmark_queries)
assert len(routing_results) == len(routing_queries)

# ------------------------------------------------------------
# 6. LANDMARK RESULTS
# ------------------------------------------------------------

landmark_counts = []

for r in landmark_results:

    count = r.get("landmarks")

    # Some implementations may store landmarks as a list.
    if isinstance(count, list):
        count = len(count)

    elif isinstance(count, dict):
        count = len(count)

    elif count is None:
        # Fall back to common count fields
        for key in ["landmark_count", "count", "num_landmarks"]:
            value = r.get(key)

            if isinstance(value, list):
                count = len(value)
                break

            if isinstance(value, (int, float)):
                count = value
                break

    if count is None:
        count = 0

    landmark_counts.append(int(count))

zero_landmarks = sum(
    1 for count in landmark_counts
    if count == 0
)

total_landmarks = sum(landmark_counts)

print("\n" + "=" * 80)
print("5. LANDMARK RESULTS")
print("-" * 80)

print("Expected :", len(landmark_queries))
print("Actual   :", len(landmark_results))
print("Counts   :", landmark_counts)
print("Total named landmarks :", total_landmarks)
print("Zero-landmark queries  :", zero_landmarks)

assert len(landmark_results) == len(landmark_queries)

# ------------------------------------------------------------
# 7. ROUTING RESULTS
# ------------------------------------------------------------

# IMPORTANT:
# The diagnostic confirmed that routing success is stored in
# r["route_found"].

routes_found = sum(
    1 for r in routing_results
    if r.get("route_found") is True
)

routes_failed = sum(
    1 for r in routing_results
    if r.get("route_found") is not True
)

routing_errors = sum(
    1 for r in routing_results
    if r.get("http_status") != 200
)

print("\n" + "=" * 80)
print("6. ROUTING RESULTS")
print("-" * 80)

print("Expected routes :", len(routing_queries))
print("Actual results  :", len(routing_results))
print("Routes found    :", routes_found)
print("Routes failed   :", routes_failed)
print("HTTP errors     :", routing_errors)

assert len(routing_results) == len(routing_queries)
assert routes_found == len(routing_queries)
assert routing_errors == 0

# ------------------------------------------------------------
# 8. FINAL METADATA
# ------------------------------------------------------------

final_data = {
    "experiment": "MODULE_7",
    "task": "gps_navigation",
    "dataset": "OpenStreetMap",
    "sources": {
        "nominatim": "OpenStreetMap Nominatim",
        "overpass": "OpenStreetMap Overpass API",
        "routing": "OSRM"
    },

    "frozen_evaluation_subset": {
        "landmark_queries": landmark_queries,
        "routing_queries": routing_queries,
        "landmark_query_count": len(landmark_queries),
        "routing_query_count": len(routing_queries),
        "total_queries": len(frozen_ids)
    },

    "benchmark": {
        "result_entries": len(results),
        "landmark_results": len(landmark_results),
        "routing_results": len(routing_results),

        "landmark_counts": landmark_counts,
        "total_named_landmarks": total_landmarks,
        "zero_landmark_queries": zero_landmarks,

        "routes_found": routes_found,
        "routes_failed": routes_failed,
        "routing_http_errors": routing_errors
    },

    "integrity": {
        "frozen_ids": len(frozen_ids),
        "result_ids": len(result_ids),
        "unique_result_ids": len(result_id_set),
        "missing_ids": missing_ids,
        "extra_ids": extra_ids,
        "duplicates": duplicates
    },

    "results": results
}

# ------------------------------------------------------------
# 9. SAVE FINAL FILE
# ------------------------------------------------------------

os.makedirs(RESULTS_DIR, exist_ok=True)

with open(FINAL_FILE, "w") as f:
    json.dump(final_data, f, indent=2, ensure_ascii=False)

# ------------------------------------------------------------
# 10. FINAL VERIFICATION
# ------------------------------------------------------------

print("\n" + "=" * 80)
