assert len(check["results"]) == 10
assert len(check["frozen_evaluation_subset"]["landmark_queries"]) == 5
assert len(check["frozen_evaluation_subset"]["routing_queries"]) == 5
assert check["benchmark"]["routes_found"] == 5
assert check["integrity"]["missing_ids"] == []
assert check["integrity"]["extra_ids"] == []
assert check["integrity"]["duplicates"] == []

