assert len(verified["routing_queries"]) == 5
assert len(verified["results"]) == 10

assert verified["benchmark"]["landmark_results"] == 5
assert verified["benchmark"]["routing_results"] == 5
assert verified["benchmark"]["routes_found"] == 5
assert verified["benchmark"]["routes_failed"] == 0

assert verified["integrity"]["missing_ids"] == []
assert verified["integrity"]["extra_ids"] == []
assert verified["integrity"]["duplicates"] == []

print("\n" + "=" * 80)
