import requests
import json
import time

print("=" * 80)
print("MODULE 8 — KITTI CANDIDATE DATASET INSPECTION")
print("=" * 80)

CANDIDATES = [
    "dangth2004/KITTI-Depth-Estimation",
    "msdkhairi/kitti-depth",
    "exander/kitti-depth-gt",
    "alextittozach/KITTI-depth-rgb-20k-pairs",
    "kronecker0122/kitti-depth-completion",
]

API = "https://huggingface.co/api/datasets"

for dataset_id in CANDIDATES:

    print("\n" + "=" * 80)
    print("DATASET:", dataset_id)
    print("=" * 80)

    try:
        start = time.time()

        response = requests.get(
            f"{API}/{dataset_id}",
            timeout=30
        )

        elapsed = time.time() - start

        print("HTTP status:", response.status_code)
        print("Time       :", round(elapsed, 2), "sec")

        if response.status_code != 200:
            print("✗ Dataset metadata unavailable")
            continue

        info = response.json()

        print("Author     :", info.get("author"))
        print("Downloads  :", info.get("downloads"))
        print("Likes      :", info.get("likes"))
        print("Private    :", info.get("private"))

        print("\nTAGS")
        print("-" * 80)

        for tag in info.get("tags", []):
            print(" ", tag)

        print("\nFILES")
        print("-" * 80)

        siblings = info.get("siblings", [])

        if not siblings:
            print("No file list returned")
        else:
            for item in siblings[:100]:
                filename = item.get("rfilename", "")
                print(" ", filename)

            if len(siblings) > 100:
                print(" ...", len(siblings) - 100, "more files")

    except Exception as e:
        print("ERROR:", repr(e))

print("\n" + "=" * 80)
print("✓ KITTI CANDIDATE INSPECTION COMPLETE")
print("=" * 80)

