import requests
import os
import time

DATASET_ID = "dangth2004/KITTI-Depth-Estimation"
BASE_URL = f"https://huggingface.co/datasets/{DATASET_ID}/resolve/main"

print("=" * 80)
print("MODULE 8 — KITTI RGB + DEPTH SOURCE VERIFICATION")
print("=" * 80)

# Representative ground-truth depth file
DEPTH_FILE = (
    "data_depth_annotated/train/"
    "2011_09_26_drive_0001_sync/"
    "proj_depth/groundtruth/image_02/0000000005.png"
)

url = f"{BASE_URL}/{DEPTH_FILE}"

print("\nGROUND-TRUTH DEPTH")
print("-" * 80)
print("URL:", url)

try:
    start = time.time()

    r = requests.get(
        url,
        stream=True,
        timeout=30
    )

    elapsed = time.time() - start

    print("HTTP status :", r.status_code)
    print("Time        :", round(elapsed, 2), "sec")
    print("Content type:", r.headers.get("Content-Type"))
    print("Size bytes  :", r.headers.get("Content-Length"))

    if r.status_code == 200:
        print("✓ Ground-truth depth file is accessible")
    else:
        print("✗ Ground-truth depth file unavailable")

except Exception as e:
    print("ERROR:", repr(e))


# Inspect repository tree through HF API
print("\n" + "=" * 80)
print("REPOSITORY TREE SEARCH")
print("-" * 80)

API_URL = f"https://huggingface.co/api/datasets/{DATASET_ID}/tree/main"

try:
    r = requests.get(
        API_URL,
        params={"recursive": "true", "expand": "false"},
        timeout=60
    )

    print("HTTP status:", r.status_code)

    if r.status_code == 200:
        files = r.json()

        rgb_candidates = []
        depth_candidates = []

        for item in files:
            path = item.get("path", "").lower()

            if (
                path.endswith(".png")
                or path.endswith(".jpg")
                or path.endswith(".jpeg")
            ):
                if "image_02" in path and "groundtruth" not in path:
                    rgb_candidates.append(item.get("path"))

                if "groundtruth/image_02" in path:
                    depth_candidates.append(item.get("path"))

        print("RGB candidates  :", len(rgb_candidates))
        print("Depth candidates:", len(depth_candidates))

        print("\nSAMPLE RGB FILES")
        for p in rgb_candidates[:5]:
            print(" ", p)

        print("\nSAMPLE DEPTH FILES")
        for p in depth_candidates[:5]:
            print(" ", p)

        if rgb_candidates and depth_candidates:
            print("\n✓ RGB + DEPTH DATA FOUND")
        else:
            print("\n✗ Could not verify both RGB and depth")

    else:
        print("✗ Repository tree request failed")

except Exception as e:
    print("ERROR:", repr(e))

print("\n" + "=" * 80)
print("✓ KITTI RGB + DEPTH SOURCE VERIFICATION COMPLETE")
print("=" * 80)

