# MODULE 8 — ALTERNATE KITTI ZIP CONTENT VERIFICATION
# ============================================================

import requests
import zipfile
import io
import os

REPO_ID = "alextittozach/KITTI-depth-rgb-20k-pairs"

ZIP_URL = (
    f"https://huggingface.co/datasets/{REPO_ID}"
    f"/resolve/main/datasets.zip"
)

print("=" * 80)
print("MODULE 8 — ALTERNATE KITTI ZIP CONTENT VERIFICATION")
print("=" * 80)

print("Repository:", REPO_ID)
print("Downloading datasets.zip...")

response = requests.get(ZIP_URL, timeout=120)

print("HTTP status:", response.status_code)
print("Size MB    :", round(len(response.content) / (1024 ** 2), 2))

if response.status_code != 200:
    raise RuntimeError("Could not download datasets.zip")

print("\nZIP CONTENTS")
print("-" * 80)

with zipfile.ZipFile(io.BytesIO(response.content)) as z:
    names = z.namelist()

    print("Total files:", len(names))

    rgb_files = []
    depth_files = []

    for name in names:
        lower = name.lower()

        if lower.endswith((".jpg", ".jpeg", ".png")):
            if any(x in lower for x in ["depth", "disp", "gt"]):
                depth_files.append(name)
            else:
                rgb_files.append(name)

    print("RGB candidates  :", len(rgb_files))
    print("Depth candidates:", len(depth_files))

    print("\nSAMPLE RGB FILES")
    for x in rgb_files[:10]:
        print(" ", x)

    print("\nSAMPLE DEPTH FILES")
    for x in depth_files[:10]:
        print(" ", x)

print("\n" + "=" * 80)

if rgb_files and depth_files:
    print("✓ BOTH RGB AND DEPTH FILES FOUND")
else:
    print("✗ Could not verify RGB + depth pairs")

print("=" * 80)
print("✓ ALTERNATE KITTI ZIP CONTENT VERIFICATION COMPLETE")
print("=" * 80)

