import requests
import time

ZIP_URL = (
    "https://huggingface.co/datasets/"
    "alextittozach/KITTI-depth-rgb-20k-pairs/"
    "resolve/main/datasets.zip"
)

print("=" * 80)
print("MODULE 8 — KITTI ZIP REMOTE SIZE CHECK")
print("=" * 80)

try:
    start = time.time()

    r = requests.head(
        ZIP_URL,
        allow_redirects=True,
        timeout=30
    )

    elapsed = time.time() - start

    print("HTTP status :", r.status_code)
    print("Time        :", round(elapsed, 2), "sec")
    print("Final URL   :", r.url)

    content_length = r.headers.get("Content-Length")
    content_type = r.headers.get("Content-Type")

    print("\nREMOTE FILE")
    print("-" * 80)
    print("Content-Type   :", content_type)
    print("Content-Length :", content_length)

    if content_length:
        size_bytes = int(content_length)
        size_gb = size_bytes / (1024 ** 3)
        size_mb = size_bytes / (1024 ** 2)

        print("Size MB        :", round(size_mb, 2))
        print("Size GB        :", round(size_gb, 2))

        if size_gb > 5:
            print("⚠ ZIP is very large — do not download yet")
        else:
            print("✓ ZIP size may be manageable")
    else:
        print("⚠ Server did not provide Content-Length")

    print("\n" + "=" * 80)
    print("✓ KITTI ZIP REMOTE SIZE CHECK COMPLETE")
    print("=" * 80)

except Exception as e:
    print("ERROR:", repr(e))

