# ============================================================

import requests
import time

REPO = "2inf/kitti-raw"
DRIVE_FILE = "2011_09_26_drive_0001_sync.zip"

URL = (
    f"https://huggingface.co/datasets/{REPO}"
    f"/resolve/main/{DRIVE_FILE}"
)

print("=" * 80)
print("MODULE 8 — KITTI DRIVE ZIP SIZE CHECK")
print("=" * 80)

print("Repository :", REPO)
print("Drive file :", DRIVE_FILE)

try:
    start = time.time()

    r = requests.head(
        URL,
        allow_redirects=True,
        timeout=30
    )

    elapsed = time.time() - start

    print("HTTP status :", r.status_code)
    print("Time        :", round(elapsed, 2), "sec")

    content_length = r.headers.get("Content-Length")
    content_type = r.headers.get("Content-Type")

    print("\nREMOTE FILE")
    print("-" * 80)
    print("Content-Type   :", content_type)
    print("Content-Length :", content_length)

    if content_length:
        size_bytes = int(content_length)
        size_mb = size_bytes / (1024 ** 2)
        size_gb = size_bytes / (1024 ** 3)

        print("Size MB        :", round(size_mb, 2))
        print("Size GB        :", round(size_gb, 2))

        if size_gb <= 1:
            print("✓ Small enough to consider downloading")
        else:
            print("⚠ Large file — inspect before downloading")
    else:
        print("⚠ Content-Length unavailable")

except Exception as e:
    print("ERROR:", repr(e))

print("\n" + "=" * 80)
print("✓ KITTI DRIVE ZIP SIZE CHECK COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 8 — KITTI DRIVE FILE METADATA CHECK
# ============================================================

import requests
import time

REPO = "2inf/kitti-raw"
DRIVE_FILE = "2011_09_26_drive_0001_sync.zip"

print("=" * 80)
print("MODULE 8 — KITTI DRIVE FILE METADATA CHECK")
print("=" * 80)

try:
    start = time.time()

    # Hugging Face dataset tree API
    url = f"https://huggingface.co/api/datasets/{REPO}/tree/main"
    params = {
        "path": "",
        "recursive": "false"
    }

    r = requests.get(url, params=params, timeout=30)

    elapsed = time.time() - start

    print("HTTP status:", r.status_code)
    print("Time       :", round(elapsed, 2), "sec")

    r.raise_for_status()

    files = r.json()

    target = None

    for item in files:
        if item.get("path") == DRIVE_FILE:
            target = item
            break

    print("\nTARGET FILE")
    print("-" * 80)

    if target is None:
        print("✗ Drive ZIP not found in repository tree")
    else:
        print("Path :", target.get("path"))
        print("Type :", target.get("type"))
        print("Size :", target.get("size"))

        if target.get("size") is not None:
            size_bytes = target["size"]
            size_mb = size_bytes / (1024 ** 2)
            size_gb = size_bytes / (1024 ** 3)

            print("Size MB:", round(size_mb, 2))
            print("Size GB:", round(size_gb, 2))

    print("\n" + "=" * 80)
    print("✓ KITTI DRIVE FILE METADATA CHECK COMPLETE")
    print("=" * 80)

except Exception as e:
    print("ERROR:", repr(e))

# ============================================================
# MODULE 8 — DOWNLOAD SINGLE KITTI RGB DRIVE
# ============================================================

import os
import requests
import time

REPO = "2inf/kitti-raw"
DRIVE_FILE = "2011_09_26_drive_0001_sync.zip"

OUTPUT_DIR = "/content/module8_depth/KITTI"
ZIP_PATH = os.path.join(OUTPUT_DIR, DRIVE_FILE)

URL = (
    f"https://huggingface.co/datasets/{REPO}"
    f"/resolve/main/{DRIVE_FILE}?download=true"
)

os.makedirs(OUTPUT_DIR, exist_ok=True)

print("=" * 80)
print("MODULE 8 — DOWNLOAD SINGLE KITTI RGB DRIVE")
print("=" * 80)

print("File :", DRIVE_FILE)
print("Target:", ZIP_PATH)
print("Expected size: ~437.4 MB")

if os.path.exists(ZIP_PATH):
    existing = os.path.getsize(ZIP_PATH)
    print("\nExisting file:", round(existing / (1024**2), 2), "MB")

    if existing > 400 * 1024 * 1024:
        print("✓ Existing download appears complete")
    else:
        print("⚠ Existing file appears incomplete")

else:
    print("\nDownloading...")

    start = time.time()

    with requests.get(
        URL,
        stream=True,
        timeout=60
    ) as r:

        print("HTTP status:", r.status_code)
        r.raise_for_status()

        total = int(r.headers.get("Content-Length", 0))
        downloaded = 0

        with open(ZIP_PATH, "wb") as f:
            for chunk in r.iter_content(chunk_size=8 * 1024 * 1024):
                if chunk:
                    f.write(chunk)
                    downloaded += len(chunk)

                    if total:
                        pct = 100 * downloaded / total
                        print(
                            f"\rDownloaded: "
                            f"{downloaded/(1024**2):.1f} MB "
                            f"({pct:.1f}%)",
                            end=""
                        )

    elapsed = time.time() - start

    print("\n\nDownload complete")
    print("Time:", round(elapsed / 60, 2), "minutes")

size = os.path.getsize(ZIP_PATH)

print("\nFINAL FILE")
print("-" * 80)
print("Exists :", os.path.exists(ZIP_PATH))
print("Size MB:", round(size / (1024**2), 2))

print("\n" + "=" * 80)
print("✓ SINGLE KITTI DRIVE DOWNLOAD COMPLETE")
print("=" * 80)

