# ============================================================
# MODULE 8 — KITTI ALTERNATIVE RGB/DEPTH STRUCTURE CHECK
# ============================================================

import requests
import json
import time

REPO = "oceanfish/kitti"

print("=" * 80)
print("MODULE 8 — KITTI ALTERNATIVE RGB/DEPTH STRUCTURE CHECK")
print("=" * 80)

# Hugging Face dataset tree API
url = f"https://huggingface.co/api/datasets/{REPO}/tree/main"

print("\nQUERYING REPOSITORY TREE")
print("-" * 80)

start = time.time()

r = requests.get(
    url,
    params={"recursive": "true", "expand": "false"},
    timeout=60
)

print("HTTP status :", r.status_code)
print("Time        :", round(time.time() - start, 2), "sec")

r.raise_for_status()

items = r.json()

print("Items       :", len(items))

# Search paths
rgb_candidates = []
depth_candidates = []
image_candidates = []

for item in items:
    path = item.get("path", "")
    lower = path.lower()

    if "rgb" in lower:
        rgb_candidates.append(path)

    if "proj_depth" in lower or "/depth/" in lower:
        depth_candidates.append(path)

    if "image_02" in lower:
        image_candidates.append(path)

print("\nRGB CANDIDATES")
print("-" * 80)
print("Count:", len(rgb_candidates))

for x in rgb_candidates[:20]:
    print(" ", x)

print("\nDEPTH CANDIDATES")
print("-" * 80)
print("Count:", len(depth_candidates))

for x in depth_candidates[:10]:
    print(" ", x)

print("\nIMAGE_02 CANDIDATES")
print("-" * 80)
print("Count:", len(image_candidates))

for x in image_candidates[:10]:
    print(" ", x)

# Top-level structure
print("\nTOP-LEVEL PATHS")
print("-" * 80)

top = sorted(set(x["path"].split("/")[0] for x in items if x.get("path")))

for x in top:
    print(" ", x)

print("\n" + "=" * 80)
print("✓ KITTI ALTERNATIVE STRUCTURE CHECK COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 8 — KITTI RGB/DEPTH ARCHIVE SIZE INVENTORY
# ============================================================

import requests
import time

REPO = "oceanfish/kitti"

DATES = [
    "2011_09_26",
    "2011_09_28",
    "2011_09_29",
    "2011_09_30",
    "2011_10_03",
]

print("=" * 80)
print("MODULE 8 — KITTI RGB/DEPTH ARCHIVE SIZE INVENTORY")
print("=" * 80)

results = []

for date in DATES:
    print(f"\n{date}")
    print("-" * 80)

    for modality in ["rgb", "depth"]:

        path = f"{modality}/{date}.tar"

        url = (
            f"https://huggingface.co/datasets/{REPO}"
            f"/resolve/main/{path}"
        )

        try:
            start = time.time()

            r = requests.head(
                url,
                allow_redirects=True,
                timeout=30
            )

            elapsed = time.time() - start

            size = r.headers.get("Content-Length")

            if size:
                size_gb = int(size) / (1024 ** 3)
                size_mb = int(size) / (1024 ** 2)
            else:
                size_gb = None
                size_mb = None

            print(
                f"{modality:6s} | "
                f"HTTP={r.status_code} | "
                f"size={size_gb:.2f} GB"
                if size_gb is not None
                else
                f"{modality:6s} | "
                f"HTTP={r.status_code} | "
                f"size=unknown"
            )

            results.append({
                "date": date,
                "modality": modality,
                "path": path,
                "status": r.status_code,
                "size_bytes": int(size) if size else None,
                "size_gb": size_gb,
                "elapsed_sec": round(elapsed, 2),
            })

        except Exception as e:
            print(
                f"{modality:6s} | ERROR: {repr(e)}"
            )

print("\n" + "=" * 80)
print("SUMMARY")
print("-" * 80)

for x in results:
    if x["size_gb"] is not None:
        print(
            f'{x["date"]} | '
            f'{x["modality"]:5s} | '
            f'{x["size_gb"]:.2f} GB | '
            f'HTTP {x["status"]}'
        )
    else:
        print(
            f'{x["date"]} | '
            f'{x["modality"]:5s} | '
            f'size unknown | '
            f'HTTP {x["status"]}'
        )

print("=" * 80)
print("✓ KITTI RGB/DEPTH ARCHIVE SIZE INVENTORY COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 8 — KITTI 2011_09_29 ARCHIVE CONTENT INSPECTION
# ============================================================

import requests
import tarfile
import io
import os
import time

REPO = "oceanfish/kitti"
DATE = "2011_09_29"

BASE = f"https://huggingface.co/datasets/{REPO}/resolve/main"

print("=" * 80)
print("MODULE 8 — KITTI 2011_09_29 ARCHIVE CONTENT INSPECTION")
print("=" * 80)

for modality in ["rgb", "depth"]:

    path = f"{modality}/{DATE}.tar"
    url = f"{BASE}/{path}"

    print(f"\n{modality.upper()} ARCHIVE")
    print("-" * 80)
    print("Path:", path)

    # Request only the beginning of the tar file.
    # This avoids downloading the full archive.
    try:
        start = time.time()

        r = requests.get(
            url,
            headers={"Range": "bytes=0-1048575"},
            allow_redirects=True,
            timeout=60
        )

        elapsed = time.time() - start

        print("HTTP status :", r.status_code)
        print("Bytes       :", len(r.content))
        print("Time        :", round(elapsed, 2), "sec")

        # A partial HTTP response cannot normally be opened as
        # a complete tar, so just report whether range was honored.
        content_range = r.headers.get("Content-Range")

        print("Content-Range:", content_range)

        if r.status_code in [200, 206]:
            print("✓ Archive is accessible")

        else:
            print("✗ Archive request failed")

    except Exception as e:
        print("ERROR:", repr(e))

print("\n" + "=" * 80)
print("✓ KITTI ARCHIVE CONTENT INSPECTION COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 8 — KITTI TAR REMOTE INDEX INSPECTION
# ============================================================

import requests
import tarfile
import io
import time

REPO = "oceanfish/kitti"
BASE = f"https://huggingface.co/datasets/{REPO}/resolve/main"

ARCHIVES = {
    "rgb": "rgb/2011_09_29.tar",
    "depth": "depth/2011_09_29.tar",
}

print("=" * 80)
print("MODULE 8 — KITTI TAR REMOTE INDEX INSPECTION")
print("=" * 80)

for modality, path in ARCHIVES.items():

    url = f"{BASE}/{path}"

    print(f"\n{modality.upper()} ARCHIVE")
    print("-" * 80)
    print("Path:", path)

    try:
        # First obtain total size
        h = requests.head(
            url,
            allow_redirects=True,
            timeout=60
        )

        total = int(h.headers.get("Content-Length", 0))

        if total == 0:
            # Some HF endpoints don't expose size through HEAD.
            # Use a 1-byte range request instead.
            probe = requests.get(
                url,
                headers={"Range": "bytes=0-0"},
                allow_redirects=True,
                timeout=60
            )

            cr = probe.headers.get("Content-Range", "")
            total = int(cr.split("/")[-1])

        print("Total bytes:", total)
        print("Total GB   :", round(total / (1024**3), 3))

        # Read final 1 MB
        chunk_size = 1024 * 1024
        start_byte = max(0, total - chunk_size)

        start = time.time()

        r = requests.get(
            url,
            headers={
                "Range": f"bytes={start_byte}-{total-1}"
            },
            allow_redirects=True,
            timeout=120
        )

        elapsed = time.time() - start

        print("HTTP status :", r.status_code)
        print("Bytes read  :", len(r.content))
        print("Time        :", round(elapsed, 2), "sec")

        if r.status_code != 206:
            print("✗ Range request failed")
            continue

        print("Content-Range:", r.headers.get("Content-Range"))

        # Try opening the returned bytes as a partial tar.
        # This may or may not work depending on where the tar
        # headers/index information are located.
        try:
            bio = io.BytesIO(r.content)

            with tarfile.open(
                fileobj=bio,
                mode="r:"
            ) as tar:

                members = tar.getmembers()

                print("Members discovered:", len(members))

                for m in members[:10]:
                    print(" ", m.name)

                print("✓ TAR structure readable")

        except Exception as e:
            print("TAR partial-read result:", repr(e))
            print("ℹ This is not necessarily a failure;")
            print("  TAR member headers may require earlier archive bytes.")

    except Exception as e:
        print("ERROR:", repr(e))

print("\n" + "=" * 80)
print("✓ KITTI TAR REMOTE INDEX INSPECTION COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 8 — KITTI TAR HEADER / FIRST-FILES INSPECTION
# ============================================================

import requests
import tarfile
import io
import time

REPO = "oceanfish/kitti"
BASE = f"https://huggingface.co/datasets/{REPO}/resolve/main"

ARCHIVES = {
    "rgb": "rgb/2011_09_29.tar",
    "depth": "depth/2011_09_29.tar",
}

CHUNK_SIZE = 16 * 1024 * 1024  # 16 MB

print("=" * 80)
print("MODULE 8 — KITTI TAR HEADER / FIRST-FILES INSPECTION")
print("=" * 80)

for modality, path in ARCHIVES.items():

    print(f"\n{modality.upper()} ARCHIVE")
    print("-" * 80)
    print("Path:", path)

    url = f"{BASE}/{path}"

    try:
        start = time.time()

        r = requests.get(
            url,
            headers={
                "Range": f"bytes=0-{CHUNK_SIZE - 1}"
            },
            allow_redirects=True,
            timeout=120
        )

        elapsed = time.time() - start

        print("HTTP status :", r.status_code)
        print("Bytes read  :", len(r.content))
        print("Time        :", round(elapsed, 2), "sec")
        print("Range       :", r.headers.get("Content-Range"))

        if r.status_code != 206:
            print("✗ Range request failed")
            continue

        # Open the first 16 MB as a streaming-like partial TAR.
        bio = io.BytesIO(r.content)

        try:
            with tarfile.open(fileobj=bio, mode="r:") as tar:

                print("\nFIRST TAR MEMBERS")
                print("-" * 60)

                count = 0

                for member in tar:

                    print(
                        f"{count + 1:3d} | "
                        f"{member.name} | "
                        f"{member.size:,} bytes"
                    )

                    count += 1

                    if count >= 20:
                        break

                print("\nMembers inspected:", count)
                print("✓ TAR headers detected")

        except Exception as e:
            print("TAR parse result:", repr(e))

    except Exception as e:
        print("ERROR:", repr(e))

print("\n" + "=" * 80)
print("✓ KITTI TAR HEADER INSPECTION COMPLETE")
print("=" * 80)

