BASE = f"https://huggingface.co/datasets/{REPO}/resolve/main"

ARCHIVES = {
    "rgb": "rgb/2011_09_29.tar",
    "depth": "depth/2011_09_29.tar",
}

CHUNK_SIZE = 32 * 1024 * 1024  # 32 MB

def get_partial_members(url, size):
    r = requests.get(
        url,
        headers={"Range": f"bytes=0-{size-1}"},
        allow_redirects=True,
        timeout=180
    )
    r.raise_for_status()

    bio = io.BytesIO(r.content)

    members = []

    with tarfile.open(fileobj=bio, mode="r:") as tar:
        for m in tar:
            if m.isfile():
                members.append({
                    "name": m.name,
                    "size": m.size,
                    "offset": m.offset_data
                })

    return members, r

print("=" * 80)
print("MODULE 8 — KITTI RGB/DEPTH MATCHING CANDIDATE DISCOVERY")
print("=" * 80)

all_members = {}

for modality, path in ARCHIVES.items():

    print(f"\n{modality.upper()}")
    print("-" * 80)

    url = f"{BASE}/{path}"

    start = time.time()

    try:
        members, response = get_partial_members(
            url,
            CHUNK_SIZE
        )

        elapsed = time.time() - start

        print("HTTP status :", response.status_code)
        print("Bytes read  :", len(response.content))
        print("Time        :", round(elapsed, 2), "sec")
        print("Files found :", len(members))

        all_members[modality] = members

        for m in members[:10]:
            print(
                f"  {m['name']} | "
                f"{m['size']:,} bytes"
            )

    except Exception as e:
        print("ERROR:", repr(e))
        all_members[modality] = []

# ------------------------------------------------------------
# Extract normalized frame keys
# ------------------------------------------------------------

def rgb_key(path):
    """
    Example:
    .../2011_09_29_drive_0108_sync/image_03/data/0000000008.png

    -> (drive, camera, frame)
    """

    match = re.search(
        r"(2011_09_29_drive_\d+_sync)"
        r"/(image_0[23])/data/"
        r"(\d{10})\.png$",
        path
    )

    if not match:
        return None

    return (
        match.group(1),
        match.group(2),
        match.group(3)
    )


def depth_key(path):
    """
    Example:
    .../2011_09_29_drive_0026_sync/
    proj_depth/groundtruth/image_02/0000000034.png

    -> (drive, camera, frame)
    """

    match = re.search(
        r"(2011_09_29_drive_\d+_sync)"
        r"/proj_depth/groundtruth/"
        r"(image_0[23])/"
        r"(\d{10})\.png$",
        path
    )

    if not match:
        return None

    return (
        match.group(1),
        match.group(2),
        match.group(3)
    )


rgb_map = {}
depth_map = {}

for m in all_members["rgb"]:
    key = rgb_key(m["name"])
    if key:
        rgb_map[key] = m

for m in all_members["depth"]:
    key = depth_key(m["name"])
    if key:
        depth_map[key] = m

matches = sorted(set(rgb_map) & set(depth_map))

print("\n" + "=" * 80)
print("MATCHING RGB/DEPTH FRAMES")
print("-" * 80)

print("RGB candidates   :", len(rgb_map))
print("Depth candidates :", len(depth_map))
print("Matched frames   :", len(matches))

for key in matches[:20]:

    drive, camera, frame = key

    print(
        f"{drive} | "
        f"{camera} | "
        f"{frame}"
    )

print("\n" + "=" * 80)

if matches:
    print("✓ RGB/DEPTH MATCHES FOUND")
else:
    print("ℹ No matches in the first 32 MB chunks")
    print("  This does NOT mean the dataset lacks matches;")
    print("  RGB and depth files may occur at different")
    print("  locations inside their respective TAR archives.")

print("=" * 80)
print("✓ KITTI RGB/DEPTH MATCHING DISCOVERY COMPLETE")
print("=" * 80)

# ============================================================
# MODULE 8 — KITTI PARTIAL TAR HEADER SCAN
# ============================================================

import requests
import tarfile
import io
import time
import re

REPO = "oceanfish/kitti"
BASE = f"https://huggingface.co/datasets/{REPO}/resolve/main"

ARCHIVES = {
    "rgb": "rgb/2011_09_29.tar",
    "depth": "depth/2011_09_29.tar",
}

CHUNK_SIZE = 16 * 1024 * 1024  # 16 MB

def scan_headers(url, chunk_size):
    r = requests.get(
        url,
        headers={"Range": f"bytes=0-{chunk_size-1}"},
        allow_redirects=True,
        timeout=180
    )
    r.raise_for_status()

    bio = io.BytesIO(r.content)
    found = []

    tar = tarfile.open(fileobj=bio, mode="r:")

    try:
        while True:
            pos = bio.tell()

            try:
                member = tar.next()
            except (tarfile.ReadError, EOFError):
                break

            if member is None:
                break

            found.append({
                "name": member.name,
                "size": member.size,
                "offset": pos
            })

    finally:
        tar.close()

    return found, r


def rgb_key(path):
    m = re.search(
        r"(2011_09_29_drive_\d+_sync)"
        r"/(image_0[23])/data/"
        r"(\d{10})\.png$",
        path
    )

    if not m:
        return None

    return m.group(1), m.group(2), m.group(3)


def depth_key(path):
    m = re.search(
        r"(2011_09_29_drive_\d+_sync)"
        r"/proj_depth/groundtruth/"
        r"(image_0[23])/"
        r"(\d{10})\.png$",
        path
    )

    if not m:
        return None

    return m.group(1), m.group(2), m.group(3)


print("=" * 80)
print("MODULE 8 — KITTI PARTIAL TAR HEADER SCAN")
print("=" * 80)

results = {}

for modality, path in ARCHIVES.items():

    print(f"\n{modality.upper()} ARCHIVE")
    print("-" * 80)

    url = f"{BASE}/{path}"

    start = time.time()

    try:
        members, response = scan_headers(
            url,
            CHUNK_SIZE
        )

        elapsed = time.time() - start

        print("HTTP status :", response.status_code)
        print("Bytes read  :", len(response.content))
        print("Time        :", round(elapsed, 2), "sec")
        print("Headers read:", len(members))

        results[modality] = members

        file_members = [
            m for m in members
            if m["size"] > 0
        ]

        print("Files found :", len(file_members))

        for m in file_members[:15]:
            print(
                f"  {m['name']} | "
                f"{m['size']:,} bytes"
            )

    except Exception as e:
        print("ERROR:", repr(e))
        results[modality] = []


# ------------------------------------------------------------
# Build candidate keys from successfully scanned headers
# ------------------------------------------------------------

rgb_map = {}
depth_map = {}

for m in results["rgb"]:
    key = rgb_key(m["name"])
    if key:
        rgb_map[key] = m

for m in results["depth"]:
    key = depth_key(m["name"])
    if key:
        depth_map[key] = m

matches = sorted(set(rgb_map) & set(depth_map))

print("\n" + "=" * 80)
print("MATCHING CANDIDATES")
print("-" * 80)

print("RGB candidates   :", len(rgb_map))
print("Depth candidates :", len(depth_map))
print("Matched frames   :", len(matches))

for drive, camera, frame in matches[:20]:
    print(
        f"{drive} | {camera} | {frame}"
    )

print("\n" + "=" * 80)
print("✓ KITTI PARTIAL TAR HEADER SCAN COMPLETE")
print("=" * 80)

