# ============================================================
# MODULE 8 — DOWNLOAD 7 MATCHED KITTI RGB + DEPTH PAIRS
# ============================================================

import os
import io
import tarfile
import requests
from PIL import Image

BASE_DIR = "/content/module8_depth"
RGB_DIR = os.path.join(BASE_DIR, "KITTI", "rgb")
DEPTH_DIR = os.path.join(BASE_DIR, "KITTI", "depth")

os.makedirs(RGB_DIR, exist_ok=True)
os.makedirs(DEPTH_DIR, exist_ok=True)

RGB_URL = "https://huggingface.co/datasets/oceanfish/kitti/resolve/main/rgb/2011_09_29.tar"
DEPTH_URL = "https://huggingface.co/datasets/oceanfish/kitti/resolve/main/depth/2011_09_29.tar"

pairs = [
    ("depth_001", "0000000008"),
    ("depth_002", "0000000009"),
    ("depth_003", "0000000020"),
    ("depth_004", "0000000021"),
    ("depth_005", "0000000034"),
    ("depth_006", "0000000140"),
    ("depth_007", "0000000141"),
]

DRIVE = "2011_09_29_drive_0026_sync"
CAMERA = "image_02"

def get_tar_members(url, wanted):
    """
    Download TAR progressively in chunks until all requested
    members are found.
    """
    response = requests.get(url, stream=True, timeout=120)
    response.raise_for_status()

    # We cannot directly stream a remote TAR with random access.
    # Build a bounded local scan until requested members are found.
    data = bytearray()

    for chunk in response.iter_content(chunk_size=8 * 1024 * 1024):
        if chunk:
            data.extend(chunk)

        try:
            tf = tarfile.open(
                fileobj=io.BytesIO(data),
                mode="r:"
            )

            found = {}
            for member in tf:
                if member.name in wanted:
                    found[member.name] = member

            if len(found) == len(wanted):
                return data, found

        except (tarfile.ReadError, EOFError):
            pass

    raise RuntimeError("Could not locate all requested TAR members.")

rgb_targets = {
    f"2011_09_29/{DRIVE}/{CAMERA}/data/{frame}.png"
    for _, frame in pairs
}

depth_targets = {
    f"2011_09_29/{DRIVE}/proj_depth/groundtruth/{CAMERA}/{frame}.png"
    for _, frame in pairs
}

print("=" * 80)
print("MODULE 8 — KITTI MATCHED PAIR RETRIEVAL")
print("=" * 80)

print("Target pairs :", len(pairs))
print("RGB targets  :", len(rgb_targets))
print("Depth targets:", len(depth_targets))

# ------------------------------------------------------------
# RGB
# ------------------------------------------------------------

print("\nDownloading RGB archive progressively...")
rgb_data, rgb_members = get_tar_members(RGB_URL, rgb_targets)

print("✓ RGB targets located:", len(rgb_members))

rgb_tf = tarfile.open(
    fileobj=io.BytesIO(rgb_data),
    mode="r:"
)

for sample_id, frame in pairs:
    name = f"2011_09_29/{DRIVE}/{CAMERA}/data/{frame}.png"
    member = rgb_members[name]

    extracted = rgb_tf.extractfile(member).read()

    path = os.path.join(RGB_DIR, f"{sample_id}.png")
    with open(path, "wb") as f:
        f.write(extracted)

# ------------------------------------------------------------
# DEPTH
# ------------------------------------------------------------

print("\nDownloading depth archive progressively...")
depth_data, depth_members = get_tar_members(DEPTH_URL, depth_targets)

print("✓ Depth targets located:", len(depth_members))

depth_tf = tarfile.open(
    fileobj=io.BytesIO(depth_data),
    mode="r:"
)

for sample_id, frame in pairs:
    name = (
        f"2011_09_29/{DRIVE}/proj_depth/"
        f"groundtruth/{CAMERA}/{frame}.png"
    )

    member = depth_members[name]
    extracted = depth_tf.extractfile(member).read()

    path = os.path.join(DEPTH_DIR, f"{sample_id}.png")
    with open(path, "wb") as f:
        f.write(extracted)

# ------------------------------------------------------------
# VERIFY
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("DOWNLOADED FILES")
print("-" * 80)

rgb_count = 0
depth_count = 0

for sample_id, _ in pairs:
    rgb_path = os.path.join(RGB_DIR, f"{sample_id}.png")
    depth_path = os.path.join(DEPTH_DIR, f"{sample_id}.png")

    rgb_ok = os.path.exists(rgb_path)
    depth_ok = os.path.exists(depth_path)

    if rgb_ok:
        rgb_count += 1

    if depth_ok:
        depth_count += 1

    print(
        sample_id,
        "| RGB =", rgb_ok,
        "| Depth =", depth_ok
    )

print("\nRGB files   :", rgb_count, "/ 7")
print("Depth files :", depth_count, "/ 7")

assert rgb_count == 7
assert depth_count == 7

print("\n" + "=" * 80)
print("✓ 7 RGB + 7 DEPTH FILES RETRIEVED")
print("=" * 80)

