# ============================================================

from datasets import load_dataset

print("=" * 80)
print("MODULE 8 — KITTI STREAM SCHEMA DISCOVERY")
print("=" * 80)

ds = load_dataset(
    "oceanfish/kitti",
    split="train",
    streaming=True
)

print("Scanning stream for RGB/depth sample types...")
print()

seen = set()
count = 0

for row in ds:
    key = row.get("__key__", "")

    if "/proj_depth/" in key:
        kind = "DEPTH"
    elif "/image_02/" in key or "/image_03/" in key:
        kind = "RGB"
    else:
        kind = "OTHER"

    if kind not in seen:
        seen.add(kind)

        print("TYPE:", kind)
        print("Key :", key)
        print("Keys:", list(row.keys()))
        print()

    count += 1

    if "RGB" in seen and "DEPTH" in seen:
        break

    if count >= 1000:
        break

print("=" * 80)
print("STREAM SAMPLES SCANNED:", count)
print("TYPES FOUND:", sorted(seen))
print("=" * 80)

