# ============================================================
# MODULE 8 — KITTI RGB ZIP RANGE-ACCESS TEST
# ============================================================

import requests
import time

REPO = "2inf/kitti-raw"
FILE = "2011_09_29_drive_0026_sync.zip"

URL = f"https://huggingface.co/datasets/{REPO}/resolve/main/{FILE}"

print("=" * 80)
print("MODULE 8 — KITTI RGB ZIP RANGE-ACCESS TEST")
print("=" * 80)

# Request only the first 1 MB
headers = {
    "Range": "bytes=0-1048575"
}

start = time.time()

r = requests.get(
    URL,
    headers=headers,
    timeout=60,
    allow_redirects=True
)

elapsed = time.time() - start

print("HTTP status :", r.status_code)
print("Time        :", round(elapsed, 2), "sec")
print("Final URL   :", r.url[:150], "...")
print("Content-Type:", r.headers.get("Content-Type"))
print("Content-Range:", r.headers.get("Content-Range"))
print("Bytes read  :", len(r.content))

print("-" * 80)

if r.status_code == 206:
    print("✓ HTTP RANGE ACCESS WORKS")
    print("✓ We can potentially retrieve portions of the ZIP")
elif r.status_code == 200:
    print("⚠ Server returned full-file response (HTTP 200)")
    print("Range request was not honored")
else:
    print("✗ Range request failed")

print("=" * 80)
