print("=" * 80)

t0 = time.time()

r = requests.get(URL, timeout=60)

print("HTTP status:", r.status_code)
print("Time:", round(time.time() - t0, 2), "sec")

r.raise_for_status()

data = r.json()
rows = data.get("rows", [])

print("Rows returned:", len(rows))

# ------------------------------------------------------------
# Inspect schema
# ------------------------------------------------------------
print("\nFEATURES")
print("-" * 80)

for f in data.get("features", []):
    print(f)

# ------------------------------------------------------------
# Inspect first 10 rows
# ------------------------------------------------------------
print("\nFIRST 10 ROWS")
print("-" * 80)

for row in rows[:10]:
    x = row["row"]

    print(
        "id =", x.get("id"),
        "| text =", x.get("text"),
        "| image size =",
        x.get("image", {}).get("width"),
        "x",
        x.get("image", {}).get("height")
    )

# ------------------------------------------------------------
# Search text/id for KITTI drive/frame information
# ------------------------------------------------------------
keywords = [
    "2011_09",
    "drive_",
    "image_02",
    "image_03",
    "0026",
    "0000000008",
    "0000000009",
    "0000000020",
    "0000000021",
    "0000000034",
    "0000000140",
    "0000000141",
]

print("\nTARGET METADATA SEARCH")
print("-" * 80)

matches = []

for row in rows:
    x = row["row"]

    combined = " ".join([
        str(x.get("id", "")),
        str(x.get("text", "")),
    ])

    if any(k in combined for k in keywords):
        matches.append(x)

print("Metadata matches:", len(matches))

for x in matches[:50]:
    print(
        "id =", x.get("id"),
        "| text =", x.get("text")
    )

# ------------------------------------------------------------
# ID inventory
# ------------------------------------------------------------
print("\nID INVENTORY")
print("-" * 80)

ids = [row["row"].get("id") for row in rows]

print("First ID :", ids[0] if ids else None)
print("Last ID  :", ids[-1] if ids else None)

numeric_ids = []

for x in ids:
    try:
        numeric_ids.append(int(x))
    except:
        pass

if numeric_ids:
    print("Numeric ID range:",
          min(numeric_ids),
          "to",
          max(numeric_ids))

# ------------------------------------------------------------
# Dimension distribution
# ------------------------------------------------------------
print("\nIMAGE DIMENSIONS")
print("-" * 80)

from collections import Counter

dims = Counter()

for row in rows:
    img = row["row"].get("image", {})
    dims[(img.get("width"), img.get("height"))] += 1

for dim, count in dims.items():
    print(dim, "|", count)

