# ============================================================
# MODULE 8 — KITTI RGB SAMPLE IMAGE RETRIEVAL
# Retrieve ONLY the first 1000 RGB images through Dataset Server
# ============================================================

import requests
import os
import time
from PIL import Image
from io import BytesIO

DATASET = "Koshti10/Kitti-Images"
CONFIG = "default"
SPLIT = "train"

OUT_DIR = "/content/module8_depth/KITTI_results/rgb_1000"
os.makedirs(OUT_DIR, exist_ok=True)

CHUNK_SIZE = 100
TOTAL_ROWS = 1000

print("=" * 80)
print("MODULE 8 — KITTI RGB SAMPLE IMAGE RETRIEVAL")
print("=" * 80)

saved = 0
failed = 0

for offset in range(0, TOTAL_ROWS, CHUNK_SIZE):

    url = (
        "https://datasets-server.huggingface.co/rows"
        f"?dataset={DATASET}"
        f"&config={CONFIG}"
        f"&split={SPLIT}"
        f"&offset={offset}"
        f"&length={CHUNK_SIZE}"
    )

    print(f"\nFetching metadata {offset}-{offset+CHUNK_SIZE-1}...")

    r = requests.get(url, timeout=60)
    r.raise_for_status()

    rows = r.json()["rows"]

    for row in rows:

        x = row["row"]

        image_info = x.get("image", {})
        image_url = image_info.get("src")
        image_id = x.get("id")

        if not image_url:
            failed += 1
            continue

        try:
            img_r = requests.get(image_url, timeout=60)
            img_r.raise_for_status()

            img = Image.open(BytesIO(img_r.content))
            img.load()

            path = os.path.join(
                OUT_DIR,
                f"{image_id}.jpg"
            )

            img.convert("RGB").save(
                path,
                quality=95
            )

            saved += 1

        except Exception as e:

            failed += 1

            if failed <= 10:
                print(
                    "FAILED:",
                    image_id,
                    repr(e)
                )

    print(
        f"Progress: saved={saved}, failed={failed}"
    )

print("\n" + "=" * 80)
print("RGB RETRIEVAL COMPLETE")
print("=" * 80)

print("Saved :", saved)
print("Failed:", failed)
print("Directory:", OUT_DIR)

