import os
from PIL import Image
import numpy as np

RGB_DIR = "/content/module8_depth/KITTI_results/rgb_1000"

files = sorted([
    f for f in os.listdir(RGB_DIR)
    if f.lower().endswith((".jpg", ".jpeg", ".png"))
])

