print("MODULE 8 — KITTI RGB 1000 SAMPLE VISUAL VALIDATION")
print("=" * 80)

print("RGB files found:", len(files))

# ------------------------------------------------------------
# Inspect image properties
# ------------------------------------------------------------

sizes = {}
modes = {}

for f in files:
    path = os.path.join(RGB_DIR, f)

    with Image.open(path) as img:
        sizes[img.size] = sizes.get(img.size, 0) + 1
        modes[img.mode] = modes.get(img.mode, 0) + 1

print("\nIMAGE SIZES")
print("-" * 80)

for size, count in sorted(sizes.items()):
    print(size, "|", count)

print("\nIMAGE MODES")
