# ============================================================
# MODULE 8 — KITTI RGB/DEPTH PAIRING ANCHOR TEST
# ============================================================

import os
import hashlib
from PIL import Image
import numpy as np

RGB_DIR = "/content/module8_depth/KITTI_results/rgb_1000"

rgb_files = sorted(
    f for f in os.listdir(RGB_DIR)
    if f.lower().endswith(".jpg")
)

print("=" * 80)
print("MODULE 8 — KITTI RGB/DEPTH PAIRING ANCHOR TEST")
print("=" * 80)

print("RGB images available:", len(rgb_files))

# ------------------------------------------------------------
# Known frozen depth frames
# ------------------------------------------------------------

KNOWN_FRAMES = [
    "0000000008",
    "0000000009",
    "0000000020",
    "0000000021",
    "0000000034",
    "0000000140",
    "0000000141",
]

print("\nKNOWN DEPTH FRAME IDs")
print("-" * 80)

for x in KNOWN_FRAMES:
    print(x)

# ------------------------------------------------------------
# Check whether numeric frame IDs exist directly
# ------------------------------------------------------------

print("\nDIRECT RGB ID CHECK")
print("-" * 80)

for frame in KNOWN_FRAMES:

    short_id = str(int(frame)).zfill(6)

    candidates = [
        f"{short_id}.jpg",
        f"{frame}.jpg",
    ]

    found = [
        f for f in candidates
        if os.path.exists(os.path.join(RGB_DIR, f))
    ]

    print(
        "Depth frame:", frame,
        "| RGB candidate:", short_id,
        "| exists:", bool(found)
    )

# ------------------------------------------------------------
# Hash / dimensions of candidate RGB images
# ------------------------------------------------------------

print("\nRGB CANDIDATE INSPECTION")
print("-" * 80)

for frame in KNOWN_FRAMES:

    short_id = str(int(frame)).zfill(6)
    path = os.path.join(RGB_DIR, short_id + ".jpg")

    if not os.path.exists(path):
        continue

    with Image.open(path) as img:

        arr = np.asarray(img.convert("RGB"))

        sha = hashlib.sha256(
            arr.tobytes()
        ).hexdigest()[:16]

        print(
            f"{short_id}.jpg"
            f" | size={img.size}"
            f" | mean={arr.mean():.2f}"
            f" | sha256={sha}"
        )

print("\n" + "=" * 80)
print("✓ PAIRING ANCHOR TEST COMPLETE")
print("=" * 80)

