# MODULE 8 — KITTI RGB/DEPTH VISUAL PAIR VERIFICATION
# ============================================================

import os
import numpy as np
from PIL import Image
import matplotlib.pyplot as plt

RGB_DIR = "/content/module8_depth/KITTI_results/rgb_1000"
DEPTH_DIR = "/content/module8_depth/KITTI_results/depth_7"

FRAMES = [
    "000008",
    "000009",
    "000020",
    "000021",
    "000034",
    "000140",
    "000141",
]

OUT_DIR = "/content/module8_depth/KITTI_results/pair_verification"
os.makedirs(OUT_DIR, exist_ok=True)

print("=" * 80)
print("MODULE 8 — KITTI RGB/DEPTH VISUAL PAIR VERIFICATION")
print("=" * 80)

for frame in FRAMES:

    rgb_path = os.path.join(RGB_DIR, frame + ".jpg")
    depth_path = os.path.join(DEPTH_DIR, frame + ".png")

    print(f"\nFRAME {frame}")
    print("-" * 60)

    if not os.path.exists(rgb_path):
        print("✗ RGB missing:", rgb_path)
        continue

    if not os.path.exists(depth_path):
        print("✗ DEPTH missing:", depth_path)
        continue

    rgb = Image.open(rgb_path).convert("RGB")
    depth = Image.open(depth_path)

    depth_np = np.asarray(depth)

    print("RGB   :", rgb.size)
    print("DEPTH :", depth.size)
    print("Depth dtype:", depth_np.dtype)
    print("Depth min :", depth_np.min())
    print("Depth max :", depth_np.max())
    print("Depth nonzero:",
          np.count_nonzero(depth_np),
          "/",
          depth_np.size)

    # --------------------------------------------------------
    # Visualize
    # --------------------------------------------------------

    fig, axes = plt.subplots(1, 2, figsize=(16, 5))

    axes[0].imshow(rgb)
    axes[0].set_title(f"RGB — {frame}")
    axes[0].axis("off")

    # Robust visualization: ignore zero values
    valid = depth_np > 0

    if np.any(valid):
        vmax = np.percentile(depth_np[valid], 99)
    else:
        vmax = 1

    axes[1].imshow(
        depth_np,
        cmap="gray",
        vmin=0,
        vmax=vmax
    )
    axes[1].set_title(f"Depth — {frame}")
    axes[1].axis("off")

    plt.tight_layout()

    output = os.path.join(
        OUT_DIR,
        f"pair_{frame}.png"
    )

    plt.savefig(
        output,
        dpi=150,
        bbox_inches="tight"
    )

    plt.show()
    plt.close()

    print("✓ Saved:", output)

print("\n" + "=" * 80)
print("✓ VISUAL PAIR VERIFICATION COMPLETE")
print("=" * 80)
print("Output:", OUT_DIR)

